// AUTO-GENERATED by tools/build_bank_v2.py — rebuild, don't edit.
const BANK2 = {"meta": {"built": "2026-08-25", "version": 2, "source": "tools/build_bank_v2.py — DO NOT EDIT BY HAND", "cards": 791, "lectures": 10}, "domains": ["01_licensing-law", "02_liens-insurance-bonds", "03_contracts-hifa", "04_business-management", "05_miosha-safety", "06_sitework-concrete-foundations", "07_carpentry-framing", "08_masonry-roofing-siding", "09_envelope-interior", "10_plans-math-trades"], "cards": [{"id": "licensing-law-001", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What law governs residential builder licensing in Michigan, and what are its MCL sections?", "back": "Article 24 of the Occupational Code, 1980 PA 299 — MCL 339.2401 through 339.2412.", "audio_front": "What law governs residential builder licensing in Michigan, and what are its M C L sections?", "audio_back": "Article twenty four of the Occupational Code, Public Act two ninety nine of nineteen eighty. M C L 339 point 2401 through 339 point 2412.", "source": "MCL 339.2401-339.2412", "domain": "01_licensing-law"}, {"id": "licensing-law-002", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Which agency administers the Michigan residential builder license?", "back": "LARA — the Department of Licensing and Regulatory Affairs, Bureau of Construction Codes, Licensing Section.", "audio_front": "Which agency administers the Michigan residential builder license?", "audio_back": "LARA. The Department of Licensing and Regulatory Affairs, Bureau of Construction Codes, Licensing Section.", "source": "michigan.gov/bcc", "domain": "01_licensing-law"}, {"id": "licensing-law-003", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "How is the Residential Builders' and M&A Contractors' Board composed?", "back": "9 members: 4 licensed residential builders, 2 licensed M&A contractors, and 3 public members (MCL 339.2402).", "audio_front": "How is the Residential Builders and M and A Contractors Board composed?", "audio_back": "Nine members. Four licensed residential builders, two licensed maintenance and alteration contractors, and three public members. M C L 339 point 2402.", "source": "MCL 339.2402", "domain": "01_licensing-law"}, {"id": "licensing-law-004", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Define 'residential structure' under current MCL 339.2401(c).", "back": "A detached 1- or 2-family dwelling with appurtenant facilities, OR a townhouse not more than 3 stories above grade plane with a separate means of egress. Amended by 2020 PA 341, retroactive to 1/1/2019.", "audio_front": "Define residential structure under current M C L 339 point 2401 subsection c.", "audio_back": "A detached one or two family dwelling with appurtenant facilities, or a townhouse not more than three stories above grade plane with a separate means of egress. Amended by Public Act three forty one of twenty twenty.", "source": "MCL 339.2401(c)", "domain": "01_licensing-law"}, {"id": "licensing-law-005", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "TRAP: Does the current definition of 'residential structure' include 'combination residential and commercial structures'?", "back": "No. That phrase was removed by 2020 PA 341. Old LARA materials still quote it, but the current statute is limited to detached 1-2 family dwellings and townhouses of 3 stories or less with separate egress.", "audio_front": "Trap question. Does the current definition of residential structure include combination residential and commercial structures?", "audio_back": "No. That phrase was removed by Public Act three forty one of twenty twenty. The current statute covers only detached one or two family dwellings and townhouses of three stories or less with a separate means of egress.", "source": "MCL 339.2401(c); 2020 PA 341", "domain": "01_licensing-law"}, {"id": "licensing-law-006", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "A person sells prefabricated shell housing but never swings a hammer. Do they need a builder's license?", "back": "Yes. MCL 339.2401(a) defines 'residential builder' to include a person who manufactures, assembles, constructs, deals in, or distributes prefabricated, preassembled, precut, packaged, or shell housing.", "audio_front": "A person sells prefabricated shell housing but never swings a hammer. Do they need a builder's license?", "audio_back": "Yes. M C L 339 point 2401 subsection a includes anyone who manufactures, deals in, or distributes prefabricated, preassembled, precut, packaged, or shell housing.", "source": "MCL 339.2401(a)", "domain": "01_licensing-law"}, {"id": "licensing-law-007", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What compensation is carved OUT of the builder licensing definitions?", "back": "'Wages for personal labor only' — money paid hourly or daily for personal labor where the worker does not contract for a fixed price and does not furnish materials (MCL 339.2401(e)).", "audio_front": "What compensation is carved out of the builder licensing definitions?", "audio_back": "Wages for personal labor only. Money paid hourly or daily for personal labor, where the worker does not contract for a fixed price and does not furnish the materials. M C L 339 point 2401 subsection e.", "source": "MCL 339.2401(e)", "domain": "01_licensing-law"}, {"id": "licensing-law-008", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "When does house flipping require an M&A contractor license?", "back": "When a person purchases, substantially rehabs or improves, and resells a residential structure, and does that activity on the same structure more than twice in 1 calendar year (MCL 339.2401(b)(ii)). Exceptions: own use and occupancy, or all work contracted to licensed persons.", "audio_front": "When does house flipping require a maintenance and alteration contractor license?", "audio_back": "When a person purchases, substantially rehabs, and resells a residential structure more than twice in one calendar year on the same structure. Exceptions include the person's own use and occupancy, or hiring all work to licensed contractors. M C L 339 point 2401 subsection b.", "source": "MCL 339.2401(b)(ii)", "domain": "01_licensing-law"}, {"id": "licensing-law-009", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Building a garage or laying concrete on residential property falls under which license definition?", "back": "Residential maintenance and alteration contractor — MCL 339.2401(b) expressly lists building of a garage and laying of concrete on residential property.", "audio_front": "Building a garage or laying concrete on residential property falls under which license definition?", "audio_back": "Residential maintenance and alteration contractor. M C L 339 point 2401 subsection b expressly lists building of a garage and laying of concrete on residential property.", "source": "MCL 339.2401(b)", "domain": "01_licensing-law"}, {"id": "licensing-law-010", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What is the difference in scope between the RB license and the M&A contractor license?", "back": "RB = full authority including new construction plus all alteration work. M&A = repair, alteration, improvement, wrecking, garages, concrete — but NO new home construction. RB covers M&A work; M&A does not cover RB work.", "audio_front": "What is the difference in scope between the residential builder license and the M and A contractor license?", "audio_back": "The residential builder license covers new construction plus all alteration work. The maintenance and alteration license covers repair, alteration, improvement, wrecking, garages, and concrete, but no new home construction. R B covers M and A work, but not the reverse.", "source": "MCL 339.2401(a)-(b)", "domain": "01_licensing-law"}, {"id": "licensing-law-011", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Who is a 'salesperson' under Article 24?", "back": "An employee or agent — other than a qualifying officer — of a licensed builder or M&A contractor who for consideration sells, negotiates, solicits, or obtains contracts for the licensee's goods and services. Occasional and incidental sales by an employee are excepted (MCL 339.2401(d)).", "audio_front": "Who is a salesperson under Article twenty four?", "audio_back": "An employee or agent, other than a qualifying officer, of a licensed builder or contractor, who for consideration sells, negotiates, solicits, or obtains contracts for the licensee's goods and services. Occasional and incidental sales are excepted. M C L 339 point 2401 subsection d.", "source": "MCL 339.2401(d)", "domain": "01_licensing-law"}, {"id": "licensing-law-012", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What is the $600 rule in MCL 339.2403(f)?", "back": "A licensure EXEMPTION: no license is required if the aggregate contract price for labor, material, and any other items on 1 undertaking is less than $600. It is NOT a written-contract trigger.", "audio_front": "What is the six hundred dollar rule in M C L 339 point 2403 subsection f?", "audio_back": "It is a licensure exemption. No license is required if the aggregate contract price for labor, material, and other items on one undertaking is less than six hundred dollars. It is not a written contract trigger.", "source": "MCL 339.2403(f)", "domain": "01_licensing-law"}, {"id": "licensing-law-013", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "A contractor splits a $2,000 job into four $500 contracts to stay under the $600 exemption. Legal?", "back": "No. MCL 339.2403(f) has an anti-evasion clause: the exemption does not apply if the work is part of a larger operation or is divided into sub-$600 contracts to evade the act.", "audio_front": "A contractor splits a two thousand dollar job into four five hundred dollar contracts to stay under the six hundred dollar exemption. Legal?", "audio_back": "No. The statute has an anti evasion clause. The exemption does not apply if the work is part of a larger operation or is divided into contracts under six hundred dollars to evade the act.", "source": "MCL 339.2403(f)", "domain": "01_licensing-law"}, {"id": "licensing-law-014", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Name the exemption in MCL 339.2403 that covers a homeowner building on their own land.", "back": "An owner of property is exempt with reference to a structure for the owner's OWN use and occupancy (MCL 339.2403(b)). Building to sell is not exempt.", "audio_front": "Name the exemption that covers a homeowner building on their own land.", "audio_back": "An owner of property is exempt for a structure for the owner's own use and occupancy. M C L 339 point 2403 subsection b. Building to sell is not exempt.", "source": "MCL 339.2403(b)", "domain": "01_licensing-law"}, {"id": "licensing-law-015", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Does a landlord need a builder's license to maintain and alter their own rental property?", "back": "No. MCL 339.2403(c) exempts an owner of rental property for the maintenance and alteration of that rental property.", "audio_front": "Does a landlord need a builder's license to maintain and alter their own rental property?", "audio_back": "No. M C L 339 point 2403 subsection c exempts an owner of rental property for maintenance and alteration of that rental property.", "source": "MCL 339.2403(c)", "domain": "01_licensing-law"}, {"id": "licensing-law-016", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Is a subcontractor working solely under contract with a LICENSED residential builder required to hold their own Article 24 license?", "back": "No. MCL 339.2403(e) exempts a person (other than a salesperson) engaged solely in performing work and services under contract with a licensed residential builder or M&A contractor.", "audio_front": "Is a subcontractor working solely under contract with a licensed residential builder required to hold their own Article twenty four license?", "audio_back": "No. M C L 339 point 2403 subsection e exempts a person, other than a salesperson, working solely under contract with a licensed residential builder or M and A contractor.", "source": "MCL 339.2403(e)", "domain": "01_licensing-law"}, {"id": "licensing-law-017", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Which trade contractors are exempt from Article 24 licensing, and how far does the exemption reach?", "back": "Licensed electrical, mechanical (HVAC), and plumbing contractors under the Skilled Trades Regulation Act — but only for their own trade's installation, maintenance, or repair work (MCL 339.2403(g)-(i)).", "audio_front": "Which trade contractors are exempt from Article twenty four licensing, and how far does the exemption reach?", "audio_back": "Licensed electrical, mechanical, and plumbing contractors under the Skilled Trades Regulation Act. The exemption applies only to their own trade's installation, maintenance, or repair work.", "source": "MCL 339.2403(g)-(i)", "domain": "01_licensing-law"}, {"id": "licensing-law-018", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Are government employees exempt from builder licensing?", "back": "Yes — authorized representatives of the US government, the state, or a county, township, city, village, or other political subdivision are exempt (MCL 339.2403(a)). Court officers acting within their office are also exempt (339.2403(d)).", "audio_front": "Are government employees exempt from builder licensing?", "audio_back": "Yes. Authorized representatives of the United States government, the state, or a political subdivision are exempt, and so are officers of a court acting within the scope of that office.", "source": "MCL 339.2403(a),(d)", "domain": "01_licensing-law"}, {"id": "licensing-law-019", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Does Michigan license commercial builders at the state level?", "back": "No. Article 24 covers residential only. Commercial contractors deal with local permit requirements, not a state contractor license.", "audio_front": "Does Michigan license commercial builders at the state level?", "audio_back": "No. Article twenty four covers residential only. Commercial contractors deal with local permit requirements, not a state contractor license.", "source": "MCL 339.2401; LARA Builders FAQ", "domain": "01_licensing-law"}, {"id": "licensing-law-020", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Does Michigan have builder-license reciprocity with any other state?", "back": "No. LARA states Michigan holds no reciprocal agreements with any state; out-of-state licensees must meet all Michigan requirements.", "audio_front": "Does Michigan have builder license reciprocity with any other state?", "audio_back": "No. Michigan holds no reciprocal agreements with any state. Out of state licensees must meet all Michigan requirements.", "source": "LARA Builders FAQ", "domain": "01_licensing-law"}, {"id": "licensing-law-021", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "How many hours of prelicensure education are required, and with what distribution?", "back": "60 hours of approved courses, with at least 6 hours in each of 7 competency areas (MCL 339.2404b(1)(c)). Required for initial licensure since June 1, 2008.", "audio_front": "How many hours of prelicensure education are required, and with what distribution?", "audio_back": "Sixty hours of approved courses, with at least six hours in each of seven competency areas. Required since June first, two thousand eight. M C L 339 point 2404 b.", "source": "MCL 339.2404b(1)(c)", "domain": "01_licensing-law"}, {"id": "licensing-law-022", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Name the 7 statutory competency areas of the 60-hour prelicensure course.", "back": "1) Business management, estimating, and job costing; 2) Design and building science; 3) Contracts, liability, and risk management; 4) Marketing and sales; 5) Project management and scheduling; 6) The current Michigan residential code; 7) MIOSHA construction safety standards (MCL 339.2404b(1)(c)).", "audio_front": "Name the seven statutory competency areas of the sixty hour prelicensure course.", "audio_back": "One, business management, estimating, and job costing. Two, design and building science. Three, contracts, liability, and risk management. Four, marketing and sales. Five, project management and scheduling. Six, the current Michigan residential code. Seven, MIOSHA construction safety standards.", "source": "MCL 339.2404b(1)(c)", "domain": "01_licensing-law"}, {"id": "licensing-law-023", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Does the 60-hour prelicensure certificate expire?", "back": "No. LARA confirms certificates for courses taken after June 1, 2008 do not expire. Courses taken before that date do not count.", "audio_front": "Does the sixty hour prelicensure certificate expire?", "audio_back": "No. Certificates for courses taken after June first, two thousand eight do not expire. Courses taken before that date do not count.", "source": "LARA Builders FAQ", "domain": "01_licensing-law"}, {"id": "licensing-law-024", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Is prior construction experience a statutory requirement for the Michigan RB license?", "back": "No. MCL 339.2404 requires good moral character evidence, proof of identity, and passing the exam; MCL 339.2404b adds the 60-hour prelicensure. No experience requirement appears in the statute.", "audio_front": "Is prior construction experience a statutory requirement for the Michigan residential builder license?", "audio_back": "No. The statute requires good moral character, proof of identity, the sixty hour prelicensure course, and passing the exam. No experience requirement appears in the statute.", "source": "MCL 339.2404; 339.2404b", "domain": "01_licensing-law"}, {"id": "licensing-law-025", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What identity document must an applicant submit, and what may LARA use it for?", "back": "A copy of the applicant's operator's (driver's) license or state personal ID card; the department may use it ONLY for proof of identity (MCL 339.2404(1)).", "audio_front": "What identity document must an applicant submit, and what may LARA use it for?", "audio_back": "A copy of the applicant's driver's license or state personal identification card, and the department may use it only for proof of identity. M C L 339 point 2404 subsection one.", "source": "MCL 339.2404(1)", "domain": "01_licensing-law"}, {"id": "licensing-law-026", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "How long after applying do you have to complete ALL licensure requirements including the exam?", "back": "1 year from the date the license application is received. Otherwise fees are forfeited and the application is void (MCL 339.409(3); R 338.1521(1)).", "audio_front": "How long after applying do you have to complete all licensure requirements including the exam?", "audio_back": "One year from the date the license application is received. Otherwise fees are forfeited and the application is void. M C L 339 point 409 subsection three.", "source": "MCL 339.409(3); R 338.1521(1)", "domain": "01_licensing-law"}, {"id": "licensing-law-027", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "List the 12 crafts and trades covered by the M&A contractor license.", "back": "Carpentry; concrete; swimming pool installation; waterproofing a basement; excavation; insulation work; masonry work; roofing; siding and gutters; screen or storm sash installation; tile and marble work; house wrecking (MCL 339.2404(3)).", "audio_front": "List the twelve crafts and trades covered by the maintenance and alteration contractor license.", "audio_back": "Carpentry. Concrete. Swimming pool installation. Waterproofing a basement. Excavation. Insulation work. Masonry work. Roofing. Siding and gutters. Screen or storm sash installation. Tile and marble work. And house wrecking.", "source": "MCL 339.2404(3)", "domain": "01_licensing-law"}, {"id": "licensing-law-028", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "May an M&A specialty contractor perform work in a craft they are NOT licensed for?", "back": "Only if that work is incidental and supplemental to the performance of work in the craft for which they hold a license (MCL 339.2404(3)).", "audio_front": "May an M and A specialty contractor perform work in a craft they are not licensed for?", "audio_back": "Only if that work is incidental and supplemental to the craft for which they hold a license. M C L 339 point 2404 subsection three.", "source": "MCL 339.2404(3)", "domain": "01_licensing-law"}, {"id": "licensing-law-029", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What are the place-of-business rules for a Michigan builder?", "back": "A licensee must maintain a place of business in Michigan; if they maintain more than one, the department issues a branch office license for each additional place of business (MCL 339.2404(4)).", "audio_front": "What are the place of business rules for a Michigan builder?", "audio_back": "A licensee must maintain a place of business in Michigan, and each additional place of business requires a branch office license. M C L 339 point 2404 subsection four.", "source": "MCL 339.2404(4)", "domain": "01_licensing-law"}, {"id": "licensing-law-030", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "How long is the Michigan residential builder license valid?", "back": "3 years (MCL 339.2404(5)).", "audio_front": "How long is the Michigan residential builder license valid?", "audio_back": "Three years. M C L 339 point 2404 subsection five.", "source": "MCL 339.2404(5)", "domain": "01_licensing-law"}, {"id": "licensing-law-031", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What two things must a renewal applicant state to the department?", "back": "That they have a current copy of the Michigan Residential Code and that they meet the applicable continuing competency requirements (MCL 339.2404(6)).", "audio_front": "What two things must a renewal applicant state to the department?", "audio_back": "That they have a current copy of the Michigan Residential Code, and that they meet the applicable continuing competency requirements. M C L 339 point 2404 subsection six.", "source": "MCL 339.2404(6)", "domain": "01_licensing-law"}, {"id": "licensing-law-032", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "How long must a licensee keep documentation of continuing competency activities?", "back": "At least 5 years (MCL 339.2404(7)).", "audio_front": "How long must a licensee keep documentation of continuing competency activities?", "audio_back": "At least five years. M C L 339 point 2404 subsection seven.", "source": "MCL 339.2404(7)", "domain": "01_licensing-law"}, {"id": "licensing-law-033", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Continuing competency for a builder FIRST licensed on or after January 1, 2009?", "back": "At least 21 hours per 3-year cycle, including at least 3 hours in each calendar year during the first 6 calendar years, with at least 3 hours on codes, safety, and law changes (MCL 339.2404b(2)(a)).", "audio_front": "What is the continuing competency requirement for a builder first licensed on or after January first, two thousand nine?", "audio_back": "At least twenty one hours per three year cycle, including at least three hours in each calendar year during the first six calendar years, with at least three hours on codes, safety, and law changes.", "source": "MCL 339.2404b(2)(a)", "domain": "01_licensing-law"}, {"id": "licensing-law-034", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Continuing competency for a builder first licensed BEFORE January 1, 2009 with no discipline?", "back": "Only 3 hours per 3-year license cycle — 1 hour of codes, 1 hour of safety, and 1 hour of legal issues (MCL 339.2404b(2)(c)-(d)).", "audio_front": "What is the continuing competency requirement for a builder first licensed before January first, two thousand nine, with no discipline?", "audio_back": "Only three hours per three year cycle. One hour of codes, one hour of safety, and one hour of legal issues.", "source": "MCL 339.2404b(2)(c)-(d)", "domain": "01_licensing-law"}, {"id": "licensing-law-035", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What extra continuing competency can be ordered after disciplinary action?", "back": "Between 3 and 21 hours in the next complete license cycle, as determined by department order, including at least 1 hour each of codes, safety, and legal issues (MCL 339.2404b(3)).", "audio_front": "What extra continuing competency can be ordered after disciplinary action?", "audio_back": "Between three and twenty one hours in the next complete license cycle, as ordered by the department, including at least one hour each of codes, safety, and legal issues.", "source": "MCL 339.2404b(3)", "domain": "01_licensing-law"}, {"id": "licensing-law-036", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Your license lapsed 4 years ago. What does relicensure require?", "back": "Completion of the 60-hour prelicensure education again, the relicensure application and fees, good moral character, AND passing the current license exam (LARA relicensure rules for lapse over 3 years).", "audio_front": "Your license lapsed four years ago. What does relicensure require?", "audio_back": "You must complete the sixty hour prelicensure education again, file the relicensure application and fees, show good moral character, and pass the current license exam.", "source": "LARA Builders FAQ", "domain": "01_licensing-law"}, {"id": "licensing-law-037", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Your license lapsed 1 year ago. What does relicensure require?", "back": "For a license expired less than 3 years: file the application and pay the $185 fee — no re-education, no re-exam (LARA FAQ). Lapse of 61 days to 3 years requires application, fees, and good moral character.", "audio_front": "Your license lapsed one year ago. What does relicensure require?", "audio_back": "For a license expired less than three years, file the application and pay the one hundred eighty five dollar fee. No re education and no re exam.", "source": "LARA Builders FAQ", "domain": "01_licensing-law"}, {"id": "licensing-law-038", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "An LLC wants a residential builder license. Who must it designate, and from what positions?", "back": "A qualifying officer, designated from its officers, partners, members, or its managing agent (MCL 339.2405(1)).", "audio_front": "An L L C wants a residential builder license. Who must it designate, and from what positions?", "audio_back": "A qualifying officer, designated from its officers, partners, members, or its managing agent. M C L 339 point 2405 subsection one.", "source": "MCL 339.2405(1)", "domain": "01_licensing-law"}, {"id": "licensing-law-039", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Must the qualifying officer hold their own individual license?", "back": "Yes. The QO must take and pass the exam, meet all requirements, and obtain AND maintain an individual Article 24 license in addition to the license to act for the entity (MCL 339.2405(1)).", "audio_front": "Must the qualifying officer hold their own individual license?", "audio_back": "Yes. The qualifying officer must pass the exam and obtain and maintain an individual license in addition to the license to act for the entity.", "source": "MCL 339.2405(1)", "domain": "01_licensing-law"}, {"id": "licensing-law-040", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What is the qualifying officer legally responsible for?", "back": "Exercising the supervision or control of the building or construction operations necessary to secure full compliance with Article 24 and its rules (MCL 339.2405(1)).", "audio_front": "What is the qualifying officer legally responsible for?", "audio_back": "Exercising the supervision or control of the building operations necessary to secure full compliance with Article twenty four and its rules.", "source": "MCL 339.2405(1)", "domain": "01_licensing-law"}, {"id": "licensing-law-041", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What age and qualification rules apply to an entity's principals?", "back": "Every partner, trustee, director, officer, member, and person exercising control must be at least 18 and meet license requirements other than those relating to knowledge and experience (MCL 339.2405(1)).", "audio_front": "What age and qualification rules apply to an entity's principals?", "audio_back": "Every partner, trustee, director, officer, member, and controlling person must be at least eighteen years old and meet the license requirements other than knowledge and experience.", "source": "MCL 339.2405(1)", "domain": "01_licensing-law"}, {"id": "licensing-law-042", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What happens to the company license when the qualifying officer's individual license is suspended, revoked, or denied?", "back": "The entity's license is suspended, and stays suspended until the board determines the disability is removed (MCL 339.2405(2)).", "audio_front": "What happens to the company license when the qualifying officer's individual license is suspended, revoked, or denied?", "audio_back": "The entity's license is suspended, and stays suspended until the board determines the disability is removed. M C L 339 point 2405 subsection two.", "source": "MCL 339.2405(2)", "domain": "01_licensing-law"}, {"id": "licensing-law-043", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "The qualifying officer quits the company. What happens to the company license?", "back": "It is suspended — but on request the department may permit it to remain in force for a reasonable time to qualify a new qualifying officer (MCL 339.2405(4)).", "audio_front": "The qualifying officer quits the company. What happens to the company license?", "audio_back": "It is suspended, but on request the department may permit the license to remain in force for a reasonable time to qualify a new qualifying officer.", "source": "MCL 339.2405(4)", "domain": "01_licensing-law"}, {"id": "licensing-law-044", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Can a licensee on inactive status serve as a qualifying officer?", "back": "No. A licensee granted inactive status under section 2404b is not eligible to serve as a qualifying officer (MCL 339.2405(1)).", "audio_front": "Can a licensee on inactive status serve as a qualifying officer?", "audio_back": "No. A licensee granted inactive status is not eligible to serve as a qualifying officer.", "source": "MCL 339.2405(1)", "domain": "01_licensing-law"}, {"id": "licensing-law-045", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "A sole proprietor with an individual RB license forms an LLC. Can they build under the old license?", "back": "No. The LLC is a new legal person and must obtain its own company license, with a licensed individual as qualifying officer (MCL 339.2405; LARA FAQ).", "audio_front": "A sole proprietor with an individual builder license forms an L L C. Can they build under the old license?", "audio_back": "No. The L L C is a new legal person and must obtain its own company license, with a licensed individual serving as qualifying officer.", "source": "MCL 339.2405; LARA Builders FAQ", "domain": "01_licensing-law"}, {"id": "licensing-law-046", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What must nonresident applicants file before licensure?", "back": "A Consent to Service of Process (MCL 339.2406).", "audio_front": "What must nonresident applicants file before licensure?", "audio_back": "A consent to service of process. M C L 339 point 2406.", "source": "MCL 339.2406", "domain": "01_licensing-law"}, {"id": "licensing-law-047", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What license information must appear in a licensee's contracts?", "back": "Information relating to the licensee's individual license and to any license issued to them as qualifying officer of another entity (MCL 339.2404a).", "audio_front": "What license information must appear in a licensee's contracts?", "audio_back": "Information relating to the licensee's individual license, and to any license issued to that person as qualifying officer of another entity. M C L 339 point 2404 a.", "source": "MCL 339.2404a", "domain": "01_licensing-law"}, {"id": "licensing-law-048", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "How long does a homeowner have to file a complaint against a builder, and from when?", "back": "18 months after the latest of: completion, occupancy, or purchase (M&A contract); or issuance of the certificate of occupancy / temporary CO, or closing (project requiring an occupancy permit) (MCL 339.2411(1)).", "audio_front": "How long does a homeowner have to file a complaint against a builder, and from when?", "audio_back": "Eighteen months after the latest of completion, occupancy, or purchase for a maintenance and alteration contract, or the certificate of occupancy or closing for a project requiring an occupancy permit.", "source": "MCL 339.2411(1)", "domain": "01_licensing-law"}, {"id": "licensing-law-049", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Name the discipline ground: taking a customer's deposit for Project A and spending it on Project B.", "back": "Diversion of funds — MCL 339.2411(2)(b): diverting funds or property received for a specific construction project or purpose to any other project, obligation, or purpose.", "audio_front": "Name the discipline ground: taking a customer's deposit for project A and spending it on project B.", "audio_back": "Diversion of funds. M C L 339 point 2411 subsection two b. Diverting funds received for a specific project or purpose to any other project, obligation, or purpose.", "source": "MCL 339.2411(2)(b)", "domain": "01_licensing-law"}, {"id": "licensing-law-050", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Walking off a job without legal excuse is which discipline ground?", "back": "Abandonment of a contract, construction project, or operation — MCL 339.2411(2)(a).", "audio_front": "Walking off a job without legal excuse is which discipline ground?", "audio_back": "Abandonment of a contract, construction project, or operation. M C L 339 point 2411 subsection two a.", "source": "MCL 339.2411(2)(a)", "domain": "01_licensing-law"}, {"id": "licensing-law-051", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Within how many days must a licensee notify the department of a change in control or direction of the business?", "back": "10 days (MCL 339.2411(2)(g)) — covers changes in partners, directors, officers, or trustees. Failure is a discipline ground.", "audio_front": "Within how many days must a licensee notify the department of a change in control or direction of the business?", "audio_back": "Ten days. Covers changes in partners, directors, officers, or trustees. Failure is a discipline ground. M C L 339 point 2411 subsection two g.", "source": "MCL 339.2411(2)(g)", "domain": "01_licensing-law"}, {"id": "licensing-law-052", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Is deviating from the plans a discipline ground even if the work is code-compliant?", "back": "Yes, if it is a willful departure from or disregard of plans or specifications in a material respect, prejudicial to another, without consent of the owner or authorized representative (MCL 339.2411(2)(d)).", "audio_front": "Is deviating from the plans a discipline ground even if the work is code compliant?", "audio_back": "Yes. A willful departure from plans or specifications in a material respect, prejudicial to another, without the owner's consent, is a discipline ground.", "source": "MCL 339.2411(2)(d)", "domain": "01_licensing-law"}, {"id": "licensing-law-053", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Is bad workmanship alone a statutory discipline ground?", "back": "Yes — workmanship not meeting the standards of the Michigan Residential Code, promulgated under the Stille-DeRossett-Hale Single State Construction Code Act, is a discipline ground (MCL 339.2411(2)(m)).", "audio_front": "Is bad workmanship alone a statutory discipline ground?", "audio_back": "Yes. Workmanship not meeting the standards of the Michigan Residential Code is a discipline ground. M C L 339 point 2411 subsection two m.", "source": "MCL 339.2411(2)(m)", "domain": "01_licensing-law"}, {"id": "licensing-law-054", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Lending your license to an unlicensed operator is covered by which discipline ground?", "back": "MCL 339.2411(2)(j): aiding or abetting an unlicensed person to evade Article 24, allowing one's license to be used by an unlicensed person, or acting as an ostensible licensee for an undisclosed person in control.", "audio_front": "Lending your license to an unlicensed operator is covered by which discipline ground?", "audio_back": "Aiding or abetting an unlicensed person to evade the law, allowing your license to be used by an unlicensed person, or fronting for an undisclosed controller. M C L 339 point 2411 subsection two j.", "source": "MCL 339.2411(2)(j)", "domain": "01_licensing-law"}, {"id": "licensing-law-055", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Can a builder be disciplined for going broke?", "back": "Yes. Becoming insolvent, filing bankruptcy, entering receivership, assigning for the benefit of creditors, failing to satisfy judgments or liens, or failing to pay obligations as due is a discipline ground (MCL 339.2411(2)(l)).", "audio_front": "Can a builder be disciplined for going broke?", "audio_back": "Yes. Insolvency, bankruptcy, receivership, assignment for creditors, unsatisfied judgments or liens, or failing to pay obligations as they come due is a discipline ground.", "source": "MCL 339.2411(2)(l)", "domain": "01_licensing-law"}, {"id": "licensing-law-056", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "In a workmanship complaint, who bears the initial presumption, and what special notice rule limits fines?", "back": "The licensee is presumed innocent until the hearing examiner finds otherwise. After a verifying building inspection report, the department must mail the verified complaint by certified mail within 30 days or it may NOT assess a fine (restitution and suspension remain available) (MCL 339.2411(4)).", "audio_front": "In a workmanship complaint, who bears the initial presumption, and what special notice rule limits fines?", "audio_back": "The licensee is presumed innocent until the hearing examiner finds otherwise. After a verifying building inspection report, the department must mail the verified complaint by certified mail within thirty days, or it cannot assess a fine. Restitution and suspension remain available.", "source": "MCL 339.2411(4)", "domain": "01_licensing-law"}, {"id": "licensing-law-057", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "How does a builder's contractual ADR clause interact with department complaints and lawsuits?", "back": "The licensee may provide a neutral third-party ADR procedure and must give the complainant certified-mail notice at least 30 days before it commences (MCL 339.2411(4)(d)). In court, the complainant's failure to use a contractual ADR procedure is an affirmative defense for the licensee (MCL 339.2412(2)).", "audio_front": "How does a builder's contractual alternative dispute resolution clause interact with department complaints and lawsuits?", "audio_back": "The licensee may provide a neutral third party procedure with at least thirty days certified mail notice before it commences. In court, the complainant's failure to use the contractual procedure is an affirmative defense for the licensee.", "source": "MCL 339.2411(4)(d); 339.2412(2)", "domain": "01_licensing-law"}, {"id": "licensing-law-058", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "List the administrative penalties available under MCL 339.602.", "back": "Limitation on the license; suspension; denial; revocation; administrative fine up to $10,000; censure; probation; and restitution based on proofs (MCL 339.602).", "audio_front": "List the administrative penalties available under M C L 339 point 602.", "audio_back": "Limitation on the license, suspension, denial, revocation, an administrative fine of up to ten thousand dollars, censure, probation, and restitution.", "source": "MCL 339.602", "domain": "01_licensing-law"}, {"id": "licensing-law-059", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Criminal penalty for a FIRST offense of unlicensed residential building?", "back": "Misdemeanor: fine of not less than $5,000 and not more than $25,000, or imprisonment up to 1 year, or both (MCL 339.601(6)(a)).", "audio_front": "What is the criminal penalty for a first offense of unlicensed residential building?", "audio_back": "A misdemeanor, with a fine of not less than five thousand dollars and not more than twenty five thousand dollars, or imprisonment up to one year, or both.", "source": "MCL 339.601(6)(a)", "domain": "01_licensing-law"}, {"id": "licensing-law-060", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Criminal penalty for a SECOND unlicensed-building offense?", "back": "Still a misdemeanor: $5,000–$25,000 fine, or imprisonment up to 2 years, or both (MCL 339.601(6)(b)).", "audio_front": "What is the criminal penalty for a second unlicensed building offense?", "audio_back": "Still a misdemeanor. A fine of five thousand to twenty five thousand dollars, or imprisonment up to two years, or both.", "source": "MCL 339.601(6)(b)", "domain": "01_licensing-law"}, {"id": "licensing-law-061", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Unlicensed building work causes a death. What is the offense level and penalty?", "back": "A FELONY: fine of $5,000–$25,000, or imprisonment up to 4 years, or both (MCL 339.601(6)(c)) — applies to offenses causing death or serious injury.", "audio_front": "Unlicensed building work causes a death. What is the offense level and penalty?", "audio_back": "A felony. A fine of five thousand to twenty five thousand dollars, or imprisonment up to four years, or both. This applies to offenses causing death or serious injury.", "source": "MCL 339.601(6)(c)", "domain": "01_licensing-law"}, {"id": "licensing-law-062", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "TRAP: The generic $500 / 90-day misdemeanor in MCL 339.601(4) — does it apply to unlicensed builders?", "back": "No. Unlicensed residential builders and M&A contractors fall under the harsher builder-specific subsection 339.601(6): $5,000–$25,000 fines and up to 1, 2, or 4 years.", "audio_front": "Trap question. The generic five hundred dollar, ninety day misdemeanor — does it apply to unlicensed builders?", "audio_back": "No. Unlicensed residential builders fall under the harsher builder specific subsection, with five thousand to twenty five thousand dollar fines and up to one, two, or four years.", "source": "MCL 339.601(4),(6)", "domain": "01_licensing-law"}, {"id": "licensing-law-063", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Who can bring a CIVIL action against an unlicensed builder, and for how much?", "back": "A prosecuting attorney or the attorney general; the court SHALL assess a civil fine of $5,000–$25,000, aside from any civil damages or restitution (MCL 339.2412(4)).", "audio_front": "Who can bring a civil action against an unlicensed builder, and for how much?", "audio_back": "A prosecuting attorney or the attorney general. The court shall assess a civil fine of five thousand to twenty five thousand dollars, aside from any damages or restitution.", "source": "MCL 339.2412(4)", "domain": "01_licensing-law"}, {"id": "licensing-law-064", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "An unlicensed builder finishes a $40,000 remodel and the owner refuses to pay. Can the builder sue?", "back": "No. MCL 339.2412(1) bars any action for compensation for work requiring a license unless the person alleges and proves they were licensed DURING the performance of the act or contract.", "audio_front": "An unlicensed builder finishes a forty thousand dollar remodel and the owner refuses to pay. Can the builder sue?", "audio_back": "No. The law bars any action for compensation unless the builder alleges and proves they were licensed during the performance of the work.", "source": "MCL 339.2412(1)", "domain": "01_licensing-law"}, {"id": "licensing-law-065", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Can an unlicensed builder record a construction lien?", "back": "No. A person may not impose or take any action to impose a lien on real property unless licensed during the performance of the act or contract (MCL 339.2412(3)).", "audio_front": "Can an unlicensed builder record a construction lien?", "audio_back": "No. A person may not impose a lien on real property unless they were licensed during the performance of the work. M C L 339 point 2412 subsection three.", "source": "MCL 339.2412(3)", "domain": "01_licensing-law"}, {"id": "licensing-law-066", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "TRAP: What is wrong with citing 'MCL 339.611' for unlicensed-practice penalties?", "back": "MCL 339.611 does not exist. The correct citations are MCL 339.601 (criminal penalties), MCL 339.602 (administrative penalties), and MCL 339.2412(4) (civil fine).", "audio_front": "Trap question. What is wrong with citing M C L 339 point 611 for unlicensed practice penalties?", "audio_back": "That section does not exist. The correct citations are M C L 339 point 601 for criminal penalties, 339 point 602 for administrative penalties, and 339 point 2412 subsection four for the civil fine.", "source": "legislature.mi.gov (339.611 returns error)", "domain": "01_licensing-law"}, {"id": "licensing-law-067", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Besides fines, what remedies exist against unlicensed operators under MCL 339.601?", "back": "Mandatory restitution on a finding of violation (339.601(8)), and injunctive relief for an 'affected person' — who, if successful, recovers actual costs and attorney fees (339.601(9)).", "audio_front": "Besides fines, what remedies exist against unlicensed operators?", "audio_back": "Mandatory restitution on a finding of violation, and injunctive relief for an affected person, who if successful recovers actual costs and attorney fees.", "source": "MCL 339.601(8)-(9)", "domain": "01_licensing-law"}, {"id": "licensing-law-068", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Two salesperson-specific discipline grounds?", "back": "Failing to immediately pay over money received to the builder/contractor under whom the salesperson is licensed (339.2411(2)(i)); and accepting a commission or other consideration from anyone other than that licensee (339.2411(2)(k)).", "audio_front": "Name two salesperson specific discipline grounds.", "audio_back": "Failing to immediately pay over money received to the licensee they work under, and accepting a commission or other consideration from anyone other than that licensee.", "source": "MCL 339.2411(2)(i),(k)", "domain": "01_licensing-law"}, {"id": "licensing-law-069", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "In an M&A contract with lender financing, what document must the contractor furnish to the lender?", "back": "The purchaser's signed completion certificate, executed upon completion of the work — failure is a discipline ground (MCL 339.2411(2)(f)).", "audio_front": "In a maintenance and alteration contract with lender financing, what document must the contractor furnish to the lender?", "audio_back": "The purchaser's signed completion certificate, executed upon completion of the work. Failure is a discipline ground.", "source": "MCL 339.2411(2)(f)", "domain": "01_licensing-law"}, {"id": "licensing-law-070", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "How many questions on the RB exam come from 'Regulatory and Statutory Requirements'?", "back": "13 of the 50 Business & Law questions — the largest B&L category (PSI content outline).", "audio_front": "How many questions on the residential builder exam come from regulatory and statutory requirements?", "audio_back": "Thirteen of the fifty business and law questions. The largest business and law category.", "source": "PSI Candidate Handbook (8/2026)", "domain": "01_licensing-law"}, {"id": "licensing-law-071", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Give the RB exam's vital statistics: questions, split, passing score, time, format.", "back": "160 questions total — 50 Business & Law + 110 Practice/Trade; passing raw score 116 (72.5%); 240 minutes; computer-based; CLOSED BOOK (PSI bulletin).", "audio_front": "Give the residential builder exam's vital statistics. Questions, split, passing score, time, and format.", "audio_back": "One hundred sixty questions total. Fifty business and law, one hundred ten trade. Passing raw score one hundred sixteen, which is seventy two point five percent. Two hundred forty minutes. Computer based and closed book.", "source": "PSI Candidate Handbook (8/2026)", "domain": "01_licensing-law"}, {"id": "licensing-law-072", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Since what date has the RB exam been one combined test, and what does that mean for retakes?", "back": "Since 11/14/2019 the Business & Law and Practice/Trade parts are combined into one exam with a single 116/160 passing score. No separate section passes — repeat candidates retake the full combined exam.", "audio_front": "Since what date has the exam been one combined test, and what does that mean for retakes?", "audio_back": "Since November fourteenth, twenty nineteen. One exam, one passing score of one hundred sixteen out of one hundred sixty. Repeat candidates retake the full combined exam.", "source": "PSI Candidate Handbook (8/2026)", "domain": "01_licensing-law"}, {"id": "licensing-law-073", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Which code edition does the PSI RB exam reference as of August 2026?", "back": "The 2015 Michigan Residential Code — listed in the PSI candidate handbook updated 8/3/2026. Not the 2021 IRC.", "audio_front": "Which code edition does the P S I residential builder exam reference as of August twenty twenty six?", "audio_back": "The twenty fifteen Michigan Residential Code, per the P S I candidate handbook updated August third, twenty twenty six. Not the twenty twenty one I R C.", "source": "PSI Candidate Handbook (8/2026)", "domain": "01_licensing-law"}, {"id": "licensing-law-074", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What are the exam and application fees? (RB exam, retest, application)", "back": "RB exam $117; retest also $117; LARA application fee $195 (individual or company). Registration fees are nonrefundable and valid 1 year.", "audio_front": "What are the exam and application fees for the residential builder?", "audio_back": "The exam is one hundred seventeen dollars, the retest is also one hundred seventeen dollars, and the LARA application fee is one hundred ninety five dollars. Fees are nonrefundable and valid for one year.", "source": "PSI Candidate Handbook; LARA", "domain": "01_licensing-law"}, {"id": "licensing-law-075", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "M&A contractor exam fees by portions?", "back": "$70 for one portion, $99 for two, $114 for three (first-time and retest alike). Max two trade exams per registration; 135 minutes for one trade combo, 270 for two.", "audio_front": "What are the M and A contractor exam fees by portions?", "audio_back": "Seventy dollars for one portion, ninety nine for two, one hundred fourteen for three. Maximum two trade exams per registration. One hundred thirty five minutes for one trade, two hundred seventy for two.", "source": "PSI Candidate Handbook (8/2026)", "domain": "01_licensing-law"}, {"id": "licensing-law-076", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Describe the salesperson exam and its prerequisites.", "back": "45 questions, passing raw score 32 (72%), 90 minutes, $85, closed book. No prelicensure education requirement, and salesperson candidates register directly with PSI without applying to the state first.", "audio_front": "Describe the salesperson exam and its prerequisites.", "audio_back": "Forty five questions. Passing score thirty two, which is seventy two percent. Ninety minutes. Eighty five dollars. Closed book. There is no prelicensure education requirement, and salesperson candidates register directly with P S I without applying to the state first.", "source": "PSI Candidate Handbook (8/2026)", "domain": "01_licensing-law"}, {"id": "licensing-law-077", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What is the correct sequence for becoming a licensed RB?", "back": "1) Complete the 60-hour prelicensure; 2) Apply to LARA (michigan.gov/bcc) with the $195 fee; 3) After LARA approval, register and schedule with PSI ($117); 4) Pass 116/160; 5) PSI notifies the state electronically and the license is issued. All within 1 year of the application.", "audio_front": "What is the correct sequence for becoming a licensed residential builder?", "audio_back": "First, complete the sixty hour prelicensure. Second, apply to LARA with the one hundred ninety five dollar fee. Third, after approval, register and schedule with P S I for one hundred seventeen dollars. Fourth, pass with one hundred sixteen out of one hundred sixty. P S I then notifies the state and the license is issued. All within one year of the application.", "source": "PSI Candidate Handbook; MCL 339.409(3)", "domain": "01_licensing-law"}, {"id": "licensing-law-078", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "PSI cancellation and lateness rules?", "back": "Cancel or reschedule at least 2 days before the appointment or forfeit the fee. Arriving after the scheduled start time also forfeits the fee. Arrive 30 minutes early; bring one valid signature-bearing photo ID matching your registered legal name.", "audio_front": "What are the P S I cancellation and lateness rules?", "audio_back": "Cancel or reschedule at least two days before the appointment or forfeit the fee. Arriving after the start time also forfeits the fee. Arrive thirty minutes early with one valid photo I D matching your registered legal name.", "source": "PSI Candidate Handbook (8/2026)", "domain": "01_licensing-law"}, {"id": "licensing-law-079", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What calculators are allowed at the PSI exam?", "back": "Silent, battery-operated, non-printing calculators without an alphabet keyboard. Measurement-converting construction calculators (Construction Master I/II, Handyman, Measure Maker) are NOT allowed.", "audio_front": "What calculators are allowed at the P S I exam?", "audio_back": "Silent, battery operated, non printing calculators without an alphabet keyboard. Measurement converting construction calculators such as the Construction Master are not allowed.", "source": "PSI Candidate Handbook (8/2026)", "domain": "01_licensing-law"}, {"id": "licensing-law-080", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What score information do you get after the exam, and can you review your test?", "back": "Pass = the word PASS only (no number). Fail = a score for each major content section, to guide re-study. No post-examination review is authorized. Up to 10 unscored experimental questions may appear.", "audio_front": "What score information do you get after the exam, and can you review your test?", "audio_back": "If you pass, you get only the word pass, with no number. If you fail, you get a score for each major section. No post examination review is allowed. Up to ten unscored experimental questions may appear.", "source": "PSI Candidate Handbook (8/2026)", "domain": "01_licensing-law"}, {"id": "licensing-law-081", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Breakdown of the 50 B&L questions by category?", "back": "Regulatory and Statutory Requirements 13; Insurance, Bonds and Liens 11; Contracts 7; Project Management and Administration 6; Accounting and Finance 6; Types of Business Organization 4; Personnel 2; Estimating 1.", "audio_front": "What is the breakdown of the fifty business and law questions by category?", "audio_back": "Regulatory and statutory requirements, thirteen. Insurance, bonds and liens, eleven. Contracts, seven. Project management and administration, six. Accounting and finance, six. Types of business organization, four. Personnel, two. Estimating, one.", "source": "PSI Candidate Handbook (8/2026)", "domain": "01_licensing-law"}, {"id": "licensing-law-082", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Were there any 2026 amendments to Article 24?", "back": "No. As of MCL complete through PA 91 of 2026, the newest Article 24 amendments are 2020 PA 341 (definitions), 2018 PA 527 (sec. 2404), and 2016 PA 412. Board membership was reorganized by E.R.O. 2024-2 (MCL 16.735).", "audio_front": "Were there any twenty twenty six amendments to Article twenty four?", "audio_back": "No. As of Public Act ninety one of twenty twenty six, the newest amendments are from twenty twenty, twenty eighteen, and twenty sixteen. Board membership was reorganized by executive reorganization order twenty twenty four dash two.", "source": "legislature.mi.gov (verified 2026-08-17)", "domain": "01_licensing-law"}, {"id": "licensing-law-083", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "TRAP: administrative fine vs criminal fine vs civil fine — match the amounts.", "back": "Administrative (LARA, MCL 339.602(e)): up to $10,000. Criminal (court, 339.601(6)): $5,000–$25,000 plus jail. Civil (AG/prosecutor suit, 339.2412(4)): $5,000–$25,000. Don't swap the $10,000 cap with the $25,000 max.", "audio_front": "Trap. Administrative fine versus criminal fine versus civil fine. Match the amounts.", "audio_back": "Administrative fine by LARA, up to ten thousand dollars. Criminal fine by a court, five thousand to twenty five thousand plus jail. Civil fine in a suit by the attorney general or prosecutor, five thousand to twenty five thousand.", "source": "MCL 339.602(e); 339.601(6); 339.2412(4)", "domain": "01_licensing-law"}, {"id": "licensing-law-084", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "A builder violates the asbestos abatement licensing act. Can LARA touch their builder license?", "back": "Yes. The department reviews such notices and may suspend or revoke the license for a KNOWING violation of the Asbestos Abatement Contractors Licensing Act, 1986 PA 135 (MCL 339.2411(3)).", "audio_front": "A builder violates the asbestos abatement licensing act. Can LARA touch their builder license?", "audio_back": "Yes. The department may suspend or revoke the license for a knowing violation of the Asbestos Abatement Contractors Licensing Act.", "source": "MCL 339.2411(3)", "domain": "01_licensing-law"}, {"id": "licensing-law-085", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "What happens to a builder's OTHER Article 24 licenses when one is suspended, revoked, or denied?", "back": "Every other license issued or applied for under Article 24 is also suspended, revoked, or denied — and the same chain runs from an entity's license to its qualifying officer's licenses (MCL 339.2405(3)).", "audio_front": "What happens to a builder's other Article twenty four licenses when one is suspended, revoked, or denied?", "audio_back": "Every other license issued or applied for under Article twenty four is also suspended, revoked, or denied. The same chain runs between an entity and its qualifying officer.", "source": "MCL 339.2405(3)", "domain": "01_licensing-law"}, {"id": "licensing-law-086", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "Failure to deliver what document set to the purchaser is a discipline ground?", "back": "The ENTIRE agreement of the parties, including any finance or other charge, for contracts involving repair/alteration/improvement/demolition of a residential structure, garages, concrete, or prefab housing (MCL 339.2411(2)(h)).", "audio_front": "Failure to deliver what document set to the purchaser is a discipline ground?", "audio_back": "The entire agreement of the parties, including any finance or other charges, for residential repair, alteration, demolition, garage, concrete, or prefab housing contracts.", "source": "MCL 339.2411(2)(h)", "domain": "01_licensing-law"}, {"id": "licensing-law-087", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "A willful violation of state or local building laws — discipline ground?", "back": "Yes. MCL 339.2411(2)(e): a willful violation of the building laws of the state or of a political subdivision subjects the licensee to Article 6 penalties.", "audio_front": "Is a willful violation of state or local building laws a discipline ground?", "audio_back": "Yes. A willful violation of the building laws of the state or of a political subdivision subjects the licensee to article six penalties.", "source": "MCL 339.2411(2)(e)", "domain": "01_licensing-law"}, {"id": "licensing-law-088", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "NUMBER DRILL: 18 months / 10 days / 30 days / 5 years — match each to its licensing-law rule.", "back": "18 months = complaint filing window (2411(1)). 10 days = notify department of change in control (2411(2)(g)). 30 days = certified-mail verified complaint deadline after inspection report, and ADR commencement notice (2411(4)). 5 years = retention of CE documentation (2404(7)).", "audio_front": "Number drill. Eighteen months, ten days, thirty days, five years. Match each to its licensing law rule.", "audio_back": "Eighteen months is the complaint filing window. Ten days to notify the department of a change in control. Thirty days for the certified mail verified complaint and for A D R notice. Five years to retain continuing education documentation.", "source": "MCL 339.2411; 339.2404(7)", "domain": "01_licensing-law"}, {"id": "licensing-law-089", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "NUMBER DRILL: $600 / $195 / $117 / $185 / $85 / $10,000 / $25,000 — match each amount.", "back": "$600 = licensure exemption cap (2403(f)). $195 = LARA application fee. $117 = RB exam fee. $185 = relicensure fee, expired under 3 years. $85 = salesperson exam. $10,000 = max administrative fine (339.602). $25,000 = max criminal/civil fine (339.601(6), 339.2412(4)).", "audio_front": "Number drill. Six hundred, one ninety five, one seventeen, one eighty five, eighty five, ten thousand, twenty five thousand. Match each amount.", "audio_back": "Six hundred dollars is the licensure exemption cap. One hundred ninety five is the application fee. One hundred seventeen is the builder exam fee. One hundred eighty five is relicensure when expired under three years. Eighty five is the salesperson exam. Ten thousand is the maximum administrative fine. Twenty five thousand is the maximum criminal or civil fine.", "source": "MCL 339.2403(f); 339.602; 339.601(6); PSI/LARA", "domain": "01_licensing-law"}, {"id": "licensing-law-090", "deck": "rb", "section": "bl", "category": "Regulatory and Statutory Requirements", "front": "SCENARIO: A licensed RB's kitchen remodel fails to meet 2015 MRC standards but passes no other complaint ground. Homeowner complains 12 months after completion. Valid complaint?", "back": "Yes. Workmanship below the Michigan Residential Code is itself a discipline ground (2411(2)(m)), and 12 months is inside the 18-month window (2411(1)). The special workmanship procedure of 2411(4) applies — presumption of innocence, inspection report, 30-day certified-mail verified complaint.", "audio_front": "Scenario. A licensed builder's kitchen remodel fails to meet the twenty fifteen Michigan Residential Code. The homeowner complains twelve months after completion. Valid complaint?", "audio_back": "Yes. Workmanship below the Michigan Residential Code is itself a discipline ground, and twelve months is inside the eighteen month window. The special workmanship procedure applies, with a presumption of innocence and the thirty day certified mail rule.", "source": "MCL 339.2411(1),(2)(m),(4)", "domain": "01_licensing-law"}, {"id": "liens-insurance-bonds-001", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What is the citation for the Michigan Construction Lien Act?", "back": "MCL 570.1101 et seq. (Act 497 of 1980, effective January 1, 1982).", "audio_front": "What is the citation for the Michigan Construction Lien Act?", "audio_back": "M C L 570 point 1101 and following, Act 497 of 1980, effective January first, 1982.", "source": "MCL 570.1101", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-002", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Who has lien rights under the Construction Lien Act?", "back": "Contractors, subcontractors, suppliers, and laborers who provide an improvement to real property (MCL 570.1107(1)).", "audio_front": "Who has lien rights under the Construction Lien Act?", "audio_back": "Contractors, subcontractors, suppliers, and laborers who provide an improvement to real property, under M C L 570 point 1107.", "source": "MCL 570.1107(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-003", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What is the maximum amount of a single construction lien?", "back": "The claimant's contract price less payments made on the contract — a lien can never exceed the unpaid contract balance (MCL 570.1107(1)).", "audio_front": "What is the maximum amount of a single construction lien?", "audio_back": "The claimant's contract price minus payments already made. A lien can never exceed the unpaid contract balance, under M C L 570 point 1107.", "source": "MCL 570.1107(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-004", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What caps the TOTAL of all liens against an owner (the no-double-payment rule)?", "back": "The sum of all construction liens cannot exceed what the owner agreed to pay the contractor, less payments made under a sworn statement or lien waiver (MCL 570.1107(6)).", "audio_front": "What caps the total of all liens against an owner? The no double payment rule.", "audio_back": "The sum of all liens cannot exceed what the owner agreed to pay the contractor, minus payments made under a sworn statement or lien waiver. M C L 570 point 1107 subsection 6.", "source": "MCL 570.1107(6)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-005", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Who prepares the Notice of Commencement on a RESIDENTIAL project, and when?", "back": "The owner or lessee prepares it, but only upon a written (certified-mail) request from a contractor, sub, supplier, or laborer — and must return it within 10 days of the request's postmark (MCL 570.1108a).", "audio_front": "Who prepares the Notice of Commencement on a residential project, and when?", "audio_back": "The owner or lessee prepares it, but only after a written certified mail request from a contractor, sub, supplier, or laborer, and must return it within ten days of the request's postmark. M C L 570 point 1108 a.", "source": "MCL 570.1108a", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-006", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Is a residential Notice of Commencement recorded with the register of deeds?", "back": "No. Residential (MCL 570.1108a) is provided on request and posted at the site if the owner doesn't live there. On COMMERCIAL projects (MCL 570.1108) the owner records it before work begins.", "audio_front": "Is a residential Notice of Commencement recorded with the register of deeds?", "audio_back": "No. The residential notice is provided on request and posted at the site if the owner does not live there. On commercial projects, under M C L 570 point 1108, the owner records it before work begins.", "source": "MCL 570.1108 / 570.1108a", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-007", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What happens if a homeowner fails to return the Notice of Commencement within 10 days of a request?", "back": "The homeowner may have to pay the expenses the requester incurs in getting the information (MCL 570.1108a warning-to-homeowner provisions).", "audio_front": "What happens if a homeowner fails to return the Notice of Commencement within ten days of a request?", "audio_back": "The homeowner may have to pay the expenses the requesting party incurs in getting the information, under M C L 570 point 1108 a.", "source": "MCL 570.1108a", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-008", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What document must be attached to a residential Notice of Commencement?", "back": "A blank, easily detachable Notice of Furnishing form (MCL 570.1108a(3)).", "audio_front": "What document must be attached to a residential Notice of Commencement?", "audio_back": "A blank, easily detachable Notice of Furnishing form. M C L 570 point 1108 a subsection 3.", "source": "MCL 570.1108a(3)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-009", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Within how many days of FIRST furnishing must a subcontractor or supplier serve a Notice of Furnishing?", "back": "20 days after furnishing the first labor or material (MCL 570.1109(1)).", "audio_front": "Within how many days of first furnishing must a subcontractor or supplier serve a Notice of Furnishing?", "audio_back": "Twenty days after furnishing the first labor or material. M C L 570 point 1109.", "source": "MCL 570.1109(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-010", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "On whom is the Notice of Furnishing served, and how?", "back": "On the designee AND the general contractor named in the Notice of Commencement (owner/lessee if no designee), personally or by certified mail. Certified-mail service is complete on mailing (MCL 570.1109(1)).", "audio_front": "On whom is the Notice of Furnishing served, and how?", "audio_back": "On the designee and the general contractor named in the Notice of Commencement, or the owner if there is no designee. Served personally or by certified mail, and certified mail service is complete on mailing.", "source": "MCL 570.1109(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-011", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Does a general contractor need to serve a Notice of Furnishing?", "back": "No. A contractor in direct contract with the owner or lessee is expressly not required to provide one (MCL 570.1109(1)).", "audio_front": "Does a general contractor need to serve a Notice of Furnishing?", "audio_back": "No. A contractor in direct contract with the owner is expressly not required to provide one, under M C L 570 point 1109.", "source": "MCL 570.1109(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-012", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What is the laborer's Notice of Furnishing deadline for unpaid WAGES?", "back": "30 days after the wages were contractually due but not paid (MCL 570.1109(2)).", "audio_front": "What is the laborer's Notice of Furnishing deadline for unpaid wages?", "audio_back": "Thirty days after the wages were contractually due but not paid. M C L 570 point 1109 subsection 2.", "source": "MCL 570.1109(2)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-013", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What is the laborer's notice deadline for unpaid FRINGE BENEFITS or withholdings?", "back": "By the 5th day of the second month following the month in which the fringes/withholdings were due but unpaid (MCL 570.1109(3)).", "audio_front": "What is the laborer's notice deadline for unpaid fringe benefits or withholdings?", "audio_back": "By the fifth day of the second month following the month in which the fringe benefits or withholdings were due but unpaid. M C L 570 point 1109 subsection 3.", "source": "MCL 570.1109(3)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-014", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "A sub serves its Notice of Furnishing LATE. What is the effect on its lien?", "back": "Work furnished AFTER the notice is fully protected. Work furnished BEFORE is also protected, except to the extent the owner already paid the contractor for it under a sworn statement or lien waiver (MCL 570.1109(5)-(6)). The lien is not automatically void.", "audio_front": "A sub serves its Notice of Furnishing late. What is the effect on its lien?", "audio_back": "Work furnished after the notice is fully protected. Work furnished before is also protected, except to the extent the owner already paid the contractor for it under a sworn statement or lien waiver. The lien is not automatically void.", "source": "MCL 570.1109(5)-(6)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-015", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Does the late-notice grace rule of MCL 570.1109(6) apply to laborers?", "back": "No. Subsection 6 expressly does not apply to a laborer — a laborer who misses the wage notice deadline loses the lien for those wages (MCL 570.1109(7)).", "audio_front": "Does the late notice grace rule apply to laborers?", "audio_back": "No. A laborer who misses the wage notice deadline loses the lien for those wages. M C L 570 point 1109 subsections 6 and 7.", "source": "MCL 570.1109(6)-(7)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-016", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "When must a CONTRACTOR give the owner a sworn statement?", "back": "When payment is due from the owner, when the contractor requests payment, or when the owner demands one (MCL 570.1110(1)).", "audio_front": "When must a contractor give the owner a sworn statement?", "audio_back": "When payment is due from the owner, when the contractor requests payment, or whenever the owner demands one. M C L 570 point 1110.", "source": "MCL 570.1110(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-017", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What does a sworn statement list?", "back": "Every subcontractor and supplier the issuer contracted with, plus unpaid laborers — with contract price, amount paid, and amount owing for each. It is notarized (MCL 570.1110(4)).", "audio_front": "What does a sworn statement list?", "audio_back": "Every subcontractor and supplier the issuer contracted with, plus unpaid laborers, showing contract price, amount paid, and amount owing for each. It is notarized.", "source": "MCL 570.1110(4)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-018", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Why does the sworn statement protect the owner?", "back": "The owner may rely on it to withhold amounts due to subs/suppliers/laborers or pay them directly, and payments made in reliance reduce the owner's lien exposure (MCL 570.1110).", "audio_front": "Why does the sworn statement protect the owner?", "audio_back": "The owner may rely on it to withhold amounts owed to subs and suppliers, or pay them directly, and payments made in reliance on it reduce the owner's lien exposure.", "source": "MCL 570.1110", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-019", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What is the consequence of giving a FALSE sworn statement with intent to defraud?", "back": "It is a crime under MCL 570.1110, plus civil fraud exposure to the owner and continuing liability to the unpaid subs.", "audio_front": "What is the consequence of giving a false sworn statement with intent to defraud?", "audio_back": "It is a crime under M C L 570 point 1110, plus civil fraud exposure to the owner and continuing liability to the unpaid subs.", "source": "MCL 570.1110", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-020", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Deadline to RECORD a claim of lien?", "back": "Within 90 days after the claimant's LAST furnishing of labor or material, recorded with the register of deeds of the county where the property is located (MCL 570.1111(1)). Absolute — no extensions.", "audio_front": "What is the deadline to record a claim of lien?", "audio_back": "Within ninety days after the claimant's last furnishing of labor or material, recorded with the register of deeds of the county where the property is located. The deadline is absolute.", "source": "MCL 570.1111(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-021", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Does warranty or punch-list work restart the 90-day lien clock?", "back": "No. The 90 days runs from the last furnishing under the contract; courtesy callbacks and warranty trips do not extend it.", "audio_front": "Does warranty or punch list work restart the ninety day lien clock?", "audio_back": "No. The ninety days runs from the last furnishing under the contract. Courtesy callbacks and warranty trips do not extend it.", "source": "MCL 570.1111(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-022", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "After recording a claim of lien, what service is required and by when?", "back": "Within 15 days after recording, serve a copy of the claim of lien (and any recorded proof of service) on the designee — or the owner/lessee if no designee — personally or by certified mail (MCL 570.1111(5)).", "audio_front": "After recording a claim of lien, what service is required and by when?", "audio_back": "Within fifteen days after recording, serve a copy of the claim of lien on the designee, or the owner if there is no designee, personally or by certified mail. M C L 570 point 1111 subsection 5.", "source": "MCL 570.1111(5)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-023", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What must a subcontractor's or supplier's claim of lien have attached?", "back": "Proof of service of its Notice of Furnishing (MCL 570.1111(4)).", "audio_front": "What must a subcontractor's or supplier's claim of lien have attached?", "audio_back": "Proof of service of its Notice of Furnishing. M C L 570 point 1111 subsection 4.", "source": "MCL 570.1111(4)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-024", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "How long do you have to file a lien FORECLOSURE action, and in what court?", "back": "No later than 1 year after the claim of lien was recorded, in the circuit court for the county where the property is located (MCL 570.1117(1), 570.1118(1)).", "audio_front": "How long do you have to file a lien foreclosure action, and in what court?", "audio_back": "No later than one year after the claim of lien was recorded, in the circuit court for the county where the property is located. M C L 570 point 1117 and 1118.", "source": "MCL 570.1117(1); 570.1118(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-025", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What must be recorded when you file the foreclosure action?", "back": "A notice of lis pendens, with the register of deeds for the county where the property is located (MCL 570.1117(2)).", "audio_front": "What must be recorded when you file the foreclosure action?", "audio_back": "A notice of lis pendens, recorded with the register of deeds for the county where the property is located. M C L 570 point 1117 subsection 2.", "source": "MCL 570.1117(2)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-026", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Can a lien claimant recover attorney fees in a foreclosure action?", "back": "Yes — the court MAY award reasonable attorney fees to a prevailing lien claimant, and to a prevailing defendant if the claimant's action was vexatious (MCL 570.1118(2)).", "audio_front": "Can a lien claimant recover attorney fees in a foreclosure action?", "audio_back": "Yes. The court may award reasonable attorney fees to a prevailing lien claimant, and to a prevailing defendant if the action was vexatious. M C L 570 point 1118 subsection 2.", "source": "MCL 570.1118(2)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-027", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What happens to a lien if no foreclosure suit is filed within 1 year of recording?", "back": "The lien expires and becomes unenforceable — the lien remedy is lost (MCL 570.1117(1)).", "audio_front": "What happens to a lien if no foreclosure suit is filed within one year of recording?", "audio_back": "The lien expires and becomes unenforceable. The lien remedy is lost.", "source": "MCL 570.1117(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-028", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What contract form is required for a contractor to have lien rights on a RESIDENTIAL structure?", "back": "A WRITTEN contract with the owner/lessee, with written amendments, containing the statutory licensure statement and the contractor's license number if a license is required (MCL 570.1114). Applies at any dollar amount.", "audio_front": "What contract form is required for a contractor to have lien rights on a residential structure?", "audio_back": "A written contract with the owner, with written amendments, containing the statutory licensure statement and the contractor's license number if a license is required. M C L 570 point 1114. It applies at any dollar amount.", "source": "MCL 570.1114", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-029", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "An unlicensed builder records a lien on a home. What exposure does he face?", "back": "The owner or any affected person can sue to discharge the lien, and the unlicensed recorder is liable for ALL resulting damages including actual costs and attorney fees (MCL 570.1114a(2)).", "audio_front": "An unlicensed builder records a lien on a home. What exposure does he face?", "audio_back": "The owner or any affected person can sue to discharge the lien, and the unlicensed recorder is liable for all resulting damages, including actual costs and attorney fees. M C L 570 point 1114 a.", "source": "MCL 570.1114a(2)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-030", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "In a suit on work requiring a license, who must prove licensure?", "back": "The plaintiff contractor must allege in the complaint and carries the burden of proving that he or she was properly licensed (MCL 570.1114a(3)).", "audio_front": "In a lawsuit on work requiring a license, who must prove licensure?", "audio_back": "The plaintiff contractor must allege in the complaint, and has the burden of proving, that he or she was properly licensed. M C L 570 point 1114 a subsection 3.", "source": "MCL 570.1114a(3)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-031", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Under Stokes v. Millen Roofing Co., what can an unlicensed residential contractor recover?", "back": "Nothing — no contract enforcement, no quantum meruit recovery, and no lien rights on residential work.", "audio_front": "Under Stokes versus Millen Roofing Company, what can an unlicensed residential contractor recover?", "audio_back": "Nothing. No contract enforcement, no quantum meruit recovery, and no lien rights on residential work.", "source": "Stokes v Millen Roofing Co (Mich 2002); MCL 570.1114", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-032", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "A licensed electrician without an RB license works on a home and isn't paid. Lien rights?", "back": "Yes. Electricians, plumbers, and mechanical contractors are licensed under their own trade acts; the trade license satisfies MCL 570.1114's licensure requirement.", "audio_front": "A licensed electrician without a residential builder license works on a home and is not paid. Does the electrician have lien rights?", "audio_back": "Yes. Electricians, plumbers, and mechanical contractors are licensed under their own trade acts, and that trade license satisfies the lien statute's licensure requirement.", "source": "MCL 570.1114", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-033", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "How many statutory lien waiver types exist, and what are they?", "back": "Four: full unconditional, full conditional, partial unconditional, partial conditional (MCL 570.1115).", "audio_front": "How many statutory lien waiver types exist, and what are they?", "audio_back": "Four. Full unconditional, full conditional, partial unconditional, and partial conditional. M C L 570 point 1115.", "source": "MCL 570.1115", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-034", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "When is a CONDITIONAL lien waiver effective?", "back": "Only upon actual payment of the amount stated in the waiver (MCL 570.1115(4)). Unconditional waivers are effective immediately on signing.", "audio_front": "When is a conditional lien waiver effective?", "audio_back": "Only upon actual payment of the amount stated in the waiver. Unconditional waivers are effective immediately on signing.", "source": "MCL 570.1115(4)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-035", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Is a contract clause waiving lien rights in advance of work enforceable?", "back": "No. An advance waiver required as part of the contract is contrary to public policy and invalid, except to the extent payment was actually made (MCL 570.1115(1)).", "audio_front": "Is a contract clause waiving lien rights in advance of work enforceable?", "audio_back": "No. An advance waiver required as part of the contract is contrary to public policy and invalid, except to the extent payment was actually made. M C L 570 point 1115 subsection 1.", "source": "MCL 570.1115(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-036", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Does accepting a promissory note waive lien rights?", "back": "No. Acceptance of a promissory note or other evidence of indebtedness does not by itself waive or discharge lien rights (MCL 570.1115(1)).", "audio_front": "Does accepting a promissory note waive lien rights?", "audio_back": "No. Accepting a promissory note or other evidence of debt does not by itself waive or discharge lien rights.", "source": "MCL 570.1115(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-037", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "A GC hands the homeowner a lien waiver signed by a sub who filed a Notice of Furnishing. Can the owner rely on it?", "back": "Not without first verifying its authenticity with the sub — in writing, by phone, or personally (MCL 570.1115(7), residential rule).", "audio_front": "A general contractor hands the homeowner a lien waiver signed by a sub who filed a Notice of Furnishing. Can the owner rely on it?", "audio_back": "Not without first verifying its authenticity with the sub, either in writing, by telephone, or in person. M C L 570 point 1115 subsection 7.", "source": "MCL 570.1115(7)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-038", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "After FULL payment, what waiver must a lien claimant provide?", "back": "A full unconditional waiver of lien (MCL 570.1115(2)). After partial payment, a partial unconditional waiver on request (MCL 570.1115(3)).", "audio_front": "After full payment, what waiver must a lien claimant provide?", "audio_back": "A full unconditional waiver of lien. After partial payment, a partial unconditional waiver if the owner requests it.", "source": "MCL 570.1115(2)-(3)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-039", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What warning is printed on the statutory waiver forms?", "back": "\"DO NOT SIGN BLANK OR INCOMPLETE FORMS. RETAIN A COPY.\" (MCL 570.1115(9)).", "audio_front": "What warning is printed on the statutory waiver forms?", "audio_back": "Do not sign blank or incomplete forms. Retain a copy.", "source": "MCL 570.1115(9)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-040", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What is the current status of the Homeowner Construction Lien Recovery Fund?", "back": "ABOLISHED. MCL 570.1201-.1207 were repealed by 2010 PA 147, effective August 23, 2010. Any answer treating the Fund as a current remedy is a trap.", "audio_front": "What is the current status of the Homeowner Construction Lien Recovery Fund?", "audio_back": "Abolished. The fund sections were repealed by Public Act 147 of 2010, effective August twenty third, 2010. Any answer treating the fund as a current remedy is a trap.", "source": "MCL 570.1201 (repealed, 2010 PA 147)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-041", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "TRAP: 'Subs must serve a Notice of Furnishing within 30 days of first furnishing.' True or false?", "back": "False. Subs and suppliers get 20 days from first furnishing. 30 days is the LABORER deadline, measured from unpaid wages — not from first furnishing (MCL 570.1109).", "audio_front": "Trap check. Subs must serve a Notice of Furnishing within thirty days of first furnishing. True or false?", "audio_back": "False. Subs and suppliers get twenty days from first furnishing. Thirty days is the laborer deadline, measured from unpaid wages, not from first furnishing.", "source": "MCL 570.1109(1)-(2)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-042", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "TRAP: 'A claim of lien is filed with the circuit court.' True or false?", "back": "False. The claim of lien is RECORDED with the county register of deeds. The circuit court is where the FORECLOSURE action goes, within 1 year (MCL 570.1111(1), 570.1118(1)).", "audio_front": "Trap check. A claim of lien is filed with the circuit court. True or false?", "audio_back": "False. The claim of lien is recorded with the county register of deeds. The circuit court is where the foreclosure action goes, within one year.", "source": "MCL 570.1111(1); 570.1118(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-043", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "TRAP: 'The 90 days runs from substantial completion of the project.' True or false?", "back": "False. It runs from THAT CLAIMANT'S last furnishing of labor or material under its contract — each claimant has its own clock (MCL 570.1111(1)).", "audio_front": "Trap check. The ninety days runs from substantial completion of the project. True or false?", "audio_back": "False. It runs from that claimant's own last furnishing of labor or material under its contract. Each claimant has its own clock.", "source": "MCL 570.1111(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-044", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "A sub last furnished material on March 1. What is its lien-recording deadline?", "back": "May 30 — 90 days after March 1. (March has 30 remaining days, April 30, then 30 more days into May.)", "audio_front": "A sub last furnished material on March first. What is its lien recording deadline?", "audio_back": "May thirtieth. Ninety days after March first.", "source": "MCL 570.1111(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-045", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "A lien is recorded June 1, 2026. Last day to start foreclosure?", "back": "June 1, 2027 — one year after the recording date (MCL 570.1117(1)).", "audio_front": "A lien is recorded June first, 2026. What is the last day to start foreclosure?", "audio_back": "June first, 2027. One year after the recording date.", "source": "MCL 570.1117(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-046", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What does BUILDERS RISK insurance cover?", "back": "First-party property coverage on the structure under construction plus materials on site, in transit, or in storage — fire, wind, theft — until the project is complete. Not liability, not employee injury, not tools.", "audio_front": "What does builders risk insurance cover?", "audio_back": "First party property coverage on the structure under construction, plus materials on site, in transit, or in storage, against perils like fire, wind, and theft, until the project is complete. It does not cover liability, employee injury, or tools.", "source": "Industry standard (builders risk)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-047", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What does COMMERCIAL GENERAL LIABILITY (CGL) insurance cover?", "back": "Third-party bodily injury and property damage arising from your operations or completed operations. It excludes your own defective work product, employee injuries (workers comp), and autos.", "audio_front": "What does commercial general liability insurance cover?", "audio_back": "Third party bodily injury and property damage arising from your operations or completed operations. It excludes your own defective work product, employee injuries, and autos.", "source": "Industry standard (CGL)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-048", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "A visitor trips over your ladder and breaks an arm. Which policy responds?", "back": "CGL — third-party bodily injury from ongoing operations. Not builders risk (property) and not workers comp (visitor is not an employee).", "audio_front": "A visitor trips over your ladder and breaks an arm. Which policy responds?", "audio_back": "Commercial general liability. That is third party bodily injury from ongoing operations. Not builders risk, and not workers comp, because the visitor is not an employee.", "source": "Industry standard (CGL)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-049", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Fire destroys a half-built house and the lumber stacked on site. Which policy responds?", "back": "Builders risk — first-party coverage on the structure under construction and materials on site.", "audio_front": "Fire destroys a half built house and the lumber stacked on site. Which policy responds?", "audio_back": "Builders risk. First party coverage on the structure under construction and the materials on site.", "source": "Industry standard (builders risk)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-050", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Your carpenter cuts his hand on the job. Which coverage responds?", "back": "Workers compensation — statutory no-fault coverage for employee injury. It is the employee's exclusive remedy against the employer.", "audio_front": "Your carpenter cuts his hand on the job. Which coverage responds?", "audio_back": "Workers compensation. Statutory no fault coverage for employee injury, and generally the employee's exclusive remedy against the employer.", "source": "MCL 418.101 et seq.", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-051", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "When is a Michigan private employer REQUIRED to carry workers comp?", "back": "If it regularly employs 3 or more employees at one time, OR fewer than 3 if at least 1 employee has worked 35+ hours per week for 13 or more weeks during the preceding 52 weeks (MCL 418.115(a)-(b)).", "audio_front": "When is a Michigan private employer required to carry workers compensation insurance?", "audio_back": "If it regularly employs three or more employees at one time, or fewer than three if at least one employee has worked thirty five or more hours per week for thirteen or more weeks during the preceding fifty two weeks. M C L 418 point 115.", "source": "MCL 418.115(a)-(b)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-052", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "A builder has 1 full-time employee (40 hrs/wk, employed 6 months). Workers comp required?", "back": "Yes. One employee at 35+ hours per week for 13+ weeks in the preceding 52 triggers mandatory coverage (MCL 418.115(b)).", "audio_front": "A builder has one full time employee working forty hours a week for the last six months. Is workers comp required?", "audio_back": "Yes. One employee at thirty five or more hours per week for thirteen or more weeks in the preceding fifty two triggers mandatory coverage.", "source": "MCL 418.115(b)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-053", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "A GC hires an uninsured sub whose worker is injured. Who pays comp benefits?", "back": "The GC (principal). Under MCL 418.171, a principal is liable for workers comp to the employees of an uninsured contractor or sub as if it employed them directly.", "audio_front": "A general contractor hires an uninsured sub whose worker is injured. Who pays the workers comp benefits?", "audio_back": "The general contractor, as principal. Under M C L 418 point 171, a principal is liable for comp to the employees of an uninsured contractor or sub, as if it employed them directly.", "source": "MCL 418.171", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-054", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What document should a GC collect from every sub before work starts, and why?", "back": "A certificate of insurance proving workers comp and CGL coverage — it protects the GC from statutory comp liability under MCL 418.171 and from uncovered liability claims. Watch expiration dates.", "audio_front": "What document should a general contractor collect from every sub before work starts, and why?", "audio_back": "A certificate of insurance proving workers comp and general liability coverage. It protects the general contractor from statutory comp liability and uncovered claims. Watch the expiration dates.", "source": "MCL 418.171; industry standard", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-055", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What does an ADDITIONAL INSURED endorsement do?", "back": "It extends a sub's CGL policy to also protect the GC or owner for liability arising out of the sub's work.", "audio_front": "What does an additional insured endorsement do?", "audio_back": "It extends a sub's general liability policy to also protect the general contractor or owner for liability arising out of the sub's work.", "source": "Industry standard (CGL endorsements)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-056", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Which policy covers a contractor's stolen tools and equipment?", "back": "An inland marine / contractor's equipment floater — NOT builders risk (structure and materials) and NOT CGL (third-party liability).", "audio_front": "Which policy covers a contractor's stolen tools and equipment?", "audio_back": "An inland marine policy, also called a contractor's equipment floater. Not builders risk, and not general liability.", "source": "Industry standard (inland marine)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-057", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Who are the THREE parties to a surety bond?", "back": "Principal (the contractor whose performance is guaranteed), obligee (the protected party — owner or government), and surety (the company guaranteeing performance).", "audio_front": "Who are the three parties to a surety bond?", "audio_back": "The principal, which is the contractor whose performance is guaranteed. The obligee, which is the protected party, usually the owner or a government unit. And the surety, the company giving the guarantee.", "source": "Industry standard (suretyship)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-058", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "How does a surety bond differ from insurance?", "back": "Insurance transfers risk and expects losses; a bond is a credit guarantee for the OBLIGEE's benefit — if the surety pays, the principal must indemnify (repay) the surety.", "audio_front": "How does a surety bond differ from insurance?", "audio_back": "Insurance transfers risk and expects losses. A bond is a credit guarantee for the obligee's benefit. If the surety pays a claim, the principal contractor must repay the surety.", "source": "Industry standard (suretyship)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-059", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What does a PERFORMANCE bond guarantee, and who does it protect?", "back": "Completion of the contract per plans, specs, and terms. It protects the obligee only — on Michigan public work, solely the governmental unit (MCL 129.202).", "audio_front": "What does a performance bond guarantee, and who does it protect?", "audio_back": "It guarantees completion of the contract according to the plans, specs, and terms, and it protects only the obligee. On Michigan public work, solely the governmental unit.", "source": "MCL 129.202", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-060", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What does a PAYMENT bond guarantee, and who does it protect?", "back": "Payment to subcontractors, suppliers, and laborers. On Michigan public work it exists solely for the protection of those claimants (MCL 129.203).", "audio_front": "What does a payment bond guarantee, and who does it protect?", "audio_back": "It guarantees payment to subcontractors, suppliers, and laborers. On Michigan public work, it exists solely for the protection of those claimants.", "source": "MCL 129.203", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-061", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "At what contract amount do Michigan PUBLIC projects require performance and payment bonds?", "back": "Contracts EXCEEDING $50,000 for construction, alteration, or repair of public buildings/works require both bonds before award (MCL 129.201).", "audio_front": "At what contract amount do Michigan public projects require performance and payment bonds?", "audio_back": "Contracts exceeding fifty thousand dollars for construction, alteration, or repair of public buildings or works require both bonds before the contract is awarded. M C L 129 point 201.", "source": "MCL 129.201", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-062", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What is the minimum amount of the performance and payment bonds on Michigan public work?", "back": "Each must be in an amount fixed by the governmental unit but NOT LESS THAN 25% of the contract amount (MCL 129.202-.203).", "audio_front": "What is the minimum amount of the performance and payment bonds on Michigan public work?", "audio_back": "Each bond must be in an amount fixed by the governmental unit, but not less than twenty five percent of the contract amount.", "source": "MCL 129.202-.203", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-063", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Why can't an unpaid sub lien a public school project, and what is the remedy?", "back": "Public property cannot be subjected to construction liens. The remedy is a claim against the payment bond required by MCL 129.201-.203.", "audio_front": "Why can an unpaid sub not lien a public school project, and what is the remedy instead?", "audio_back": "Public property cannot be liened. The remedy is a claim against the statutory payment bond required on public projects over fifty thousand dollars.", "source": "MCL 129.201-.207", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-064", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Public payment-bond claim: what notice must a claimant with NO direct contract with the principal contractor give?", "back": "Two notices, by certified mail: (1) written notice to the principal contractor within 30 days after first furnishing; (2) written notice of the claim to the principal contractor AND the governmental unit within 90 days after last furnishing (MCL 129.207).", "audio_front": "On a public payment bond claim, what notice must a claimant with no direct contract with the principal contractor give?", "audio_back": "Two notices by certified mail. First, written notice to the principal contractor within thirty days after first furnishing. Second, written notice of the claim to the principal contractor and the governmental unit within ninety days after last furnishing. M C L 129 point 207.", "source": "MCL 129.207", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-065", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "When may a claimant SUE on a public payment bond?", "back": "After remaining unpaid for 90 days following its last furnishing of labor or material (MCL 129.207).", "audio_front": "When may a claimant sue on a public payment bond?", "audio_back": "After remaining unpaid for ninety days following its last furnishing of labor or material.", "source": "MCL 129.207", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-066", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What does a BID bond guarantee?", "back": "That the winning bidder will enter into the contract and furnish the required performance/payment bonds; if not, the surety covers the obligee's loss up to the bond penalty.", "audio_front": "What does a bid bond guarantee?", "audio_back": "That the winning bidder will sign the contract and furnish the required performance and payment bonds. If not, the surety covers the owner's loss up to the bond amount.", "source": "Industry standard (bid bonds)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-067", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What is a LICENSE or PERMIT bond?", "back": "A bond required by a government unit guaranteeing the contractor complies with the applicable law or ordinance (e.g., municipal right-of-way or sidewalk permit bonds). Obligee = the government. Michigan's state RB license itself does not require a bond.", "audio_front": "What is a license or permit bond?", "audio_back": "A bond required by a government unit guaranteeing the contractor will comply with the applicable law or ordinance, such as a municipal right of way or sidewalk permit bond. The obligee is the government. Michigan's state residential builder license itself does not require a bond.", "source": "Industry standard; LARA licensing requirements", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-068", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "TRAP: 'The payment bond on public work protects the governmental unit.' True or false?", "back": "False. The PERFORMANCE bond protects the governmental unit (MCL 129.202); the PAYMENT bond protects subs, suppliers, and laborers (MCL 129.203).", "audio_front": "Trap check. The payment bond on public work protects the governmental unit. True or false?", "audio_back": "False. The performance bond protects the governmental unit. The payment bond protects subs, suppliers, and laborers.", "source": "MCL 129.202-.203", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-069", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "TRAP: 'CGL will pay to redo my own defective tile work.' True or false?", "back": "False. CGL excludes your own work product / faulty workmanship. It covers resulting damage to OTHER property or persons, not the cost of redoing your work.", "audio_front": "Trap check. General liability will pay to redo my own defective tile work. True or false?", "audio_back": "False. General liability excludes your own work product. It covers resulting damage to other property or people, not the cost of redoing your own work.", "source": "Industry standard (CGL your-work exclusion)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-070", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Who typically buys builders risk, and when does coverage end?", "back": "Either the owner or the contractor — the construction contract should assign it. Coverage runs during construction and typically ends at completion/occupancy.", "audio_front": "Who typically buys builders risk insurance, and when does the coverage end?", "audio_back": "Either the owner or the contractor. The construction contract should say who. Coverage runs during construction and typically ends at completion or occupancy.", "source": "Industry standard (builders risk)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-071", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "A foreclosure complaint by a contractor must show what about sworn statements?", "back": "That the owner or lessee was provided a sworn statement, if one was requested or required (MCL 570.1117(7)).", "audio_front": "A foreclosure complaint by a contractor must show what about sworn statements?", "audio_back": "That the owner or lessee was provided a sworn statement, if one was requested or required. M C L 570 point 1117 subsection 7.", "source": "MCL 570.1117(7)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-072", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "When must a SUBCONTRACTOR give the GC a sworn statement?", "back": "When payment is due to the sub from the contractor or when the sub requests payment (MCL 570.1110(3)). The sub gives one to the OWNER only on demand.", "audio_front": "When must a subcontractor give the general contractor a sworn statement?", "audio_back": "When payment is due to the sub from the contractor, or when the sub requests payment. The sub gives one to the owner only on demand.", "source": "MCL 570.1110(2)-(3)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-073", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Scenario: verbal $35,000 residential remodel, homeowner refuses to pay. Lien position?", "back": "No lien. Residential lien rights require a written contract containing the licensure statement and license number (MCL 570.1114). The verbal deal defeats the lien regardless of amount.", "audio_front": "Scenario. A verbal thirty five thousand dollar residential remodel, and the homeowner refuses to pay. What is the lien position?", "audio_back": "No lien. Residential lien rights require a written contract containing the licensure statement and license number. A verbal deal defeats the lien regardless of the amount.", "source": "MCL 570.1114", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-074", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Can a claim of lien be recorded before the project is finished?", "back": "Yes. Nothing prohibits recording mid-project; the 90-day period is a deadline measured from last furnishing, not a start date. Early filing preserves a buffer.", "audio_front": "Can a claim of lien be recorded before the project is finished?", "audio_back": "Yes. Nothing prohibits recording mid project. The ninety day period is a deadline measured from last furnishing, not a start date.", "source": "MCL 570.1111(1)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-075", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "What interest does a construction lien attach to?", "back": "The entire interest of the owner or lessee who contracted for the improvement, including after-acquired legal or equitable interests (MCL 570.1107(2)).", "audio_front": "What interest does a construction lien attach to?", "audio_back": "The entire interest of the owner or lessee who contracted for the improvement, including after acquired legal or equitable interests. M C L 570 point 1107 subsection 2.", "source": "MCL 570.1107(2)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-076", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Rapid drill: 20 / 30 / 90 / 15 / 1 year — what are they?", "back": "20 days = sub/supplier Notice of Furnishing (first furnishing). 30 days = laborer notice (unpaid wages). 90 days = record claim of lien (last furnishing). 15 days = serve recorded lien copy on designee/owner. 1 year = foreclosure suit after recording.", "audio_front": "Rapid drill. Twenty, thirty, ninety, fifteen, and one year. What are they?", "audio_back": "Twenty days is the sub's Notice of Furnishing from first furnishing. Thirty days is the laborer notice from unpaid wages. Ninety days to record the claim of lien from last furnishing. Fifteen days to serve the recorded lien copy. One year from recording to file foreclosure.", "source": "MCL 570.1109, .1111, .1117", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-077", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Rapid drill: $50,000 / 25% / 30 / 90 on public work — what are they?", "back": "Over $50,000 = bonds required. 25% = minimum of each bond. 30 days = notice to principal contractor after first furnishing (no privity). 90 days = claim notice to principal and government after last furnishing (MCL 129.201-.207).", "audio_front": "Rapid drill. Fifty thousand dollars, twenty five percent, thirty, and ninety, on public work. What are they?", "audio_back": "Over fifty thousand dollars, bonds are required. Twenty five percent is the minimum of each bond. Thirty days is the notice to the principal contractor after first furnishing when there is no direct contract. Ninety days is the claim notice to the principal contractor and the governmental unit after last furnishing.", "source": "MCL 129.201-.207", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-078", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Match the loss to the policy: (a) neighbor's window broken by your crew, (b) burst of vandalism destroys framed walls, (c) roofer employee falls.", "back": "(a) CGL — third-party property damage. (b) Builders risk — first-party damage to the structure under construction. (c) Workers compensation — employee injury.", "audio_front": "Match the loss to the policy. A, the neighbor's window is broken by your crew. B, vandalism destroys the framed walls. C, your roofer employee falls.", "audio_back": "A is general liability, third party property damage. B is builders risk, first party damage to the structure under construction. C is workers compensation, employee injury.", "source": "Industry standard; MCL 418.115", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-079", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "Is workers comp optional for a public employer in Michigan?", "back": "No. All public employers are covered irrespective of the number of employees (MCL 418.115(c)).", "audio_front": "Is workers comp optional for a public employer in Michigan?", "audio_back": "No. All public employers are covered, regardless of the number of employees. M C L 418 point 115 subsection c.", "source": "MCL 418.115(c)", "domain": "02_liens-insurance-bonds"}, {"id": "liens-insurance-bonds-080", "deck": "rb", "section": "bl", "category": "Insurance Bonds & Liens", "front": "TRAP: 'The Recovery Fund will reimburse the homeowner, so the builder should cite it as protection.' What's wrong?", "back": "The Homeowner Construction Lien Recovery Fund was repealed by 2010 PA 147 (effective 8/23/2010). It no longer pays anyone and builders no longer contribute. Present-tense Fund answers are wrong.", "audio_front": "Trap check. The Recovery Fund will reimburse the homeowner, so the builder should cite it as protection. What is wrong with that?", "audio_back": "The Homeowner Construction Lien Recovery Fund was repealed in 2010 by Public Act 147, effective August twenty third, 2010. It no longer pays anyone, and builders no longer contribute.", "source": "MCL 570.1201 (repealed, 2010 PA 147)", "domain": "02_liens-insurance-bonds"}, {"id": "contracts-hifa-001", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is the Home Improvement Finance Act (HIFA) citation and what type of transaction does it regulate?", "back": "HIFA is Act 332 of 1965, MCL 445.1101 et seq. It regulates home improvement installment contracts and charge agreements — improvements the homeowner finances on credit through the contractor. It is not a general written-contract statute.", "audio_front": "What is the Home Improvement Finance Act, or HIFA, citation, and what type of transaction does it regulate?", "audio_back": "HIFA is Act three thirty two of nineteen sixty five, M C L four forty five point eleven oh one and following. It regulates home improvement installment contracts and charge agreements, meaning improvements the homeowner finances on credit through the contractor. It is not a general written contract statute.", "source": "MCL 445.1101 et seq.", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-002", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is HIFA's cash-price trigger, and is a contract at exactly $300 covered?", "back": "HIFA applies when the stated cash price is IN EXCESS OF $300 and paid on installment credit. A contract at exactly $300 or less is excluded (MCL 445.1102).", "audio_front": "What is HIFA's cash price trigger, and is a contract at exactly three hundred dollars covered?", "audio_back": "HIFA applies when the stated cash price is in excess of three hundred dollars and is paid on installment credit. A contract at exactly three hundred dollars or less is excluded, under M C L four forty five point eleven oh two.", "source": "MCL 445.1102(j),(m)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-003", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Does HIFA apply to new-home construction?", "back": "No. HIFA's definitions of goods and contractor expressly exclude construction of new homes (MCL 445.1102(g),(k)). HIFA covers modernization, rehabilitation, repair, alteration, or improvement of existing residential property.", "audio_front": "Does HIFA apply to new home construction?", "audio_back": "No. HIFA's definitions of goods and contractor expressly exclude construction of new homes, under M C L four forty five point eleven oh two. HIFA covers modernization, rehabilitation, repair, alteration, or improvement of existing residential property.", "source": "MCL 445.1102(g),(k)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-004", "deck": "rb", "section": "bl", "category": "Contracts", "front": "A homeowner pays for a $15,000 remodel with a loan she obtained directly from her own bank. Does HIFA govern the contractor's contract?", "back": "No. A loan contracted for or obtained directly by the buyer from a lending institution is excluded from the definition of a home improvement installment contract (MCL 445.1102(l)(v)). HIFA applies when the contractor extends or arranges the credit.", "audio_front": "A homeowner pays for a fifteen thousand dollar remodel with a loan she obtained directly from her own bank. Does HIFA govern the contractor's contract?", "audio_back": "No. A loan contracted for or obtained directly by the buyer from a lending institution is excluded from the definition of a home improvement installment contract, under M C L four forty five point eleven oh two, subsection L. HIFA applies when the contractor extends or arranges the credit.", "source": "MCL 445.1102(l)(v)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-005", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Name three transaction types excluded from HIFA installment-contract coverage besides new homes.", "back": "(1) Real property used for commercial or business purposes; (2) goods-only sales where the seller performs no installation services; (3) free-standing appliances not built into the structure (stove, refrigerator, freezer, non-central air conditioner, water heater); also direct bank loans (MCL 445.1102(l)).", "audio_front": "Name three transaction types excluded from HIFA installment contract coverage besides new homes.", "audio_back": "One, real property used for commercial or business purposes. Two, goods only sales where the seller performs no installation services. Three, free standing appliances not built into the structure, such as a stove, refrigerator, freezer, non central air conditioner, or water heater. Direct bank loans are also excluded. M C L four forty five point eleven oh two.", "source": "MCL 445.1102(l)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-006", "deck": "rb", "section": "bl", "category": "Contracts", "front": "TRAP: Does HIFA contain a $600 written-contract requirement, and does MCL 445.1108 exist?", "back": "No and no. HIFA has no general $600 written-contract rule, and MCL 445.1108 does not exist. The $600 figure is the licensure exemption in MCL 339.2403 (work under $600 labor plus materials is exempt from RB/RMAC licensure).", "audio_front": "Trap question. Does HIFA contain a six hundred dollar written contract requirement, and does M C L four forty five point eleven oh eight exist?", "audio_back": "No and no. HIFA has no general six hundred dollar written contract rule, and M C L four forty five point eleven oh eight does not exist. The six hundred dollar figure is the licensure exemption in M C L three thirty nine point two four oh three.", "source": "MCL 445.1101 et seq.; MCL 339.2403", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-007", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What formatting does HIFA require for a home improvement installment contract?", "back": "The contract must be dated, in writing, with the printed portion in at least 8-point type (MCL 445.1201). The words 'home improvement installment contract' must appear in at least 10-point bold at the top or directly above the buyer's signature space (MCL 445.1202(b)).", "audio_front": "What formatting does HIFA require for a home improvement installment contract?", "audio_back": "The contract must be dated, in writing, with the printed portion in at least eight point type, under M C L four forty five point twelve oh one. The words home improvement installment contract must appear in at least ten point bold type at the top or directly above the buyer's signature space.", "source": "MCL 445.1201; MCL 445.1202(b)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-008", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What four statements must appear in the HIFA 'Notice to buyer'?", "back": "(1) Do not sign this contract before you read it; (2) you are entitled to a completely filled-in copy; (3) you have the right to pay off in advance and under certain conditions obtain a partial refund of the finance charge; (4) you may rescind by 5 p.m. of the next business day (MCL 445.1202(c)).", "audio_front": "What four statements must appear in the HIFA notice to buyer?", "audio_back": "One, do not sign this contract before you read it. Two, you are entitled to a completely filled in copy. Three, you have the right to pay off in advance and, under certain conditions, obtain a partial refund of the finance charge. Four, you may rescind by five P M of the next business day. M C L four forty five point twelve oh two.", "source": "MCL 445.1202(c)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-009", "deck": "rb", "section": "bl", "category": "Contracts", "front": "List six of the itemized dollar figures a HIFA installment contract must state under MCL 445.1203.", "back": "Cash price; down payment; unpaid cash balance; insurance premiums (if charged); official fees; principal amount financed; finance charge in dollars; time balance; installment number/amount/due dates; and time sale price. Any six of these is a full answer.", "audio_front": "List six of the itemized dollar figures a HIFA installment contract must state under M C L four forty five point twelve oh three.", "audio_back": "The contract must state the cash price, the down payment, the unpaid cash balance, insurance premiums if charged, official fees, the principal amount financed, the finance charge in dollars, the time balance, the number and amount of installments with due dates, and the time sale price.", "source": "MCL 445.1203", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-010", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Under HIFA, what happens if the contractor fails to deliver a completed copy of the contract to the buyer at execution?", "back": "The buyer is not obligated to pay until the contractor delivers a copy completed in accordance with the act (MCL 445.1204). Delivery must occur at the time the contract is executed.", "audio_front": "Under HIFA, what happens if the contractor fails to deliver a completed copy of the contract to the buyer at execution?", "audio_back": "The buyer is not obligated to pay until the contractor delivers a copy completed in accordance with the act, under M C L four forty five point twelve oh four. Delivery must occur at the time the contract is executed.", "source": "MCL 445.1204", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-011", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is the HIFA right of rescission deadline?", "back": "The buyer may rescind not later than 5 p.m. on the business day FOLLOWING the date of the contract, by written notice delivered to the contractor's place of business or mailed by certified letter (MCL 445.1202(c)(4), 445.1203(l)).", "audio_front": "What is the HIFA right of rescission deadline?", "audio_back": "The buyer may rescind not later than five P M on the business day following the date of the contract, by written notice delivered to the contractor's place of business, or mailed by certified letter. M C L four forty five point twelve oh two and twelve oh three.", "source": "MCL 445.1202(c)(4); MCL 445.1203(l)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-012", "deck": "rb", "section": "bl", "category": "Contracts", "front": "TRAP: Distinguish the HIFA rescission period from the HSSA cancellation period.", "back": "HIFA (installment-financed sale): rescind until 5 p.m. of the NEXT business day. HSSA (seller-solicited in-home sale): cancel until MIDNIGHT of the THIRD business day after signing (MCL 445.112(1)). Both can apply to the same transaction; the buyer gets each applicable right.", "audio_front": "Trap question. Distinguish the HIFA rescission period from the H S S A cancellation period.", "audio_back": "Under HIFA, an installment financed sale can be rescinded until five P M of the next business day. Under the Home Solicitation Sales Act, a seller solicited in home sale can be canceled until midnight of the third business day after signing. Both can apply to the same transaction.", "source": "MCL 445.1202(c)(4); MCL 445.112(1)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-013", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Name four provisions that are PROHIBITED in a HIFA installment contract or charge agreement.", "back": "Under MCL 445.1206: waiver of buyer's claims/defenses; arbitrary acceleration absent default; waiver of action for illegal collection acts; relieving the contractor of liability; authorization of unlawful entry or breach of peace in repossession; and liquidated damages to the contractor for cancellation or rescission. A prohibited provision is void but the rest of the contract stands.", "audio_front": "Name four provisions that are prohibited in a HIFA installment contract or charge agreement.", "audio_back": "Under M C L four forty five point twelve oh six: waiver of the buyer's claims or defenses; arbitrary acceleration without default; waiver of any right of action for illegal collection acts; relieving the contractor of liability; authorizing unlawful entry or breach of the peace in repossession; and liquidated damages to the contractor for cancellation or rescission. A prohibited provision is void, but the rest of the contract stands.", "source": "MCL 445.1206", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-014", "deck": "rb", "section": "bl", "category": "Contracts", "front": "TRAP: A HIFA installment contract states the contractor keeps 20% of the contract price as liquidated damages if the buyer cancels. Enforceable?", "back": "No. MCL 445.1206(1)(f) prohibits any provision entitling the contractor to liquidated damages for cancellation, rescission, or refusal to accept delivery. The provision is void, though the rest of the contract remains valid.", "audio_front": "Trap question. A HIFA installment contract states the contractor keeps twenty percent of the contract price as liquidated damages if the buyer cancels. Is that enforceable?", "audio_back": "No. M C L four forty five point twelve oh six prohibits any provision entitling the contractor to liquidated damages for cancellation, rescission, or refusal to accept delivery. The provision is void, though the rest of the contract remains valid.", "source": "MCL 445.1206(1)(f)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-015", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is the penalty for a willful violation of HIFA?", "back": "Misdemeanor: up to 90 days in county jail and/or a fine up to $500 for a first offense; a like fine and/or up to 1 year for each subsequent offense (MCL 445.1421). Courts may also enjoin violations (MCL 445.1422).", "audio_front": "What is the penalty for a willful violation of HIFA?", "audio_back": "It is a misdemeanor. Up to ninety days in county jail, a fine up to five hundred dollars, or both, for a first offense. For each subsequent offense, a like fine, imprisonment up to one year, or both. M C L four forty five point fourteen twenty one.", "source": "MCL 445.1421", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-016", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Under HIFA, may a contractor pay a referral fee or reward to induce someone to procure a home improvement contract?", "back": "No. MCL 445.1404 prohibits giving compensation or reward for the procurement of a home improvement installment contract or charge agreement (small advertising items excepted).", "audio_front": "Under HIFA, may a contractor pay a referral fee or reward to induce someone to procure a home improvement contract?", "audio_back": "No. M C L four forty five point fourteen oh four prohibits giving compensation or a reward for the procurement of a home improvement installment contract or charge agreement, with an exception for small advertising items.", "source": "MCL 445.1404", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-017", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is a 'home improvement charge agreement' under HIFA?", "back": "An open-end instrument for home improvement charge sales — secured or unsecured — where a time price differential is computed on the buyer's unpaid balance from time to time, with cash price over $300 (MCL 445.1102(i),(j)). MCL 445.1204b bars taking a lien on the buyer's principal residence under a charge agreement.", "audio_front": "What is a home improvement charge agreement under HIFA?", "audio_back": "An open end instrument for home improvement charge sales, secured or unsecured, where a time price differential is computed on the buyer's unpaid balance from time to time, with a cash price over three hundred dollars. M C L four forty five point twelve oh four B bars taking a lien on the buyer's principal residence under a charge agreement.", "source": "MCL 445.1102(i),(j); MCL 445.1204b", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-018", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is the Home Solicitation Sales Act citation and cancellation window?", "back": "Act 227 of 1971, MCL 445.111 to 445.117. The buyer may cancel a home solicitation sale until MIDNIGHT of the third business day after the day the buyer signs (MCL 445.112(1)).", "audio_front": "What is the Home Solicitation Sales Act citation and cancellation window?", "audio_back": "Act two twenty seven of nineteen seventy one, M C L four forty five point one eleven through one seventeen. The buyer may cancel a home solicitation sale until midnight of the third business day after the day the buyer signs.", "source": "MCL 445.111–445.117; MCL 445.112(1)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-019", "deck": "rb", "section": "bl", "category": "Contracts", "front": "When is a mailed HSSA cancellation notice effective?", "back": "When it is deposited in a mailbox, properly addressed with postage prepaid — the mailbox rule (MCL 445.112(3)). It does not need to be received by the deadline, only mailed.", "audio_front": "When is a mailed cancellation notice under the Home Solicitation Sales Act effective?", "audio_back": "When it is deposited in a mailbox, properly addressed with postage prepaid. That is the mailbox rule, under M C L four forty five point one twelve. It does not need to be received by the deadline, only mailed.", "source": "MCL 445.112(3)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-020", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What are the THREE statutory conditions that all must be met for the HSSA emergency exception to cut off the buyer's cancellation right?", "back": "Under MCL 445.112(5): (a) the seller in good faith makes a substantial beginning of performance before notice of cancellation; (b) the buyer furnishes a separate, dated, signed personal statement IN THE BUYER'S HANDWRITING describing the emergency and expressly waiving the 3-day right; and (c) the goods cannot be returned in substantially as-good condition.", "audio_front": "What are the three statutory conditions that all must be met for the Home Solicitation Sales Act emergency exception to cut off the buyer's cancellation right?", "audio_back": "Under M C L four forty five point one twelve, subsection five: first, the seller in good faith makes a substantial beginning of performance before notice of cancellation. Second, the buyer furnishes a separate, dated, signed personal statement in the buyer's own handwriting describing the emergency and expressly waiving the three day right. Third, the goods cannot be returned in substantially as good condition.", "source": "MCL 445.112(5)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-021", "deck": "rb", "section": "bl", "category": "Contracts", "front": "TRAP: Is the handwritten emergency waiver merely a federal FTC formality, or a Michigan statutory requirement?", "back": "It is a Michigan statutory requirement. MCL 445.112(5)(b) itself requires a separate dated, signed personal statement in the buyer's handwriting to defeat cancellation. The FTC Cooling-Off Rule (16 CFR Part 429) independently requires it as well.", "audio_front": "Trap question. Is the handwritten emergency waiver merely a federal F T C formality, or a Michigan statutory requirement?", "audio_back": "It is a Michigan statutory requirement. M C L four forty five point one twelve, subsection five B, itself requires a separate, dated, signed personal statement in the buyer's handwriting to defeat cancellation. The federal F T C cooling off rule independently requires it as well.", "source": "MCL 445.112(5)(b); 16 CFR Part 429", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-022", "deck": "rb", "section": "bl", "category": "Contracts", "front": "After a valid HSSA cancellation, how quickly must the seller return the buyer's payments, trade-ins, and negotiable instruments?", "back": "Within 10 BUSINESS days following the seller's receipt of the cancellation notice; any security interest arising from the transaction is also canceled (MCL 445.113(2)).", "audio_front": "After a valid cancellation under the Home Solicitation Sales Act, how quickly must the seller return the buyer's payments, trade ins, and negotiable instruments?", "audio_back": "Within ten business days following the seller's receipt of the cancellation notice. Any security interest arising from the transaction is also canceled. M C L four forty five point one thirteen.", "source": "MCL 445.113(2)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-023", "deck": "rb", "section": "bl", "category": "Contracts", "front": "After an HSSA cancellation, the buyer makes delivered goods available at the residence. How long does the seller have to pick them up?", "back": "20 days from the date of the cancellation notice. If the seller does not pick them up within 20 days, the buyer may retain or dispose of the goods without further obligation (MCL 445.113(2) notice form).", "audio_front": "After a cancellation under the Home Solicitation Sales Act, the buyer makes delivered goods available at the residence. How long does the seller have to pick them up?", "audio_back": "Twenty days from the date of the cancellation notice. If the seller does not pick them up within twenty days, the buyer may retain or dispose of the goods without further obligation.", "source": "MCL 445.113(2)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-024", "deck": "rb", "section": "bl", "category": "Contracts", "front": "May a seller send a courier to pick up the buyer's payment at the residence during the HSSA cancellation period?", "back": "No. The seller shall not acquire payment by having an independent courier or other third party pick up payment at the buyer's residence until the right-to-revoke period has expired (MCL 445.112(1)).", "audio_front": "May a seller send a courier to pick up the buyer's payment at the residence during the cancellation period?", "audio_back": "No. The seller shall not acquire payment by having an independent courier service or other third party pick up payment at the buyer's residence until the right to revoke period has expired. M C L four forty five point one twelve.", "source": "MCL 445.112(1)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-025", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What cancellation paperwork must an HSSA contract include?", "back": "A cancellation statement in immediate proximity to the buyer's signature space, and a NOTICE OF CANCELLATION form in duplicate, attached or printed on the reverse of the buyer's copy (MCL 445.113(1)-(2)), dated with the transaction date.", "audio_front": "What cancellation paperwork must a home solicitation sale contract include?", "audio_back": "A cancellation statement in immediate proximity to the buyer's signature space, and a notice of cancellation form in duplicate, attached to or printed on the reverse of the buyer's copy, dated with the transaction date. M C L four forty five point one thirteen.", "source": "MCL 445.113(1)-(2)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-026", "deck": "rb", "section": "bl", "category": "Contracts", "front": "A contractor starts tear-out the same day a kitchen-table contract is signed, with no emergency and no handwritten waiver. The homeowner cancels on day 2. What is the contractor's position?", "back": "The cancellation is valid; the contractor must return all payments within 10 business days and bears the risk of the work performed. Without meeting all MCL 445.112(5) conditions, starting work does not cut off the cancellation right.", "audio_front": "A contractor starts tear out the same day a kitchen table contract is signed, with no emergency and no handwritten waiver. The homeowner cancels on day two. What is the contractor's position?", "audio_back": "The cancellation is valid. The contractor must return all payments within ten business days and bears the risk of the work performed. Without meeting all conditions of M C L four forty five point one twelve, subsection five, starting work does not cut off the cancellation right.", "source": "MCL 445.112(5); MCL 445.113(2)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-027", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Under MCL 570.1114, what must a residential contractor's contract contain to preserve construction lien rights?", "back": "(1) A written contract with the owner or lessee; (2) all amendments and additions (change orders) in writing; (3) a statement that RB/RMAC, electrical, plumbing, and mechanical contractors must be licensed; and (4) if licensure is required, a statement that the contractor is licensed plus the license number. Applies at any dollar amount.", "audio_front": "Under M C L five seventy point eleven fourteen, what must a residential contractor's contract contain to preserve construction lien rights?", "audio_back": "One, a written contract with the owner or lessee. Two, all amendments and additions, meaning change orders, in writing. Three, a statement that residential builder, electrical, plumbing, and mechanical contractors must be licensed. Four, if licensure is required, a statement that the contractor is licensed, plus the license number. This applies at any dollar amount.", "source": "MCL 570.1114", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-028", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Is there a dollar threshold below which MCL 570.1114's written-contract lien condition does not apply?", "back": "No. The written contract, licensing statement, license number, and written amendments are conditions of residential lien rights at ANY contract amount.", "audio_front": "Is there a dollar threshold below which the written contract lien condition of M C L five seventy point eleven fourteen does not apply?", "audio_back": "No. The written contract, licensing statement, license number, and written amendments are conditions of residential lien rights at any contract amount.", "source": "MCL 570.1114", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-029", "deck": "rb", "section": "bl", "category": "Contracts", "front": "A licensed builder has a signed written contract but forgot to print the license number in it. Effect on lien rights?", "back": "Lien rights on the residential structure are at risk — MCL 570.1114(b) requires the contract to state that the contractor is licensed AND the license number. Actually holding a license does not cure the omission.", "audio_front": "A licensed builder has a signed written contract but forgot to print the license number in it. What is the effect on lien rights?", "audio_back": "Lien rights on the residential structure are at risk. M C L five seventy point eleven fourteen requires the contract to state that the contractor is licensed and to include the license number. Actually holding a license does not cure the omission.", "source": "MCL 570.1114(b)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-030", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Mid-project, the scope grows by $6,000. What does MCL 570.1114 require for the extra amount to be lien-protected?", "back": "A written amendment or change order — the statute requires any amendments or additions to the contract to be in writing. A verbal change order leaves the added scope without lien protection.", "audio_front": "Mid project, the scope grows by six thousand dollars. What does M C L five seventy point eleven fourteen require for the extra amount to be lien protected?", "audio_back": "A written amendment or change order. The statute requires any amendments or additions to the contract to be in writing. A verbal change order leaves the added scope without lien protection.", "source": "MCL 570.1114", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-031", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Which statute bars an UNLICENSED residential builder from suing to collect payment, and what is the $600 rule?", "back": "MCL 339.2412 bars an unlicensed builder from bringing an action to collect compensation for residential work. Separately, MCL 339.2403 exempts jobs under $600 (labor plus materials) from the licensure requirement — a licensure exemption, not a contract rule.", "audio_front": "Which statute bars an unlicensed residential builder from suing to collect payment, and what is the six hundred dollar rule?", "audio_back": "M C L three thirty nine point twenty four twelve bars an unlicensed builder from bringing an action to collect compensation for residential work. Separately, M C L three thirty nine point twenty four oh three exempts jobs under six hundred dollars, labor plus materials, from the licensure requirement. That is a licensure exemption, not a contract rule.", "source": "MCL 339.2412; MCL 339.2403", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-032", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What are the five elements of a valid contract?", "back": "Offer, acceptance, consideration, capacity, and legality. Missing any element makes the contract void or voidable.", "audio_front": "What are the five elements of a valid contract?", "audio_back": "Offer, acceptance, consideration, capacity, and legality. Missing any element makes the contract void or voidable.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-033", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is 'consideration' in contract law?", "back": "Something of legal value exchanged by each party — money, goods, services, or a promise. A contract without consideration on both sides is generally unenforceable.", "audio_front": "What is consideration in contract law?", "audio_back": "Something of legal value exchanged by each party. Money, goods, services, or a promise. A contract without consideration on both sides is generally unenforceable.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-034", "deck": "rb", "section": "bl", "category": "Contracts", "front": "In a fixed-price (lump-sum) contract, who bears the risk of cost overruns?", "back": "The contractor. If actual costs exceed the bid the contractor absorbs the loss; if costs come in under, the contractor keeps the savings.", "audio_front": "In a fixed price, or lump sum, contract, who bears the risk of cost overruns?", "audio_back": "The contractor. If actual costs exceed the bid, the contractor absorbs the loss. If costs come in under, the contractor keeps the savings.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-035", "deck": "rb", "section": "bl", "category": "Contracts", "front": "In a cost-plus contract, who bears the cost risk, and what does the owner pay?", "back": "The owner bears the cost risk. The owner pays actual costs plus an agreed fee — either a fixed amount or a percentage — so the contractor's fee is protected.", "audio_front": "In a cost plus contract, who bears the cost risk, and what does the owner pay?", "audio_back": "The owner bears the cost risk. The owner pays actual costs plus an agreed fee, either a fixed amount or a percentage, so the contractor's fee is protected.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-036", "deck": "rb", "section": "bl", "category": "Contracts", "front": "How is risk allocated in a unit-price contract?", "back": "Shared: the contractor bears the risk that unit costs exceed the unit price; the owner bears quantity risk because the final price depends on actual measured quantities.", "audio_front": "How is risk allocated in a unit price contract?", "audio_back": "It is shared. The contractor bears the risk that unit costs exceed the unit price, and the owner bears quantity risk, because the final price depends on actual measured quantities.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-037", "deck": "rb", "section": "bl", "category": "Contracts", "front": "When is a time-and-materials contract typically used and who bears the risk?", "back": "When scope is uncertain (e.g., hidden damage repair). The owner pays hourly labor rates plus material costs, usually with markup, so the owner bears most of the cost risk.", "audio_front": "When is a time and materials contract typically used, and who bears the risk?", "audio_back": "When the scope is uncertain, for example hidden damage repair. The owner pays hourly labor rates plus material costs, usually with markup, so the owner bears most of the cost risk.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-038", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What are the requirements of a valid change order?", "back": "In writing, signed by both owner and contractor, describing the change in scope and the adjustment to price and/or time. In Michigan, written change orders are also a residential lien-rights condition under MCL 570.1114.", "audio_front": "What are the requirements of a valid change order?", "audio_back": "In writing, signed by both owner and contractor, describing the change in scope and the adjustment to price or time. In Michigan, written change orders are also a residential lien rights condition under M C L five seventy point eleven fourteen.", "source": "General contract law; MCL 570.1114", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-039", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Distinguish substantial completion from final completion.", "back": "Substantial completion: the owner can use the work for its intended purpose — triggers retainage release and warranty start. Final completion: all work and punch-list items are 100% done and all contract obligations fulfilled.", "audio_front": "Distinguish substantial completion from final completion.", "audio_back": "Substantial completion means the owner can use the work for its intended purpose. It triggers retainage release and the start of the warranty period. Final completion means all work and punch list items are one hundred percent done and all contract obligations are fulfilled.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-040", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is retainage and what is the typical percentage?", "back": "A portion of each progress payment — typically 5 to 10 percent — withheld by the owner until substantial completion, to ensure the contractor finishes and corrects deficiencies.", "audio_front": "What is retainage, and what is the typical percentage?", "audio_back": "A portion of each progress payment, typically five to ten percent, withheld by the owner until substantial completion, to ensure the contractor finishes and corrects deficiencies.", "source": "Industry standard", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-041", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is a material breach and what does it allow the non-breaching party to do?", "back": "A breach that defeats the essential purpose of the contract. It excuses the non-breaching party's further performance and allows suit for damages. A minor breach allows damages but performance must continue.", "audio_front": "What is a material breach, and what does it allow the non breaching party to do?", "audio_back": "A breach that defeats the essential purpose of the contract. It excuses the non breaching party from further performance and allows a suit for damages. A minor breach allows damages, but performance must continue.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-042", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Name the principal remedies for breach of a construction contract.", "back": "Compensatory damages (put the injured party where performance would have); specific performance (rare in construction); rescission and restitution; and quantum meruit (reasonable value of work performed). The injured party must mitigate damages.", "audio_front": "Name the principal remedies for breach of a construction contract.", "audio_back": "Compensatory damages, which put the injured party where performance would have. Specific performance, which is rare in construction. Rescission and restitution. And quantum meruit, the reasonable value of work performed. The injured party must mitigate damages.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-043", "deck": "rb", "section": "bl", "category": "Contracts", "front": "When is a liquidated damages clause enforceable in a construction contract?", "back": "When damages are difficult to estimate at contracting and the amount is a reasonable pre-estimate of actual harm — not a penalty. Commonly a per-day amount for late completion. TRAP: liquidated damages for buyer cancellation are prohibited in HIFA contracts (MCL 445.1206(1)(f)).", "audio_front": "When is a liquidated damages clause enforceable in a construction contract?", "audio_back": "When damages are difficult to estimate at contracting and the amount is a reasonable pre estimate of actual harm, not a penalty. Commonly a per day amount for late completion. Trap: liquidated damages for buyer cancellation are prohibited in HIFA contracts under M C L four forty five point twelve oh six.", "source": "General contract law; MCL 445.1206(1)(f)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-044", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is an indemnification (hold-harmless) clause?", "back": "A provision in which one party agrees to compensate the other for specified losses, damages, or liabilities. In construction, the subcontractor typically indemnifies the general contractor for claims arising from the sub's work.", "audio_front": "What is an indemnification, or hold harmless, clause?", "audio_back": "A provision in which one party agrees to compensate the other for specified losses, damages, or liabilities. In construction, the subcontractor typically indemnifies the general contractor for claims arising from the sub's work.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-045", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What does a force majeure clause do?", "back": "Excuses or suspends performance when extraordinary events beyond either party's control occur — natural disasters, war, government action. It typically extends the schedule but does not increase the contract price.", "audio_front": "What does a force majeure clause do?", "audio_back": "It excuses or suspends performance when extraordinary events beyond either party's control occur, such as natural disasters, war, or government action. It typically extends the schedule but does not increase the contract price.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-046", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Rank the three main construction dispute-resolution methods from least to most formal.", "back": "Mediation (voluntary, non-binding, facilitated negotiation) → arbitration (binding decision by a neutral, common in AIA contracts) → litigation (court lawsuit).", "audio_front": "Rank the three main construction dispute resolution methods from least to most formal.", "audio_back": "Mediation, which is voluntary, non binding, facilitated negotiation. Then arbitration, a binding decision by a neutral third party, common in A I A contracts. Then litigation, a formal lawsuit in court.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-047", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is the Michigan statute of limitations for breach of contract, with citation?", "back": "6 years from the date the claim accrues (breach), under MCL 600.5807(9).", "audio_front": "What is the Michigan statute of limitations for breach of contract, with citation?", "audio_back": "Six years from the date the claim accrues, meaning the breach, under M C L six hundred point fifty eight oh seven, subsection nine.", "source": "MCL 600.5807(9)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-048", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is the Michigan statute of limitations for negligence causing injury to a person or property, with citation?", "back": "3 years after the death or injury, under MCL 600.5805(2).", "audio_front": "What is the Michigan statute of limitations for negligence causing injury to a person or property, with citation?", "audio_back": "Three years after the death or injury, under M C L six hundred point fifty eight oh five, subsection two.", "source": "MCL 600.5805(2)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-049", "deck": "rb", "section": "bl", "category": "Contracts", "front": "State Michigan's statute of repose for defective improvements to real property.", "back": "6 years from the time of occupancy of the completed improvement, use, or acceptance — whichever event applies — for actions against contractors, licensed architects, and professional engineers (MCL 600.5839(1)(a)).", "audio_front": "State Michigan's statute of repose for defective improvements to real property.", "audio_back": "Six years from the time of occupancy of the completed improvement, use, or acceptance, for actions against contractors, licensed architects, and professional engineers. M C L six hundred point fifty eight thirty nine.", "source": "MCL 600.5839(1)(a)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-050", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is the gross-negligence exception to Michigan's construction statute of repose?", "back": "If the defect results from gross negligence, the action may be brought within 1 year after the defect is discovered or should have been discovered — but never more than 10 years after occupancy, use, or acceptance (MCL 600.5839(1)(b)).", "audio_front": "What is the gross negligence exception to Michigan's construction statute of repose?", "audio_back": "If the defect results from gross negligence, the action may be brought within one year after the defect is discovered or should have been discovered, but never more than ten years after occupancy, use, or acceptance. M C L six hundred point fifty eight thirty nine.", "source": "MCL 600.5839(1)(b)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-051", "deck": "rb", "section": "bl", "category": "Contracts", "front": "TRAP: Distinguish a statute of limitations from a statute of repose.", "back": "A statute of limitations runs from when the claim accrues (breach or injury, sometimes discovery). A statute of repose runs from a FIXED event — occupancy, use, or acceptance — and bars the claim after the period even if the defect was never discovered.", "audio_front": "Trap question. Distinguish a statute of limitations from a statute of repose.", "audio_back": "A statute of limitations runs from when the claim accrues, meaning the breach or injury. A statute of repose runs from a fixed event, occupancy, use, or acceptance, and bars the claim after the period even if the defect was never discovered.", "source": "MCL 600.5807; MCL 600.5839", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-052", "deck": "rb", "section": "bl", "category": "Contracts", "front": "A homeowner discovers an ordinary (not grossly negligent) construction defect 7 years after moving in. Can they sue the builder?", "back": "No. The 6-year statute of repose (MCL 600.5839(1)(a)) ran from occupancy — the claim is barred even though the defect was just discovered. Only gross negligence gets the 1-year-after-discovery window, capped at 10 years.", "audio_front": "A homeowner discovers an ordinary construction defect seven years after moving in. Can they sue the builder?", "audio_back": "No. The six year statute of repose ran from occupancy, so the claim is barred even though the defect was just discovered. Only gross negligence gets the one year after discovery window, capped at ten years.", "source": "MCL 600.5839(1)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-053", "deck": "rb", "section": "bl", "category": "Contracts", "front": "TRAP: Does the 10-year period in MCL 600.5839 apply to all construction-defect claims?", "back": "No. 10 years is the absolute outer cap for the GROSS-NEGLIGENCE exception only. The standard repose period is 6 years from occupancy, use, or acceptance.", "audio_front": "Trap question. Does the ten year period in M C L six hundred point fifty eight thirty nine apply to all construction defect claims?", "audio_back": "No. Ten years is the absolute outer cap for the gross negligence exception only. The standard repose period is six years from occupancy, use, or acceptance.", "source": "MCL 600.5839(1)(b)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-054", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is the statute of limitations for a Michigan Consumer Protection Act claim?", "back": "6 years from the violation, or 1 year after the last payment on the transaction, whichever is later (MCL 445.911(9)). Note licensed builders are largely exempt from MCPA for license-regulated conduct (Liss v Lewiston-Richards).", "audio_front": "What is the statute of limitations for a Michigan Consumer Protection Act claim?", "audio_back": "Six years from the violation, or one year after the last payment on the transaction, whichever is later, under M C L four forty five point nine eleven. Note that licensed builders are largely exempt from the act for license regulated conduct, under Liss versus Lewiston Richards.", "source": "MCL 445.911(9)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-055", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is an express warranty?", "back": "A warranty explicitly stated in the contract — a promise of specific quality, performance, or duration, such as 'roof free from leaks for 5 years.' Enforceable as a contract term.", "audio_front": "What is an express warranty?", "audio_back": "A warranty explicitly stated in the contract. A promise of specific quality, performance, or duration, such as a roof free from leaks for five years. It is enforceable as a contract term.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-056", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is the implied warranty of habitability and when does Michigan recognize it?", "back": "A warranty imposed by law that a newly built home is fit for human habitation — structurally sound, weathertight, safe. Michigan recognizes it in builder-vendor new-home sales (Smith v Foerster-Bolser Construction). In Michigan, disclaimers of it MAY be enforceable.", "audio_front": "What is the implied warranty of habitability, and when does Michigan recognize it?", "audio_back": "A warranty imposed by law that a newly built home is fit for human habitation. Structurally sound, weathertight, and safe. Michigan recognizes it in builder vendor new home sales, under Smith versus Foerster Bolser Construction. In Michigan, disclaimers of this warranty may be enforceable.", "source": "Smith v Foerster-Bolser Constr (MI case law)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-057", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is the implied warranty of workmanship?", "back": "A warranty imposed by law that construction will be performed in a workmanlike manner — the standard of a reasonably skilled tradesperson. It applies even if not written in the contract and survives expiration of a shorter express warranty.", "audio_front": "What is the implied warranty of workmanship?", "audio_back": "A warranty imposed by law that construction will be performed in a workmanlike manner, meeting the standard of a reasonably skilled tradesperson. It applies even if not written in the contract, and it survives expiration of a shorter express warranty.", "source": "MI common law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-058", "deck": "rb", "section": "bl", "category": "Contracts", "front": "A roof leaks from bad flashing 3 years in; the contract's 1-year express warranty has expired. Homeowner's strongest theory?", "back": "The implied warranty of workmanship — it exists independently of the express warranty and covers defective installation. The claim is timely: within the 6-year repose period (MCL 600.5839) and 6-year contract SOL.", "audio_front": "A roof leaks from bad flashing three years in. The contract's one year express warranty has expired. What is the homeowner's strongest theory?", "audio_back": "The implied warranty of workmanship. It exists independently of the express warranty and covers defective installation. The claim is timely, falling within the six year repose period and the six year contract statute of limitations.", "source": "MI common law; MCL 600.5839", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-059", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Warranty versus maintenance — which is the owner's responsibility?", "back": "Warranty covers defects in materials or workmanship — builder's responsibility. Maintenance covers normal wear and routine upkeep — owner's responsibility. The contract should define the boundary.", "audio_front": "Warranty versus maintenance. Which is the owner's responsibility?", "audio_back": "Warranty covers defects in materials or workmanship, which are the builder's responsibility. Maintenance covers normal wear and routine upkeep, which are the owner's responsibility. The contract should define the boundary.", "source": "General construction practice", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-060", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What are the four elements of negligence?", "back": "Duty, breach, causation, damages. The plaintiff must prove all four.", "audio_front": "What are the four elements of negligence?", "audio_back": "Duty, breach, causation, and damages. The plaintiff must prove all four.", "source": "General tort law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-061", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is strict liability and where does it appear in construction?", "back": "Liability without proof of fault, applied mainly to defective products. A builder who installs a defective product can face liability even without negligent installation.", "audio_front": "What is strict liability, and where does it appear in construction?", "audio_back": "Liability without proof of fault, applied mainly to defective products. A builder who installs a defective product can face liability even without negligent installation.", "source": "General tort law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-062", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What is vicarious liability in the GC-subcontractor relationship?", "back": "The general contractor may be held liable for a subcontractor's actions on the jobsite even without direct fault — the GC has a duty to ensure subs work safely and to code.", "audio_front": "What is vicarious liability in the general contractor and subcontractor relationship?", "audio_back": "The general contractor may be held liable for a subcontractor's actions on the jobsite even without direct fault. The general contractor has a duty to ensure subs work safely and to code.", "source": "General tort law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-063", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What does a Commercial General Liability (CGL) policy cover — and what does it NOT cover?", "back": "Covers third-party bodily injury, third-party property damage, and personal/advertising injury. Does NOT cover the contractor's own property, vehicles, employees' injuries (workers' comp), or the work product itself.", "audio_front": "What does a commercial general liability, or C G L, policy cover, and what does it not cover?", "audio_back": "It covers third party bodily injury, third party property damage, and personal and advertising injury. It does not cover the contractor's own property, vehicles, employee injuries, which are workers' compensation, or the work product itself.", "source": "Insurance practice", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-064", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What does builder's risk insurance cover and when does it end?", "back": "The structure under construction plus materials on site and in transit, against perils like fire, wind, theft, and vandalism. Coverage runs from project start until occupancy or policy expiration.", "audio_front": "What does builder's risk insurance cover, and when does it end?", "audio_back": "The structure under construction, plus materials on site and in transit, against perils like fire, wind, theft, and vandalism. Coverage runs from project start until occupancy or policy expiration.", "source": "Insurance practice", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-065", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What does a Certificate of Insurance prove — and not prove?", "back": "It proves coverage existed when the certificate was issued. It does NOT guarantee the policy remains in force, won't be canceled, or that limits haven't been eroded. Additional-insured status requires a separate endorsement.", "audio_front": "What does a certificate of insurance prove, and not prove?", "audio_back": "It proves coverage existed when the certificate was issued. It does not guarantee the policy remains in force, will not be canceled, or that limits have not been eroded. Additional insured status requires a separate endorsement.", "source": "Insurance practice", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-066", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Why does a GC require an additional insured endorsement from subs, and what is a waiver of subrogation?", "back": "The endorsement adds the GC to the sub's CGL policy, giving direct access to the sub's coverage for claims from the sub's work. A waiver of subrogation stops an insurer from pursuing recovery against the named party after paying a claim.", "audio_front": "Why does a general contractor require an additional insured endorsement from subs, and what is a waiver of subrogation?", "audio_back": "The endorsement adds the general contractor to the sub's liability policy, giving direct access to the sub's coverage for claims arising from the sub's work. A waiver of subrogation stops an insurer from pursuing recovery against the named party after paying a claim.", "source": "Insurance practice", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-067", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Umbrella versus excess liability coverage — what is the difference?", "back": "Both sit above underlying policy limits. An umbrella may also BROADEN coverage to claims the underlying policy excludes; excess liability only extends limits without broadening.", "audio_front": "Umbrella versus excess liability coverage. What is the difference?", "audio_back": "Both sit above underlying policy limits. An umbrella may also broaden coverage to claims the underlying policy excludes. Excess liability only extends the limits without broadening coverage.", "source": "Insurance practice", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-068", "deck": "rb", "section": "bl", "category": "Contracts", "front": "NUMBER DRILL: HIFA trigger, HIFA rescission, HSSA cancellation, HSSA refund.", "back": "HIFA trigger: cash price over $300 on installment credit. HIFA rescission: 5 p.m. next business day. HSSA cancellation: midnight of the 3rd business day. HSSA refund: 10 business days.", "audio_front": "Number drill. HIFA trigger, HIFA rescission, H S S A cancellation, H S S A refund.", "audio_back": "HIFA trigger: cash price over three hundred dollars on installment credit. HIFA rescission: five P M of the next business day. Home solicitation cancellation: midnight of the third business day. Refund after cancellation: ten business days.", "source": "MCL 445.1102; MCL 445.1202; MCL 445.112; MCL 445.113", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-069", "deck": "rb", "section": "bl", "category": "Contracts", "front": "NUMBER DRILL: contract SOL, negligence SOL, repose, gross-negligence window, repose cap.", "back": "Contract: 6 years (MCL 600.5807(9)). Negligence: 3 years (MCL 600.5805(2)). Repose: 6 years from occupancy/use/acceptance (MCL 600.5839(1)(a)). Gross negligence: 1 year after discovery, 10-year absolute cap (MCL 600.5839(1)(b)).", "audio_front": "Number drill. Contract statute of limitations, negligence statute of limitations, statute of repose, gross negligence window, and repose cap.", "audio_back": "Contract: six years. Negligence: three years. Repose: six years from occupancy, use, or acceptance. Gross negligence: one year after discovery, with a ten year absolute cap.", "source": "MCL 600.5807(9); MCL 600.5805(2); MCL 600.5839", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-070", "deck": "rb", "section": "bl", "category": "Contracts", "front": "TRAP: 'Any home improvement contract over $600 must be in writing under HIFA.' What is wrong with this statement?", "back": "Everything. HIFA's trigger is a cash price OVER $300 on installment credit, not $600; HIFA does not impose a general written-contract rule for cash jobs; and $600 is the MCL 339.2403 licensure exemption. The written-contract rule that matters for lien rights is MCL 570.1114, at any amount.", "audio_front": "Trap question. Any home improvement contract over six hundred dollars must be in writing under HIFA. What is wrong with this statement?", "audio_back": "Everything. HIFA's trigger is a cash price over three hundred dollars on installment credit, not six hundred. HIFA does not impose a general written contract rule for cash jobs. And six hundred dollars is the licensure exemption in M C L three thirty nine point twenty four oh three. The written contract rule that matters for lien rights is M C L five seventy point eleven fourteen, at any amount.", "source": "MCL 445.1102; MCL 339.2403; MCL 570.1114", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-071", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Scenario: A siding contractor door-knocks after a storm, signs a $9,000 installment-financed contract at the kitchen table. Which consumer statutes apply?", "back": "Both: HSSA (seller-solicited sale at the residence — 3-business-day cancellation) and HIFA (installment financing over $300 — contract form/content rules and next-business-day rescission). MCL 570.1114 also governs lien rights.", "audio_front": "Scenario. A siding contractor door knocks after a storm and signs a nine thousand dollar installment financed contract at the kitchen table. Which consumer statutes apply?", "audio_back": "Both. The Home Solicitation Sales Act, because it is a seller solicited sale at the residence, giving a three business day cancellation right. And HIFA, because it is installment financing over three hundred dollars, imposing contract form and content rules plus a next business day rescission right. The Construction Lien Act written contract rule also governs lien rights.", "source": "MCL 445.111–117; MCL 445.1101 et seq.; MCL 570.1114", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-072", "deck": "rb", "section": "bl", "category": "Contracts", "front": "May a HIFA contract include a provision authorizing the holder to accelerate the balance at will?", "back": "No — arbitrary acceleration without reasonable cause, absent buyer default, is a prohibited provision (MCL 445.1206(1)(b)). The provision is void; the rest of the contract survives.", "audio_front": "May a HIFA contract include a provision authorizing the holder to accelerate the balance at will?", "audio_back": "No. Arbitrary acceleration without reasonable cause, absent buyer default, is a prohibited provision under M C L four forty five point twelve oh six. The provision is void, but the rest of the contract survives.", "source": "MCL 445.1206(1)(b)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-073", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Under HIFA, what happens if one installment payment is substantially larger than the others (a balloon)?", "back": "The contract must carry a legend in 10-point bold or typewritten and underlined: 'This contract is not payable in installments of equal amounts,' stating the larger installment amounts and due dates (MCL 445.1203(k)).", "audio_front": "Under HIFA, what happens if one installment payment is substantially larger than the others, a balloon payment?", "audio_back": "The contract must carry a legend in ten point bold, or typewritten and underlined, stating: this contract is not payable in installments of equal amounts, and listing the larger installment amounts and due dates. M C L four forty five point twelve oh three.", "source": "MCL 445.1203(k)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-074", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Can a buyer waive the protections of HIFA by contract?", "back": "No — MCL 445.1409 provides that a buyer's waiver of the act's protections is unenforceable, and MCL 445.1206 voids contract terms waiving claims and defenses.", "audio_front": "Can a buyer waive the protections of HIFA by contract?", "audio_back": "No. M C L four forty five point fourteen oh nine makes a buyer's waiver of the act's protections unenforceable, and section twelve oh six voids contract terms waiving claims and defenses.", "source": "MCL 445.1409; MCL 445.1206", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-075", "deck": "rb", "section": "bl", "category": "Contracts", "front": "Does an Assignment of Benefits (AOB) or carrier direct-pay arrangement replace the MCL 570.1114 written-contract requirements?", "back": "No. The contractor-homeowner agreement must still be written, include the licensing statement and license number, and use written change orders to preserve residential lien rights — regardless of how payment flows.", "audio_front": "Does an assignment of benefits or carrier direct pay arrangement replace the written contract requirements of M C L five seventy point eleven fourteen?", "audio_back": "No. The contractor and homeowner agreement must still be written, include the licensing statement and license number, and use written change orders to preserve residential lien rights, regardless of how payment flows.", "source": "MCL 570.1114", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-076", "deck": "rb", "section": "bl", "category": "Contracts", "front": "An assignee (finance company) buys a HIFA installment contract. Can it collect free of the buyer's defenses against the contractor?", "back": "No. The holder is subject to the claims and defenses of the buyer arising from the sale (MCL 445.1207), and the buyer cannot be made to waive them (MCL 445.1206(1)(a)).", "audio_front": "An assignee finance company buys a HIFA installment contract. Can it collect free of the buyer's defenses against the contractor?", "audio_back": "No. The holder is subject to the claims and defenses of the buyer arising from the sale, under M C L four forty five point twelve oh seven, and the buyer cannot be made to waive them.", "source": "MCL 445.1207; MCL 445.1206(1)(a)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-077", "deck": "rb", "section": "bl", "category": "Contracts", "front": "TRAP: Which runs to 'midnight' and which runs to '5 p.m.' — HSSA cancellation or HIFA rescission?", "back": "HSSA: midnight of the third business day. HIFA: 5 p.m. of the first business day after the contract date. Swapping these is a classic exam trap.", "audio_front": "Trap question. Which deadline runs to midnight and which runs to five P M, the home solicitation cancellation or the HIFA rescission?", "audio_back": "The home solicitation cancellation runs to midnight of the third business day. The HIFA rescission runs to five P M of the first business day after the contract date. Swapping these is a classic exam trap.", "source": "MCL 445.112(1); MCL 445.1202(c)(4)", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-078", "deck": "rb", "section": "bl", "category": "Contracts", "front": "A contract is missing 'capacity' — one signer is a minor. What is the contract's status?", "back": "Voidable at the option of the party lacking capacity. A voidable contract can be affirmed or disaffirmed by the protected party; a void contract (e.g., illegal purpose) is unenforceable by anyone.", "audio_front": "A contract is missing capacity, because one signer is a minor. What is the contract's status?", "audio_back": "It is voidable at the option of the party lacking capacity. A voidable contract can be affirmed or disaffirmed by the protected party. A void contract, such as one with an illegal purpose, is unenforceable by anyone.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-079", "deck": "rb", "section": "bl", "category": "Contracts", "front": "What duty does the non-breaching party have after the other side breaches?", "back": "The duty to mitigate — take reasonable steps to limit the loss. Damages that could have been reasonably avoided are not recoverable.", "audio_front": "What duty does the non breaching party have after the other side breaches?", "audio_back": "The duty to mitigate. Take reasonable steps to limit the loss. Damages that could have been reasonably avoided are not recoverable.", "source": "General contract law", "domain": "03_contracts-hifa"}, {"id": "contracts-hifa-080", "deck": "rb", "section": "bl", "category": "Contracts", "front": "NUMBER DRILL: HIFA type sizes, HIFA penalty, HSSA goods-pickup window.", "back": "HIFA: 8-point minimum body type; 10-point bold heading and notices. Penalty: misdemeanor, 90 days/$500 first offense. HSSA: seller has 20 days to pick up goods after cancellation or the buyer keeps them.", "audio_front": "Number drill. HIFA type sizes, HIFA penalty, and the goods pickup window after cancellation.", "audio_back": "HIFA: eight point minimum body type, ten point bold for the heading and notices. Penalty: misdemeanor, up to ninety days or five hundred dollars for a first offense. And the seller has twenty days to pick up goods after cancellation, or the buyer keeps them.", "source": "MCL 445.1201–.1202; MCL 445.1421; MCL 445.113(2)", "domain": "03_contracts-hifa"}, {"id": "business-management-001", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "Which business entity offers NO liability protection and requires no state filing?", "back": "Sole proprietorship. The owner is personally liable for all business debts and judgments; profit is reported on Schedule C of the owner's 1040.", "audio_front": "Which business entity offers no liability protection and requires no state filing?", "audio_back": "The sole proprietorship. The owner is personally liable for all business debts and judgments, and profit is reported on Schedule C of the owner's ten forty.", "source": "IRS / general business law", "domain": "04_business-management"}, {"id": "business-management-002", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "In a general partnership, what is each partner's liability for partnership debts?", "back": "Unlimited, joint and several — any one partner can be held liable for the full partnership debt, including debts created by the other partner.", "audio_front": "In a general partnership, what is each partner's liability for partnership debts?", "audio_back": "Unlimited, joint and several. Any one partner can be held liable for the full partnership debt, including debts created by the other partner.", "source": "general partnership law", "domain": "04_business-management"}, {"id": "business-management-003", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "What document is filed with LARA to create a Michigan LLC?", "back": "Articles of Organization. (A corporation files Articles of Incorporation.)", "audio_front": "What document is filed with LARA to create a Michigan L L C?", "audio_back": "Articles of Organization. A corporation instead files Articles of Incorporation.", "source": "MI Limited Liability Company Act", "domain": "04_business-management"}, {"id": "business-management-004", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "When is a Michigan LLC's Annual Statement due, and what is the fee?", "back": "February 15 each year, $25 fee, filed with LARA (MCL 450.4207). An LLC formed after September 30 skips the immediately following February 15.", "audio_front": "When is a Michigan L L C's annual statement due, and what is the fee?", "audio_back": "February fifteenth each year, with a twenty five dollar fee, filed with LARA under M C L four fifty point four two zero seven. An L L C formed after September thirtieth skips the immediately following February fifteenth.", "source": "MCL 450.4207", "domain": "04_business-management"}, {"id": "business-management-005", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "TRAP: Does a Michigan LLC automatically dissolve if it misses its Annual Statement?", "back": "No. After roughly 2 years of non-filing it falls to 'not in good standing' status, which is restorable — not automatic dissolution.", "audio_front": "Trap question. Does a Michigan L L C automatically dissolve if it misses its annual statement?", "audio_back": "No. After roughly two years of non filing it falls to not in good standing status, which is restorable. It is not automatic dissolution.", "source": "MCL 450.4207 / LARA", "domain": "04_business-management"}, {"id": "business-management-006", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "How is S-corporation status obtained?", "back": "By federal IRS election (Form 2553) — it is not a separate Michigan filing. Requirements: 100 or fewer shareholders, one class of stock, US-person shareholders.", "audio_front": "How is S corporation status obtained?", "audio_back": "By federal I R S election on form twenty five fifty three. It is not a separate Michigan filing. Requirements are one hundred or fewer shareholders, one class of stock, and U S person shareholders.", "source": "IRC Subchapter S / IRS Form 2553", "domain": "04_business-management"}, {"id": "business-management-007", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "Which entity type is subject to 'double taxation,' and what does that mean?", "back": "C-corporation: the corporation pays income tax on profits, then shareholders pay tax again on dividends.", "audio_front": "Which entity type is subject to double taxation, and what does that mean?", "audio_back": "The C corporation. The corporation pays income tax on its profits, then shareholders pay tax again on dividends they receive.", "source": "IRC Subchapter C", "domain": "04_business-management"}, {"id": "business-management-008", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "What is the key tax difference between an LLC taxed as default vs. an S-corp election?", "back": "Default LLC profit passes through and is all subject to self-employment tax; with an S-corp election the owner takes a reasonable W-2 salary (payroll-taxed) and remaining profit passes through free of SE tax.", "audio_front": "What is the key tax difference between a default taxed L L C and an S corp election?", "audio_back": "Default L L C profit passes through and is all subject to self employment tax. With an S corp election the owner takes a reasonable W two salary that is payroll taxed, and the remaining profit passes through free of self employment tax.", "source": "IRS pass-through rules", "domain": "04_business-management"}, {"id": "business-management-009", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "Name three practices that preserve the LLC/corporate liability shield ('the veil').", "back": "Separate business bank accounts (no commingling), adequate capitalization, and signing all contracts in the entity's name with proper documentation.", "audio_front": "Name three practices that preserve the L L C or corporate liability shield, known as the veil.", "audio_back": "Separate business bank accounts with no commingling of funds, adequate capitalization, and signing all contracts in the entity's name with proper documentation.", "source": "general corporate law", "domain": "04_business-management"}, {"id": "business-management-010", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "A builder wants pass-through taxation AND limited liability with the simplest structure. Which entity?", "back": "An LLC — limited liability with default pass-through taxation and minimal formalities. It is the most common choice for small Michigan builders.", "audio_front": "A builder wants pass through taxation and limited liability with the simplest structure. Which entity?", "audio_back": "An L L C. It gives limited liability with default pass through taxation and minimal formalities, and is the most common choice for small Michigan builders.", "source": "general business law", "domain": "04_business-management"}, {"id": "business-management-011", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "Who is liable for business debts in a sole proprietorship vs. an LLC?", "back": "Sole prop: the owner personally, without limit — home, savings, everything. LLC: only business assets are at risk if the veil is maintained.", "audio_front": "Who is liable for business debts in a sole proprietorship versus an L L C?", "audio_back": "In a sole proprietorship the owner is personally liable without limit, including home and savings. In an L L C only business assets are at risk, as long as the veil is maintained.", "source": "general business law", "domain": "04_business-management"}, {"id": "business-management-012", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "What is a DBA / assumed name, and where does a sole proprietor file it in Michigan?", "back": "A trade name different from the owner's legal name; a sole proprietor files an assumed-name certificate with the county clerk. It creates no liability protection.", "audio_front": "What is a D B A or assumed name, and where does a sole proprietor file it in Michigan?", "audio_back": "A trade name different from the owner's legal name. A sole proprietor files an assumed name certificate with the county clerk. It creates no liability protection.", "source": "MI assumed-name statutes", "domain": "04_business-management"}, {"id": "business-management-013", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "State the basic accounting equation.", "back": "Assets = Liabilities + Owner's Equity. It must always balance — it is the structure of the balance sheet.", "audio_front": "State the basic accounting equation.", "audio_back": "Assets equal liabilities plus owner's equity. It must always balance, and it is the structure of the balance sheet.", "source": "GAAP", "domain": "04_business-management"}, {"id": "business-management-014", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "Cash basis vs. accrual basis — when is income recorded under each?", "back": "Cash basis: when money is actually received (expenses when paid). Accrual: when income is EARNED/billed and expenses when INCURRED — required for accurate job costing.", "audio_front": "Cash basis versus accrual basis. When is income recorded under each?", "audio_back": "Under cash basis, income is recorded when money is actually received and expenses when paid. Under accrual, income is recorded when earned or billed and expenses when incurred, which is required for accurate job costing.", "source": "GAAP", "domain": "04_business-management"}, {"id": "business-management-015", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "Balance sheet vs. income statement (P&L) — what period does each cover?", "back": "Balance sheet = snapshot at a single point in time. Income statement = performance over a PERIOD (month, quarter, year). Profit appears on the P&L, not the balance sheet.", "audio_front": "Balance sheet versus income statement. What period does each cover?", "audio_back": "The balance sheet is a snapshot at a single point in time. The income statement shows performance over a period such as a month, quarter, or year. Profit appears on the income statement, not the balance sheet.", "source": "GAAP", "domain": "04_business-management"}, {"id": "business-management-016", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "On a contractor's P&L: revenue − direct job costs = ? And that figure minus overhead = ?", "back": "Revenue minus direct costs = GROSS profit. Gross profit minus overhead (G&A) = NET profit.", "audio_front": "On a contractor's profit and loss statement, revenue minus direct job costs equals what? And that figure minus overhead equals what?", "audio_back": "Revenue minus direct costs equals gross profit. Gross profit minus overhead, or general and administrative expense, equals net profit.", "source": "GAAP", "domain": "04_business-management"}, {"id": "business-management-017", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "MATH: Cost is $100,000 with a 25% markup. What are the selling price and the actual profit margin?", "back": "Price = $125,000; profit $25,000; margin = 25,000/125,000 = 20%. A 25% markup is a 20% margin.", "audio_front": "Math drill. Cost is one hundred thousand dollars with a twenty five percent markup. What are the selling price and the actual profit margin?", "audio_back": "The price is one hundred twenty five thousand dollars, profit is twenty five thousand, and the margin is twenty percent. A twenty five percent markup is a twenty percent margin.", "source": "markup/margin math", "domain": "04_business-management"}, {"id": "business-management-018", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "Give the conversion formulas between markup and margin.", "back": "Margin = Markup ÷ (1 + Markup). Markup = Margin ÷ (1 − Margin). Price = Cost × (1 + markup) or Cost ÷ (1 − margin).", "audio_front": "Give the conversion formulas between markup and margin.", "audio_back": "Margin equals markup divided by one plus markup. Markup equals margin divided by one minus margin. Price equals cost times one plus markup, or cost divided by one minus margin.", "source": "markup/margin math", "domain": "04_business-management"}, {"id": "business-management-019", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "TRAP: To earn a 20% profit MARGIN on a $80,000 cost job, what do you do — and what is the price?", "back": "Divide by (1 − 0.20): $80,000 ÷ 0.80 = $100,000. Multiplying by 1.20 ($96,000) yields only a 16.7% margin — the classic trap.", "audio_front": "Trap question. To earn a twenty percent profit margin on an eighty thousand dollar cost job, what do you do, and what is the price?", "audio_back": "Divide by one minus point two zero. Eighty thousand divided by point eight equals one hundred thousand dollars. Multiplying by one point two gives ninety six thousand, which yields only a sixteen point seven percent margin. That is the classic trap.", "source": "markup/margin math", "domain": "04_business-management"}, {"id": "business-management-020", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "The Xactimate '10 and 10' overhead and profit — what actual margin does it produce?", "back": "10% + 10% = 20% markup on cost, which is a 16.67% margin of the selling price — not 20%.", "audio_front": "The ten and ten overhead and profit standard. What actual margin does it produce?", "audio_back": "Ten percent plus ten percent is a twenty percent markup on cost, which works out to a sixteen point six seven percent margin of the selling price, not twenty percent.", "source": "markup/margin math", "domain": "04_business-management"}, {"id": "business-management-021", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "MATH: Annual overhead $126,000; expected direct costs $840,000. What overhead rate applies to each job?", "back": "$126,000 ÷ $840,000 = 15%. Every dollar of direct cost must carry 15 cents of overhead just to break even.", "audio_front": "Math drill. Annual overhead is one hundred twenty six thousand dollars and expected direct costs are eight hundred forty thousand dollars. What overhead rate applies to each job?", "audio_back": "One hundred twenty six thousand divided by eight hundred forty thousand equals fifteen percent. Every dollar of direct cost must carry fifteen cents of overhead just to break even.", "source": "job costing math", "domain": "04_business-management"}, {"id": "business-management-022", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "MATH: Fixed overhead is $150,000 and gross margin is 30%. What is break-even revenue?", "back": "$150,000 ÷ 0.30 = $500,000. Break-even revenue = fixed costs ÷ gross margin percentage.", "audio_front": "Math drill. Fixed overhead is one hundred fifty thousand dollars and gross margin is thirty percent. What is break even revenue?", "audio_back": "One hundred fifty thousand divided by point three equals five hundred thousand dollars. Break even revenue equals fixed costs divided by gross margin percentage.", "source": "break-even math", "domain": "04_business-management"}, {"id": "business-management-023", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "Define accounts receivable vs. accounts payable.", "back": "AR = money owed TO the contractor by customers. AP = money the contractor owes suppliers/subs. High AR with low cash = profitable on paper but cash-poor — a leading cause of contractor failure.", "audio_front": "Define accounts receivable versus accounts payable.", "audio_back": "Accounts receivable is money owed to the contractor by customers. Accounts payable is money the contractor owes suppliers and subs. High receivables with low cash means profitable on paper but cash poor, a leading cause of contractor failure.", "source": "GAAP", "domain": "04_business-management"}, {"id": "business-management-024", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "What is underbilling, and why is it dangerous?", "back": "Work completed exceeds amounts billed — the contractor is financing the owner's project. It drains cash flow; a profitable job can still sink the company if cash runs out.", "audio_front": "What is underbilling, and why is it dangerous?", "audio_back": "Underbilling means work completed exceeds amounts billed, so the contractor is financing the owner's project. It drains cash flow. A profitable job can still sink the company if cash runs out.", "source": "construction accounting", "domain": "04_business-management"}, {"id": "business-management-025", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "What is the current ratio and what does it measure?", "back": "Current assets ÷ current liabilities. It measures liquidity — the ability to pay bills due within a year. Above 1.0 means current obligations are covered.", "audio_front": "What is the current ratio and what does it measure?", "audio_back": "Current assets divided by current liabilities. It measures liquidity, the ability to pay bills due within a year. A ratio above one point zero means current obligations are covered.", "source": "GAAP", "domain": "04_business-management"}, {"id": "business-management-026", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "Percentage-of-completion vs. completed-contract accounting — what's the difference?", "back": "Percentage-of-completion recognizes revenue progressively as work is performed (usually by cost-to-cost). Completed-contract defers all revenue and profit until the project is finished.", "audio_front": "Percentage of completion versus completed contract accounting. What is the difference?", "audio_back": "Percentage of completion recognizes revenue progressively as work is performed, usually measured cost to cost. Completed contract defers all revenue and profit until the project is finished.", "source": "GAAP long-term contract methods", "domain": "04_business-management"}, {"id": "business-management-027", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "Direct costs vs. indirect costs (overhead) — give examples of each.", "back": "Direct: job labor, materials, subcontracts, equipment for a specific project. Indirect/overhead: office rent, admin salaries, insurance, vehicles, marketing — costs of running the business not traceable to one job.", "audio_front": "Direct costs versus indirect costs or overhead. Give examples of each.", "audio_back": "Direct costs are job labor, materials, subcontracts, and equipment for a specific project. Indirect or overhead costs are office rent, administrative salaries, insurance, vehicles, and marketing. Those are costs of running the business not traceable to one job.", "source": "job costing", "domain": "04_business-management"}, {"id": "business-management-028", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "What is variance analysis in job costing?", "back": "Comparing actual job costs to the estimate. Favorable = under estimate; unfavorable = over. Investigate variances beyond roughly plus-or-minus 5-10% to improve future estimates.", "audio_front": "What is variance analysis in job costing?", "audio_back": "Comparing actual job costs to the estimate. Favorable means under the estimate, unfavorable means over. Investigate variances beyond roughly plus or minus five to ten percent to improve future estimates.", "source": "job costing", "domain": "04_business-management"}, {"id": "business-management-029", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "What is the Michigan sales tax rate, and how does it apply to a construction contract?", "back": "6%. The contractor pays sales tax on materials at purchase; installation labor is exempt; the contractor does NOT charge sales tax on the contract price to the homeowner.", "audio_front": "What is the Michigan sales tax rate, and how does it apply to a construction contract?", "audio_back": "Six percent. The contractor pays sales tax on materials at purchase. Installation labor is exempt. The contractor does not charge sales tax on the contract price to the homeowner.", "source": "MI General Sales Tax Act", "domain": "04_business-management"}, {"id": "business-management-030", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "SCENARIO: A builder sells leftover cabinets to a neighbor without installing them. Sales tax?", "back": "Yes — selling materials WITHOUT installation is a retail sale, and 6% Michigan sales tax applies. Installed under a construction contract, the contractor is the consumer and pays tax at purchase instead.", "audio_front": "Scenario. A builder sells leftover cabinets to a neighbor without installing them. Does sales tax apply?", "audio_back": "Yes. Selling materials without installation is a retail sale, and six percent Michigan sales tax applies. When installed under a construction contract, the contractor is the consumer and pays tax at purchase instead.", "source": "MI General Sales Tax Act", "domain": "04_business-management"}, {"id": "business-management-031", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "What is the critical path in a CPM schedule?", "back": "The longest sequence of dependent tasks — it sets the minimum project duration. Any delay to a critical-path task delays the whole project; critical tasks have zero float.", "audio_front": "What is the critical path in a C P M schedule?", "audio_back": "The longest sequence of dependent tasks. It sets the minimum project duration. Any delay to a critical path task delays the whole project, and critical tasks have zero float.", "source": "CPM scheduling", "domain": "04_business-management"}, {"id": "business-management-032", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "Define float (slack). What is the float of a critical-path task?", "back": "Float = time a task can slip without delaying project completion. Total float affects the end date; free float affects successors. Critical-path tasks have ZERO float.", "audio_front": "Define float, also called slack. What is the float of a critical path task?", "audio_back": "Float is the time a task can slip without delaying project completion. Total float affects the end date, free float affects successor tasks. Critical path tasks have zero float.", "source": "CPM scheduling", "domain": "04_business-management"}, {"id": "business-management-033", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "What is a Gantt (bar) chart, and what does it NOT show?", "back": "A horizontal bar chart of tasks vs. time showing start, duration, and finish — the standard residential scheduling visual. It does not inherently show task dependencies; CPM network diagrams do.", "audio_front": "What is a Gantt or bar chart, and what does it not show?", "audio_back": "A horizontal bar chart of tasks against time showing start, duration, and finish. It is the standard residential scheduling visual, but it does not inherently show task dependencies. C P M network diagrams do.", "source": "scheduling", "domain": "04_business-management"}, {"id": "business-management-034", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "What is lead time, and how does a scheduler handle long-lead items?", "back": "Time to procure materials or approvals before work can start (custom windows can run 6-12 weeks). Identify long-lead items at project start and order them early.", "audio_front": "What is lead time, and how does a scheduler handle long lead items?", "audio_back": "Lead time is the time to procure materials or approvals before work can start. Custom windows can run six to twelve weeks. Identify long lead items at project start and order them early.", "source": "scheduling", "domain": "04_business-management"}, {"id": "business-management-035", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "Substantial completion vs. final completion — and what does substantial completion trigger?", "back": "Substantial = owner can use the work for its intended purpose; triggers the punch list, warranty start, and release of most retainage. Final = all work including punch list is done.", "audio_front": "Substantial completion versus final completion, and what does substantial completion trigger?", "audio_back": "Substantial completion means the owner can use the work for its intended purpose. It triggers the punch list, the warranty start, and release of most retainage. Final completion means all work including the punch list is done.", "source": "construction contract practice", "domain": "04_business-management"}, {"id": "business-management-036", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "What is a punch list and who pays to correct the items on it?", "back": "A list of incomplete or defective items identified at the substantial-completion walkthrough. The contractor corrects them at no extra charge — they were in the original scope.", "audio_front": "What is a punch list and who pays to correct the items on it?", "audio_back": "A list of incomplete or defective items identified at the substantial completion walkthrough. The contractor corrects them at no extra charge because they were in the original scope.", "source": "construction contract practice", "domain": "04_business-management"}, {"id": "business-management-037", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "Name the three construction bond types and what each guarantees.", "back": "Bid bond — contractor honors the bid (typically 5-10% of bid). Performance bond — contractor completes the work (typically 100% of contract). Payment bond — subs and suppliers get paid.", "audio_front": "Name the three construction bond types and what each guarantees.", "audio_back": "The bid bond guarantees the contractor honors the bid, typically five to ten percent of the bid. The performance bond guarantees the contractor completes the work, typically one hundred percent of the contract. The payment bond guarantees subs and suppliers get paid.", "source": "surety practice", "domain": "04_business-management"}, {"id": "business-management-038", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "TRAP: Which bond protects subcontractors and material suppliers — performance or payment?", "back": "The PAYMENT bond. The performance bond protects the owner by guaranteeing project completion. They are usually issued together.", "audio_front": "Trap question. Which bond protects subcontractors and material suppliers, performance or payment?", "audio_back": "The payment bond. The performance bond protects the owner by guaranteeing project completion. They are usually issued together.", "source": "surety practice", "domain": "04_business-management"}, {"id": "business-management-039", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "Who are the three parties to a surety bond?", "back": "Principal (the contractor), obligee (the owner/party protected), and surety (the company guaranteeing performance).", "audio_front": "Who are the three parties to a surety bond?", "audio_back": "The principal, who is the contractor. The obligee, who is the owner or protected party. And the surety, the company guaranteeing performance.", "source": "surety practice", "domain": "04_business-management"}, {"id": "business-management-040", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "What is retainage, and what is typical on residential work?", "back": "A percentage withheld from each progress payment until substantial or final completion — typically 5-10%. Michigan has no statutory retainage cap on private residential projects.", "audio_front": "What is retainage, and what is typical on residential work?", "audio_back": "A percentage withheld from each progress payment until substantial or final completion, typically five to ten percent. Michigan has no statutory retainage cap on private residential projects.", "source": "construction contract practice", "domain": "04_business-management"}, {"id": "business-management-041", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "MATH: A $50,000 draw with 10% retainage — how much does the builder receive?", "back": "$50,000 − $5,000 = $45,000. The $5,000 is held until substantial or final completion.", "audio_front": "Math drill. A fifty thousand dollar draw with ten percent retainage. How much does the builder receive?", "audio_back": "Fifty thousand minus five thousand equals forty five thousand dollars. The five thousand is held until substantial or final completion.", "source": "retainage math", "domain": "04_business-management"}, {"id": "business-management-042", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "What is a schedule of values, and what forms document a progress payment application?", "back": "The contract price broken into line items used as the billing basis. AIA G702 (Application and Certificate for Payment) summarizes; G703 (Continuation Sheet) shows line-by-line percent complete.", "audio_front": "What is a schedule of values, and what forms document a progress payment application?", "audio_back": "The contract price broken into line items used as the billing basis. A I A form G seven zero two, the application and certificate for payment, summarizes it. G seven zero three, the continuation sheet, shows line by line percent complete.", "source": "AIA G702/G703", "domain": "04_business-management"}, {"id": "business-management-043", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "Design a lien-safe residential draw schedule in outline.", "back": "Draws tied to completed milestones (about 10-15% mobilization, 20-25% foundation, 20-25% dry-in, 20-25% rough-ins, 15-20% final), each exchanged for a conditional lien waiver and sworn statement before funds release.", "audio_front": "Describe a lien safe residential draw schedule in outline.", "audio_back": "Draws tied to completed milestones. Roughly ten to fifteen percent at mobilization, twenty to twenty five percent at foundation, the same at dry in and rough ins, and fifteen to twenty percent at final. Each draw is exchanged for a conditional lien waiver and sworn statement before funds release.", "source": "MI Construction Lien Act practice", "domain": "04_business-management"}, {"id": "business-management-044", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "TRAP: A sub is handed a check and asked to sign a waiver before depositing it. Which waiver type is safe?", "back": "A CONDITIONAL waiver on progress payment — effective only when the payment clears. Never sign an unconditional waiver before the funds clear; it is effective immediately, paid or not.", "audio_front": "Trap question. A sub is handed a check and asked to sign a waiver before depositing it. Which waiver type is safe?", "audio_back": "A conditional waiver on progress payment, which is effective only when the payment clears. Never sign an unconditional waiver before the funds clear, because it is effective immediately whether or not you are paid.", "source": "MI lien waiver practice", "domain": "04_business-management"}, {"id": "business-management-045", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "What is a change order and what does Michigan practice require of it?", "back": "A written modification of scope, price, or schedule signed by owner and contractor. Changes to a home-improvement contract must be documented in writing — no verbal change orders.", "audio_front": "What is a change order and what does Michigan practice require of it?", "audio_back": "A written modification of scope, price, or schedule signed by both owner and contractor. Changes to a home improvement contract must be documented in writing. No verbal change orders.", "source": "contract practice", "domain": "04_business-management"}, {"id": "business-management-046", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "SCENARIO: Kitchen remodel, walls not yet opened, scope unknown. Best contract type?", "back": "Cost-plus with a not-to-exceed cap. Lump sum forces the contractor to absorb concealed conditions; unit price fits uncertain quantities of known work, not unknown scope.", "audio_front": "Scenario. A kitchen remodel where the walls are not yet opened and the scope is unknown. What is the best contract type?", "audio_back": "Cost plus with a not to exceed cap. Lump sum forces the contractor to absorb concealed conditions. Unit price fits uncertain quantities of known work, not unknown scope.", "source": "contract types", "domain": "04_business-management"}, {"id": "business-management-047", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "In which contract type does the CONTRACTOR bear the risk of cost overruns?", "back": "Lump sum (fixed price). In cost-plus and T&M the owner bears the cost risk; in unit price the owner bears quantity risk.", "audio_front": "In which contract type does the contractor bear the risk of cost overruns?", "audio_back": "Lump sum, also called fixed price. In cost plus and time and materials contracts the owner bears the cost risk. In unit price contracts the owner bears the quantity risk.", "source": "contract types", "domain": "04_business-management"}, {"id": "business-management-048", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "What is an allowance in a construction contract?", "back": "A dollar amount carried for an unselected item (e.g., $5,000 for countertops). Actual cost above the allowance is owed by the owner via change order; below it, the owner gets a credit.", "audio_front": "What is an allowance in a construction contract?", "audio_back": "A dollar amount carried for an item not yet selected, for example five thousand dollars for countertops. Actual cost above the allowance is owed by the owner through a change order. Below it, the owner gets a credit.", "source": "contract practice", "domain": "04_business-management"}, {"id": "business-management-049", "deck": "rb", "section": "bl", "category": "Estimating", "front": "MATH: How many board feet in a 2x6 that is 10 feet long?", "back": "(2 × 6 × 10) ÷ 12 = 10 board feet. Use NOMINAL dimensions in the formula.", "audio_front": "Math drill. How many board feet in a two by six that is ten feet long?", "audio_back": "Two times six times ten, divided by twelve, equals ten board feet. Use nominal dimensions in the formula.", "source": "board-foot math", "domain": "04_business-management"}, {"id": "business-management-050", "deck": "rb", "section": "bl", "category": "Estimating", "front": "MATH: Cubic yards of concrete for a 4-inch slab, 24 ft by 36 ft, with 10% waste?", "back": "24 × 36 × (4/12) = 288 CF; ÷27 = 10.67 CY; × 1.10 = about 11.7 CY — order 12.", "audio_front": "Math drill. How many cubic yards of concrete for a four inch slab, twenty four feet by thirty six feet, with ten percent waste?", "audio_back": "Twenty four times thirty six times one third of a foot equals two hundred eighty eight cubic feet. Divided by twenty seven, that is ten point six seven cubic yards. Times one point one for waste is about eleven point seven. Order twelve.", "source": "concrete takeoff math", "domain": "04_business-management"}, {"id": "business-management-051", "deck": "rb", "section": "bl", "category": "Estimating", "front": "How many square feet in a roofing 'square,' and what waste factor is typical for shingles?", "back": "1 square = 100 SF. Typical waste 10-15% on standard roofs, 15-20% on complex roofs with many hips/valleys.", "audio_front": "How many square feet are in a roofing square, and what waste factor is typical for shingles?", "audio_back": "One square equals one hundred square feet. Typical waste is ten to fifteen percent on standard roofs, and fifteen to twenty percent on complex roofs with many hips and valleys.", "source": "roofing takeoff", "domain": "04_business-management"}, {"id": "business-management-052", "deck": "rb", "section": "bl", "category": "Estimating", "front": "Give typical waste factors: framing lumber, drywall, concrete, engineered trusses.", "back": "Framing 10-15%; drywall 10-12%; concrete 5-10%; engineered trusses about 0% (pre-built).", "audio_front": "Give typical waste factors for framing lumber, drywall, concrete, and engineered trusses.", "audio_back": "Framing lumber ten to fifteen percent. Drywall ten to twelve percent. Concrete five to ten percent. Engineered trusses about zero percent because they arrive pre built.", "source": "estimating practice", "domain": "04_business-management"}, {"id": "business-management-053", "deck": "rb", "section": "bl", "category": "Estimating", "front": "What is a contingency, how big, and where in the estimate does it go?", "back": "A risk reserve for unforeseen conditions: 5-10% new construction, 10-20% renovation. It is applied BEFORE overhead/profit markup — it is not profit.", "audio_front": "What is a contingency, how big is it, and where in the estimate does it go?", "audio_back": "A risk reserve for unforeseen conditions. Five to ten percent on new construction, ten to twenty percent on renovation. It is applied before overhead and profit markup. It is not profit.", "source": "estimating practice", "domain": "04_business-management"}, {"id": "business-management-054", "deck": "rb", "section": "bl", "category": "Estimating", "front": "Rank the three estimate types by accuracy: conceptual/SF, detailed takeoff, unit price.", "back": "Conceptual/square-foot roughly ±20-30%; detailed quantity takeoff about ±5-10% (most accurate); unit-price accuracy depends on measured quantities.", "audio_front": "Rank the estimate types by accuracy. Conceptual square foot, detailed takeoff, and unit price.", "audio_back": "Conceptual or square foot estimates run plus or minus twenty to thirty percent. A detailed quantity takeoff is most accurate at about plus or minus five to ten percent. Unit price accuracy depends on measured quantities.", "source": "estimating practice", "domain": "04_business-management"}, {"id": "business-management-055", "deck": "rb", "section": "bl", "category": "Estimating", "front": "What is a labor productivity factor?", "back": "A multiplier on theoretical labor hours for real-world conditions — typically 1.1 to 1.5 in residential work. A 1.3 factor turns 10 theoretical hours into 13 actual.", "audio_front": "What is a labor productivity factor?", "audio_back": "A multiplier applied to theoretical labor hours to account for real world conditions, typically one point one to one point five in residential work. A factor of one point three turns ten theoretical hours into thirteen actual hours.", "source": "estimating practice", "domain": "04_business-management"}, {"id": "business-management-056", "deck": "rb", "section": "bl", "category": "Estimating", "front": "List the takeoff units for: lumber, concrete, roofing, trim, excavation.", "back": "Lumber = board feet; concrete = cubic yards (CF ÷ 27); roofing = squares (100 SF); trim = linear feet; excavation = cubic yards.", "audio_front": "List the takeoff units for lumber, concrete, roofing, trim, and excavation.", "audio_back": "Lumber is measured in board feet. Concrete in cubic yards, cubic feet divided by twenty seven. Roofing in squares of one hundred square feet. Trim in linear feet. Excavation in cubic yards.", "source": "estimating practice", "domain": "04_business-management"}, {"id": "business-management-057", "deck": "rb", "section": "bl", "category": "Personnel", "front": "What are the three categories of the IRS common-law test for employee vs. independent contractor?", "back": "Behavioral control, financial control, and the relationship of the parties. The detailed 20 factors come from Revenue Ruling 87-41.", "audio_front": "What are the three categories of the I R S common law test for employee versus independent contractor?", "audio_back": "Behavioral control, financial control, and the relationship of the parties. The detailed twenty factors come from revenue ruling eighty seven dash forty one.", "source": "IRS common-law test / Rev. Rul. 87-41", "domain": "04_business-management"}, {"id": "business-management-058", "deck": "rb", "section": "bl", "category": "Personnel", "front": "Which test decides employee status under Michigan workers comp law, and since when?", "back": "The IRS 20-factor test (Rev. Rul. 87-41), adopted by MCL 418.161(1)(n) for services on or after January 1, 2013. Federal income-tax withholding = prima facie employee.", "audio_front": "Which test decides employee status under Michigan workers comp law, and since when?", "audio_back": "The I R S twenty factor test from revenue ruling eighty seven dash forty one, adopted by M C L four eighteen point one six one, subsection one, paragraph n, for services on or after January first, twenty thirteen. Federal income tax withholding is prima facie evidence of employment.", "source": "MCL 418.161(1)(n)", "domain": "04_business-management"}, {"id": "business-management-059", "deck": "rb", "section": "bl", "category": "Personnel", "front": "What FICA rates do employer and employee each pay?", "back": "6.2% Social Security (up to the annual wage base) + 1.45% Medicare (no cap) = 7.65% each. Employees also owe 0.9% Additional Medicare over $200,000.", "audio_front": "What FICA rates do the employer and employee each pay?", "audio_back": "Six point two percent for social security up to the annual wage base, plus one point four five percent for medicare with no cap. That is seven point six five percent each. Employees also owe an additional zero point nine percent medicare tax over two hundred thousand dollars.", "source": "IRS payroll tax", "domain": "04_business-management"}, {"id": "business-management-060", "deck": "rb", "section": "bl", "category": "Personnel", "front": "FUTA: rate, wage base, and typical net rate?", "back": "6.0% on the first $7,000 of each employee's wages; with the full state credit the net rate is 0.6%. Employer-paid only.", "audio_front": "FUTA. What are the rate, the wage base, and the typical net rate?", "audio_back": "Six percent on the first seven thousand dollars of each employee's wages. With the full state credit the net rate is zero point six percent. It is paid by the employer only.", "source": "IRS FUTA", "domain": "04_business-management"}, {"id": "business-management-061", "deck": "rb", "section": "bl", "category": "Personnel", "front": "Why are withheld income tax and FICA called 'trust fund taxes'?", "back": "They are the employee's money held in trust for the IRS. Owners and responsible officers are PERSONALLY liable (Trust Fund Recovery Penalty) if the company fails to remit them.", "audio_front": "Why are withheld income tax and FICA called trust fund taxes?", "audio_back": "Because they are the employee's money held in trust for the I R S. Owners and responsible officers are personally liable under the trust fund recovery penalty if the company fails to remit them.", "source": "IRS TFRP", "domain": "04_business-management"}, {"id": "business-management-062", "deck": "rb", "section": "bl", "category": "Personnel", "front": "2026 CHANGE: What is the federal 1099-NEC reporting threshold for payments made in 2026?", "back": "$2,000 (raised from $600 by the 2025 OBBBA, indexed for inflation from 2027). Older prep materials still say $600 — know both numbers.", "audio_front": "Twenty twenty six change. What is the federal ten ninety nine N E C reporting threshold for payments made in twenty twenty six?", "audio_back": "Two thousand dollars, raised from six hundred dollars by the twenty twenty five federal tax law, and indexed for inflation from twenty twenty seven. Older prep materials still say six hundred dollars, so know both numbers.", "source": "PL 119-21 §70433 / 26 USC 6041(a)", "domain": "04_business-management"}, {"id": "business-management-063", "deck": "rb", "section": "bl", "category": "Personnel", "front": "Michigan UIA: what is the taxable wage base and the standard new-employer rate?", "back": "Statutory default wage base $9,500, reduced to $9,000 for qualified employers (reports filed, no unpaid balance) while the UIA Trust Fund exceeds $2.5B — $9,000 applies in 2025-2026. Standard new-employer rate 2.7% — but NOT for construction (see next card).", "audio_front": "Michigan unemployment insurance. What is the taxable wage base and the standard new employer rate?", "audio_back": "The statutory default wage base is nine thousand five hundred dollars, but it drops to nine thousand dollars for qualified employers while the trust fund is healthy — and nine thousand is the number that applies in twenty twenty five and twenty twenty six. The standard new employer rate is two point seven percent, but not for construction.", "source": "MI UIA", "domain": "04_business-management"}, {"id": "business-management-064", "deck": "rb", "section": "bl", "category": "Personnel", "front": "TRAP: What UIA rate does a NEW construction employer pay in Michigan?", "back": "Not 2.7%. New construction employers pay the average construction-industry rate, announced annually by the UIA (historically several times higher than 2.7%).", "audio_front": "Trap question. What unemployment tax rate does a new construction employer pay in Michigan?", "audio_back": "Not two point seven percent. New construction employers pay the average construction industry rate, announced annually by the U I A, which has historically been several times higher than two point seven percent.", "source": "MI UIA", "domain": "04_business-management"}, {"id": "business-management-065", "deck": "rb", "section": "bl", "category": "Personnel", "front": "Under the FLSA, when is overtime owed and at what rate?", "back": "1.5 times the regular rate for hours OVER 40 in a workweek. There is no federal daily overtime and no federal weekend/holiday premium as such.", "audio_front": "Under the Fair Labor Standards Act, when is overtime owed and at what rate?", "audio_back": "One and a half times the regular rate for hours over forty in a workweek. There is no federal daily overtime and no federal weekend or holiday premium as such.", "source": "29 USC 207", "domain": "04_business-management"}, {"id": "business-management-066", "deck": "rb", "section": "bl", "category": "Personnel", "front": "MIOSHA recordkeeping: who must keep the Form 300 log, and what are the posting/retention rules?", "back": "Employers with 11 or more employees keep the 300 injury/illness log; the 300A annual summary is posted February 1 through April 30; records are kept 5 years.", "audio_front": "MIOSHA recordkeeping. Who must keep the form three hundred log, and what are the posting and retention rules?", "audio_back": "Employers with eleven or more employees keep the three hundred injury and illness log. The three A annual summary is posted February first through April thirtieth, and records are kept five years.", "source": "MIOSHA recordkeeping rules", "domain": "04_business-management"}, {"id": "business-management-067", "deck": "rb", "section": "bl", "category": "Personnel", "front": "MIOSHA reporting deadlines: fatality vs. hospitalization/amputation/eye loss?", "back": "Work-related fatality: report within 8 HOURS. In-patient hospitalization, amputation, or loss of an eye: within 24 HOURS.", "audio_front": "MIOSHA reporting deadlines. Fatality versus hospitalization, amputation, or eye loss?", "audio_back": "A work related fatality must be reported within eight hours. An in patient hospitalization, amputation, or loss of an eye must be reported within twenty four hours.", "source": "MIOSHA / michigan.gov", "domain": "04_business-management"}, {"id": "business-management-068", "deck": "rb", "section": "bl", "category": "Personnel", "front": "State BOTH Michigan workers comp coverage triggers.", "back": "MCL 418.115: (a) regularly employ 3 or more employees at one time, OR (b) fewer than 3 if at least 1 employee worked 35+ hrs/week for 13+ weeks during the preceding 52 weeks. Either alone triggers coverage.", "audio_front": "State both Michigan workers compensation coverage triggers.", "audio_back": "Under M C L four eighteen point one one five. A, regularly employing three or more employees at one time. Or B, fewer than three, if at least one employee worked thirty five or more hours per week for thirteen weeks or longer during the preceding fifty two weeks. Either one alone triggers coverage.", "source": "MCL 418.115", "domain": "04_business-management"}, {"id": "business-management-069", "deck": "rb", "section": "bl", "category": "Personnel", "front": "Who may be EXCLUDED from Michigan workers comp coverage, and by what form?", "back": "Form WC-337 (Notice of Exclusion) with the WDCA: corporate officers owning 10%+ of a corporation with 10 or fewer stockholders; LLC member-managers owning 10%+ of an LLC with 10 or fewer members; partners.", "audio_front": "Who may be excluded from Michigan workers comp coverage, and by what form?", "audio_back": "Form W C three thirty seven, the notice of exclusion, filed with the workers disability compensation agency. Eligible are corporate officers owning ten percent or more of a corporation with ten or fewer stockholders, L L C member managers owning ten percent or more of an L L C with ten or fewer members, and partners.", "source": "WDCA / MCL 418.161", "domain": "04_business-management"}, {"id": "business-management-070", "deck": "rb", "section": "bl", "category": "Personnel", "front": "SCENARIO: Your drywall sub has employees but no WC certificate and no WC-337 on file. His worker is injured on your site. Who pays?", "back": "You — the general contractor — become legally responsible for the claim (statutory-principal liability, MCL 418.171). Always collect a WC certificate or valid exclusion before a sub starts.", "audio_front": "Scenario. Your drywall sub has employees but no workers comp certificate and no exclusion form on file. His worker is injured on your site. Who pays?", "audio_back": "You do. The general contractor becomes legally responsible for the claim under statutory principal liability, M C L four eighteen point one seven one. Always collect a workers comp certificate or a valid exclusion form before a sub starts.", "source": "MCL 418.171", "domain": "04_business-management"}, {"id": "business-management-071", "deck": "rb", "section": "bl", "category": "Personnel", "front": "Penalties for operating without required workers comp in Michigan?", "back": "Misdemeanor: fine up to $1,000 and/or up to 6 months, each day a separate offense (MCL 418.641(1)); plus circuit-court injunction and civil fine up to $1,000/day with a 3-year lookback (MCL 418.645). The uninsured employer also loses exclusive-remedy protection.", "audio_front": "What are the penalties for operating without required workers comp in Michigan?", "audio_back": "It is a misdemeanor with a fine up to one thousand dollars and or up to six months in jail, and each day is a separate offense, under M C L four eighteen point six four one. Enforcement adds a circuit court injunction and a civil fine of up to one thousand dollars per day with a three year lookback under M C L four eighteen point six four five. The uninsured employer also loses exclusive remedy protection.", "source": "MCL 418.641 / 418.645", "domain": "04_business-management"}, {"id": "business-management-072", "deck": "rb", "section": "bl", "category": "Personnel", "front": "What is the exclusive remedy doctrine, and what is the big exception for uninsured employers?", "back": "WC benefits are generally the injured employee's ONLY remedy — no lawsuit against the employer. But if the employer failed to carry required coverage, the employee MAY sue civilly (MCL 418.641(2)).", "audio_front": "What is the exclusive remedy doctrine, and what is the big exception for uninsured employers?", "audio_back": "Workers comp benefits are generally the injured employee's only remedy, meaning no lawsuit against the employer. But if the employer failed to carry required coverage, the employee may sue civilly under M C L four eighteen point six four one, subsection two.", "source": "MCL 418.131 / 418.641(2)", "domain": "04_business-management"}, {"id": "business-management-073", "deck": "rb", "section": "bl", "category": "Personnel", "front": "Which agency administers Michigan workers comp, and under which department?", "back": "The Workers' Disability Compensation Agency (WDCA), under the Department of Labor and Economic Opportunity (LEO) — NOT LARA.", "audio_front": "Which agency administers Michigan workers comp, and under which department?", "audio_back": "The Workers Disability Compensation Agency, under the Department of Labor and Economic Opportunity. Not LARA.", "source": "MCL 418.101 et seq. / LEO", "domain": "04_business-management"}, {"id": "business-management-074", "deck": "rb", "section": "bl", "category": "Personnel", "front": "What is the Experience Modification Rate (EMR)?", "back": "A multiplier on WC premium based on claims history vs. industry average. 1.0 = average; below 1.0 = better safety record and lower premium; above 1.0 = higher premium.", "audio_front": "What is the experience modification rate, or E M R?", "audio_back": "A multiplier on workers comp premium based on claims history versus the industry average. One point zero is average. Below one means a better safety record and a lower premium. Above one means a higher premium.", "source": "WC insurance practice", "domain": "04_business-management"}, {"id": "business-management-075", "deck": "rb", "section": "bl", "category": "Personnel", "front": "Name four benefit categories Michigan workers comp provides.", "back": "Medical treatment, wage-loss benefits, vocational rehabilitation, and death benefits to dependents. It is a no-fault system — negligence is irrelevant.", "audio_front": "Name four benefit categories Michigan workers comp provides.", "audio_back": "Medical treatment, wage loss benefits, vocational rehabilitation, and death benefits to dependents. It is a no fault system, so negligence is irrelevant.", "source": "MCL 418.101 et seq.", "domain": "04_business-management"}, {"id": "business-management-076", "deck": "rb", "section": "bl", "category": "Personnel", "front": "SCENARIO: A sole-proprietor painter with no employees subs for you. Must you collect a WC certificate from him?", "back": "No — a sole proprietor with no employees is not required to carry WC (he may elect it). You may still require coverage by contract as a risk-management practice.", "audio_front": "Scenario. A sole proprietor painter with no employees subs for you. Must you collect a workers comp certificate from him?", "audio_back": "No. A sole proprietor with no employees is not required to carry workers comp, though he may elect coverage. You may still require coverage by contract as a risk management practice.", "source": "MCL 418.115 / WDCA", "domain": "04_business-management"}, {"id": "business-management-077", "deck": "rb", "section": "bl", "category": "Accounting & Finance", "front": "MATH: A job bills $50,000; total costs are $42,500. What is the profit margin?", "back": "($50,000 − $42,500) ÷ $50,000 = 15%. Margin is always computed on the selling price.", "audio_front": "Math drill. A job bills fifty thousand dollars and total costs are forty two thousand five hundred. What is the profit margin?", "audio_back": "Fifty thousand minus forty two thousand five hundred, divided by fifty thousand, equals fifteen percent. Margin is always computed on the selling price.", "source": "margin math", "domain": "04_business-management"}, {"id": "business-management-078", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "TRAP: Michigan requires general liability insurance to hold an RB license — true or false?", "back": "False. No state-level GL minimum is required for RB licensure, but most municipalities require proof of insurance to pull permits; $1M/$2M is the industry standard.", "audio_front": "Trap question. Michigan requires general liability insurance to hold a residential builder license. True or false?", "audio_back": "False. No state level general liability minimum is required for the license, but most municipalities require proof of insurance to pull permits. One million per occurrence and two million aggregate is the industry standard.", "source": "LARA / municipal permit practice", "domain": "04_business-management"}, {"id": "business-management-079", "deck": "rb", "section": "bl", "category": "Types of Business Organization", "front": "W-2 employee vs. 1099 contractor — what does the EMPLOYER owe for each?", "back": "W-2: withhold income tax, pay employer half of FICA (7.65%), FUTA/SUTA, and WC coverage. 1099: none of those — the contractor pays self-employment tax — but misclassification triggers back taxes, penalties, and WC exposure.", "audio_front": "W two employee versus ten ninety nine contractor. What does the employer owe for each?", "audio_back": "For a W two employee, the employer withholds income tax, pays the employer half of FICA at seven point six five percent, pays federal and state unemployment tax, and provides workers comp coverage. For a ten ninety nine contractor, none of those apply and the contractor pays self employment tax. But misclassification triggers back taxes, penalties, and workers comp exposure.", "source": "IRS / MI UIA / WDCA", "domain": "04_business-management"}, {"id": "business-management-080", "deck": "rb", "section": "bl", "category": "Project Management & Administration", "front": "What documentation should a GC collect from EVERY subcontractor before work starts?", "back": "License verification (LARA lookup), certificate of general liability insurance naming the GC as additional insured, and a WC certificate or valid WC-337 exclusion.", "audio_front": "What documentation should a general contractor collect from every subcontractor before work starts?", "audio_back": "License verification through the LARA lookup, a certificate of general liability insurance naming the G C as additional insured, and a workers comp certificate or a valid W C three thirty seven exclusion.", "source": "risk-management practice", "domain": "04_business-management"}, {"id": "miosha-safety-001", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "What does MIOSHA stand for, and what statute created it?", "back": "Michigan Occupational Safety and Health Administration, created by the MIOSHA Act, Act 154 of 1974 (MCL 408.1001 et seq.).", "audio_front": "What does M I O S H A stand for, and what statute created it?", "audio_back": "Michigan Occupational Safety and Health Administration, created by the MIOSHA Act, Act one fifty four of nineteen seventy four, M C L 408 point 1001 and following.", "source": "MCL 408.1001", "domain": "05_miosha-safety"}, {"id": "miosha-safety-002", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Which state agency administers MIOSHA today?", "back": "LEO — the Department of Labor and Economic Opportunity (since Executive Order 2019-13, August 2019). Not LARA. Construction sites are enforced by the Construction Safety and Health Division (CSHD).", "audio_front": "Which state agency administers M I O S H A today?", "audio_back": "L E O, the Department of Labor and Economic Opportunity, since Executive Order twenty nineteen thirteen. Not LARA. Construction sites are enforced by the Construction Safety and Health Division.", "source": "EO 2019-13", "domain": "05_miosha-safety"}, {"id": "miosha-safety-003", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "What legal standard must a state OSHA plan like MIOSHA meet?", "back": "It must be 'at least as effective' as the federal OSHA program, per Section 18 of the federal OSH Act of 1970.", "audio_front": "What legal standard must a state O S H A plan like M I O S H A meet?", "audio_back": "It must be at least as effective as the federal O S H A program, under Section eighteen of the federal O S H Act of nineteen seventy.", "source": "OSH Act 1970 s.18", "domain": "05_miosha-safety"}, {"id": "miosha-safety-004", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Who does MIOSHA cover that federal OSHA does NOT?", "back": "Public-sector employees — state, county, and municipal workers. Federal OSHA covers only private employers and federal agencies.", "audio_front": "Who does M I O S H A cover that federal O S H A does not?", "audio_back": "Public sector employees. State, county, and municipal workers. Federal O S H A covers only private employers and federal agencies.", "source": "MIOSHA Act coverage", "domain": "05_miosha-safety"}, {"id": "miosha-safety-005", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "State the General Duty Clause and its Michigan citation.", "back": "MCL 408.1011: every employer must furnish each employee a workplace free from recognized hazards that are causing or likely to cause death or serious physical harm. It applies when no specific standard covers the hazard.", "audio_front": "State the General Duty Clause and its Michigan citation.", "audio_back": "M C L 408 point 1011. Every employer must furnish a workplace free from recognized hazards likely to cause death or serious physical harm. It applies when no specific standard covers the hazard.", "source": "MCL 408.1011", "domain": "05_miosha-safety"}, {"id": "miosha-safety-006", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Under MIOSHA Construction Part 1, what safety program must every construction employer have?", "back": "An accident prevention program, developed, maintained, and coordinated with employees (R 408.40114).", "audio_front": "Under M I O S H A Construction Part One, what safety program must every construction employer have?", "audio_back": "An accident prevention program, developed, maintained, and coordinated with employees, under rule R 408 point 40114.", "source": "R 408.40114", "domain": "05_miosha-safety"}, {"id": "miosha-safety-007", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "At what height is fall protection required on a construction site (general rule)?", "back": "6 feet above a lower level (MIOSHA Part 45, adopting federal Subpart M).", "audio_front": "At what height is fall protection required on a construction site, general rule?", "audio_back": "Six feet above a lower level, under M I O S H A Part forty five.", "source": "Part 45 / R 408.44502", "domain": "05_miosha-safety"}, {"id": "miosha-safety-008", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Name the three conventional fall protection systems.", "back": "Guardrail systems, safety net systems, and personal fall arrest systems (PFAS).", "audio_front": "Name the three conventional fall protection systems.", "audio_back": "Guardrail systems, safety net systems, and personal fall arrest systems.", "source": "Part 45", "domain": "05_miosha-safety"}, {"id": "miosha-safety-009", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Guardrail top rail: required height and strength?", "back": "42 inches plus or minus 3 inches above the walking surface, able to withstand a 200-pound force.", "audio_front": "Guardrail top rail. Required height and strength?", "audio_back": "Forty two inches, plus or minus three inches, above the walking surface, and able to withstand a two hundred pound force.", "source": "Part 45 (1926.502)", "domain": "05_miosha-safety"}, {"id": "miosha-safety-010", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Maximum free-fall distance in a personal fall arrest system?", "back": "6 feet, and the system must be rigged so the worker cannot contact a lower level. Anchorage: 5,000 pounds per attached worker.", "audio_front": "Maximum free fall distance in a personal fall arrest system?", "audio_back": "Six feet, and the system must be rigged so the worker cannot contact a lower level. Anchorage must hold five thousand pounds per attached worker.", "source": "Part 45 (1926.502(d))", "domain": "05_miosha-safety"}, {"id": "miosha-safety-011", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "TRAP: fall protection at 6 feet vs 10 feet — which applies where?", "back": "6 feet = general fall protection and leading edges (Part 45). 10 feet = guardrail on an open side or end of a scaffold platform (Part 12, R 408.41213).", "audio_front": "Trap question. Fall protection at six feet versus ten feet. Which applies where?", "audio_back": "Six feet is the general fall protection trigger under Part forty five. Ten feet is the scaffold platform guardrail trigger under Part twelve, rule R 408 point 41213.", "source": "R 408.41213 / Part 45", "domain": "05_miosha-safety"}, {"id": "miosha-safety-012", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "A roofer says guardrails and harnesses are infeasible at one spot on a residential roof. What is the lawful fallback?", "back": "A written, site-specific fall protection plan in lieu of conventional systems at that location, per Part 45.", "audio_front": "A roofer says guardrails and harnesses are infeasible at one spot on a residential roof. What is the lawful fallback?", "audio_back": "A written, site specific fall protection plan in place of conventional systems at that location, under Part forty five.", "source": "Part 45", "domain": "05_miosha-safety"}, {"id": "miosha-safety-013", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "What is the required angle (pitch) for a portable ladder?", "back": "4 to 1 — the horizontal distance from top support to base may not exceed one quarter of the vertical distance (R 408.41124).", "audio_front": "What is the required angle, or pitch, for a portable ladder?", "audio_back": "Four to one. The horizontal distance from the top support to the base may not exceed one quarter of the vertical distance. Rule R 408 point 41124.", "source": "R 408.41124", "domain": "05_miosha-safety"}, {"id": "miosha-safety-014", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "How far must ladder side rails extend above the upper landing surface?", "back": "At least 3 feet above the upper landing surface (R 408.41124).", "audio_front": "How far must ladder side rails extend above the upper landing surface?", "audio_back": "At least three feet above the upper landing surface. Rule R 408 point 41124.", "source": "R 408.41124", "domain": "05_miosha-safety"}, {"id": "miosha-safety-015", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "What keeps a portable ladder from displacing?", "back": "Safety feet, or the ladder must be tied, blocked, or otherwise secured (R 408.41124). Also: never stand on the top 3 feet.", "audio_front": "What keeps a portable ladder from displacing?", "audio_back": "Safety feet, or the ladder must be tied, blocked, or otherwise secured. Also, never stand on the top three feet of the ladder.", "source": "R 408.41124", "domain": "05_miosha-safety"}, {"id": "miosha-safety-016", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Ladder rung spacing, and the elevation change that requires a ladder or other access?", "back": "Rungs uniformly spaced 10 to 14 inches apart; access (ladder, stair, or ramp) is required at elevation breaks of 19 inches or more (R 408.41113).", "audio_front": "Ladder rung spacing, and the elevation change that requires a ladder or other access?", "audio_back": "Rungs are uniformly spaced ten to fourteen inches apart. Access is required at any elevation break of nineteen inches or more. Rule R 408 point 41113.", "source": "R 408.41113", "domain": "05_miosha-safety"}, {"id": "miosha-safety-017", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Minimum clearance between a portable ladder and power transmission or distribution lines?", "back": "20 feet (R 408.41124). Do not confuse with the 10-foot equipment clearance for lines up to 50 kV.", "audio_front": "Minimum clearance between a portable ladder and power transmission or distribution lines?", "audio_back": "Twenty feet, under rule R 408 point 41124. Do not confuse this with the ten foot equipment clearance for lines up to fifty kilovolts.", "source": "R 408.41124", "domain": "05_miosha-safety"}, {"id": "miosha-safety-018", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "A self-supporting stepladder must sustain how much load?", "back": "At least 4 times the maximum intended load (R 408.41124).", "audio_front": "A self supporting step ladder must sustain how much load?", "audio_back": "At least four times the maximum intended load.", "source": "R 408.41124", "domain": "05_miosha-safety"}, {"id": "miosha-safety-019", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "At what height must a guardrail be installed on an open side of a scaffold work platform?", "back": "10 feet or more above the floor or ground (R 408.41213, MIOSHA Part 12).", "audio_front": "At what height must a guardrail be installed on an open side of a scaffold work platform?", "audio_back": "Ten feet or more above the floor or ground. Rule R 408 point 41213, M I O S H A Part twelve.", "source": "R 408.41213", "domain": "05_miosha-safety"}, {"id": "miosha-safety-020", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "What fall protection is required on a two-point adjustable suspension scaffold?", "back": "BOTH a personal fall arrest system AND a guardrail system (R 408.41213).", "audio_front": "What fall protection is required on a two point adjustable suspension scaffold?", "audio_back": "Both a personal fall arrest system and a guardrail system. Rule R 408 point 41213.", "source": "R 408.41213", "domain": "05_miosha-safety"}, {"id": "miosha-safety-021", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "A scaffold must be designed to support how many times its maximum intended load?", "back": "4 times the maximum intended load (4:1 safety factor).", "audio_front": "A scaffold must be designed to support how many times its maximum intended load?", "audio_back": "Four times the maximum intended load. A four to one safety factor.", "source": "Part 12", "domain": "05_miosha-safety"}, {"id": "miosha-safety-022", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Minimum scaffold planking?", "back": "Nominal 2x10 scaffold-grade lumber or equivalent.", "audio_front": "What is the minimum scaffold planking?", "audio_back": "Nominal two by ten scaffold grade lumber, or equivalent.", "source": "Part 12", "domain": "05_miosha-safety"}, {"id": "miosha-safety-023", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "May workers climb scaffold cross-braces for access?", "back": "No. A ladder, stair tower, ramp, or equivalent safe access must be provided (R 408.41211).", "audio_front": "May workers climb scaffold cross braces for access?", "audio_back": "No. A ladder, stair tower, ramp, or equivalent safe access must be provided. Rule R 408 point 41211.", "source": "R 408.41211", "domain": "05_miosha-safety"}, {"id": "miosha-safety-024", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "At what depth does an excavation require a protective system (sloping or support)?", "back": "More than 5 feet deep (R 408.40941). Under 5 feet, protection is still required if hazardous earth movement is expected.", "audio_front": "At what depth does an excavation require a protective system, sloping or support?", "audio_back": "More than five feet deep, under rule R 408 point 40941. Under five feet, protection is still required if hazardous earth movement is expected.", "source": "R 408.40941", "domain": "05_miosha-safety"}, {"id": "miosha-safety-025", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Trench egress: at what depth is a ladder required, how far must it extend, and how close must it be?", "back": "At 48 inches (4 feet) or deeper; it must extend at least 3 feet above the top and be within 25 feet of lateral travel of every worker (R 408.40933(4)).", "audio_front": "Trench egress. At what depth is a ladder required, how far must it extend, and how close must it be?", "audio_back": "At forty eight inches, that is four feet, or deeper. It must extend at least three feet above the top, and be within twenty five feet of lateral travel of every worker. Rule R 408 point 40933.", "source": "R 408.40933(4)", "domain": "05_miosha-safety"}, {"id": "miosha-safety-026", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "TRAP: 4 feet vs 5 feet in trenching — which is which?", "back": "4 feet = ladder/egress required. 5 feet = protective system (sloping, shoring, or shield) required. Do not swap them.", "audio_front": "Trap question. Four feet versus five feet in trenching. Which is which?", "audio_back": "Four feet means a ladder for egress is required. Five feet means a protective system, sloping, shoring, or a trench shield, is required. Do not swap them.", "source": "R 408.40933 / R 408.40941", "domain": "05_miosha-safety"}, {"id": "miosha-safety-027", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "How far from the excavation edge must spoil piles be kept?", "back": "At least 2 feet from the edge (R 408.40933(2)).", "audio_front": "How far from the excavation edge must spoil piles be kept?", "audio_back": "At least two feet from the edge. Rule R 408 point 40933.", "source": "R 408.40933(2)", "domain": "05_miosha-safety"}, {"id": "miosha-safety-028", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Who inspects excavations, and when?", "back": "A competent person — ongoing inspections plus a re-inspection after every rainstorm or other hazard-producing occurrence (R 408.40932(4)).", "audio_front": "Who inspects excavations, and when?", "audio_back": "A competent person, with ongoing inspections, plus a re-inspection after every rainstorm or other hazard producing event. Rule R 408 point 40932.", "source": "R 408.40932(4)", "domain": "05_miosha-safety"}, {"id": "miosha-safety-029", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Define 'competent person.'", "back": "Someone capable of identifying existing and predictable hazards AND with authority to take prompt corrective action.", "audio_front": "Define competent person.", "audio_back": "Someone capable of identifying existing and predictable hazards, and who has the authority to take prompt corrective action.", "source": "Part 9 / Part 1 definitions", "domain": "05_miosha-safety"}, {"id": "miosha-safety-030", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Name the three soil types and their maximum slopes.", "back": "Type A (most stable, clay): 3/4H:1V, 53 degrees. Type B (silt, angular gravel, disturbed soil): 1H:1V, 45 degrees. Type C (sand, submerged soil): 1.5H:1V, 34 degrees.", "audio_front": "Name the three soil types and their maximum slopes.", "audio_back": "Type A, the most stable, like clay, slopes three quarters to one, fifty three degrees. Type B, like silt or disturbed soil, slopes one to one, forty five degrees. Type C, like sand or wet soil, slopes one and a half to one, thirty four degrees.", "source": "fed Subpart P (as tested)", "domain": "05_miosha-safety"}, {"id": "miosha-safety-031", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "A trench is dug in previously disturbed soil. What is the best possible soil classification?", "back": "Type B at best — previously disturbed soil can NEVER be classified Type A.", "audio_front": "A trench is dug in previously disturbed soil. What is the best possible soil classification?", "audio_back": "Type B at best. Previously disturbed soil can never be classified Type A.", "source": "fed Subpart P (as tested)", "domain": "05_miosha-safety"}, {"id": "miosha-safety-032", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "A 6-foot trench in sandy soil: what slope if sloping is the chosen protection?", "back": "Sand is Type C: slope at 1.5 horizontal to 1 vertical (34 degrees) — the flattest required slope.", "audio_front": "A six foot trench in sandy soil. What slope, if sloping is the chosen protection?", "audio_back": "Sand is Type C. Slope at one and a half horizontal to one vertical, thirty four degrees, the flattest required slope.", "source": "fed Subpart P (as tested)", "domain": "05_miosha-safety"}, {"id": "miosha-safety-033", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "How long before digging must you contact MISS DIG 811?", "back": "At least 3 full working days before excavating (PA 174 of 2013).", "audio_front": "How long before digging must you contact MISS DIG eight one one?", "audio_back": "At least three full working days before excavating, under Public Act one seventy four of twenty thirteen.", "source": "PA 174 of 2013", "domain": "05_miosha-safety"}, {"id": "miosha-safety-034", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "MISS DIG marking colors: red, yellow, blue, green, white?", "back": "Red = electric, yellow = gas/oil, blue = water, green = sewer, white = your proposed dig area. (Orange = telecom, pink = survey, purple = reclaimed water.)", "audio_front": "MISS DIG marking colors. Red, yellow, blue, green, and white mean what?", "audio_back": "Red is electric. Yellow is gas or oil. Blue is water. Green is sewer. White marks your proposed dig area. Also, orange is telecom, pink is survey, and purple is reclaimed water.", "source": "MISS DIG / APWA colors", "domain": "05_miosha-safety"}, {"id": "miosha-safety-035", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "What protection is required on 120-volt, 15- and 20-amp temporary receptacles on a construction site?", "back": "GFCI protection, OR an Assured Equipment Grounding Conductor Program (AEGCP) per Part 17, R 408.41722.", "audio_front": "What protection is required on one hundred twenty volt, fifteen and twenty amp temporary receptacles on a construction site?", "audio_back": "G F C I protection, or an assured equipment grounding conductor program, under Part seventeen, rule R 408 point 41722.", "source": "R 408.41722", "domain": "05_miosha-safety"}, {"id": "miosha-safety-036", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "What must an Assured Equipment Grounding Conductor Program cover?", "back": "All extension cord sets, receptacles not part of permanent wiring, and cord-and-plug equipment — with scheduled testing and documentation (R 408.41722).", "audio_front": "What must an assured equipment grounding conductor program cover?", "audio_back": "All extension cord sets, receptacles that are not part of the permanent wiring, and cord and plug equipment, with scheduled testing and documentation.", "source": "R 408.41722", "domain": "05_miosha-safety"}, {"id": "miosha-safety-037", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Minimum clearance for equipment working near overhead power lines up to 50 kV?", "back": "10 feet; add 4 inches for every 10 kV above 50 kV.", "audio_front": "Minimum clearance for equipment working near overhead power lines up to fifty kilovolts?", "audio_back": "Ten feet. Add four inches for every ten kilovolts above fifty.", "source": "Part 10 / fed 1926", "domain": "05_miosha-safety"}, {"id": "miosha-safety-038", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "What is lockout/tagout?", "back": "De-energizing machines or circuits and physically locking and tagging the energy source so it cannot be re-energized during servicing.", "audio_front": "What is lockout tagout?", "audio_back": "De-energizing machines or circuits, then physically locking and tagging the energy source so it cannot be re-energized while workers service it.", "source": "Part 17 / fed LOTO", "domain": "05_miosha-safety"}, {"id": "miosha-safety-039", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "What first aid capability must be at a construction worksite?", "back": "A person with a valid first aid training certificate (Red Cross or equivalent) present at the worksite to render first aid (R 408.40132), plus first aid supplies.", "audio_front": "What first aid capability must be at a construction worksite?", "audio_back": "A person holding a valid first aid training certificate, Red Cross or equivalent, present at the worksite to render first aid, plus first aid supplies. Rule R 408 point 40132.", "source": "R 408.40132", "domain": "05_miosha-safety"}, {"id": "miosha-safety-040", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "When are hard hats required?", "back": "Whenever there is danger of head injury from impact, falling or flying objects, or electrical shock — essentially any overhead hazard.", "audio_front": "When are hard hats required?", "audio_back": "Whenever there is danger of head injury from impact, falling or flying objects, or electrical shock. Essentially, any overhead hazard.", "source": "PPE / Part 6", "domain": "05_miosha-safety"}, {"id": "miosha-safety-041", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Silica: PEL and action level?", "back": "PEL = 50 micrograms per cubic meter (8-hour TWA); action level = 25 micrograms per cubic meter. Controls: wet methods, vacuum dust collection, then respirators.", "audio_front": "Silica. What are the P E L and the action level?", "audio_back": "The permissible exposure limit is fifty micrograms per cubic meter as an eight hour time weighted average. The action level is twenty five micrograms per cubic meter. Controls are wet methods, vacuum dust collection, then respirators.", "source": "fed 1926.1153 (adopted)", "domain": "05_miosha-safety"}, {"id": "miosha-safety-042", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "TRAP: construction noise limit — 90 or 85 dBA?", "back": "Construction PEL is 90 dBA (8-hr TWA, Part 680). The 85 dBA action level with audiometric testing is GENERAL INDUSTRY only.", "audio_front": "Trap question. Construction noise limit. Ninety or eighty five decibels?", "audio_back": "The construction permissible exposure limit is ninety decibels A weighted, eight hour time weighted average, under Part six eighty. The eighty five decibel action level with hearing tests applies to general industry only.", "source": "Part 680", "domain": "05_miosha-safety"}, {"id": "miosha-safety-043", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Three defining characteristics of a confined space?", "back": "Large enough to enter and work in; limited or restricted entry/exit; not designed for continuous occupancy. Permit-required if it also has a serious recognized hazard. Test the atmosphere BEFORE entry.", "audio_front": "What are the three defining characteristics of a confined space?", "audio_back": "Large enough to enter and work in. Limited or restricted entry and exit. Not designed for continuous occupancy. It becomes permit required if it also has a serious recognized hazard. Always test the atmosphere before entry.", "source": "confined space std", "domain": "05_miosha-safety"}, {"id": "miosha-safety-044", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Three core elements of a Hazard Communication program?", "back": "(1) Container labeling, (2) Safety Data Sheets for every hazardous chemical, (3) employee training. This is the employee Right to Know.", "audio_front": "What are the three core elements of a hazard communication program?", "audio_back": "One, container labeling. Two, safety data sheets for every hazardous chemical. Three, employee training. This is the employee right to know.", "source": "HazCom std", "domain": "05_miosha-safety"}, {"id": "miosha-safety-045", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "An SDS must be available for which chemicals, and how accessible?", "back": "Every hazardous chemical on the job site, regardless of who brought it — readily accessible to employees during their shift.", "audio_front": "A safety data sheet must be available for which chemicals, and how accessible?", "audio_back": "Every hazardous chemical on the job site, no matter who brought it, and it must be readily accessible to employees during their shift.", "source": "HazCom std", "domain": "05_miosha-safety"}, {"id": "miosha-safety-046", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Within what time must a workplace fatality be reported to MIOSHA?", "back": "Within 8 hours of the employer learning of the death (MIOSHA fatality hotline 800-858-0397).", "audio_front": "Within what time must a workplace fatality be reported to M I O S H A?", "audio_back": "Within eight hours of the employer learning of the death, by calling the M I O S H A fatality hotline.", "source": "MIOSHA Part 11 recordkeeping, R 408.22139", "domain": "05_miosha-safety"}, {"id": "miosha-safety-047", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Reporting window for in-patient hospitalization, amputation, or loss of an eye?", "back": "Within 24 hours of the incident.", "audio_front": "What is the reporting window for an in-patient hospitalization, an amputation, or the loss of an eye?", "audio_back": "Within twenty four hours of the incident.", "source": "MIOSHA Part 11 recordkeeping, R 408.22139", "domain": "05_miosha-safety"}, {"id": "miosha-safety-048", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "SCENARIO: A worker is hospitalized overnight after a fall Friday at 3 pm. When must the builder report, and does a 9-employee company have to?", "back": "Report within 24 hours of the incident. Yes — the small-employer recordkeeping exemption (10 or fewer) never exempts the 8-hour fatality and 24-hour hospitalization/amputation/eye reports.", "audio_front": "Scenario. A worker is hospitalized overnight after a fall on Friday at three P M. When must the builder report, and does a nine employee company have to?", "audio_back": "Report within twenty four hours of the incident. And yes. The small employer recordkeeping exemption for ten or fewer employees never exempts the eight hour fatality report or the twenty four hour hospitalization, amputation, or eye loss report.", "source": "MIOSHA Part 11 recordkeeping, R 408.22139", "domain": "05_miosha-safety"}, {"id": "miosha-safety-049", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Name the three injury/illness recordkeeping forms and the 300A posting window.", "back": "OSHA 300 (log), 300A (annual summary — posted February 1 through April 30), 301 (incident report). Records kept 5 years.", "audio_front": "Name the three injury and illness recordkeeping forms, and the three hundred A posting window.", "audio_back": "Form three hundred is the log. Form three hundred A is the annual summary, posted February first through April thirtieth. Form three oh one is the incident report. Keep records five years.", "source": "R 408.22132 (posting) / R 408.22133 (5-yr retention)", "domain": "05_miosha-safety"}, {"id": "miosha-safety-050", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Who is exempt from routine injury/illness recordkeeping?", "back": "Employers with 10 or fewer employees at all times during the previous calendar year — but they must still make the 8-hour and 24-hour reports.", "audio_front": "Who is exempt from routine injury and illness recordkeeping?", "audio_back": "Employers with ten or fewer employees at all times during the previous calendar year. But they must still make the eight hour and twenty four hour reports.", "source": "recordkeeping rules", "domain": "05_miosha-safety"}, {"id": "miosha-safety-051", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Maximum MIOSHA civil penalty for a serious violation?", "back": "Up to $7,000 per violation (MCL 408.1035). Michigan amounts are set by state statute — the federal inflation-adjusted figures do not apply.", "audio_front": "What is the maximum M I O S H A civil penalty for a serious violation?", "audio_back": "Up to seven thousand dollars per violation, under M C L 408 point 1035. Michigan amounts are set by state statute. The higher federal inflation adjusted figures do not apply.", "source": "MCL 408.1035", "domain": "05_miosha-safety"}, {"id": "miosha-safety-052", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Penalty range for willful or repeat MIOSHA violations?", "back": "Up to $70,000 per violation; willful violations carry a $5,000 minimum (MCL 408.1035).", "audio_front": "What is the penalty range for willful or repeat M I O S H A violations?", "audio_back": "Up to seventy thousand dollars per violation, and a willful violation carries a five thousand dollar minimum. M C L 408 point 1035.", "source": "MCL 408.1035", "domain": "05_miosha-safety"}, {"id": "miosha-safety-053", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "What happens if a willful MIOSHA violation causes an employee's death?", "back": "Felony: up to 1 year imprisonment and/or $10,000 fine; a second offense is up to 3 years and/or $20,000 (MCL 408.1035).", "audio_front": "What happens if a willful M I O S H A violation causes an employee's death?", "audio_back": "It is a felony. Up to one year imprisonment and or a ten thousand dollar fine. A second offense is up to three years and or twenty thousand dollars. M C L 408 point 1035.", "source": "MCL 408.1035", "domain": "05_miosha-safety"}, {"id": "miosha-safety-054", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "May a MIOSHA inspector enter your jobsite without notice?", "back": "Yes — upon presenting credentials, at reasonable times, without delay (MCL 408.1029). Advance notice is generally prohibited. If you deny entry, MIOSHA must get a warrant.", "audio_front": "May a M I O S H A inspector enter your jobsite without notice?", "audio_back": "Yes. Upon presenting credentials, at reasonable times, without delay, under M C L 408 point 1029. Advance notice is generally prohibited. If you deny entry, M I O S H A must get a warrant.", "source": "MCL 408.1029", "domain": "05_miosha-safety"}, {"id": "miosha-safety-055", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Who may accompany a MIOSHA inspector on the walkaround?", "back": "Both an employer representative and an authorized employee representative; participating employees cannot lose wages or be discriminated against (MCL 408.1029).", "audio_front": "Who may accompany a M I O S H A inspector on the walk around?", "audio_back": "Both an employer representative and an authorized employee representative. Participating employees cannot lose wages or be discriminated against. M C L 408 point 1029.", "source": "MCL 408.1029", "domain": "05_miosha-safety"}, {"id": "miosha-safety-056", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "What is the normal sequence of a MIOSHA inspection?", "back": "Opening conference, walkaround inspection, closing conference, then any citations — which must be posted at or near the violation location.", "audio_front": "What is the normal sequence of a M I O S H A inspection?", "audio_back": "Opening conference, walk around inspection, closing conference, then any citations, which must be posted at or near the violation location.", "source": "MIOSHA inspection procedure", "domain": "05_miosha-safety"}, {"id": "miosha-safety-057", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "When may an employee lawfully refuse a work task?", "back": "When it poses imminent danger of death or serious physical harm, the employee asked the employer to correct it and was refused, and there is no reasonable alternative.", "audio_front": "When may an employee lawfully refuse a work task?", "audio_back": "When it poses imminent danger of death or serious physical harm, the employee asked the employer to correct it and was refused, and there is no reasonable alternative.", "source": "MIOSHA Act employee rights", "domain": "05_miosha-safety"}, {"id": "miosha-safety-058", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "May an employer fire a worker for filing a MIOSHA complaint?", "back": "No — complaints are confidential and the Act prohibits discharge or discrimination for exercising safety rights (anti-retaliation).", "audio_front": "May an employer fire a worker for filing a M I O S H A complaint?", "audio_back": "No. Complaints are confidential, and the act prohibits discharge or discrimination against a worker for exercising safety rights.", "source": "MIOSHA Act employee rights", "domain": "05_miosha-safety"}, {"id": "miosha-safety-059", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "When must a Michigan employer carry workers' compensation insurance?", "back": "When it regularly employs 1 or more employees 35+ hours/week for 13+ weeks in the preceding 52 weeks, OR 3 or more employees at any one time.", "audio_front": "When must a Michigan employer carry workers compensation insurance?", "audio_back": "When it regularly employs one or more employees thirty five or more hours per week for thirteen or more weeks in the preceding fifty two weeks, or three or more employees at any one time.", "source": "WDCA thresholds", "domain": "05_miosha-safety"}, {"id": "miosha-safety-060", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "A sub with no workers' comp has an employee injured on your job. Who pays?", "back": "The general contractor can be held responsible for the workers' comp claim. Always verify subs' coverage before work begins.", "audio_front": "A subcontractor with no workers compensation has an employee injured on your job. Who pays?", "audio_back": "The general contractor can be held responsible for the workers compensation claim. Always verify each subcontractor's coverage before work begins.", "source": "WDCA GC liability", "domain": "05_miosha-safety"}, {"id": "miosha-safety-061", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "How many prelicensure education hours cover MIOSHA safety standards for the RB license?", "back": "At least 6 of the 60 required prelicensure hours must be in MIOSHA construction safety standards.", "audio_front": "How many prelicensure education hours cover M I O S H A safety standards for the residential builder license?", "audio_back": "At least six of the sixty required prelicensure hours must be in M I O S H A construction safety standards.", "source": "LARA/BCC curriculum", "domain": "05_miosha-safety"}, {"id": "miosha-safety-062", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Which MIOSHA construction Part covers: fall protection, scaffolds, ladders, excavation, electrical?", "back": "Part 45 = fall protection; Part 12 = scaffolds; Part 11 = fixed and portable ladders; Part 9 = excavation, trenching, shoring; Part 17 = electrical installations.", "audio_front": "Which M I O S H A construction part covers fall protection, scaffolds, ladders, excavation, and electrical?", "audio_back": "Part forty five is fall protection. Part twelve is scaffolds. Part eleven is fixed and portable ladders. Part nine is excavation, trenching, and shoring. Part seventeen is electrical installations.", "source": "MIOSHA CS parts", "domain": "05_miosha-safety"}, {"id": "miosha-safety-063", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "SCENARIO: You're framing a floor deck 7 feet above the basement slab with an open leading edge. Required?", "back": "Fall protection — the 6-foot Part 45 trigger applies to leading-edge work: guardrails, safety nets, or PFAS.", "audio_front": "Scenario. You are framing a floor deck seven feet above the basement slab with an open leading edge. What is required?", "audio_back": "Fall protection. The six foot Part forty five trigger applies to leading edge work. Use guardrails, safety nets, or a personal fall arrest system.", "source": "Part 45", "domain": "05_miosha-safety"}, {"id": "miosha-safety-064", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "SCENARIO: Baker scaffold platform at 8 feet with an open side. Guardrail required?", "back": "Not by Part 12's scaffold rule — the scaffold guardrail trigger is 10 feet (R 408.41213). At 10 feet or more, yes.", "audio_front": "Scenario. A baker scaffold platform at eight feet with an open side. Is a guardrail required?", "audio_back": "Not by Part twelve's scaffold rule. The scaffold guardrail trigger is ten feet. At ten feet or more, yes.", "source": "R 408.41213", "domain": "05_miosha-safety"}, {"id": "miosha-safety-065", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "SCENARIO: Extension ladder to a 16-foot eave. How far above the eave must it reach, and how far out at the base?", "back": "Rails at least 3 feet above the landing (about 19 feet of ladder), base about 4 feet out — one quarter of the 16-foot working height (R 408.41124).", "audio_front": "Scenario. An extension ladder to a sixteen foot eave. How far above the eave must it reach, and how far out at the base?", "audio_back": "The rails must reach at least three feet above the landing, about nineteen feet of ladder. The base sits about four feet out, one quarter of the sixteen foot working height. Rule R 408 point 41124.", "source": "R 408.41124", "domain": "05_miosha-safety"}, {"id": "miosha-safety-066", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "SCENARIO: 4.5-foot-deep footing trench, crew inside, ladder 30 feet away. Violations?", "back": "Yes — at 48 inches or deeper a ladder is required within 25 feet of lateral travel, extending 3 feet above the top (R 408.40933(4)). A protective system is not yet mandatory (that starts above 5 feet) unless hazardous earth movement is expected.", "audio_front": "Scenario. A four and a half foot deep footing trench, crew inside, ladder thirty feet away. Any violations?", "audio_back": "Yes. At forty eight inches or deeper, a ladder is required within twenty five feet of lateral travel, extending three feet above the top. A protective system is not yet mandatory, that starts above five feet, unless hazardous earth movement is expected.", "source": "R 408.40933(4) / R 408.40941", "domain": "05_miosha-safety"}, {"id": "miosha-safety-067", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "TRAP: Which agency figure is the MIOSHA serious-violation max — $7,000 or about $16,000?", "back": "$7,000. Michigan penalties are fixed by MCL 408.1035; the ~$16,000+ figure is federal OSHA's inflation-adjusted amount and is a trap answer.", "audio_front": "Trap question. Which figure is the M I O S H A serious violation maximum. Seven thousand dollars, or about sixteen thousand?", "audio_back": "Seven thousand dollars. Michigan penalties are fixed by statute, M C L 408 point 1035. The sixteen thousand dollar figure is federal O S H A's inflation adjusted amount, and it is a trap answer.", "source": "MCL 408.1035", "domain": "05_miosha-safety"}, {"id": "miosha-safety-068", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "TRAP: Fatality vs hospitalization reporting — 8 or 24 hours?", "back": "Fatality = 8 hours. In-patient hospitalization, amputation, or eye loss = 24 hours. Never 48.", "audio_front": "Trap question. Fatality versus hospitalization reporting. Eight or twenty four hours?", "audio_back": "A fatality must be reported within eight hours. An in-patient hospitalization, amputation, or eye loss within twenty four hours. Never forty eight.", "source": "MIOSHA Part 11 recordkeeping, R 408.22139", "domain": "05_miosha-safety"}, {"id": "miosha-safety-069", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "Does Michigan's Part 9 rule text use soil Types A/B/C?", "back": "No — Michigan's own Part 9 uses an angle-of-repose table by soil description. But exam questions and prep courses test the federal A/B/C system (3/4:1, 1:1, 1.5:1). Answer with A/B/C values unless the question quotes the Michigan table.", "audio_front": "Does Michigan's Part nine rule text use soil types A, B, and C?", "audio_back": "No. Michigan's own Part nine uses an angle of repose table by soil description. But exam questions test the federal A B C system. Answer with the A B C slope values unless the question quotes the Michigan table.", "source": "R 408.40941 Table 1 / fed Subpart P", "domain": "05_miosha-safety"}, {"id": "miosha-safety-070", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "A worker on a ladder jack scaffold — what fall protection?", "back": "A personal fall arrest system (ladder jack, boatswain's chair, catenary, float, and needle beam scaffolds all require PFAS instead of guardrails) — R 408.41213.", "audio_front": "A worker on a ladder jack scaffold. What fall protection is required?", "audio_back": "A personal fall arrest system. Ladder jack, boatswain's chair, catenary, float, and needle beam scaffolds all require personal fall arrest instead of guardrails. Rule R 408 point 41213.", "source": "R 408.41213", "domain": "05_miosha-safety"}, {"id": "miosha-safety-071", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "When is respiratory protection required?", "back": "When exposures exceed the PEL for dusts, fumes, mists, gases, or vapors — common residential triggers: silica cutting, lead paint disturbance, asbestos, spray coatings. Engineering controls come first.", "audio_front": "When is respiratory protection required?", "audio_back": "When exposures exceed the permissible exposure limit for dusts, fumes, mists, gases, or vapors. Common residential triggers are silica cutting, lead paint disturbance, asbestos, and spray coatings. Engineering controls come first.", "source": "respiratory std", "domain": "05_miosha-safety"}, {"id": "miosha-safety-072", "deck": "rb", "section": "trade", "category": "Safety/MIOSHA", "front": "At what ladder angle does a ladder get treated as a fixed ladder?", "back": "80 degrees or more from horizontal (R 408.41124).", "audio_front": "At what ladder angle does a ladder get treated as a fixed ladder?", "audio_back": "Eighty degrees or more from horizontal. Rule R 408 point 41124.", "source": "R 408.41124", "domain": "05_miosha-safety"}, {"id": "sitework-concrete-foundations-001", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "What is the minimum depth below grade for exterior footings in Michigan?", "back": "42 inches below actual grade — a Michigan amendment in MRC R403.1.4. The base IRC's '12 inches below undisturbed ground / local frost line' is the trap.", "audio_front": "What is the minimum depth below grade for exterior footings in Michigan?", "audio_back": "Forty-two inches below actual grade. That is a Michigan amendment in section R four zero three point one point four. The base I R C answer of twelve inches is the trap.", "source": "MRC R403.1.4 (MI amendment)", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-002", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Minimum thickness of a residential concrete footing?", "back": "6 inches, per MRC R403.1.1 and Tables R403.1(1)-(3).", "audio_front": "What is the minimum thickness of a residential concrete footing?", "audio_back": "Six inches, per M R C section R four zero three point one point one.", "source": "MRC R403.1.1", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-003", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Footing projection rule: minimum and maximum projection beyond the wall face?", "back": "Minimum 2 inches each side; the projection may not exceed the thickness of the footing (MRC R403.1.1).", "audio_front": "What are the minimum and maximum footing projections beyond the wall face?", "audio_back": "Minimum two inches each side, and the projection may not exceed the thickness of the footing. M R C R four zero three point one point one.", "source": "MRC R403.1.1", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-004", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "What must footings bear on?", "back": "Undisturbed natural soil or engineered fill — never organic soil, uncompacted fill, or frozen soil (unless the frozen condition is permanent).", "audio_front": "What must footings bear on?", "audio_back": "Undisturbed natural soil or engineered fill. Never organic soil, uncompacted fill, or frozen soil, unless the frozen condition is permanent.", "source": "MRC R403.1, R403.1.4.1", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-005", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Anchor bolts: diameter, maximum spacing, and embedment?", "back": "Minimum 1/2-inch diameter, maximum 6 feet on center, embedded minimum 7 inches into concrete or grouted CMU cells (MRC R403.1.6).", "audio_front": "Anchor bolts. What are the diameter, maximum spacing, and embedment?", "audio_back": "Minimum one half inch diameter, maximum six feet on center, embedded a minimum of seven inches into concrete or grouted block cells. M R C R four zero three point one point six.", "source": "MRC R403.1.6", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-006", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "How many anchor bolts per sill plate section, and how close to the plate ends?", "back": "Minimum two bolts per plate section, with one bolt not more than 12 inches (and not less than 7 bolt diameters) from each end; bolts sit in the middle third of the plate width.", "audio_front": "How many anchor bolts per sill plate section, and how close to the plate ends must they be?", "audio_back": "Minimum two bolts per plate section, with one bolt not more than twelve inches, and not less than seven bolt diameters, from each end. Bolts sit in the middle third of the plate width.", "source": "MRC R403.1.6", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-007", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "TRAP: Does anchor bolt spacing ever drop from 6 ft to 4 ft o.c. in Michigan?", "back": "No. The 4-ft-o.c.-for-buildings-over-two-stories rule is R403.1.6.1, a seismic provision for SDC C/D0/D1/D2 only. Michigan is SDC A/B, so the answer is 6 feet on center regardless of stories.", "audio_front": "Trap question. Does anchor bolt spacing ever drop from six feet to four feet on center in Michigan?", "audio_back": "No. The four foot rule for buildings over two stories is a seismic provision for design categories C and D only. Michigan is category A or B, so the answer is six feet on center regardless of stories.", "source": "MRC R403.1.6 / R403.1.6.1", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-008", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Are 3x3x0.229-inch plate washers required on anchor bolts in Michigan?", "back": "No — that rule applies in Seismic Design Categories C/D. Michigan is SDC A/B, so standard cut washers with a nut are acceptable.", "audio_front": "Are three inch by three inch plate washers required on anchor bolts in Michigan?", "audio_back": "No. That rule applies in seismic design categories C and D. Michigan is category A or B, so standard cut washers with a nut are acceptable.", "source": "MRC R403.1.6 / R602.11.1", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-009", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Footing slope rules: top surface, bottom surface, and what to do on steep ground?", "back": "Top of footing must be level; bottom may slope up to 1 vertical in 10 horizontal (10%); beyond that, step the footing (MRC R403.1.5).", "audio_front": "Footing slope rules. What about the top surface, the bottom surface, and steep ground?", "audio_back": "The top of the footing must be level. The bottom may slope up to one in ten, that is ten percent. Beyond that you must step the footing. M R C R four zero three point one point five.", "source": "MRC R403.1.5", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-010", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "At what slope steepness do the special footing setback/clearance provisions apply?", "back": "On or adjacent to slopes steeper than 1 vertical in 3 horizontal — a 33.3 percent slope (MRC R403.1.7).", "audio_front": "At what slope steepness do the special footing setback provisions apply?", "audio_back": "On slopes steeper than one vertical in three horizontal, which is a thirty-three point three percent slope. M R C R four zero three point one point seven.", "source": "MRC R403.1.7", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-011", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Which structures are EXEMPT from frost-depth footings?", "back": "Freestanding accessory structures up to 600 sq ft (light-frame) or 400 sq ft (other construction) with eave height 10 ft or less, and decks not supported by the dwelling (R403.1.4.1 exceptions).", "audio_front": "Which structures are exempt from frost depth footings?", "audio_back": "Freestanding accessory structures up to six hundred square feet of light frame construction, or four hundred square feet of other construction, with an eave height of ten feet or less. Also decks not supported by the dwelling.", "source": "MRC R403.1.4.1", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-012", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "What three factors set required foundation wall thickness in the R404 tables?", "back": "Wall height, height of unbalanced backfill, and soil class. Weaker soil or taller backfill requires a thicker or reinforced wall.", "audio_front": "What three factors set required foundation wall thickness in the R four zero four tables?", "audio_back": "Wall height, height of unbalanced backfill, and soil class. Weaker soil or taller backfill requires a thicker or reinforced wall.", "source": "MRC R404.1.1/R404.1.2", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-013", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "How far must the foundation wall extend above finished grade?", "back": "Minimum 4 inches where masonry veneer is used; minimum 6 inches elsewhere (MRC R404.1.6).", "audio_front": "How far must the foundation wall extend above finished grade?", "audio_back": "Minimum four inches where masonry veneer is used, and minimum six inches everywhere else. M R C R four zero four point one point six.", "source": "MRC R404.1.6", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-014", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "When may you backfill against a foundation wall?", "back": "Only after the wall has gained sufficient strength AND is anchored to the floor above or adequately braced. Backfill in 6-12 inch compacted lifts of clean material.", "audio_front": "When may you backfill against a foundation wall?", "audio_back": "Only after the wall has gained sufficient strength and is anchored to the floor above or adequately braced. Backfill in six to twelve inch compacted lifts of clean material.", "source": "MRC R404.1.7", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-015", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Where are foundation drains required, and where do they discharge?", "back": "Around concrete/masonry foundations that retain earth and enclose habitable or usable space below grade; installed at or below the top of the footing; discharge by gravity or mechanical means to an approved drainage system (MRC R405.1).", "audio_front": "Where are foundation drains required, and where do they discharge?", "audio_back": "Around foundations that retain earth and enclose habitable or usable space below grade. They are installed at or below the top of the footing and discharge by gravity or mechanical means to an approved drainage system. M R C R four zero five point one.", "source": "MRC R405.1", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-016", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Gravel foundation drain dimensions?", "back": "Extend at least 1 foot beyond the outside edge of the footing and 6 inches above the top of the footing, covered with an approved filter membrane (MRC R405.1).", "audio_front": "What are the gravel foundation drain dimensions?", "audio_back": "The gravel extends at least one foot beyond the outside edge of the footing, and six inches above the top of the footing, covered with an approved filter membrane.", "source": "MRC R405.1", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-017", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Bedding and cover for perforated foundation drain pipe?", "back": "Placed on at least 2 inches of washed gravel and covered with at least 6 inches of the same; perforated pipe gets a filter membrane, open tile joints get building-paper strips (R405.1).", "audio_front": "What bedding and cover does perforated foundation drain pipe need?", "audio_back": "At least two inches of washed gravel under the pipe, and at least six inches of the same material over it. Perforated pipe is wrapped with a filter membrane.", "source": "MRC R405.1", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-018", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "When is a foundation drainage system NOT required?", "back": "Where the foundation sits on well-drained ground or sand-gravel mixture soils — Unified Soil Classification System Group I (R405.1 exception).", "audio_front": "When is a foundation drainage system not required?", "audio_back": "Where the foundation sits on well-drained ground or sand and gravel mixture soils, classified as group one under the unified soil classification system.", "source": "MRC R405.1", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-019", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "TRAP: Dampproofing vs waterproofing — which is the default and when is the other required?", "back": "Dampproofing (R406.1) is the default for walls retaining earth enclosing interior space below grade. Waterproofing (R406.2) is required only where a high water table or other severe soil-water conditions are known to exist.", "audio_front": "Trap. Dampproofing versus waterproofing. Which is the default, and when is the other required?", "audio_back": "Dampproofing is the default for below grade walls enclosing interior space. Waterproofing is required only where a high water table or other severe soil water conditions are known to exist.", "source": "MRC R406.1, R406.2", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-020", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "How is a masonry foundation wall dampproofed?", "back": "Parged with at least 3/8-inch portland cement parging, then coated — typically a bituminous coating (or acrylic modified cement at 3 lb/sq yd, surface-bonding cement, or any R406.2 waterproofing material). Applied from top of footing to finished grade.", "audio_front": "How is a masonry foundation wall dampproofed?", "audio_back": "Parged with at least three eighths inch of portland cement parging, then coated, typically with a bituminous coating, from the top of the footing to finished grade.", "source": "MRC R406.1", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-021", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Name three approved waterproofing membranes under R406.2.", "back": "Any of: 2-ply hot-mopped felts, 55-lb roll roofing, 6-mil polyethylene or PVC, 40-mil polymer-modified asphalt, 60-mil flexible polymer cement, 60-mil liquid-applied synthetic rubber. Joints lapped and sealed.", "audio_front": "Name three approved waterproofing membranes under R four zero six point two.", "audio_back": "Options include two ply hot mopped felts, fifty five pound roll roofing, six mil polyethylene, forty mil polymer modified asphalt, and sixty mil liquid applied synthetic rubber. Joints must be lapped and sealed.", "source": "MRC R406.2", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-022", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Crawl space ventilation ratio, and the reduction with a ground vapor retarder?", "back": "1 sq ft of vent per 150 sq ft of under-floor area; with a Class 1 vapor retarder ground cover it drops to 1 per 1,500. One vent within 3 feet of each corner (R408.1/R408.2).", "audio_front": "What is the crawl space ventilation ratio, and the reduction with a ground vapor retarder?", "audio_back": "One square foot of vent per one hundred fifty square feet of crawl space. With a class one vapor retarder ground cover, it drops to one per fifteen hundred. One vent within three feet of each corner.", "source": "MRC R408.1/R408.2", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-023", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "TRAP: Crawl space access opening sizes — floor vs wall?", "back": "Through the floor: 18 x 24 inches. Through a perimeter wall: 16 x 24 inches (with a 16 x 24 areaway if below grade). Never under a door to the residence (R408.4).", "audio_front": "Trap. Crawl space access opening sizes, through the floor versus through the wall?", "audio_back": "Through the floor, eighteen by twenty four inches. Through a perimeter wall, sixteen by twenty four inches. Never located under a door to the residence.", "source": "MRC R408.4", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-024", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Required grade slope away from the foundation?", "back": "Minimum 6 inches of fall within the first 10 feet; impervious surfaces within 10 feet need at least a 2 percent slope away (MRC R401.3).", "audio_front": "What is the required grade slope away from the foundation?", "audio_back": "Minimum six inches of fall within the first ten feet. Impervious surfaces within ten feet need at least a two percent slope away. M R C R four zero one point three.", "source": "MRC R401.3", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-025", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Presumptive soil bearing values: clay, sand, gravel, sedimentary rock, bedrock?", "back": "Clay/silt 1,500 psf; sand/silty sand 2,000 psf; sandy gravel 3,000 psf; sedimentary rock 4,000 psf; crystalline bedrock 12,000 psf (Table R401.4.1).", "audio_front": "Presumptive soil bearing values for clay, sand, gravel, sedimentary rock, and bedrock?", "audio_back": "Clay and silt, fifteen hundred pounds per square foot. Sand, two thousand. Sandy gravel, three thousand. Sedimentary rock, four thousand. Crystalline bedrock, twelve thousand.", "source": "MRC Table R401.4.1", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-026", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "A builder finds soft organic muck at footing depth. What are the options?", "back": "Organic soil has no presumptive bearing value — remove it down to suitable soil, or use engineered fill or a designed deep foundation. The building official may require a soils investigation (R401.4).", "audio_front": "A builder finds soft organic muck at footing depth. What are the options?", "audio_back": "Organic soil has no presumptive bearing value. Remove it down to suitable soil, or use engineered fill or a designed foundation. The building official may require a soils investigation.", "source": "MRC R401.4", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-027", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Minimum 28-day compressive strength for footings and interior slabs in Michigan?", "back": "2,500 psi. All of Michigan is severe weathering, but footings and concrete not exposed to weather stay at 2,500 psi (Table R402.2).", "audio_front": "Minimum twenty eight day compressive strength for footings and interior slabs in Michigan?", "audio_back": "Twenty five hundred P S I. Footings and concrete not exposed to the weather stay at twenty five hundred, even though Michigan is severe weathering. Table R four zero two point two.", "source": "MRC Table R402.2", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-028", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Minimum strength for vertical concrete EXPOSED to weather?", "back": "3,000 psi in severe weathering (all of Michigan), per Table R402.2. Not-exposed walls remain 2,500 psi.", "audio_front": "Minimum strength for vertical concrete exposed to the weather?", "audio_back": "Three thousand P S I in severe weathering, which is all of Michigan. Walls not exposed to weather remain twenty five hundred.", "source": "MRC Table R402.2", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-029", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Minimum strength for garage floor slabs, porches, and exterior steps in Michigan?", "back": "3,500 psi — severe weathering plus deicer exposure (Table R402.2). This is the classic trap; 2,500 and 3,000 are wrong.", "audio_front": "Minimum strength for garage floor slabs, porches, and exterior steps in Michigan?", "audio_back": "Thirty five hundred P S I, because of severe weathering and deicer exposure. Twenty five hundred and three thousand are trap answers.", "source": "MRC Table R402.2", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-030", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Required air content for exterior concrete in Michigan, and why?", "back": "Not less than 5% and not more than 7% total air content. Entrained microscopic bubbles give freezing water room to expand, preventing freeze-thaw and deicer spalling (R402.2).", "audio_front": "What is the required air content for exterior concrete in Michigan, and why?", "audio_back": "Between five and seven percent total air content. The tiny entrained bubbles give freezing water room to expand, which prevents freeze thaw and deicer spalling.", "source": "MRC R402.2", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-031", "deck": "rb", "section": "trade", "category": "Concrete", "front": "What does a slump test measure, and what is normal for residential work?", "back": "Workability/consistency of fresh concrete. Typical residential slump is 4-6 inches; footings often 2-4 inches. Higher slump = wetter mix.", "audio_front": "What does a slump test measure, and what is normal for residential work?", "audio_back": "It measures the workability of fresh concrete. Typical residential slump is four to six inches. Footings often run two to four inches.", "source": "industry standard / ASTM C143", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-032", "deck": "rb", "section": "trade", "category": "Concrete", "front": "What happens when you add water to concrete at the job site?", "back": "Slump and workability go up, but the water-cement ratio rises, cutting strength and durability. Typical residential w/c ratio is about 0.45-0.50.", "audio_front": "What happens when you add water to concrete at the job site?", "audio_back": "Workability goes up, but the water cement ratio rises, which cuts strength and durability. The typical ratio is point four five to point five zero.", "source": "industry standard / ACI", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-033", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Why is calcium chloride accelerator banned around embedded or prestressed steel?", "back": "Chlorides corrode steel reinforcement and tendons — catastrophic in post-tensioned work. Use a non-chloride accelerator when steel is present.", "audio_front": "Why is calcium chloride accelerator banned around embedded or prestressed steel?", "audio_back": "Chlorides corrode steel reinforcement and tendons, which is catastrophic in post tensioned work. Use a non chloride accelerator when steel is present.", "source": "ACI practice", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-034", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Match the admixture to the job: hot day long haul; cold pour; stronger without stiffer; freeze-thaw.", "back": "Retarder for hot weather/long hauls; accelerator (non-chloride near steel) for cold; water reducer/plasticizer for workability without added water; air-entraining agent for freeze-thaw.", "audio_front": "Match the admixture to the job. Hot day long haul. Cold pour. Stronger without stiffer. Freeze thaw.", "audio_back": "Retarder for hot weather and long hauls. Accelerator for cold pours. Water reducer for workability without added water. Air entraining agent for freeze thaw protection.", "source": "ACI practice", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-035", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Rebar sizes: what do #3, #4, #5 mean in inches?", "back": "Bar number = diameter in eighths of an inch. #3 = 3/8 inch, #4 = 1/2 inch, #5 = 5/8 inch.", "audio_front": "Rebar sizes. What do number three, number four, and number five mean in inches?", "audio_back": "The bar number is the diameter in eighths of an inch. Number three is three eighths. Number four is one half. Number five is five eighths.", "source": "industry standard", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-036", "deck": "rb", "section": "trade", "category": "Concrete", "front": "TRAP: Where does rebar go in a footing, and where does wire mesh go in a slab?", "back": "Footing rebar in the BOTTOM third (tension zone) with 3 inches of cover against earth. Slab mesh in the UPPER third — chaired or pulled up; mesh on the ground does nothing.", "audio_front": "Trap. Where does rebar go in a footing, and where does wire mesh go in a slab?", "audio_back": "Footing rebar goes in the bottom third, the tension zone, with three inches of cover against earth. Slab mesh goes in the upper third, supported on chairs. Mesh lying on the ground does nothing.", "source": "ACI 318 / industry standard", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-037", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Minimum concrete cover for rebar cast directly against earth?", "back": "3 inches (ACI 318). That is why footing steel is chaired up off the soil.", "audio_front": "What is the minimum concrete cover for rebar cast directly against earth?", "audio_back": "Three inches, per A C I three eighteen. That is why footing steel is chaired up off the soil.", "source": "ACI 318", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-038", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Correct flatwork finishing sequence?", "back": "Screed, bull float, WAIT for bleed water to evaporate, then edge, joint, float, trowel (interior only), broom for exterior traction. Never finish bleed water back into the surface.", "audio_front": "What is the correct concrete flatwork finishing sequence?", "audio_back": "Screed, then bull float, then wait for the bleed water to evaporate. Then edge, joint, float, trowel for interior only, and broom finish for exterior traction. Never work bleed water back into the surface.", "source": "ACI practice", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-039", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Control joint depth and spacing rule of thumb for a 4-inch slab?", "back": "Cut at least 1/4 of the slab thickness (1 inch deep on a 4-inch slab); space roughly 2-3 times the thickness in feet, so 8-12 feet.", "audio_front": "Control joint depth and spacing rule of thumb for a four inch slab?", "audio_back": "Cut at least one quarter of the slab thickness, so one inch deep on a four inch slab. Space the joints roughly eight to twelve feet apart.", "source": "ACI practice", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-040", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Isolation joint vs construction joint?", "back": "Isolation joints separate the slab from fixed objects (walls, columns, pipes) so differential movement doesn't crack it. Construction joints are formed bulkheads where a pour stops, often keyed or doweled.", "audio_front": "What is the difference between an isolation joint and a construction joint?", "audio_back": "An isolation joint separates the slab from fixed objects like walls and columns so movement does not crack it. A construction joint is a formed bulkhead where a pour stops, often keyed or doweled.", "source": "ACI practice", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-041", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Concrete strength timeline: 7 days and 28 days?", "back": "About 70% of design strength at 7 days with proper moist curing; full design strength is measured at 28 days.", "audio_front": "Concrete strength timeline. What happens at seven days and twenty eight days?", "audio_back": "About seventy percent of design strength at seven days with proper curing. Full design strength is measured at twenty eight days.", "source": "ACI practice", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-042", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Cold-weather concreting rules?", "back": "Never place on frozen ground; concrete about 50 degrees F at placement; protect from freezing until it reaches 500 psi — roughly the first 48-72 hours — using blankets, enclosures, or heat.", "audio_front": "What are the cold weather concreting rules?", "audio_back": "Never place concrete on frozen ground. Keep the mix around fifty degrees at placement, and protect it from freezing until it reaches five hundred P S I, roughly the first forty eight to seventy two hours.", "source": "ACI 306 practice", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-043", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Slab-on-grade minimums: thickness, base, vapor retarder?", "back": "3.5-inch minimum slab, on a 4-inch minimum base of approved granular fill, with a 6-mil polyethylene vapor retarder (joints lapped 6 inches) under interior slabs (MRC R506).", "audio_front": "Slab on grade minimums. Thickness, base, and vapor retarder?", "audio_back": "Three and one half inch minimum slab, on a four inch minimum granular base, with a six mil polyethylene vapor retarder, joints lapped six inches. M R C R five zero six.", "source": "MRC R506", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-044", "deck": "rb", "section": "trade", "category": "Concrete", "front": "How many cubic yards for a 24 x 30 ft garage slab, 4 inches thick?", "back": "24 x 30 x 0.333 = about 240 cu ft; 240 / 27 = 8.9 CY. Order about 10% extra — roughly 9.8 CY.", "audio_front": "How many cubic yards of concrete for a twenty four by thirty foot garage slab, four inches thick?", "audio_back": "Twenty four times thirty times one third of a foot is about two hundred forty cubic feet. Divide by twenty seven for about eight point nine cubic yards. Order about ten percent extra, roughly nine point eight yards.", "source": "math", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-045", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "MISS DIG: number to call and required notice?", "back": "Call 811 (or 1-800-482-7171) at least 3 full WORKING days before excavating — Michigan's MISS DIG law, 2013 PA 174.", "audio_front": "MISS DIG. What number do you call, and how much notice is required?", "audio_back": "Call eight one one at least three full working days before excavating. That is Michigan Public Act one seventy four of twenty thirteen.", "source": "2013 PA 174 (MCL 460.721 et seq.)", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-046", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "Penalty for failing to notify MISS DIG before digging?", "back": "A civil fine up to $5,000 through the MPSC (MCL 460.731). Knowingly damaging or concealing utility marks is a misdemeanor — failing to call is not the crime, the fine is.", "audio_front": "What is the penalty for failing to notify MISS DIG before digging?", "audio_back": "A civil fine of up to five thousand dollars under M C L four sixty point seven thirty one. Knowingly damaging or concealing utility marks is a misdemeanor. Failing to call is the civil fine, not the crime.", "source": "MCL 460.731", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-047", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "Does MISS DIG mark the homeowner's private underground lines?", "back": "No — it marks member utilities' lines only. Private lines (well feeds, septic runs, gas to a garage, landscape lighting) are the excavator's/owner's responsibility.", "audio_front": "Does MISS DIG mark the homeowner's private underground lines?", "audio_back": "No. It marks member utility lines only. Private lines like well feeds, septic runs, and gas to a detached garage are the owner's responsibility.", "source": "MISS DIG 811 program", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-048", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "Utility marking colors: red, yellow, orange, blue, green, white?", "back": "Red = electric; yellow = gas/oil/steam; orange = telecom/cable; blue = water; green = sewer/storm; white = proposed excavation (you mark it). Pink = survey, purple = reclaimed water.", "audio_front": "Utility marking colors. Red, yellow, orange, blue, green, and white?", "audio_back": "Red is electric. Yellow is gas, oil, or steam. Orange is telecom and cable. Blue is water. Green is sewer and storm. White is your proposed excavation. Pink is survey, and purple is reclaimed water.", "source": "APWA / MISS DIG color code", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-049", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "TRAP: trench depth triggers — protective system vs ladder?", "back": "Protective system (slope/shore/shield) at 5 feet. Ladder or ramp egress at 4 feet, within 25 feet of lateral travel. Don't swap them.", "audio_front": "Trap. Trench depth triggers. Protective system versus ladder?", "audio_back": "Protective system at five feet deep. Ladder or ramp egress at four feet deep, within twenty five feet of lateral travel. Do not swap them.", "source": "MIOSHA Part 9 / OSHA 1926 Subpart P", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-050", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "When must a trench protective system be designed by a registered professional engineer?", "back": "When the excavation is 20 feet deep or more.", "audio_front": "When must a trench protective system be designed by a registered professional engineer?", "audio_back": "When the excavation is twenty feet deep or more.", "source": "OSHA 1926 Subpart P", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-051", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "How far must spoil piles and equipment be kept from a trench edge?", "back": "At least 2 feet back from the edge, so they can't fall in or surcharge the walls.", "audio_front": "How far must spoil piles and equipment be kept from a trench edge?", "audio_back": "At least two feet back from the edge, so they cannot fall in or overload the trench walls.", "source": "OSHA 1926 Subpart P", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-052", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "Maximum allowable slopes for soil Types A, B, and C?", "back": "Type A: 3/4H:1V (53 degrees). Type B: 1H:1V (45 degrees). Type C: 1-1/2H:1V (34 degrees). Stable rock may be vertical.", "audio_front": "Maximum allowable trench slopes for soil types A, B, and C?", "audio_back": "Type A, three quarters to one, fifty three degrees. Type B, one to one, forty five degrees. Type C, one and one half to one, thirty four degrees. Stable rock may be cut vertical.", "source": "OSHA 1926 Subpart P App B", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-053", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "TRAP: Which soil type can never be benched?", "back": "Type C. Benching is allowed only in Type A and Type B soils. Type C (granular, submerged, or under 0.5 tsf) must be sloped at 1.5:1 or shielded/shored.", "audio_front": "Trap. Which soil type can never be benched?", "audio_back": "Type C. Benching is allowed only in type A and type B soils. Type C must be sloped at one and a half to one, or shielded or shored.", "source": "OSHA 1926 Subpart P App B", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-054", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "How are the soil types defined by unconfined compressive strength?", "back": "Type A: 1.5 tsf or more (cohesive clay). Type B: 0.5 to 1.5 tsf. Type C: 0.5 tsf or less, granular soils, or any submerged/seeping soil. Fissured or vibrated Type A downgrades to B.", "audio_front": "How are trench soil types defined by unconfined compressive strength?", "audio_back": "Type A is one and a half tons per square foot or more. Type B is between one half and one and a half. Type C is one half or less, granular soils, or any submerged or seeping soil.", "source": "OSHA 1926 Subpart P App A", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-055", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "Who is a 'competent person' on an excavation, and when do they inspect?", "back": "Someone able to identify existing and predictable hazards AND authorized to correct them. Inspects daily before work and after every rainstorm or other hazard-increasing event.", "audio_front": "Who is a competent person on an excavation, and when do they inspect?", "audio_back": "Someone who can identify existing and predictable hazards, and who has authority to correct them. They inspect daily before work, and after every rainstorm or other hazard increasing event.", "source": "OSHA 1926.650/.651", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-056", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "What triggers a Michigan SESC (soil erosion) permit?", "back": "Earth disturbance of 1 acre or more, OR any earth change within 500 feet of a lake or stream — Part 91 of NREPA (1994 PA 451), administered by county enforcing agencies.", "audio_front": "What triggers a Michigan soil erosion and sedimentation control permit?", "audio_back": "Disturbing one acre or more of earth, or any earth change within five hundred feet of a lake or stream. That is part ninety one of the natural resources act, administered by county agencies.", "source": "NREPA Part 91 (1994 PA 451)", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-057", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "TRAP: Does Part 91 cover wetlands?", "back": "No — Part 91 is soil erosion/sedimentation. Wetland protection is Part 303 of NREPA, a separate permit program through EGLE.", "audio_front": "Trap. Does part ninety one cover wetlands?", "audio_back": "No. Part ninety one is soil erosion and sedimentation control. Wetland protection is part three zero three, a separate permit program.", "source": "NREPA Parts 91 & 303", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-058", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "What does a Proctor test establish, and what field compaction is typically specified?", "back": "Maximum dry density and optimum moisture content of a soil (Standard ASTM D698 / Modified D1557). Field compaction is typically specified at 90-95% of maximum Proctor density.", "audio_front": "What does a Proctor test establish, and what field compaction is typically specified?", "audio_back": "It establishes a soil's maximum dry density and optimum moisture content. Field compaction is typically specified at ninety to ninety five percent of that maximum density.", "source": "ASTM D698/D1557", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-059", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "Proper foundation backfill lifts?", "back": "Clean granular material placed in 6-12 inch lifts, each lift compacted. No organics, frozen chunks, or large rocks against the wall.", "audio_front": "What are proper foundation backfill lifts?", "audio_back": "Clean granular material placed in six to twelve inch lifts, with each lift compacted. No organic material, frozen chunks, or large rocks against the wall.", "source": "industry standard", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-060", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "What is dewatering and its main site restriction?", "back": "Removing groundwater from an excavation (wellpoints, sump pumps, deep wells) to work dry. Discharge must not erode or flood adjacent property and must meet local rules.", "audio_front": "What is dewatering, and what is its main site restriction?", "audio_back": "Removing groundwater from an excavation using well points or sump pumps so you can work dry. The discharge must not erode or flood adjacent property.", "source": "industry standard", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-061", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "Before demolishing a 1965 house, what hazardous-material step is required?", "back": "An asbestos inspection by a certified inspector under EPA NESHAP (40 CFR 61, Subpart M); regulated asbestos must be removed first. EGLE administers this in Michigan. Lead RRP rules also apply to pre-1978 renovation work.", "audio_front": "Before demolishing a nineteen sixty five house, what hazardous material step is required?", "audio_back": "An asbestos inspection by a certified inspector under the federal NESHAP rule, with regulated asbestos removed before demolition. Lead safe work rules also apply to homes built before nineteen seventy eight.", "source": "40 CFR 61 Subpart M; EPA RRP 40 CFR 745", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-062", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "EPA RRP thresholds: what work in a pre-1978 home triggers lead-safe practices?", "back": "Disturbing more than 6 sq ft of painted surface per interior room, or more than 20 sq ft exterior. Firm and renovator certification plus lead-safe work practices required.", "audio_front": "What work in a home built before nineteen seventy eight triggers the lead renovation rule?", "audio_back": "Disturbing more than six square feet of painted surface in any interior room, or more than twenty square feet outside. Certification and lead safe work practices are required.", "source": "EPA RRP, 40 CFR 745", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-063", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "Cut vs fill — and the grading goal?", "back": "Cut removes soil to lower grade; fill adds soil to raise it. The goal is balancing cut and fill so nothing is hauled in or out; fill under structures goes in compacted lifts.", "audio_front": "Cut versus fill, and what is the grading goal?", "audio_back": "Cut removes soil to lower the grade. Fill adds soil to raise it. The goal is to balance cut and fill so no soil is hauled in or out. Fill under structures goes in compacted lifts.", "source": "industry standard", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-064", "deck": "rb", "section": "trade", "category": "Excavation/Sitework", "front": "Scenario: trench is 4.5 feet deep in wet sand next to a driveway. What does OSHA/MIOSHA require?", "back": "Wet/submerged sand is Type C. Under 5 feet, a protective system is required only if the competent person sees cave-in potential — but egress isn't the issue at 4.5 ft either (ladder trigger is 4 ft, so a ladder IS required within 25 ft). The surcharge from the driveway/equipment must be kept 2 ft back.", "audio_front": "Scenario. A trench is four and a half feet deep in wet sand next to a driveway. What is required?", "audio_back": "Wet sand is type C soil. At four and a half feet, a ladder is required within twenty five feet of travel, since the egress trigger is four feet. A protective system is required at five feet, or shallower if the competent person sees cave in potential. Keep loads two feet back from the edge.", "source": "OSHA 1926 Subpart P", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-065", "deck": "rb", "section": "trade", "category": "Site Engineering", "front": "Benchmark vs monument?", "back": "Benchmark = permanent point of known ELEVATION (vertical control). Monument = permanent marker of a property BOUNDARY or corner (horizontal control); disturbing one is illegal.", "audio_front": "What is the difference between a benchmark and a monument?", "audio_back": "A benchmark is a permanent point of known elevation, used for vertical control. A monument marks a property boundary or corner. Disturbing a monument is illegal.", "source": "surveying standard", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-066", "deck": "rb", "section": "trade", "category": "Site Engineering", "front": "Leveling: how do you compute an unknown elevation with a builder's level?", "back": "HI = benchmark elevation + backsight reading. Point elevation = HI minus foresight reading. A HIGHER rod reading means LOWER ground.", "audio_front": "How do you compute an unknown elevation with a builder's level?", "audio_back": "Height of instrument equals the benchmark elevation plus the backsight rod reading. Then any point's elevation equals the height of instrument minus the foresight reading. A higher rod reading means lower ground.", "source": "surveying standard", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-067", "deck": "rb", "section": "trade", "category": "Site Engineering", "front": "Drill: benchmark 100.00 ft, backsight 4.50 ft, foresight at garage corner 6.25 ft. Elevation at the corner?", "back": "HI = 100.00 + 4.50 = 104.50. Elevation = 104.50 - 6.25 = 98.25 feet.", "audio_front": "Drill. Benchmark one hundred point zero zero feet. Backsight four point five zero. Foresight at the garage corner six point two five. What is the corner elevation?", "audio_back": "Height of instrument is one hundred four point five zero. Subtract the foresight of six point two five, giving ninety eight point two five feet.", "source": "surveying math", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-068", "deck": "rb", "section": "trade", "category": "Site Engineering", "front": "What do closely spaced contour lines mean? Can contours cross?", "back": "Closely spaced = steep slope; widely spaced = gentle/flat. Contour lines connect equal elevations and never cross.", "audio_front": "What do closely spaced contour lines mean, and can contours cross?", "audio_back": "Closely spaced contour lines mean a steep slope. Widely spaced lines mean gentle ground. Contours connect points of equal elevation and never cross each other.", "source": "surveying standard", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-069", "deck": "rb", "section": "trade", "category": "Site Engineering", "front": "What appears on a plot (site) plan?", "back": "Property lines and dimensions, building footprint, setbacks, easements, utilities, driveway, well and septic locations, contours/elevations, north arrow, and scale (engineer's scale, commonly 1 inch = 20 or 30 feet).", "audio_front": "What appears on a plot plan?", "audio_back": "Property lines and dimensions, the building footprint, setbacks, easements, utilities, driveway, well and septic locations, contours, a north arrow, and the scale, commonly one inch equals twenty or thirty feet.", "source": "drafting standard", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-070", "deck": "rb", "section": "trade", "category": "Site Engineering", "front": "Setback vs easement?", "back": "A setback is the zoning-required minimum distance from a structure to a lot line. An easement is another party's legal right to use part of the property (utilities, drainage, access) — don't build in it.", "audio_front": "What is the difference between a setback and an easement?", "audio_back": "A setback is the zoning required minimum distance between a structure and a lot line. An easement is another party's legal right to use part of the property. You do not build in an easement.", "source": "zoning/real property standard", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-071", "deck": "rb", "section": "trade", "category": "Site Engineering", "front": "What does a percolation test measure and what does a very slow rate mean?", "back": "How fast water drains through soil, in minutes per inch, for septic drain-field sizing. Slower than about 60 min/inch (dense clay) generally fails — needs an engineered/mound system or sewer.", "audio_front": "What does a percolation test measure, and what does a very slow rate mean?", "audio_back": "It measures how fast water drains through soil, in minutes per inch, to size a septic drain field. Slower than about sixty minutes per inch generally fails, and needs an engineered system or a sewer connection.", "source": "MI local health dept practice", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-072", "deck": "rb", "section": "trade", "category": "Site Engineering", "front": "Typical Michigan septic numbers: tank size and separation to the well?", "back": "1,000-gallon minimum tank regardless of flow (EGLE Michigan Criteria for Subsurface Sewage Disposal; the 1,250-gallon step for 4 bedrooms is common local practice). State well-code minimum: 50 feet from a single-family well to BOTH the septic tank and the drainfield (R 325.1622) - many local health departments require 75-100 feet to the drainfield.", "audio_front": "Typical Michigan septic numbers. Tank size and separation to the well?", "audio_back": "A one thousand gallon tank minimum regardless of flow, under the state E G L E criteria. The twelve fifty gallon step for four bedrooms is common local practice. The state well code minimum is fifty feet from a single family well to both the septic tank and the drain field, and many local health departments require seventy five to one hundred feet to the drain field.", "source": "EGLE criteria / R 325.1622", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-073", "deck": "rb", "section": "trade", "category": "Site Engineering", "front": "Septic setbacks from the house: tank and drain field to foundation?", "back": "Tank minimum 10 feet from the foundation; drain field minimum 20 feet. Verify locally — these are common Michigan minimums.", "audio_front": "Septic setbacks from the house. Tank and drain field to foundation?", "audio_back": "The tank is a minimum of ten feet from the foundation, and the drain field a minimum of twenty feet. Always verify with the local health department.", "source": "MI local health dept practice", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-074", "deck": "rb", "section": "trade", "category": "Site Engineering", "front": "Minimum well casing depth in Michigan and its height above grade?", "back": "Casing minimum 25 feet below grade and terminating at least 12 inches above the ground surface (Michigan Well Construction Code, R 325.1632(3)).", "audio_front": "What is the minimum well casing depth in Michigan, and its height above grade?", "audio_back": "The casing runs a minimum of twenty five feet below grade, and terminates at least twelve inches above the ground surface. That is state well construction code rule R 325 point 1632.", "source": "R 325.1632(3)", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-075", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "Scenario: pouring an exterior deck pier. How deep, and what strength concrete?", "back": "Bottom of the pier at least 42 inches below grade (MI frost depth) on undisturbed soil; exposed vertical concrete in Michigan's severe weathering = 3,000 psi with 5-7% air.", "audio_front": "Scenario. You are pouring an exterior deck pier. How deep must it go, and what strength concrete?", "audio_back": "The bottom of the pier goes at least forty two inches below grade on undisturbed soil. Exposed vertical concrete in Michigan needs three thousand P S I with five to seven percent air entrainment.", "source": "MRC R403.1.4; Table R402.2", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-076", "deck": "rb", "section": "trade", "category": "Concrete", "front": "What is bleed water and the finishing rule about it?", "back": "Water that rises to the surface as concrete settles. Let it evaporate before finishing — working it back in weakens the surface and causes dusting/scaling.", "audio_front": "What is bleed water, and what is the finishing rule about it?", "audio_back": "Bleed water is the water that rises to the surface as fresh concrete settles. Let it evaporate before finishing. Working it back into the surface weakens it and causes dusting and scaling.", "source": "ACI practice", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-077", "deck": "rb", "section": "trade", "category": "Concrete", "front": "Why is a steel-trowel finish wrong for exterior flatwork?", "back": "It seals and slicks the surface — dangerously slippery when wet and prone to trapping bleed water/air under the densified skin. Exterior surfaces get a broom finish for traction.", "audio_front": "Why is a steel trowel finish wrong for exterior flatwork?", "audio_back": "It creates a dense, slick surface that is dangerously slippery when wet. Exterior surfaces get a broom finish for traction.", "source": "ACI practice", "domain": "06_sitework-concrete-foundations"}, {"id": "sitework-concrete-foundations-078", "deck": "rb", "section": "trade", "category": "Footings & Foundation Walls", "front": "TRAP: The gravel over a foundation drain extends how far beyond and above the footing?", "back": "1 FOOT beyond the outside edge of the footing and 6 inches ABOVE the top of the footing — covered with filter membrane. (Not 6 inches beyond.)", "audio_front": "Trap. The gravel over a foundation drain extends how far beyond and above the footing?", "audio_back": "One full foot beyond the outside edge of the footing, and six inches above the top of the footing, covered with a filter membrane. Not six inches beyond.", "source": "MRC R405.1", "domain": "06_sitework-concrete-foundations"}, {"id": "carpentry-framing-001", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "What is the minimum bearing length for a floor joist on wood or metal?", "back": "1-1/2 inches minimum bearing on wood or metal (MRC R502.6).", "audio_front": "What is the minimum bearing length for a floor joist resting on wood or metal?", "audio_back": "One and one half inches minimum bearing on wood or metal, per M R C section R five oh two point six.", "source": "MRC R502.6", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-002", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "What is the minimum bearing length for a floor joist on masonry or concrete?", "back": "3 inches minimum bearing on masonry or concrete (MRC R502.6).", "audio_front": "What is the minimum bearing length for a floor joist resting on masonry or concrete?", "audio_back": "Three inches minimum bearing on masonry or concrete, per M R C section R five oh two point six.", "source": "MRC R502.6", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-003", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "When is mid-span bridging/blocking required for floor joists, and at what interval?", "back": "Joists exceeding nominal 2x12 in depth require solid blocking, diagonal bridging, or a continuous 1x3 strip at intervals not exceeding 8 feet (MRC R502.7.1). Joists 2x12 and shallower need none.", "audio_front": "When is mid span bridging or blocking required for floor joists, and at what interval?", "audio_back": "Joists deeper than a nominal two by twelve require solid blocking, diagonal bridging, or a continuous one by three strip at intervals not exceeding eight feet. Joists two by twelve and shallower need none. M R C R five oh two point seven point one.", "source": "MRC R502.7.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-004", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "TRAP: Do standard 2x10 floor joists require mid-span bridging under the 2015 MRC?", "back": "No. Bridging is only required for joists EXCEEDING nominal 2x12. A 2x10 (and even a 2x12) requires no intermediate bridging (R502.7.1).", "audio_front": "Trap question. Do standard two by ten floor joists require mid span bridging under the twenty fifteen M R C?", "audio_back": "No. Bridging is only required for joists deeper than a nominal two by twelve. A two by ten, and even a two by twelve, requires no intermediate bridging.", "source": "MRC R502.7.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-005", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "How must joist ends be laterally restrained at supports?", "back": "By full-depth solid blocking not less than 2-inch nominal thickness, or by attachment to a full-depth header, band or rim joist, or an adjoining stud (R502.7).", "audio_front": "How must joist ends be laterally restrained at their supports?", "audio_back": "By full depth solid blocking at least two inch nominal thickness, or by attachment to a full depth header, band or rim joist, or an adjoining stud. Section R five oh two point seven.", "source": "MRC R502.7", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-006", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Maximum depth of a notch in the top or bottom of a sawn-lumber floor joist (not at the end)?", "back": "One-sixth (D/6) of the joist depth, and the notch may not be longer than D/3 or located in the middle third of the span (R502.8.1).", "audio_front": "What is the maximum depth of a notch in the top or bottom of a sawn lumber floor joist, not at the end?", "audio_back": "One sixth of the joist depth. The notch also may not be longer than one third of the depth, and may not be located in the middle third of the span. Section R five oh two point eight point one.", "source": "MRC R502.8.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-007", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Maximum notch depth at the END of a joist (over a bearing)?", "back": "One-fourth (D/4) of the joist depth (R502.8.1).", "audio_front": "What is the maximum notch depth at the end of a joist, over a bearing?", "audio_back": "One fourth of the joist depth. Section R five oh two point eight point one.", "source": "MRC R502.8.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-008", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Maximum diameter of a bored hole in a sawn floor joist, and required clearances?", "back": "Hole diameter max one-third (D/3) of the depth; holes must be at least 2 inches from the top or bottom edge, from any other hole, and from any notch (R502.8.1).", "audio_front": "What is the maximum diameter of a bored hole in a sawn floor joist, and what clearances are required?", "audio_back": "Maximum one third of the joist depth, and the hole must be at least two inches from the top or bottom edge, from any other hole, and from any notch. Section R five oh two point eight point one.", "source": "MRC R502.8.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-009", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "TRAP: Which fraction goes with which joist cut — D/6, D/4, D/3?", "back": "D/6 = max notch depth in the span; D/4 = max notch at the member END; D/3 = max notch LENGTH and max bored-hole diameter (R502.8.1).", "audio_front": "Trap question. Match the fractions. One sixth, one fourth, and one third of joist depth each limit what?", "audio_back": "One sixth is the maximum notch depth within the span. One fourth is the maximum notch at the end of the member. One third is both the maximum notch length and the maximum bored hole diameter.", "source": "MRC R502.8.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-010", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "A plumber wants to notch the bottom of a 2x10 joist at mid-span. Allowed?", "back": "No. Notches are prohibited in the middle third of the span regardless of size (R502.8.1). Elsewhere the notch could be up to D/6.", "audio_front": "A plumber wants to notch the bottom of a two by ten joist at mid span. Is that allowed?", "audio_back": "No. Notches are prohibited in the middle third of the span regardless of size. Outside the middle third, a notch up to one sixth of the depth is allowed.", "source": "MRC R502.8.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-011", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Can you field-cut or notch an I-joist flange or LVL beam?", "back": "No. Cuts, notches, and holes in trusses, structural composite lumber, glulam, and I-joists are prohibited unless permitted by the manufacturer or approved by a registered design professional (R502.8.2).", "audio_front": "Can you field cut or notch an I joist flange or an L V L beam?", "audio_back": "No. Cuts, notches, and holes in trusses, structural composite lumber, glue laminated members, and I joists are prohibited unless the manufacturer permits them or a registered design professional approves. Section R five oh two point eight point two.", "source": "MRC R502.8.2", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-012", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Rule for double joists under parallel bearing partitions that are separated for piping?", "back": "Double joists separated to permit piping or vents must be full-depth solid blocked with lumber ≥2-inch nominal at not more than 4 feet on center (R502.4).", "audio_front": "What is the rule for double joists under parallel bearing partitions that are separated to run piping?", "audio_back": "They must be full depth solid blocked with lumber at least two inch nominal, spaced not more than four feet on center. Section R five oh two point four.", "source": "MRC R502.4", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-013", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Prescriptive limit for a floor joist cantilever supporting a light-frame wall and roof?", "back": "Per R502.3.3, cantilevers are limited by Table R502.3.3(1); the general prescriptive rule is the cantilever cannot exceed the nominal depth of the joist. The L/4 rule is a deck provision from the 2021 IRC, not the 2015 MRC.", "audio_front": "What is the prescriptive limit for a floor joist cantilever supporting a light frame wall and roof?", "audio_back": "Cantilevers follow Table R five oh two point three point three. The general prescriptive rule is that the cantilever cannot exceed the nominal depth of the joist. The L over four rule is a deck provision from the twenty twenty one I R C, not the tested twenty fifteen code.", "source": "MRC R502.3.3", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-014", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Floor opening framing: when must the header joist and trimmer joists be doubled?", "back": "When the header joist span exceeds 4 feet, both the header and trimmers must be doubled. Approved hangers are required when the header span exceeds 6 feet (R502.10).", "audio_front": "When framing a floor opening, when must the header joist and trimmer joists be doubled?", "audio_back": "When the header joist span exceeds four feet, both header and trimmers must be doubled. Approved hangers are required when the header span exceeds six feet. Section R five oh two point ten.", "source": "MRC R502.10", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-015", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "A stairway opening header spans 3'-6\". What framing is required?", "back": "A single header joist the same size as the floor joists is permitted (span ≤4 ft), with single trimmers if the header is within 3 feet of the trimmer bearing (R502.10).", "audio_front": "A stairway floor opening header spans three feet six inches. What framing is required?", "audio_back": "A single header joist the same size as the floor joists is permitted, because the span is four feet or less. Single trimmers are allowed if the header is within three feet of the trimmer bearing.", "source": "MRC R502.10", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-016", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "What five factors determine allowable floor joist span in the R502.3.1 tables?", "back": "Species, lumber grade, joist spacing, design live load (30 psf sleeping rooms / 40 psf other rooms), and dead load (10 or 20 psf). You read the span from the table — spans are not memorized values.", "audio_front": "What factors determine allowable floor joist span in the code span tables?", "audio_back": "Wood species, lumber grade, joist spacing, design live load, thirty pounds for sleeping rooms or forty for other rooms, and the dead load. You read the span from the table.", "source": "MRC R502.3.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-017", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "How are built-up girders of 2-inch lumber nailed?", "back": "Each layer: 20d common nails at 32 inches on center at top and bottom, staggered, plus two 20d at the ends and at each splice (Table R602.3(1)).", "audio_front": "How are built up girders made of two inch lumber nailed together?", "audio_back": "Twenty penny common nails at thirty two inches on center, top and bottom, staggered, plus two twenty penny nails at the ends and at each splice. Fastening schedule Table R six oh two point three.", "source": "Table R602.3(1)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-018", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Max spacing for 2x4 bearing studs supporting roof and ceiling only?", "back": "24 inches on center, up to 10 feet in height (Table R602.3(5)).", "audio_front": "What is the maximum spacing for two by four bearing studs supporting a roof and ceiling only?", "audio_back": "Twenty four inches on center, up to ten feet in height. Table R six oh two point three, number five.", "source": "MRC Table R602.3(5)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-019", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Max spacing for 2x4 bearing studs supporting one floor plus roof and ceiling?", "back": "16 inches on center (Table R602.3(5)).", "audio_front": "What is the maximum spacing for two by four bearing studs supporting one floor plus a roof and ceiling?", "audio_back": "Sixteen inches on center. Table R six oh two point three, number five.", "source": "MRC Table R602.3(5)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-020", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "What studs are required for a wall supporting two floors plus a roof?", "back": "2x6 studs at 16 inches on center. 2x4s are not permitted prescriptively for two floors plus roof (Table R602.3(5)).", "audio_front": "What studs are required for a bearing wall supporting two floors plus a roof?", "audio_back": "Two by six studs at sixteen inches on center. Two by fours are not permitted prescriptively for that load. Table R six oh two point three, number five.", "source": "MRC Table R602.3(5)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-021", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Limits on utility-grade studs?", "back": "Not spaced more than 16 inches o.c., may support only a roof and ceiling, and may not exceed 8 feet in height for exterior/bearing walls (R602.3.1 exception).", "audio_front": "What are the limits on using utility grade studs?", "audio_back": "They may not be spaced more than sixteen inches on center, may support only a roof and ceiling, and may not exceed eight feet in height for exterior walls. Section R six oh two point three point one.", "source": "MRC R602.3.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-022", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Top plate rules: how many plates, and joint offset?", "back": "Double top plate, overlapping at corners and intersections, with end joints offset at least 24 inches (R602.3.2).", "audio_front": "What are the top plate rules? How many plates, and how much joint offset?", "audio_back": "A double top plate, overlapping at corners and intersections, with end joints offset at least twenty four inches. Section R six oh two point three point two.", "source": "MRC R602.3.2", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-023", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "When is a SINGLE top plate permitted?", "back": "With a galvanized steel splice plate (3x6 inch, 0.036-inch/20-gauge) nailed with six 8d nails each side at joints, corners, and intersections, and joists/rafters centered over studs within 1 inch (R602.3.2 exception).", "audio_front": "When is a single top plate permitted?", "audio_back": "When joints are tied with a three by six inch, twenty gauge galvanized splice plate nailed with six eight penny nails on each side, and joists or rafters land within one inch of the stud centers. Exception to R six oh two point three point two.", "source": "MRC R602.3.2", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-024", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Maximum notch in a stud of a bearing or exterior wall?", "back": "25 percent of the stud width (R602.6). For a 2x4, that is 7/8 inch.", "audio_front": "What is the maximum notch in a stud of a bearing or exterior wall?", "audio_back": "Twenty five percent of the stud width. For a two by four, that is seven eighths of an inch. Section R six oh two point six.", "source": "MRC R602.6", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-025", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Maximum notch in a nonbearing partition stud?", "back": "40 percent of a single stud width (R602.6).", "audio_front": "What is the maximum notch in a non bearing partition stud?", "audio_back": "Forty percent of a single stud width. Section R six oh two point six.", "source": "MRC R602.6", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-026", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Maximum bored hole in a single bearing-wall stud?", "back": "40 percent of the stud width, with the hole edge at least 5/8 inch from the stud edge and not in the same section as a notch (R602.6).", "audio_front": "What is the maximum bored hole in a single bearing wall stud?", "audio_back": "Forty percent of the stud width. The hole edge must stay at least five eighths of an inch from the stud edge, and not land in the same section as a notch. Section R six oh two point six.", "source": "MRC R602.6", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-027", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "When may a bearing stud be bored up to 60 percent?", "back": "When the studs are doubled, with no more than two successive doubled studs bored. Nonbearing studs may also be bored to 60 percent (R602.6).", "audio_front": "When may a bearing wall stud be bored up to sixty percent of its width?", "audio_back": "When the studs are doubled, with no more than two successive doubled studs bored. Non bearing studs may also be bored to sixty percent. Section R six oh two point six.", "source": "MRC R602.6", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-028", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "TRAP: Stud notching vs boring percentages — recite all four.", "back": "Notch: 25% bearing, 40% nonbearing. Bore: 40% bearing (single stud), 60% nonbearing or doubled bearing studs (R602.6).", "audio_front": "Trap drill. Recite all four stud notching and boring percentages.", "audio_back": "Notching, twenty five percent for bearing walls, forty percent for non bearing. Boring, forty percent for a single bearing stud, sixty percent for non bearing studs or doubled bearing studs.", "source": "MRC R602.6", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-029", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "An HVAC installer cuts 60% of the width of a bearing-wall top plate for a duct. What repair does the code require?", "back": "A galvanized metal tie, 16 gauge (0.054 inch) and 1-1/2 inches wide, fastened with eight 10d nails on each side, extending at least 6 inches past the opening (R602.6.1). Trigger: cut more than 50% of plate width.", "audio_front": "An H V A C installer cuts sixty percent of the width of a bearing wall top plate for a duct. What repair does the code require?", "audio_back": "A galvanized metal tie, sixteen gauge and one and a half inches wide, fastened with eight ten penny nails on each side and extending at least six inches past the opening. The trigger is any cut over fifty percent of the plate width. Section R six oh two point six point one.", "source": "MRC R602.6.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-030", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "TRAP: 16-gauge vs 20-gauge plates in wall framing — which is which?", "back": "16-gauge (0.054\") x 1-1/2\" tie = repair for a top plate cut over 50% (R602.6.1). 20-gauge (0.036\") 3x6 splice plate = the single-top-plate exception (R602.3.2). Don't swap them.", "audio_front": "Trap question. Sixteen gauge versus twenty gauge steel plates in wall framing. Which is which?", "audio_back": "The sixteen gauge tie repairs a top plate that was cut more than fifty percent. The twenty gauge three by six splice plate is the single top plate exception. Do not swap them.", "source": "MRC R602.6.1 | R602.3.2", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-031", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "How are header spans for exterior bearing walls determined?", "back": "From Tables R602.7(1) and (2), based on header size and plies, ground snow load, and building width. The tables also give the required number of jack studs.", "audio_front": "How are header spans for exterior bearing walls determined?", "audio_back": "From the header tables in section R six oh two point seven, based on header size, ground snow load, and building width. The same tables give the required number of jack studs.", "source": "MRC R602.7, Tables R602.7(1)-(2)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-032", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "What is a jack stud vs a king stud at a wall opening?", "back": "The jack (trimmer) stud is cut to header height and carries the header load to the plate; the king stud runs full height alongside and is nailed to the header end. The number of jacks comes from the header tables (R602.7).", "audio_front": "What is a jack stud versus a king stud at a wall opening?", "audio_back": "The jack or trimmer stud is cut to header height and carries the header load down. The king stud runs full height beside it and is nailed to the header end. The header tables tell you how many jacks are required.", "source": "MRC R602.7", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-033", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Wall bracing: where must braced wall panels be located along a braced wall line?", "back": "A panel must begin within 10 feet of each end of the braced wall line, and edges of adjacent panels may be no more than 20 feet apart (R602.10.2.2).", "audio_front": "Where must braced wall panels be located along a braced wall line?", "audio_back": "A panel must begin within ten feet of each end of the braced wall line, and adjacent panels may be no more than twenty feet apart. Section R six oh two point ten point two point two.", "source": "MRC R602.10.2.2", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-034", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Name the common wall-bracing method abbreviations LIB, WSP, GB, CS-WSP.", "back": "LIB = 1x4 let-in brace; WSP = wood structural panel (min 3/8\"); GB = gypsum board; CS-WSP = continuously sheathed wood structural panel (Table R602.10.4).", "audio_front": "Name the common wall bracing methods. L I B, W S P, G B, and C S dash W S P.", "audio_back": "L I B is a one by four let in brace. W S P is wood structural panel, minimum three eighths inch. G B is gypsum board. C S W S P is continuously sheathed wood structural panel.", "source": "MRC R602.10, Table R602.10.4", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-035", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "In Michigan, which load governs wall-bracing amounts — wind or seismic?", "back": "Wind. Michigan is Seismic Design Category A or B, so bracing is selected from the wind tables (R602.10.3, R301.2.2).", "audio_front": "In Michigan, which load governs wall bracing amounts, wind or seismic?", "audio_back": "Wind. Michigan is seismic design category A or B, so bracing comes from the wind tables.", "source": "MRC R602.10.3 | R301.2.2", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-036", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Minimum ridge board size?", "back": "Not less than 1-inch nominal thickness, and not less in depth than the cut end of the rafter (R802.3).", "audio_front": "What is the minimum ridge board size?", "audio_back": "Not less than one inch nominal thickness, and not less in depth than the cut end of the rafter. Section R eight oh two point three.", "source": "MRC R802.3", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-037", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Minimum valley or hip rafter size?", "back": "Not less than 2-inch nominal thickness and not less in depth than the cut end of the rafter (R802.3).", "audio_front": "What is the minimum valley or hip rafter size?", "audio_back": "Not less than two inch nominal thickness, and not less in depth than the cut end of the rafter. Section R eight oh two point three.", "source": "MRC R802.3", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-038", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "When must a ridge be designed as a beam?", "back": "When the roof pitch is less than 3:12 — ridge, hips, and valleys supporting rafters must then be designed as beams (R802.3).", "audio_front": "When must a roof ridge be designed as a structural beam?", "audio_back": "When the roof pitch is less than three in twelve. At that slope, ridges, hips, and valleys supporting rafters must be designed as beams. Section R eight oh two point three.", "source": "MRC R802.3", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-039", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Collar ties: location, size, spacing, and purpose?", "back": "Upper third of the attic space, minimum 1x4 nominal, spaced not more than 4 feet on center; they resist WIND UPLIFT at the ridge. Ridge straps (1-1/4\" x 20 ga) may substitute (R802.3.1).", "audio_front": "Collar ties. Where do they go, what size, what spacing, and what do they do?", "audio_back": "Upper third of the attic, minimum one by four nominal, spaced not more than four feet on center. They resist wind uplift at the ridge, and a twenty gauge ridge strap may substitute. Section R eight oh two point three point one.", "source": "MRC R802.3.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-040", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "TRAP: Collar ties vs rafter ties — which resists rafter thrust?", "back": "Rafter ties (or ceiling joists acting as ties) resist outward thrust, located in the lower portion of the attic at or near the plate. Collar ties in the upper third resist wind uplift only (R802.3.1).", "audio_front": "Trap question. Collar ties versus rafter ties. Which one resists rafter thrust?", "audio_back": "Rafter ties, or ceiling joists acting as ties, resist the outward thrust, and they sit low, at or near the plate. Collar ties in the upper third resist wind uplift only.", "source": "MRC R802.3.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-041", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "When are rafter ties required, and what minimum size?", "back": "Where ceiling joists are not connected to rafters at the top plate, or run perpendicular to the rafters. Minimum 2x4 nominal, providing a continuous tie; otherwise the ridge must be a designed beam (R802.3.1).", "audio_front": "When are rafter ties required, and what is the minimum size?", "audio_back": "When ceiling joists are not connected to the rafters at the top plate, or run perpendicular to the rafters. Minimum two by four nominal forming a continuous tie. Otherwise the ridge must be a designed beam.", "source": "MRC R802.3.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-042", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Minimum lap for ceiling joists over a bearing partition?", "back": "3 inches minimum lap, or butted over the bearing and toenailed to the bearing member (R802.3.2).", "audio_front": "What is the minimum lap for ceiling joists over a bearing partition?", "audio_back": "Three inches minimum lap, or the joists may be butted over the bearing and toe nailed to the bearing member. Section R eight oh two point three point two.", "source": "MRC R802.3.2", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-043", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Purlin brace requirements when purlins reduce rafter spans?", "back": "Purlins at least the size of the rafters supported; braced with 2x4s to bearing walls at not less than 45 degrees, spaced max 4 feet o.c., with unbraced brace length max 8 feet (R802.5.1).", "audio_front": "What are the purlin and purlin brace requirements when purlins are used to reduce rafter spans?", "audio_back": "Purlins must be at least the size of the rafters they support, braced with two by fours down to bearing walls at no less than forty five degrees, braces spaced at most four feet on center, and no brace longer than eight feet unbraced.", "source": "MRC R802.5.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-044", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Do the joist notching rules apply to rafters?", "back": "Yes. Rafters and ceiling joists follow the same sawn-lumber limits: notch D/6, end notch D/4, notch length D/3, holes D/3 with 2-inch clearances, no notches in the middle third (R802.7 / R502.8.1).", "audio_front": "Do the joist notching and boring rules also apply to rafters?", "audio_back": "Yes. Rafters and ceiling joists follow the same sawn lumber limits. Notch one sixth of depth, end notch one fourth, notch length one third, holes one third with two inch clearances, and no notches in the middle third of the span.", "source": "MRC R802.7 | R502.8.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-045", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Can roof trusses be field-altered (cut, drilled, notched)?", "back": "No — truss members shall not be cut, notched, drilled, spliced, or otherwise altered without approval of a registered design professional (R802.10.4).", "audio_front": "Can roof trusses be field altered, cut, drilled, or notched?", "audio_back": "No. Truss members may not be cut, notched, drilled, spliced, or otherwise altered without approval from a registered design professional. Section R eight oh two point ten point four.", "source": "MRC R802.10.4", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-046", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Fastening: joist to sill or girder?", "back": "3-8d toenails per joist (Table R602.3(1)).", "audio_front": "Fastening schedule. How is a joist nailed to a sill or girder?", "audio_back": "Three eight penny toe nails per joist, from the fastening schedule, Table R six oh two point three.", "source": "Table R602.3(1)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-047", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Fastening: top plate to top plate?", "back": "16d common nails at 16 inches on center, face nailed (Table R602.3(1)).", "audio_front": "Fastening schedule. How is the upper top plate nailed to the lower top plate?", "audio_back": "Sixteen penny common nails at sixteen inches on center, face nailed.", "source": "Table R602.3(1)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-048", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Fastening: double top plate splice (at end joints)?", "back": "8-16d common nails face-nailed on each side of the end joint (Table R602.3(1)).", "audio_front": "Fastening schedule. How is a double top plate splice nailed at end joints?", "audio_back": "Eight sixteen penny common nails, face nailed on each side of the end joint.", "source": "Table R602.3(1)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-049", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Fastening: stud to plate (end-nailed)?", "back": "2-16d common end nails (or toenail with 3-4 8d/16d box nails) (Table R602.3(1)).", "audio_front": "Fastening schedule. How is a stud end nailed to a plate?", "audio_back": "Two sixteen penny common nails, end nailed. Toe nailing with three or four smaller nails is the alternative.", "source": "Table R602.3(1)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-050", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Fastening: collar tie to rafter?", "back": "3-10d common nails face-nailed at each rafter, or a 1-1/4 inch 20-gauge ridge strap (Table R602.3(1)).", "audio_front": "Fastening schedule. How is a collar tie nailed to a rafter?", "audio_back": "Three ten penny common nails, face nailed at each rafter, or a one and a quarter inch twenty gauge ridge strap.", "source": "Table R602.3(1)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-051", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Fastening: wood structural panel sheathing (3/8\" to 1/2\") nail spacing?", "back": "6 inches on center at supported panel edges and 12 inches on center at intermediate supports (field) (Table R602.3(1)).", "audio_front": "Fastening schedule. What is the nail spacing for wood structural panel sheathing, three eighths to one half inch?", "audio_back": "Six inches on center at supported panel edges, and twelve inches on center in the field at intermediate supports.", "source": "Table R602.3(1)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-052", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Fastening: ceiling joist to top plate?", "back": "3-8d toenails per joist (Table R602.3(1)).", "audio_front": "Fastening schedule. How is a ceiling joist nailed to the top plate?", "audio_back": "Three eight penny toe nails per joist.", "source": "Table R602.3(1)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-053", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "MICHIGAN AMENDMENT: minimum stair tread depth?", "back": "9 inches — Michigan amendment (Mich Admin Code R 408.30519, amending MRC R311.7.5.2). The IRC default of 10 inches is the trap answer.", "audio_front": "Michigan amendment. What is the minimum stair tread depth?", "audio_back": "Nine inches, under Michigan administrative rule four oh eight point three oh five one nine. The I R C default of ten inches is the trap answer.", "source": "R 408.30519 | MRC R311.7.5.2", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-054", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "MICHIGAN AMENDMENT: maximum stair riser height?", "back": "8-1/4 inches — Michigan amendment (R 408.30519, amending MRC R311.7.5.1). IRC default 7-3/4 inches is the trap.", "audio_front": "Michigan amendment. What is the maximum stair riser height?", "audio_back": "Eight and one quarter inches under the Michigan amendment. The I R C default of seven and three quarters inches is the trap.", "source": "R 408.30519 | MRC R311.7.5.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-055", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Maximum variation between largest and smallest riser (or tread) in a flight?", "back": "3/8 inch (R311.7.5 / R 408.30519).", "audio_front": "What is the maximum variation between the largest and smallest riser or tread in one flight of stairs?", "audio_back": "Three eighths of an inch.", "source": "MRC R311.7.5 | R 408.30519", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-056", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Winder tread minimums in Michigan?", "back": "10 inches minimum tread depth measured at the 12-inch walk line from the narrow side, and 6 inches minimum at any point (R 408.30519).", "audio_front": "What are the winder tread minimums in Michigan?", "audio_back": "Ten inches minimum tread depth measured twelve inches from the narrow side, and six inches minimum at any point.", "source": "R 408.30519", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-057", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Minimum stair headroom?", "back": "6 feet 8 inches, measured vertically from a sloped plane along the tread nosings (R311.7.2).", "audio_front": "What is the minimum stair headroom?", "audio_back": "Six feet eight inches, measured vertically above the tread nosings. Section R three eleven point seven point two.", "source": "MRC R311.7.2", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-058", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Minimum stair width, and clear widths at handrails?", "back": "36 inches clear above the handrail height; 31-1/2 inches clear with a handrail on one side; 27 inches with handrails both sides (R311.7.1).", "audio_front": "What is the minimum stair width, and the clear widths at handrail level?", "audio_back": "Thirty six inches clear above handrail height. Thirty one and a half inches clear with one handrail, twenty seven inches with handrails on both sides.", "source": "MRC R311.7.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-059", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "When is a stair handrail required, and at what height?", "back": "On at least one side of flights with 4 or more risers; height 34 to 38 inches above the tread nosings, continuous (R311.7.8).", "audio_front": "When is a stair handrail required, and at what height?", "audio_back": "On at least one side of any flight with four or more risers, set thirty four to thirty eight inches above the tread nosings, and continuous for the flight.", "source": "MRC R311.7.8", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-060", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Type I circular handrail grip size?", "back": "Outside diameter 1-1/4 to 2 inches (R311.7.8.3).", "audio_front": "What is the grip size for a type one circular handrail?", "audio_back": "An outside diameter of one and a quarter to two inches.", "source": "MRC R311.7.8.3", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-061", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "When are guards required, and at what minimum height?", "back": "Where a walking surface is more than 30 inches above the floor or grade within 3 feet horizontally; minimum 36 inches high, openings rejecting a 4-inch sphere, 200-lb load at top (R312).", "audio_front": "When are guards required, and what is the minimum height?", "audio_back": "Where a walking surface is more than thirty inches above floor or grade. Minimum thirty six inches high, openings must reject a four inch sphere, and the top must resist a two hundred pound load. Section R three twelve.", "source": "MRC R312", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-062", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "TRAP: A builder frames stairs with 7-3/4\" risers and 10\" treads, another with 8-1/4\" risers and 9\" treads. Which complies in Michigan?", "back": "Both comply. Michigan's limits are MAXIMUM 8-1/4\" riser and MINIMUM 9\" tread — the stricter IRC-default stair also passes. The trap is thinking Michigan REQUIRES 9/8-1/4.", "audio_front": "Trap scenario. One builder frames stairs with seven and three quarter inch risers and ten inch treads. Another uses eight and a quarter inch risers and nine inch treads. Which complies in Michigan?", "audio_back": "Both comply. Michigan sets a maximum riser of eight and a quarter inches and a minimum tread of nine inches, so the stricter stair also passes.", "source": "R 408.30519", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-063", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Deck ledger: minimum size and material?", "back": "Minimum 2x8 pressure-preservative-treated No. 2 grade lumber (R507.2).", "audio_front": "What is the minimum size and material for a deck ledger board?", "audio_back": "A minimum two by eight, pressure preservative treated, number two grade lumber. Section R five oh seven point two.", "source": "MRC R507.2", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-064", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Deck ledger fasteners: type and finish?", "back": "1/2-inch lag screws or through-bolts with washers, hot-dipped galvanized or stainless steel — never electroplated (R507.2). Spacing per Table R507.2 based on joist span.", "audio_front": "What fasteners attach a deck ledger, and what finish is required?", "audio_back": "Half inch lag screws or through bolts with washers, hot dipped galvanized or stainless steel. Electroplated fasteners are prohibited. Spacing comes from Table R five oh seven point two based on joist span.", "source": "MRC R507.2, Table R507.2", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-065", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Deck lateral-load connection requirement (where provided)?", "back": "Hold-down tension devices at not fewer than 2 locations per deck, each with at least 1,500 lb allowable capacity (R507.2.3).", "audio_front": "What is the deck lateral load connection requirement, where hold downs are provided?", "audio_back": "Hold down tension devices at no fewer than two locations per deck, each rated for at least fifteen hundred pounds.", "source": "MRC R507.2.3", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-066", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Is flashing required at a deck ledger, and how deep must deck footings be in Michigan?", "back": "Yes — corrosion-resistant flashing at the ledger-to-house connection. Deck footings follow Michigan's 42-inch frost depth (R703.8 flashing; R403.1.4 MI amendment).", "audio_front": "Is flashing required at a deck ledger, and how deep must deck footings go in Michigan?", "audio_back": "Yes, corrosion resistant flashing is required where the ledger meets the house, and deck footings must reach Michigan's forty two inch frost depth.", "source": "MRC R703.8 | R403.1.4 (MI amend)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-067", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "TRAP: Does the 2015 MRC give prescriptive deck post height limits (4x4 = 8 ft, 6x6 = 14 ft)?", "back": "No. Those limits come from DCA 6 guidance and were codified in the 2021 IRC Table R507.4. The tested 2015 MRC has no deck post-height table.", "audio_front": "Trap question. Does the twenty fifteen M R C give prescriptive deck post height limits, like eight feet for a four by four?", "audio_back": "No. Those limits come from D C A six guidance and the twenty twenty one I R C. The tested twenty fifteen code has no deck post height table.", "source": "2015 MRC R507 (absent) | 2021 IRC R507.4", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-068", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Minimum wood structural panel thickness for the WSP wall-bracing method?", "back": "3/8-inch minimum wood structural panel (Table R602.10.4).", "audio_front": "What is the minimum wood structural panel thickness for the W S P wall bracing method?", "audio_back": "Three eighths of an inch minimum.", "source": "MRC Table R602.10.4", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-069", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Minimum subfloor panel for joists at 16\" o.c.?", "back": "15/32-inch (nominal 1/2\") APA-rated 32/16 wood structural panel (R503.2). 23/32-inch is the 24\" o.c. rating, not the 16\" minimum.", "audio_front": "What is the minimum subfloor panel for joists at sixteen inches on center?", "audio_back": "Fifteen thirty seconds of an inch, a nominal half inch panel with a thirty two sixteen span rating. The twenty three thirty seconds panel is the twenty four inch rating, not the sixteen inch minimum.", "source": "MRC R503.2", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-070", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Which code edition is tested on the MI Residential Builder exam for framing questions?", "back": "The 2015 Michigan Residential Code (IRC 2015 base with Michigan amendments). The 2021-based update was stayed by court order in July 2025 and is not in force.", "audio_front": "Which code edition is tested on the Michigan residential builder exam for framing questions?", "audio_back": "The twenty fifteen Michigan Residential Code, based on the twenty fifteen I R C with Michigan amendments. The twenty twenty one based update was stayed by court order in July of twenty twenty five.", "source": "LARA / HBAM v. LARA stay (7/7/2025)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-071", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "A 2x10 joist (9-1/4\" actual depth): max hole size and where can it go?", "back": "Max hole = 9.25/3 ≈ 3-1/16 inches, anywhere along the span, kept 2 inches clear of top/bottom edges, other holes, and notches (R502.8.1).", "audio_front": "For a two by ten joist with an actual depth of nine and a quarter inches, what is the maximum hole size, and where can it go?", "audio_back": "About three and one sixteenth inches, one third of the depth. It can go anywhere along the span as long as it stays two inches clear of the edges, other holes, and any notch.", "source": "MRC R502.8.1", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-072", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Cripple wall rules?", "back": "Framed with studs not smaller than the studs above; if over 4 feet tall, use the stud size required for an additional story; if under 14 inches, sheathe continuously or use solid blocking (R602.9).", "audio_front": "What are the cripple wall framing rules?", "audio_back": "Studs not smaller than the studding above. Over four feet tall, use the stud size required for an additional story. Under fourteen inches, sheathe continuously with structural panels.", "source": "MRC R602.9", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-073", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Fastening: band or rim joist to joist?", "back": "3-16d common nails, end-nailed (Table R602.3(1)).", "audio_front": "Fastening schedule. How is a band or rim joist nailed to each joist?", "audio_back": "Three sixteen penny common nails, end nailed.", "source": "Table R602.3(1)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-074", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Where must fireblocking be installed in framed construction?", "back": "At ceiling/floor levels of concealed stud spaces, horizontally at intervals not exceeding 10 feet, at interconnections of vertical and horizontal concealed spaces (soffits, drop ceilings), at stair stringers top and bottom, and around chimneys/vents at floor and ceiling levels (R302.11).", "audio_front": "Where must fire blocking be installed in framed construction?", "audio_back": "At ceiling and floor levels of concealed stud spaces, horizontally at least every ten feet, where vertical and horizontal concealed spaces meet such as soffits, at stair stringers top and bottom, and around chimneys and vents at floor and ceiling levels. Section R three oh two point eleven.", "source": "MRC R302.11", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-075", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "A framer bores a 2-1/2\" hole for a drain through a single 2x6 bearing stud (5-1/2\" wide). Legal?", "back": "No — 2-1/2\" is about 45% of 5-1/2\". A single bearing stud is limited to 40% (2.2\"). Legal only if the studs are doubled (up to 60%, max two successive) (R602.6).", "audio_front": "A framer bores a two and a half inch hole through a single two by six bearing stud. Is that legal?", "audio_back": "No. Two and a half inches is about forty five percent of the stud width, and a single bearing stud is limited to forty percent. It becomes legal only if the studs are doubled, which allows sixty percent on up to two successive studs.", "source": "MRC R602.6", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-076", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Bottom plate requirement under studs?", "back": "Studs must have full bearing on a nominal 2-by or larger plate/sill at least as wide as the studs (R602.3.4).", "audio_front": "What is the bottom plate requirement under wall studs?", "audio_back": "Studs must have full bearing on a nominal two by or larger plate at least as wide as the studs. Section R six oh two point three point four.", "source": "MRC R602.3.4", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-077", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "Max spacing of 2x4 studs in a NONBEARING wall, and height limit?", "back": "24 inches on center up to 14 feet in height (Table R602.3(5)).", "audio_front": "What is the maximum spacing of two by four studs in a non bearing wall, and the height limit?", "audio_back": "Twenty four inches on center, up to fourteen feet in height.", "source": "MRC Table R602.3(5)", "domain": "07_carpentry-framing"}, {"id": "carpentry-framing-078", "deck": "rb", "section": "trade", "category": "Trade: Carpentry", "front": "What supports a wood girder end that pockets into a masonry or concrete wall?", "back": "At least 3 inches of bearing (R502.6); untreated wood girders entering masonry/concrete need a 1/2-inch air space on tops, sides, and ends for decay protection (R317.1 condition).", "audio_front": "What is required where a wood girder end pockets into a masonry or concrete wall?", "audio_back": "At least three inches of bearing, and untreated wood needs a half inch air space at the top, sides, and end of the pocket for decay protection.", "source": "MRC R502.6 | R317.1", "domain": "07_carpentry-framing"}, {"id": "masonry-roofing-siding-001", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Rank the four mortar types from strongest to weakest.", "back": "M, S, N, O — mnemonic: every other letter of MaSoNwOrK. M = 2,500 psi, S = 1,800, N = 750, O = 350 (ASTM C270).", "audio_front": "Rank the four mortar types from strongest to weakest.", "audio_back": "M, S, N, O. Remember every other letter of the word masonwork. Type M is twenty five hundred p s i, S is eighteen hundred, N is seven fifty, and O is three fifty.", "source": "ASTM C270", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-002", "deck": "rb", "section": "trade", "category": "Masonry", "front": "A builder is laying CMU for a below-grade foundation wall. Which mortar type?", "back": "Type M — 2,500 psi minimum, for below-grade, foundations, retaining walls, and earth contact (ASTM C270).", "audio_front": "A builder is laying concrete block for a below grade foundation wall. Which mortar type should be used?", "audio_back": "Type M. It is the strongest at twenty five hundred p s i minimum and is used below grade, for foundations, retaining walls, and anywhere in contact with earth.", "source": "ASTM C270", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-003", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Which mortar type is standard for residential brick veneer above grade?", "back": "Type N — general-purpose, 750 psi minimum. Trap: Type M is NOT better here; M is for below grade.", "audio_front": "Which mortar type is standard for residential brick veneer above grade?", "audio_back": "Type N, the general purpose mortar at seven hundred fifty p s i minimum. Do not pick Type M just because it is strongest. M belongs below grade.", "source": "ASTM C270", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-004", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Which mortar type for tuckpointing soft historic masonry?", "back": "Type O — 350 psi, interior non-load-bearing and repointing where original mortar was soft.", "audio_front": "Which mortar type is used for tuck pointing soft historic masonry?", "audio_back": "Type O, the weakest at three hundred fifty p s i. It is for interior non load bearing work and repointing old soft mortar.", "source": "ASTM C270", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-005", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Minimum compressive strength of grout, and how does grout differ from mortar?", "back": "2,000 psi (ASTM C476). Grout is fluid, poured into CMU cells around rebar; mortar is stiffer, placed in bed and head joints (3/8-inch typical).", "audio_front": "What is the minimum compressive strength of grout, and how does grout differ from mortar?", "audio_back": "Two thousand p s i per A S T M C four seventy six. Grout is fluid and poured into block cells around rebar. Mortar is stiffer and placed in the bed and head joints, typically three eighths of an inch thick.", "source": "ASTM C476", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-006", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Cold-weather masonry: what changes below 40 degrees F? Below 20?", "back": "20-40 F: heat mixing water and sand so mortar is 40-120 F at use; protect work 24 hours. Below 20 F: no laying without heated enclosures. Antifreeze admixtures are never permitted.", "audio_front": "Cold weather masonry. What changes below forty degrees Fahrenheit, and below twenty degrees?", "audio_back": "Between twenty and forty degrees, heat the mixing water and sand so mortar is between forty and one twenty at time of use, and protect finished work for twenty four hours. Below twenty degrees, no laying without heated enclosures. Antifreeze in mortar is never permitted.", "source": "Industry standard (Kreh / masonry practice)", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-007", "deck": "rb", "section": "trade", "category": "Masonry", "front": "How long is mixed mortar usable, and can it be retempered?", "back": "About 2.5 hours board life. It may be retempered (water added and remixed) once within that window, then must be discarded.", "audio_front": "How long is mixed mortar usable, and can it be re tempered?", "audio_back": "About two and a half hours. It may be re tempered once within that window by adding water and remixing, then it must be discarded.", "source": "Industry standard (masonry practice)", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-008", "deck": "rb", "section": "trade", "category": "Masonry", "front": "What is efflorescence and its cause?", "back": "White powdery salt deposit on masonry. Water migrates through the wall, dissolves soluble salts, and leaves them behind on evaporation. Cure = fix the water path (flashing, weeps).", "audio_front": "What is efflorescence and what causes it?", "audio_back": "A white powdery salt deposit on masonry. Water moves through the wall, dissolves salts, and leaves them on the surface when it evaporates. The fix is the water path, flashing and weep holes, not the stain.", "source": "Industry standard", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-009", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Brick veneer: required air space between veneer and sheathing?", "back": "1 inch minimum, 4-1/2 inches maximum (MRC R703.8.4). Trap: 2 inches is chimney clearance, not air space.", "audio_front": "Brick veneer. What air space is required between the veneer and the sheathing?", "audio_back": "One inch minimum, four and a half inches maximum, per M R C R seven oh three point eight point four. Two inches is the chimney clearance trap answer, not the air space.", "source": "MRC R703.8.4", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-010", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Brick veneer wall tie spacing (area, horizontal, vertical)?", "back": "Each tie supports max 2.67 sq ft; max 32 inches o.c. horizontally and 24 inches o.c. vertically (MRC R703.8.4.1).", "audio_front": "Brick veneer wall tie spacing. Area per tie, horizontal, and vertical?", "audio_back": "Each tie supports no more than two point six seven square feet, spaced no more than thirty two inches on center horizontally and twenty four inches on center vertically. That is R seven oh three point eight point four point one.", "source": "MRC R703.8.4.1", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-011", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Trap: is veneer tie spacing 32 horizontal / 24 vertical, or 24 horizontal / 32 vertical?", "back": "32 inches HORIZONTAL, 24 inches VERTICAL. The bigger number runs along the course.", "audio_front": "Trap check. Is veneer tie spacing thirty two horizontal and twenty four vertical, or the reverse?", "audio_back": "Thirty two inches horizontal, twenty four inches vertical. The bigger number runs along the course.", "source": "MRC R703.8.4.1", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-012", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Corrugated sheet-metal veneer tie: minimum gauge and width?", "back": "No. 22 gage, 7/8 inch wide (MRC R703.8.4.1).", "audio_front": "Corrugated sheet metal veneer tie. Minimum gauge and width?", "audio_back": "Number twenty two gauge, seven eighths of an inch wide.", "source": "MRC R703.8.4.1", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-013", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Weephole spacing, minimum size, and location in brick veneer?", "back": "Max 33 inches o.c., min 3/16 inch diameter, located immediately above the flashing (MRC R703.8.6). First course above base flashing.", "audio_front": "Weep hole spacing, minimum size, and location in brick veneer?", "audio_back": "Maximum thirty three inches on center, minimum three sixteenths of an inch in diameter, located immediately above the flashing, in the first course of brick. That is R seven oh three point eight point six.", "source": "MRC R703.8.6", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-014", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Trap: ties at 32 inches, weeps at 33 inches — which is which?", "back": "Wall TIES max 32 inches o.c. horizontal; WEEPHOLES max 33 inches o.c. Weeps get the extra inch.", "audio_front": "Trap check. Ties at thirty two inches and weeps at thirty three. Which is which?", "audio_back": "Wall ties are thirty two inches on center horizontally. Weep holes are thirty three inches on center. Weeps get the extra inch.", "source": "MRC R703.8.4.1 / R703.8.6", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-015", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Steel lintel for brick veneer: typical angle size, max span, and bearing?", "back": "3 x 3 x 1/4 inch steel angle spans up to 6 feet; minimum 4 inches bearing each end; rust-inhibitive coating required (MRC R703.8.3, R703.8.3.1).", "audio_front": "Steel lintel for brick veneer. Typical angle size, maximum span, and bearing?", "audio_back": "A three by three by quarter inch steel angle spans up to six feet, with a minimum of four inches of bearing at each end, and a rust inhibitive coating.", "source": "MRC R703.8.3.1", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-016", "deck": "rb", "section": "trade", "category": "Masonry", "front": "What load may masonry veneer support?", "back": "Only the dead load of the veneer above it — never floor or roof loads (MRC R703.8.3). Veneer over wood framing is generally limited to the first story, 5 inches max thickness.", "audio_front": "What load may masonry veneer support?", "audio_back": "Only the dead load of the veneer above it, never floor or roof loads. Veneer over wood framing is generally limited to the first story and five inches of thickness.", "source": "MRC R703.8 / R703.8.3", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-017", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Name the seven flashing locations required by MRC R703.4.", "back": "Window/door openings; chimney or masonry intersections with frame or stucco walls; under and at ends of copings and sills; above projecting wood trim; where porches, decks, or stairs attach; wall-roof intersections; built-in gutters.", "audio_front": "Name the flashing locations required by M R C R seven oh three point four.", "audio_back": "Window and door openings. Chimney to wall intersections. Under and at the ends of copings and sills. Above projecting wood trim. Where porches, decks, or stairs attach to the wall. Wall to roof intersections. And built in gutters.", "source": "MRC R703.4", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-018", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Standard rebar in residential CMU cells, and horizontal joint reinforcement spacing?", "back": "#4 (1/2 inch) vertical bar in grouted cells (#5 for tall/retaining walls); 9-gage ladder or truss wire in bed joints every 16 inches vertically — every other course of 8-inch block.", "audio_front": "What rebar goes in residential block cells, and how is horizontal joint reinforcement spaced?", "audio_back": "Number four bar, one half inch, in grouted cells, with number five for taller or retaining walls. Nine gauge ladder or truss wire goes in the bed joints every sixteen inches vertically, which is every other course of eight inch block.", "source": "Industry standard (Kreh)", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-019", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Expansion joint vs. control joint — which material gets which?", "back": "Clay BRICK expands over time → EXPANSION joints (compressible filler). CMU SHRINKS as it cures → CONTROL joints (continuous vertical break). Opposite movements.", "audio_front": "Expansion joint versus control joint. Which masonry material gets which?", "audio_back": "Clay brick expands over time, so brick gets expansion joints with compressible filler. Concrete block shrinks as it cures, so block gets control joints. Brick grows, block shrinks.", "source": "Industry standard (Kreh)", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-020", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Define rowlock, soldier, and sailor courses.", "back": "Rowlock: brick on its face edge, end into the wall — sills and caps. Soldier: standing on end, narrow face out — over openings. Sailor: standing on end, broad face out.", "audio_front": "Define rowlock, soldier, and sailor brick courses.", "audio_back": "A rowlock is laid on its face edge with the end into the wall, used for sills and caps. A soldier stands on end with the narrow face out, used over openings. A sailor stands on end with the broad face showing.", "source": "Industry standard (Kreh)", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-021", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Which brick bond has a header course every 5th to 7th course?", "back": "Common (American) bond. Running bond = all stretchers offset half brick; Flemish = alternating headers and stretchers within each course; English = alternating all-header and all-stretcher courses; stack bond needs joint reinforcement.", "audio_front": "Which brick bond pattern has a header course every fifth to seventh course?", "audio_back": "Common bond, also called American bond. Running bond is all stretchers. Flemish alternates headers and stretchers within each course. English alternates full header courses and full stretcher courses. Stack bond needs joint reinforcement.", "source": "Industry standard (Kreh)", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-022", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Firebox wall thickness with and without firebrick lining?", "back": "10 inches solid masonry without lining; 8 inches total including a firebrick lining. Firebrick joints max 1/4 inch refractory mortar (MRC R1001.5).", "audio_front": "Firebox wall thickness with and without a firebrick lining?", "audio_back": "Ten inches of solid masonry without a lining, or eight inches total when lined with firebrick. Firebrick joints are a quarter inch maximum. That is R ten oh one point five.", "source": "MRC R1001.5", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-023", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Minimum firebox depth?", "back": "20 inches (MRC R1001.6).", "audio_front": "What is the minimum firebox depth?", "audio_back": "Twenty inches, per R ten oh one point six.", "source": "MRC R1001.6", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-024", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Hearth thickness vs. hearth extension thickness — and the exception?", "back": "Hearth slab: 4 inches min. Hearth extension: 2 inches min — may be 3/8 inch where the firebox opening is raised at least 8 inches above it (MRC R1001.9).", "audio_front": "Hearth thickness versus hearth extension thickness, and the exception?", "audio_back": "The hearth slab is four inches minimum. The hearth extension is two inches minimum, and it may be only three eighths of an inch where the firebox opening is raised at least eight inches above the extension.", "source": "MRC R1001.9", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-025", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Hearth extension dimensions for openings under vs. 6 sq ft and over?", "back": "Under 6 sq ft: 16 inches front, 8 inches each side. 6 sq ft or larger: 20 inches front, 12 inches each side (MRC R1001.10).", "audio_front": "Hearth extension dimensions for fireplace openings under six square feet, and six square feet or larger?", "audio_back": "Under six square feet, sixteen inches in front and eight inches each side. Six square feet or larger, twenty inches in front and twelve inches each side.", "source": "MRC R1001.10", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-026", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Fireplace clearance to combustibles per R1001.11?", "back": "2 inches from front faces and sides, 4 inches from the back face. Trap: it is not 2 inches everywhere.", "audio_front": "Fireplace clearance to combustibles?", "audio_back": "Two inches from the front faces and sides, and four inches from the back face. It is not two inches everywhere. That is R ten oh one point eleven.", "source": "MRC R1001.11", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-027", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Where must the fireplace damper be located?", "back": "At least 8 inches above the top of the fireplace opening (lintel) (MRC R1001.7.1). The lintel itself is noncombustible with 4-inch bearing each end.", "audio_front": "Where must the fireplace damper be located?", "audio_back": "At least eight inches above the top of the fireplace opening. The lintel itself must be noncombustible with four inches of bearing at each end.", "source": "MRC R1001.7.1", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-028", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Footing requirements for masonry fireplaces and chimneys?", "back": "Minimum 12 inches thick, extending at least 6 inches beyond the face on all sides, founded below frost depth — 42 inches in Michigan (MRC R1003.2).", "audio_front": "Footing requirements for masonry fireplaces and chimneys?", "audio_back": "At least twelve inches thick, extending at least six inches beyond the face on all sides, and founded below frost depth, which is forty two inches in Michigan.", "source": "MRC R1003.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-029", "deck": "rb", "section": "trade", "category": "Masonry", "front": "State the chimney termination rule (3-2-10).", "back": "At least 3 feet above the highest point where the chimney passes through the roof, AND at least 2 feet higher than any part of the building within 10 feet horizontally (MRC R1003.9).", "audio_front": "State the chimney termination rule, the three two ten rule.", "audio_back": "The chimney must extend at least three feet above the highest point where it passes through the roof, and at least two feet higher than any part of the building within ten feet measured horizontally.", "source": "MRC R1003.9", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-030", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Chimney crown requirements?", "back": "Slope at least 10 degrees to shed water; at least 2 inches thick at the outer edge; overhang (drip) projecting at least 2 inches; drip edge at least 1-1/2 inches from the chimney face (MRC R1003.9.1).", "audio_front": "Chimney crown requirements?", "audio_back": "Sloped at least ten degrees to shed water, at least two inches thick at the outer edge, overhanging at least two inches, with the drip at least one and a half inches from the chimney face.", "source": "MRC R1003.9.1", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-031", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Flue sizing ratios: round, square/rect under 2:1, rect 2:1 or more?", "back": "Round: 1/12 of fireplace opening area. Square and rectangular under 2:1 aspect: 1/10. Rectangular 2:1 or greater: 1/8 (MRC R1003.15).", "audio_front": "Flue sizing ratios. Round, square or rectangular under two to one, and rectangular two to one or more?", "audio_back": "A round flue must be at least one twelfth of the fireplace opening area. Square and rectangular flues under a two to one aspect ratio, one tenth. Rectangular flues at two to one or greater, one eighth.", "source": "MRC R1003.15", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-032", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Fireplace opening is 36 x 30 inches. Minimum round flue area?", "back": "1,080 sq in / 12 = 90 square inches (about an 11-inch diameter round flue).", "audio_front": "A fireplace opening is thirty six by thirty inches. What is the minimum round flue area?", "audio_back": "Thirty six times thirty is one thousand eighty square inches. Divide by twelve for a round flue. Ninety square inches, roughly an eleven inch diameter.", "source": "MRC R1003.15.1", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-033", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Chimney clearance to combustibles: interior vs. exterior chimney?", "back": "2 inches for chimneys interior to the building or within an exterior wall; 1 inch for chimneys located entirely outside the exterior walls (MRC R1003.18). The split is interior/exterior — NOT below/above the roofline.", "audio_front": "Chimney clearance to combustibles. Interior versus exterior chimney?", "audio_back": "Two inches for chimneys inside the building or within an exterior wall. One inch for chimneys entirely outside the exterior walls. The distinction is interior versus exterior, not below versus above the roof line.", "source": "MRC R1003.18", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-034", "deck": "rb", "section": "trade", "category": "Masonry", "front": "When is a chimney cricket required?", "back": "When the chimney dimension parallel to the ridgeline exceeds 30 inches and the chimney does not intersect the ridge (MRC R1003.20).", "audio_front": "When is a chimney cricket required?", "audio_back": "When the chimney dimension parallel to the ridge line is greater than thirty inches and the chimney does not intersect the ridge. That is R ten oh three point twenty.", "source": "MRC R1003.20", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-035", "deck": "rb", "section": "trade", "category": "Masonry", "front": "A mason is laying brick at 95 degrees F with 10 mph wind. What precautions?", "back": "Hot-weather rules trigger above 100 F, or above 90 F with wind over 8 mph: shade materials, dampen absorptive brick, fog-spray finished work, mix smaller batches.", "audio_front": "A mason is laying brick at ninety five degrees with a ten mile per hour wind. What precautions apply?", "audio_back": "Hot weather rules trigger above one hundred degrees, or above ninety with wind over eight miles per hour. Shade the materials, dampen absorptive brick, fog spray finished work, and mix smaller batches.", "source": "Industry standard (masonry practice)", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-036", "deck": "rb", "section": "trade", "category": "Masonry", "front": "What is a brick ledge?", "back": "A shelf formed at the top of the foundation wall that supports the veneer: brick width (3-5/8 inch modular) plus the 1-inch air space.", "audio_front": "What is a brick ledge?", "audio_back": "A shelf formed at the top of the foundation wall that supports the brick veneer. It carries the brick width, about three and five eighths inches for modular brick, plus the one inch air space.", "source": "Industry standard", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-037", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Minimum slope for asphalt shingles, and the underlayment rule below 4:12?", "back": "Minimum 2:12. From 2:12 up to 4:12, DOUBLE underlayment is required (19-inch starter, 36-inch sheets lapped 19 inches). 4:12 and steeper: single layer (MRC R905.2.2).", "audio_front": "Minimum slope for asphalt shingles, and the underlayment rule below four in twelve?", "audio_back": "Minimum slope is two in twelve. From two in twelve up to four in twelve you need double underlayment, a nineteen inch starter course and thirty six inch sheets lapped nineteen inches. At four in twelve and steeper, a single layer.", "source": "MRC R905.2.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-038", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Asphalt shingle fastener specs?", "back": "Galvanized, stainless, aluminum, or copper roofing nails; min 12-gage shank; 3/8-inch head; penetrating at least 3/4 inch into sheathing or through sheathing thinner than 3/4 inch (MRC R905.2.5).", "audio_front": "Asphalt shingle fastener specifications?", "audio_back": "Corrosion resistant roofing nails, minimum twelve gauge shank with a three eighths inch head, penetrating at least three quarters of an inch into the sheathing, or through sheathing thinner than that.", "source": "MRC R905.2.5", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-039", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Minimum number of fasteners per strip shingle?", "back": "4 per strip shingle (2 per individual shingle), or more if the manufacturer requires (MRC R905.2.6). Six nails is a high-wind or manufacturer spec, not the code minimum.", "audio_front": "Minimum number of fasteners per strip shingle?", "audio_back": "Four per strip shingle, two per individual shingle, or more where the manufacturer requires it. Six nails is a high wind or manufacturer specification, not the code minimum.", "source": "MRC R905.2.6", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-040", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Ice barrier: how far must it extend, and the steep-slope add-on?", "back": "From the lowest roof edge to at least 24 inches INSIDE the exterior wall line. Where slope is 8:12 or steeper, at least 36 inches measured along the slope from the eave edge (MRC R905.1.2). Michigan eaves require it.", "audio_front": "Ice barrier. How far must it extend, and what is the steep slope add on?", "audio_back": "From the lowest edge of the roof to at least twenty four inches inside the exterior wall line. On slopes of eight in twelve or steeper, at least thirty six inches measured along the slope from the eave edge. Michigan roofs require it.", "source": "MRC R905.1.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-041", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Trap: is the ice barrier measured from the eave edge or the wall line?", "back": "24 inches inside the EXTERIOR WALL LINE — not 24 inches from the eave edge. Wide overhangs need more membrane.", "audio_front": "Trap check. Is the ice barrier measured from the eave edge or the wall line?", "audio_back": "Twenty four inches inside the exterior wall line, not from the eave edge. A wide overhang means you need more membrane.", "source": "MRC R905.1.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-042", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Which structures are exempt from the ice barrier requirement?", "back": "Detached accessory structures with no conditioned floor area (MRC R905.1.2 exception).", "audio_front": "Which structures are exempt from the ice barrier requirement?", "audio_back": "Detached accessory structures that contain no conditioned floor area.", "source": "MRC R905.1.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-043", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Drip edge dimensions and lap?", "back": "Extends at least 1/4 inch below the sheathing and at least 2 inches back onto the roof deck; adjacent pieces overlap at least 2 inches (MRC R905.2.8.5).", "audio_front": "Drip edge dimensions and lap?", "audio_back": "It extends at least a quarter inch below the sheathing, at least two inches back onto the roof deck, and adjacent pieces overlap at least two inches.", "source": "MRC R905.2.8.5", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-044", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Drip edge sequencing: eaves vs. rakes?", "back": "At EAVES the underlayment goes OVER the drip edge. At RAKES the drip edge goes OVER the underlayment. Classic reversal trap.", "audio_front": "Drip edge sequencing at eaves versus rakes?", "audio_back": "At the eaves, the underlayment goes over the drip edge. At the rakes, the drip edge goes over the underlayment. They love to reverse this one.", "source": "MRC R905.2.8.5", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-045", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Step flashing size at a roof-sidewall intersection, and what goes at the bottom?", "back": "Minimum 4 inches high by 4 inches wide (MRC R905.2.8.3). A kickout (diverter) flashing at the bottom directs water into the gutter — key ice-dam and siding-rot detail.", "audio_front": "Step flashing size at a roof to sidewall intersection, and what goes at the bottom of the run?", "audio_back": "Minimum four inches high by four inches wide. At the bottom of the run, a kick out flashing diverts water into the gutter instead of behind the siding.", "source": "MRC R905.2.8.3", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-046", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Open valley metal flashing width?", "back": "At least 24 inches wide (MRC R905.2.8.2). Roll-roofing valley: 18-inch bottom ply plus 36-inch top ply.", "audio_front": "Open valley metal flashing width?", "audio_back": "At least twenty four inches wide. A roll roofing valley uses an eighteen inch bottom ply and a thirty six inch top ply.", "source": "MRC R905.2.8.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-047", "deck": "rb", "section": "trade", "category": "Roofing", "front": "When does reroofing require full tear-off?", "back": "When the existing roof is water-soaked or deteriorated; when the existing covering is wood shake, slate, or clay/cement/asbestos-cement tile; or when TWO or more layers of any covering already exist (MRC R908.3). Max = 2 layers.", "audio_front": "When does re roofing require a full tear off?", "audio_back": "When the existing roof is water soaked or deteriorated. When the existing covering is wood shake, slate, or tile. Or when two or more layers of any roof covering already exist. Two layers is the maximum.", "source": "MRC R908.3", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-048", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Underlayment application on a 5:12 asphalt shingle roof?", "back": "Single layer applied shingle fashion parallel to the eaves; 2-inch horizontal laps and 4-inch end laps offset 6 feet (MRC Table R905.1.1).", "audio_front": "Underlayment application on a five in twelve asphalt shingle roof?", "audio_back": "A single layer applied shingle fashion parallel to the eaves, with two inch horizontal laps and four inch end laps offset six feet.", "source": "MRC Table R905.1.1", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-049", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Minimum slopes: standing-seam metal, lapped metal with and without sealant?", "back": "Standing seam: 1/4:12. Lapped with sealant: 1/2:12. Lapped without sealant: 3:12 (MRC R905.10.2).", "audio_front": "Minimum slopes for standing seam metal, and lapped metal panels with and without sealant?", "audio_back": "Standing seam, one quarter in twelve. Lapped panels with lap sealant, one half in twelve. Lapped panels without sealant, three in twelve.", "source": "MRC R905.10.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-050", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Minimum slopes: built-up roofing, single-ply (EPDM/TPO), mineral-surfaced roll roofing?", "back": "Built-up: 1/4:12 (coal tar 1/8:12). Thermoset and thermoplastic single-ply: 1/4:12. Mineral-surfaced roll roofing: 1:12 (MRC R905.9.1, R905.12.1/.13.1, R905.5.2).", "audio_front": "Minimum slopes for built up roofing, single ply membranes, and mineral surfaced roll roofing?", "audio_back": "Built up roofing, one quarter in twelve, with coal tar allowed at one eighth. Single ply membranes like E P D M and T P O, one quarter in twelve. Mineral surfaced roll roofing, one in twelve.", "source": "MRC R905.5.2 / R905.9.1 / R905.12.1", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-051", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Minimum roof slopes for wood shingles vs. wood shakes?", "back": "Both 3:12 (MRC R905.7.2 / R905.8.2). Trap: 4:12 for shakes is the commercial IBC number, not the MRC. Shakes also need 18-inch-wide No. 30 felt interlayment between courses.", "audio_front": "Minimum roof slopes for wood shingles versus wood shakes?", "audio_back": "Both are three in twelve under the residential code. Four in twelve for shakes is the commercial code trap. Shakes also need eighteen inch wide number thirty felt interlayment between the courses.", "source": "MRC R905.7.2 / R905.8.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-052", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Attic ventilation: base ratio and the two paths to 1/300?", "back": "Base: 1/150 of the vented attic area. 1/300 allowed with EITHER (a) Class I or II vapor retarder on the warm side in Climate Zones 6-8, OR (b) 40-50 percent of vent area high (within 3 ft of ridge) with the balance at the eaves (MRC R806.2).", "audio_front": "Attic ventilation. Base ratio and the two paths to one to three hundred?", "audio_back": "The base is one to one fifty of the attic area. You may use one to three hundred with either a class one or two vapor retarder on the warm side in climate zones six through eight, or with forty to fifty percent of the vent area high, within three feet of the ridge, and the rest at the eaves.", "source": "MRC R806.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-053", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Trap: can a Zone 5A (southern Michigan) house use the vapor-retarder path to 1/300 ventilation?", "back": "No — the vapor-retarder condition applies only in Climate Zones 6, 7, and 8. Zone 5A must use the balanced 40-50 percent high-vent path (MRC R806.2).", "audio_front": "Trap check. Can a climate zone five A house in southern Michigan use the vapor retarder path to one to three hundred ventilation?", "audio_back": "No. The vapor retarder condition applies only in climate zones six, seven, and eight. In zone five A you must use the balanced high and low vent path.", "source": "MRC R806.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-054", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Minimum airspace between insulation and roof sheathing at vents?", "back": "1 inch (MRC R806.3) — maintained with baffles at the eaves.", "audio_front": "Minimum air space between insulation and roof sheathing at vent locations?", "audio_back": "One inch, maintained with baffles at the eaves. That is R eight oh six point three.", "source": "MRC R806.3", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-055", "deck": "rb", "section": "trade", "category": "Roofing", "front": "A roofer is shingling a 3:12 porch roof. What underlayment is required?", "back": "Two layers (double underlayment) — 3:12 falls in the 2:12-to-4:12 band (MRC R905.2.2). Shingles themselves are permitted since slope is at least 2:12.", "audio_front": "A roofer is shingling a three in twelve porch roof. What underlayment is required?", "audio_back": "Two layers. Three in twelve falls in the band between two in twelve and four in twelve, which requires double underlayment. Shingles are allowed because the slope is at least two in twelve.", "source": "MRC R905.2.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-056", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Roof-to-masonry base and cap flashing material spec?", "back": "Corrosion-resistant metal, minimum nominal 0.019 inch thickness (MRC R905.2.8.4); cap (counter) flashing same metal.", "audio_front": "Roof to masonry base and cap flashing material specification?", "audio_back": "Corrosion resistant metal at least nineteen thousandths of an inch thick, with cap flashing of the same metal.", "source": "MRC R905.2.8.4", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-057", "deck": "rb", "section": "trade", "category": "Roofing", "front": "How many roofing squares in a 2,400 sq ft roof?", "back": "24 squares — one square = 100 sq ft of roof area.", "audio_front": "How many roofing squares in a twenty four hundred square foot roof?", "audio_back": "Twenty four squares. One square equals one hundred square feet of roof area.", "source": "Industry standard", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-058", "deck": "rb", "section": "trade", "category": "Siding", "front": "WRB (housewrap/felt) lap requirements?", "back": "No. 15 asphalt felt or equivalent; horizontal laps at least 2 inches, vertical laps at least 6 inches, upper over lower shingle-fashion (MRC R703.2).", "audio_front": "Water resistive barrier lap requirements?", "audio_back": "Number fifteen felt or an approved equivalent, lapped at least two inches horizontally and six inches at vertical joints, always upper over lower, shingle fashion.", "source": "MRC R703.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-059", "deck": "rb", "section": "trade", "category": "Siding", "front": "General siding fastener penetration requirement?", "back": "At least 1-1/4 inches into sheathing and framing combined, or per manufacturer instructions or test report (MRC R703.3.3).", "audio_front": "General siding fastener penetration requirement?", "audio_back": "At least one and a quarter inches into the sheathing and framing combined, or as the manufacturer's instructions or test report specify.", "source": "MRC R703.3.3", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-060", "deck": "rb", "section": "trade", "category": "Siding", "front": "Why is vinyl siding never nailed tight?", "back": "High thermal movement — a 12-foot panel can move about 1/2 inch. Center nails in slots and leave about 1/32 inch between head and flange; 1/4-inch gaps at trim. Tight nailing buckles panels.", "audio_front": "Why is vinyl siding never nailed tight?", "audio_back": "Vinyl moves a lot with temperature. A twelve foot panel can move about half an inch. Center the nails in the slots, leave about one thirty second of an inch under the head, and a quarter inch gap at trim. Nail it tight and it buckles.", "source": "MRC R703.11 / VSI installation standard", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-061", "deck": "rb", "section": "trade", "category": "Siding", "front": "Vinyl siding installation order?", "back": "WRB, flashing at openings, level starter strip, corner posts, J-channel at openings and transitions, then panels bottom-up, each course locking into the one below.", "audio_front": "Vinyl siding installation order?", "audio_back": "Weather barrier first, flashing at the openings, a level starter strip, corner posts, J channel around windows and doors, then hang panels from the bottom up, locking each course into the one below.", "source": "VSI installation standard", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-062", "deck": "rb", "section": "trade", "category": "Siding", "front": "Fiber cement lap siding: minimum lap, and what must be done to field cuts?", "back": "Lapped at least 1-1/4 inches (MRC R703.10.2); corrosion-resistant fasteners; prime or seal all field-cut edges to stop moisture absorption.", "audio_front": "Fiber cement lap siding. Minimum lap, and what must be done to field cuts?", "audio_back": "Lapped at least one and a quarter inches, fastened with corrosion resistant nails, and every field cut edge must be primed or sealed so it does not absorb moisture.", "source": "MRC R703.10.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-063", "deck": "rb", "section": "trade", "category": "Siding", "front": "Fiber cement manufacturer clearances (Hardie-type): grade and roofing?", "back": "Commonly 6 inches above finished grade and 2 inches above roofing — manufacturer installation requirements, not MRC numbers. Trap: 1-1/4 inches is the LAP, not a clearance.", "audio_front": "Fiber cement manufacturer clearances above grade and above roofing?", "audio_back": "Commonly six inches above finished grade and two inches above roofing, per the manufacturer's instructions. One and a quarter inches is the lap, not a clearance.", "source": "Manufacturer installation instructions (James Hardie)", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-064", "deck": "rb", "section": "trade", "category": "Siding", "front": "Wood shingles vs. shakes — the physical difference?", "back": "Shingles are sawn both sides (smooth, uniform); shakes are split on at least one side (thick, rustic). Both: 2 fasteners per piece and a keyway gap between units.", "audio_front": "Wood shingles versus shakes. What is the physical difference?", "audio_back": "Shingles are sawn on both sides, smooth and uniform. Shakes are split on at least one side, thicker and rustic. Both take two fasteners per piece with a small gap between units.", "source": "MRC R905.7 / R905.8", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-065", "deck": "rb", "section": "trade", "category": "Siding", "front": "Stucco: coats over lath vs. over masonry, and curing?", "back": "3 coats over metal or wire lath; 2 coats over masonry or concrete. Moist-cure each coat at least 48 hours (MRC R703.7.2, R703.7.4).", "audio_front": "Stucco. How many coats over lath versus over masonry, and what curing is required?", "audio_back": "Three coats over metal or wire lath, two coats over masonry or concrete, and each coat is kept moist for at least forty eight hours.", "source": "MRC R703.7.2 / R703.7.4", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-066", "deck": "rb", "section": "trade", "category": "Siding", "front": "Stucco weep screed height above earth and paving?", "back": "At least 4 inches above earth or 2 inches above paved areas (MRC R703.7.2.1). Trap: 6 inches is the fiber-cement grade clearance.", "audio_front": "Stucco weep screed height above earth and above paving?", "audio_back": "At least four inches above the earth, or two inches above paved areas. Six inches is the fiber cement clearance, a different number.", "source": "MRC R703.7.2.1", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-067", "deck": "rb", "section": "trade", "category": "Siding", "front": "Where is kickout flashing required and why?", "back": "Where a roof slope terminates against a sidewall — it diverts water into the gutter instead of behind the siding. In Michigan this is a prime ice-dam and hidden-rot location.", "audio_front": "Where is kick out flashing required and why?", "audio_back": "Where a roof slope dies into a sidewall. It kicks the water out into the gutter instead of letting it run behind the siding. In Michigan that is a prime ice dam and hidden rot location.", "source": "MRC R703.4 / R905.2.8.3", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-068", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "The five drywall finish levels — one-line each.", "back": "L1: tape embedded (plenums). L2: tape + 1 coat (garages, behind tile). L3: tape + 2 coats (heavy texture). L4: tape + 3 coats (standard flat paint). L5: three coats + full skim coat (gloss, critical light). L0 = none.", "audio_front": "Name the five drywall finish levels.", "audio_back": "Level one, tape embedded in compound, for plenums. Level two, tape plus one coat, garages and behind tile. Level three, tape plus two coats, for heavy texture. Level four, tape plus three coats, the standard wall. Level five, three coats plus a skim coat over everything, for gloss paint and critical lighting.", "source": "GA-214 industry standard", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-069", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "A client wants semi-gloss on the great-room walls with big windows. What finish level?", "back": "Level 5 — three coats plus a skim coat over the entire surface. Sheen and raking light telegraph joints at Level 4 and below.", "audio_front": "A client wants semi gloss paint on great room walls with big windows. What drywall finish level?", "audio_back": "Level five. Three coats plus a skim coat over the whole surface. Sheen and raking light will telegraph the joints at level four or below.", "source": "GA-214 industry standard", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-070", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "Thinset vs. mastic — where is each allowed?", "back": "Thinset (cement-based) works everywhere: floors, walls, wet areas, exterior. Mastic (organic adhesive) is DRY-AREA WALL tile only — never showers, tub surrounds, or floors.", "audio_front": "Thin set versus mastic. Where is each allowed?", "audio_back": "Thin set, the cement based mortar, works everywhere, floors, walls, wet areas, exterior. Mastic, the organic adhesive, is for dry area wall tile only. Never in showers, tub surrounds, or on floors.", "source": "ANSI A108/A118 industry standard", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-071", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "Required substrate for tile in a shower?", "back": "Cement backer board (or equivalent) with a waterproof membrane — never green board (moisture-resistant drywall) as a wet-area tile substrate.", "audio_front": "Required substrate for tile in a shower?", "audio_back": "Cement backer board or an equivalent, with a waterproof membrane. Never green board. Moisture resistant drywall is not a wet area tile substrate.", "source": "ANSI A118.9 industry standard", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-072", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "Hardwood flooring over wood subfloor: direction, fastening, expansion gap?", "back": "Run perpendicular to joists; blind-nail through the tongue at 45 degrees, cleats/staples every 6-8 inches; leave a 3/8-inch expansion gap at walls (hidden by base). Underlayment felt below.", "audio_front": "Hardwood flooring over a wood subfloor. Direction, fastening, and expansion gap?", "audio_back": "Run it perpendicular to the joists, blind nail through the tongue at forty five degrees every six to eight inches, and leave a three eighths inch expansion gap at the walls, covered by the baseboard.", "source": "NWFA industry standard", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-073", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "Exterior painting: bare-wood priming window and pre-1978 rule?", "back": "Prime bare wood within about 2 weeks of exposure (UV degrades fibers); one primer coat plus two finish coats. Homes built before 1978: EPA RRP lead-safe rules apply.", "audio_front": "Exterior painting. The bare wood priming window and the pre nineteen seventy eight rule?", "audio_back": "Prime bare wood within about two weeks of exposure, then one primer coat and two finish coats. On homes built before nineteen seventy eight, the E P A lead renovation rules apply.", "source": "Industry standard / EPA RRP", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-074", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "Interior trim: name the piece at wall-floor, wall-ceiling, and around openings.", "back": "Baseboard at wall-floor; crown at wall-ceiling; casing around door and window openings; shoe/quarter-round covers the base-to-floor gap; chair rail at 32-36 inches.", "audio_front": "Interior trim. Name the piece at the wall to floor joint, wall to ceiling joint, and around openings.", "audio_back": "Baseboard at the wall to floor joint. Crown molding at the wall to ceiling joint. Casing around doors and windows. Shoe molding covers the gap under the base, and chair rail runs at about thirty two to thirty six inches.", "source": "Industry standard", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-075", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Spark arrestor screen requirements (where installed)?", "back": "Net free area at least 4 times the flue outlet area; openings must not pass a sphere larger than 1/2 inch nor block one smaller than 3/8 inch (MRC R1003.9.2).", "audio_front": "Spark arrestor screen requirements where one is installed?", "audio_back": "Net free area at least four times the flue outlet area, with openings that will not pass a half inch sphere and will not block a three eighths inch sphere.", "source": "MRC R1003.9.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-076", "deck": "rb", "section": "trade", "category": "Masonry", "front": "Cricket height for a 12:12 roof vs. a 6:12 roof (as fraction of chimney width)?", "back": "12:12 roof: cricket height = 1/2 the chimney width. 6:12: 1/4 the width. (8:12 = 1/3, 4:12 = 1/6, 3:12 = 1/8 — MRC R1003.20 table.)", "audio_front": "Cricket height for a twelve twelve roof versus a six twelve roof, as a fraction of chimney width?", "audio_back": "On a twelve twelve roof the cricket height is half the chimney width. On a six twelve it is one quarter. Eight twelve is one third, four twelve is one sixth, three twelve is one eighth.", "source": "MRC R1003.20", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-077", "deck": "rb", "section": "trade", "category": "Roofing", "front": "Minimum slope for clay and concrete tile?", "back": "2-1/2:12, with double underlayment required below 4:12 (MRC R905.3.2).", "audio_front": "Minimum slope for clay and concrete roof tile?", "audio_back": "Two and a half in twelve, with double underlayment required on slopes below four in twelve.", "source": "MRC R905.3.2", "domain": "08_masonry-roofing-siding"}, {"id": "masonry-roofing-siding-078", "deck": "rb", "section": "trade", "category": "Siding", "front": "Scenario: siding contractor nails vinyl tight through the top of the flange. What happens?", "back": "Panels cannot move with temperature — buckling and waviness. Nails belong centered in the slots with about 1/32-inch clearance under the head.", "audio_front": "A siding contractor nails vinyl tight through the top of the flange. What happens?", "audio_back": "The panels cannot move with temperature, so they buckle and ripple. Nails belong centered in the slots with about one thirty second of an inch of clearance under the head.", "source": "VSI installation standard", "domain": "08_masonry-roofing-siding"}, {"id": "envelope-interior-001", "deck": "rb", "section": "trade", "category": "Insulation", "front": "What is the required ceiling insulation R-value in Michigan climate zone 5A (southern Lower Peninsula)?", "back": "R-38 per 2015 MRC Table N1102.1.1. This is a Michigan amendment — the base 2015 IECC requires R-49 in zone 5, so R-49 is the trap answer.", "audio_front": "What is the required ceiling insulation R value in Michigan climate zone five A, the southern Lower Peninsula?", "audio_back": "R thirty eight, per the twenty fifteen Michigan Residential Code energy table. This is a Michigan amendment. The base national code says R forty nine in zone five, so R forty nine is the trap answer.", "source": "MRC Table N1102.1.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-002", "deck": "rb", "section": "trade", "category": "Insulation", "front": "What is the required ceiling R-value in Michigan climate zones 6A and 7 (northern LP and UP)?", "back": "R-49 per MRC Table N1102.1.1. Only zone 5A drops to R-38.", "audio_front": "What is the required ceiling R value in Michigan climate zones six A and seven, the northern Lower Peninsula and the Upper Peninsula?", "audio_back": "R forty nine per the energy table. Only zone five A drops to R thirty eight.", "source": "MRC Table N1102.1.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-003", "deck": "rb", "section": "trade", "category": "Insulation", "front": "What wood-frame wall insulation satisfies the Michigan energy code in all three climate zones?", "back": "R-20 cavity insulation, OR R-13 cavity plus R-5 continuous insulated sheathing (Table N1102.1.1). Same requirement in zones 5A, 6A, and 7.", "audio_front": "What wood frame wall insulation satisfies the Michigan energy code in all three climate zones?", "audio_back": "R twenty cavity insulation, or R thirteen cavity plus R five continuous insulated sheathing. The same requirement applies in zones five A, six A, and seven.", "source": "MRC Table N1102.1.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-004", "deck": "rb", "section": "trade", "category": "Insulation", "front": "Basement wall insulation: zone 5A vs zones 6A/7?", "back": "Zone 5A: R-10 continuous or R-13 cavity (10/13). Zones 6A and 7: R-15 continuous or R-19 cavity (15/19). Table N1102.1.1.", "audio_front": "Basement wall insulation. What is required in zone five A versus zones six A and seven?", "audio_back": "Zone five A requires R ten continuous or R thirteen cavity. Zones six A and seven require R fifteen continuous or R nineteen cavity.", "source": "MRC Table N1102.1.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-005", "deck": "rb", "section": "trade", "category": "Insulation", "front": "In the energy table notation '10/13' for basement walls, what do the two numbers mean?", "back": "First number = continuous insulation R-value (e.g., rigid foam); second = cavity insulation R-value in a framed wall. Either method complies.", "audio_front": "In the energy table notation ten slash thirteen for basement walls, what do the two numbers mean?", "audio_back": "The first number is the continuous insulation R value, such as rigid foam. The second is the cavity insulation R value in a framed wall. Either method complies.", "source": "MRC Table N1102.1.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-006", "deck": "rb", "section": "trade", "category": "Insulation", "front": "Slab-edge insulation requirements in Michigan zone 5A vs zones 6A/7?", "back": "R-10 in all zones; depth differs — 2 feet in zone 5A, 4 feet in zones 6A and 7 (Table N1102.1.1).", "audio_front": "What are the slab edge insulation requirements in Michigan zone five A versus zones six A and seven?", "audio_back": "R ten in all zones. The depth differs. Two feet deep in zone five A, and four feet deep in zones six A and seven.", "source": "MRC Table N1102.1.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-007", "deck": "rb", "section": "trade", "category": "Insulation", "front": "Floor insulation (over unconditioned space) in Michigan: zones 5A/6A vs zone 7?", "back": "R-30 in zones 5A and 6A; R-38 in zone 7 (Table N1102.1.1).", "audio_front": "What floor insulation is required over unconditioned space in Michigan zones five A and six A, versus zone seven?", "audio_back": "R thirty in zones five A and six A. R thirty eight in zone seven.", "source": "MRC Table N1102.1.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-008", "deck": "rb", "section": "trade", "category": "Insulation", "front": "What is Michigan's maximum air-leakage rate for a new dwelling, and how is it verified?", "back": "4 air changes per hour at 50 pascals (4 ACH50), verified by a mandatory blower-door test (N1102.4.1.2, Michigan amendment). The model IECC's 3 ACH50 is a trap.", "audio_front": "What is Michigan's maximum air leakage rate for a new dwelling, and how is it verified?", "audio_back": "Four air changes per hour at fifty pascals, verified by a mandatory blower door test. This is a Michigan amendment. The model code value of three is a trap answer.", "source": "MRC N1102.4.1.2", "domain": "09_envelope-interior"}, {"id": "envelope-interior-009", "deck": "rb", "section": "trade", "category": "Insulation", "front": "Which climate zones cover Michigan, and where?", "back": "Zone 5A = southern Lower Peninsula; zone 6A = northern Lower Peninsula and eastern UP; zone 7 = western Upper Peninsula.", "audio_front": "Which climate zones cover Michigan, and where is each?", "audio_back": "Zone five A is the southern Lower Peninsula. Zone six A is the northern Lower Peninsula and eastern Upper Peninsula. Zone seven is the western Upper Peninsula.", "source": "MRC N1101 / Table N1102.1.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-010", "deck": "rb", "section": "trade", "category": "Insulation", "front": "Which vapor retarder class is required on frame walls in Michigan, and on which side?", "back": "Class I or Class II on the INTERIOR (warm-in-winter) side in climate zones 5, 6, and 7 (MRC R702.7). Exterior-side placement is the trap.", "audio_front": "Which vapor retarder class is required on frame walls in Michigan, and on which side of the wall?", "audio_back": "Class one or class two, on the interior, warm in winter side, in climate zones five, six, and seven. Putting it on the exterior side is the trap.", "source": "MRC R702.7", "domain": "09_envelope-interior"}, {"id": "envelope-interior-011", "deck": "rb", "section": "trade", "category": "Insulation", "front": "Define vapor retarder Classes I, II, and III with examples.", "back": "Class I: 0.1 perm or less — polyethylene sheet, foil facing. Class II: over 0.1 up to 1.0 perm — kraft-faced batts. Class III: over 1.0 up to 10 perms — latex or enamel paint.", "audio_front": "Define vapor retarder classes one, two, and three, with an example of each.", "audio_back": "Class one is zero point one perm or less, such as polyethylene sheet or foil facing. Class two is over zero point one up to one perm, such as kraft faced batts. Class three is over one up to ten perms, such as latex or enamel paint.", "source": "MRC R202 / R702.7", "domain": "09_envelope-interior"}, {"id": "envelope-interior-012", "deck": "rb", "section": "trade", "category": "Insulation", "front": "When is a Class III vapor retarder (painted drywall) permitted on a zone 5 wall?", "back": "Only with vented cladding over wood structural panels, fiberboard, or gypsum sheathing, OR with continuous insulated sheathing of at least R-5 over a 2x4 wall or R-7.5 over a 2x6 wall (Table R702.7.1).", "audio_front": "When is a class three vapor retarder, meaning painted drywall, permitted on a climate zone five wall?", "audio_back": "Only with vented cladding over wood structural panels, fiberboard, or gypsum sheathing, or with continuous insulated sheathing of at least R five over a two by four wall, or R seven point five over a two by six wall.", "source": "MRC Table R702.7.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-013", "deck": "rb", "section": "trade", "category": "Insulation", "front": "Zone 6 insulated-sheathing minimums that allow a Class III vapor retarder?", "back": "R-7.5 continuous over a 2x4 wall; R-11.25 over a 2x6 wall. Zones 7-8: R-10 over 2x4, R-15 over 2x6 (Table R702.7.1).", "audio_front": "What insulated sheathing minimums allow a class three vapor retarder in zone six?", "audio_back": "R seven point five continuous over a two by four wall, and R eleven point two five over a two by six wall. In zone seven it rises to R ten over a two by four and R fifteen over a two by six.", "source": "MRC Table R702.7.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-014", "deck": "rb", "section": "trade", "category": "Insulation", "front": "Why is polyethylene sheeting on the EXTERIOR side of a Michigan frame wall wrong?", "back": "With the required interior Class I/II retarder it creates a double vapor barrier — moisture entering the assembly cannot dry in either direction, trapping water and causing rot/mold.", "audio_front": "Why is polyethylene sheeting on the exterior side of a Michigan frame wall wrong?", "audio_back": "Combined with the required interior vapor retarder it creates a double vapor barrier. Moisture that enters the assembly cannot dry in either direction, so it stays trapped and causes rot and mold.", "source": "MRC R702.7 (principle)", "domain": "09_envelope-interior"}, {"id": "envelope-interior-015", "deck": "rb", "section": "trade", "category": "Insulation", "front": "Approximate R-value per inch: fiberglass batt, blown cellulose, XPS, closed-cell spray foam?", "back": "Fiberglass batt about 3.2, blown cellulose about 3.5, extruded polystyrene (XPS) about 5, closed-cell spray foam about 6 to 6.5 per inch.", "audio_front": "Give the approximate R value per inch for fiberglass batt, blown cellulose, extruded polystyrene, and closed cell spray foam.", "audio_back": "Fiberglass batt about three point two per inch. Blown cellulose about three point five. Extruded polystyrene about five. Closed cell spray foam about six to six and a half per inch.", "source": "industry standard", "domain": "09_envelope-interior"}, {"id": "envelope-interior-016", "deck": "rb", "section": "trade", "category": "Insulation", "front": "A builder compresses an R-19 batt into a 2x4 wall cavity. What happens to its R-value?", "back": "It drops below R-19 (to roughly R-13/R-14). Insulation only delivers rated R at full loft; compression reduces performance.", "audio_front": "A builder compresses an R nineteen batt into a two by four wall cavity. What happens to its R value?", "audio_back": "It drops below R nineteen, to roughly R thirteen or R fourteen. Insulation only delivers its rated R value at full thickness. Compression reduces performance.", "source": "industry standard", "domain": "09_envelope-interior"}, {"id": "envelope-interior-017", "deck": "rb", "section": "trade", "category": "Insulation", "front": "What clearance must attic insulation baffles maintain at eave vents?", "back": "A minimum 1-inch airspace between the insulation and the roof sheathing so ventilation air can flow from soffit to ridge (R806.3).", "audio_front": "What clearance must attic insulation baffles maintain at eave vents?", "audio_back": "A minimum one inch air space between the insulation and the roof sheathing, so ventilation air can flow from the soffit to the ridge.", "source": "MRC R806.3", "domain": "09_envelope-interior"}, {"id": "envelope-interior-018", "deck": "rb", "section": "trade", "category": "Insulation", "front": "What is the maximum fenestration (window) U-factor under the 2015 Michigan energy code?", "back": "0.32 in all Michigan zones (Table N1102.1.1). 0.30 is the 2021 IECC value — a trap; the 2021 code is not in force for the exam.", "audio_front": "What is the maximum window U factor under the twenty fifteen Michigan energy code?", "audio_back": "Zero point three two, in all Michigan zones. Zero point three zero is the twenty twenty one national value, which is a trap. The twenty twenty one code is not in force for the exam.", "source": "MRC Table N1102.1.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-019", "deck": "rb", "section": "trade", "category": "Insulation", "front": "What does U-factor measure and how does it relate to R-value?", "back": "U-factor is the rate of heat transmission through an assembly; U = 1/R. LOWER U-factor = better insulating performance.", "audio_front": "What does U factor measure, and how does it relate to R value?", "audio_back": "U factor is the rate of heat transmission through an assembly. It is the reciprocal of R value, one divided by R. A lower U factor means better insulating performance.", "source": "industry standard", "domain": "09_envelope-interior"}, {"id": "envelope-interior-020", "deck": "rb", "section": "trade", "category": "Insulation", "front": "Is there an SHGC (solar heat gain coefficient) requirement for windows in Michigan?", "back": "No — SHGC is 'NR' (not required) in climate zones 5 through 8. Any numeric SHGC answer for Michigan is a trap; SHGC limits apply in southern climates.", "audio_front": "Is there a solar heat gain coefficient requirement for windows in Michigan?", "audio_back": "No. Solar heat gain is marked not required in climate zones five through eight. Any numeric answer for Michigan is a trap. Those limits apply in southern climates.", "source": "MRC Table N1102.1.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-021", "deck": "rb", "section": "trade", "category": "Ventilation", "front": "What is the minimum net free ventilating area for a vented attic?", "back": "1/150 of the vented attic floor area (R806.2). It may be reduced to 1/300 under either qualifying condition.", "audio_front": "What is the minimum net free ventilating area for a vented attic?", "audio_back": "One one hundred fiftieth of the vented attic floor area. It may be reduced to one three hundredth under either qualifying condition.", "source": "MRC R806.2", "domain": "09_envelope-interior"}, {"id": "envelope-interior-022", "deck": "rb", "section": "trade", "category": "Ventilation", "front": "What conditions allow the attic vent ratio to drop from 1:150 to 1:300?", "back": "EITHER a Class I or II vapor retarder on the warm side of the ceiling (zones 6-8), OR 40-50% of vent area located in the upper portion (not more than 3 ft below the ridge, measured vertically) with the balance at the eaves. Either alone qualifies (R806.2).", "audio_front": "What conditions allow the attic vent ratio to drop from one to one fifty, down to one to three hundred?", "audio_back": "Either a class one or class two vapor retarder on the warm side of the ceiling, or forty to fifty percent of the vent area located in the upper portion of the attic, within three feet of the ridge measured vertically, with the balance at the eaves. Either condition alone qualifies.", "source": "MRC R806.2", "domain": "09_envelope-interior"}, {"id": "envelope-interior-023", "deck": "rb", "section": "trade", "category": "Ventilation", "front": "A 1,500 sq ft attic uses a Class II ceiling vapor retarder. How much net free vent area is required?", "back": "1,500 / 300 = 5 sq ft. Without a qualifying condition it would be 1,500 / 150 = 10 sq ft.", "audio_front": "A fifteen hundred square foot attic uses a class two ceiling vapor retarder. How much net free vent area is required?", "audio_back": "Fifteen hundred divided by three hundred equals five square feet. Without a qualifying condition it would be fifteen hundred divided by one fifty, which is ten square feet.", "source": "MRC R806.2", "domain": "09_envelope-interior"}, {"id": "envelope-interior-024", "deck": "rb", "section": "trade", "category": "Ventilation", "front": "Required bathroom exhaust capacity?", "back": "50 cfm intermittent or 20 cfm continuous, ducted to the exterior (Table M1507.4).", "audio_front": "What is the required bathroom exhaust capacity?", "audio_back": "Fifty C F M intermittent, or twenty C F M continuous, ducted to the exterior.", "source": "MRC Table M1507.4", "domain": "09_envelope-interior"}, {"id": "envelope-interior-025", "deck": "rb", "section": "trade", "category": "Ventilation", "front": "Required kitchen exhaust capacity?", "back": "100 cfm intermittent or 25 cfm continuous (Table M1507.4). Don't swap with the bathroom's 50/20.", "audio_front": "What is the required kitchen exhaust capacity?", "audio_back": "One hundred C F M intermittent, or twenty five C F M continuous. Do not swap this with the bathroom numbers of fifty and twenty.", "source": "MRC Table M1507.4", "domain": "09_envelope-interior"}, {"id": "envelope-interior-026", "deck": "rb", "section": "trade", "category": "Ventilation", "front": "Where must bath and kitchen exhaust fans discharge?", "back": "Directly to the outdoors — never into an attic, soffit, ridge vent, or crawl space (M1501.1). Attic discharge causes condensation, mold, and ice dams.", "audio_front": "Where must bath and kitchen exhaust fans discharge?", "audio_back": "Directly to the outdoors. Never into an attic, soffit, ridge vent, or crawl space. Attic discharge causes condensation, mold, and ice dams.", "source": "MRC M1501.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-027", "deck": "rb", "section": "trade", "category": "Ventilation", "front": "When is whole-house mechanical ventilation required, and why does that cover every new Michigan home?", "back": "When the tested infiltration rate is less than 5 ACH50 (R303.4). Michigan caps leakage at 4 ACH50, so every new Michigan dwelling requires whole-house mechanical ventilation.", "audio_front": "When is whole house mechanical ventilation required, and why does that cover every new Michigan home?", "audio_back": "When the tested infiltration rate is less than five air changes per hour at fifty pascals. Michigan caps leakage at four, so every new Michigan dwelling requires whole house mechanical ventilation.", "source": "MRC R303.4 / N1102.4.1.2", "domain": "09_envelope-interior"}, {"id": "envelope-interior-028", "deck": "rb", "section": "trade", "category": "Ventilation", "front": "Whole-house ventilation rate for a 2,400 sq ft, 3-bedroom home?", "back": "60 cfm continuous per Table M1507.3.3(1) (1,501-3,000 sq ft, 2-3 bedrooms row).", "audio_front": "What is the whole house ventilation rate for a twenty four hundred square foot, three bedroom home?", "audio_back": "Sixty C F M continuous, from the table row for fifteen hundred one to three thousand square feet with two to three bedrooms.", "source": "MRC Table M1507.3.3(1)", "domain": "09_envelope-interior"}, {"id": "envelope-interior-029", "deck": "rb", "section": "trade", "category": "Ventilation", "front": "What is an unvented (conditioned) attic and when is it allowed?", "back": "An attic with insulation at the roof deck instead of the ceiling and no vents — permitted under R806.5 with air-impermeable insulation (e.g., spray foam) directly under the sheathing meeting the condensation-control R-values.", "audio_front": "What is an unvented, conditioned attic, and when is it allowed?", "audio_back": "An attic insulated at the roof deck instead of the ceiling, with no vents. It is permitted with air impermeable insulation, such as spray foam, applied directly under the sheathing, meeting the condensation control requirements.", "source": "MRC R806.5", "domain": "09_envelope-interior"}, {"id": "envelope-interior-030", "deck": "rb", "section": "trade", "category": "Ventilation", "front": "What is the EPA radon action level, and what is the standard new-construction control system?", "back": "4.0 picocuries per liter (EPA guidance). Standard control: passive sub-slab depressurization — 4-inch gas-permeable gravel layer, poly soil-gas retarder, and a 3-to-4-inch vent pipe from below the slab through the roof (MRC Appendix F pattern, adopted locally).", "audio_front": "What is the E P A radon action level, and what is the standard new construction control system?", "audio_back": "Four point zero picocuries per liter, which is E P A guidance. The standard control is passive sub slab depressurization. A four inch gravel layer, a poly soil gas retarder, and a three to four inch vent pipe running from below the slab up through the roof.", "source": "EPA / MRC Appendix F", "domain": "09_envelope-interior"}, {"id": "envelope-interior-031", "deck": "rb", "section": "trade", "category": "Ventilation", "front": "Habitable rooms natural ventilation: what fraction of floor area must be openable, and what replaces it?", "back": "Openable area of at least 4% of the room's floor area (R303.1); whole-house mechanical ventilation may substitute where provided.", "audio_front": "For natural ventilation of habitable rooms, what fraction of floor area must be openable, and what can replace it?", "audio_back": "Openable area of at least four percent of the room's floor area. Whole house mechanical ventilation may substitute where provided.", "source": "MRC R303.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-032", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Minimum net clear opening AREA for an emergency escape and rescue opening?", "back": "5.7 sq ft; reduced to 5.0 sq ft for grade-floor openings (R310.1).", "audio_front": "What is the minimum net clear opening area for an emergency escape and rescue opening?", "audio_back": "Five point seven square feet. Reduced to five point zero square feet for grade floor openings.", "source": "MRC R310.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-033", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Egress window minimum net clear HEIGHT and WIDTH?", "back": "24 inches minimum height, 20 inches minimum width (R310.1). Height is the bigger number — think '24 high, 20 wide.'", "audio_front": "What are the egress window minimum net clear height and width?", "audio_back": "Twenty four inches minimum height, and twenty inches minimum width. Height is the bigger number. Think twenty four high, twenty wide.", "source": "MRC R310.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-034", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Maximum sill height for an egress window?", "back": "44 inches above the floor, measured to the bottom of the clear opening (R310.1).", "audio_front": "What is the maximum sill height for an egress window?", "audio_back": "Forty four inches above the floor, measured to the bottom of the clear opening.", "source": "MRC R310.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-035", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "TRAP: Does a window measuring exactly 20 inches wide by 24 inches high satisfy egress?", "back": "No. 20 x 24 = 480 sq in = 3.33 sq ft, well under 5.7 sq ft. Meeting both minimum dimensions does not meet the area — at least one dimension must be larger.", "audio_front": "Trap question. Does a window measuring exactly twenty inches wide by twenty four inches high satisfy egress?", "audio_back": "No. Twenty by twenty four is only three point three three square feet, well under the required five point seven. Meeting both minimum dimensions does not meet the area. At least one dimension must be larger.", "source": "MRC R310.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-036", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Where are emergency escape and rescue openings required?", "back": "In every sleeping room, in basements with habitable space, and in habitable attics (R310.1). Operable from inside without keys, tools, or special knowledge.", "audio_front": "Where are emergency escape and rescue openings required?", "audio_back": "In every sleeping room, in basements with habitable space, and in habitable attics. They must be operable from inside without keys, tools, or special knowledge.", "source": "MRC R310.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-037", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Window well requirements for an egress window below grade?", "back": "Minimum 9 sq ft horizontal area with minimum 36-inch horizontal projection and width; a permanently affixed ladder or steps is required when the well is deeper than 44 inches (R310.2).", "audio_front": "What are the window well requirements for an egress window below grade?", "audio_back": "Minimum nine square feet of horizontal area, with a minimum thirty six inch projection and width. A permanently affixed ladder or steps is required when the well is deeper than forty four inches.", "source": "MRC R310.2", "domain": "09_envelope-interior"}, {"id": "envelope-interior-038", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Are bars or grilles allowed over an egress window?", "back": "Only if releasable or removable from the inside without keys, tools, force, or special knowledge (R310.4).", "audio_front": "Are bars or grilles allowed over an egress window?", "audio_back": "Only if they can be released or removed from the inside without keys, tools, force, or special knowledge.", "source": "MRC R310.4", "domain": "09_envelope-interior"}, {"id": "envelope-interior-039", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Is safety glazing required in door glass?", "back": "Yes — glazing in all swinging, sliding, and bifold doors is a hazardous location (R308.4.1). Exception: openings a 3-inch sphere cannot pass through and small decorative lites.", "audio_front": "Is safety glazing required in door glass?", "audio_back": "Yes. Glazing in all swinging, sliding, and bifold doors is a hazardous location. The exception is openings that a three inch sphere cannot pass through, and small decorative lites.", "source": "MRC R308.4.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-040", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "When does glazing NEXT TO a door require tempering?", "back": "When within a 24-inch arc of either side of the door in its closed position AND its bottom edge is less than 60 inches above the floor (R308.4.2).", "audio_front": "When does glazing next to a door require tempering?", "audio_back": "When it is within a twenty four inch arc of either side of the closed door, and its bottom edge is less than sixty inches above the floor.", "source": "MRC R308.4.2", "domain": "09_envelope-interior"}, {"id": "envelope-interior-041", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "The four conditions that ALL must be met for a large window pane to require safety glazing?", "back": "(1) Exceeds 9 sq ft; (2) bottom edge less than 18 inches above the floor; (3) top edge more than 36 inches above the floor; (4) a walking surface within 36 inches horizontally (R308.4.3). All four together.", "audio_front": "What are the four conditions that all must be met for a large window pane to require safety glazing?", "audio_back": "One, it exceeds nine square feet. Two, the bottom edge is less than eighteen inches above the floor. Three, the top edge is more than thirty six inches above the floor. Four, there is a walking surface within thirty six inches horizontally. All four together.", "source": "MRC R308.4.3", "domain": "09_envelope-interior"}, {"id": "envelope-interior-042", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "When does glazing near a tub or shower require safety glazing?", "back": "When the bottom edge is less than 60 inches above the drain or standing surface and the glazing is within 60 inches horizontally of the water's edge (R308.4.5). 60 — not 72 — inches.", "audio_front": "When does glazing near a tub or shower require safety glazing?", "audio_back": "When the bottom edge is less than sixty inches above the drain or standing surface, and the glazing is within sixty inches horizontally of the water's edge. Sixty inches, not seventy two.", "source": "MRC R308.4.5", "domain": "09_envelope-interior"}, {"id": "envelope-interior-043", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Safety glazing rules adjacent to stairways?", "back": "Tempered where glazing is within 36 inches horizontally of a walking surface and less than 60 inches above it (R308.4.6), and within 60 inches horizontally of the bottom tread of a stairway when less than 60 inches above the nose of the tread (R308.4.7).", "audio_front": "What are the safety glazing rules adjacent to stairways?", "audio_back": "Tempered glass is required where glazing is within thirty six inches horizontally of a walking surface and less than sixty inches above it, and within sixty inches horizontally of the bottom tread of a stairway when less than sixty inches above the nose of the tread.", "source": "MRC R308.4.6-.7", "domain": "09_envelope-interior"}, {"id": "envelope-interior-044", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Is glazing in guards and railings ever exempt from safety glazing?", "back": "No — glazing in guards and railings is always a hazardous location regardless of size or height (R308.4.4).", "audio_front": "Is glazing in guards and railings ever exempt from safety glazing?", "audio_back": "No. Glazing in guards and railings is always a hazardous location, regardless of size or height.", "source": "MRC R308.4.4", "domain": "09_envelope-interior"}, {"id": "envelope-interior-045", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "How is safety glazing identified in the field?", "back": "By a permanent manufacturer's label (etched/ceramic-fired bug) on each pane identifying the safety glazing standard (R308.1). Unlabeled glass fails inspection.", "audio_front": "How is safety glazing identified in the field?", "audio_back": "By a permanent manufacturer's label etched or fired onto each pane, identifying the safety glazing standard. Unlabeled glass fails inspection.", "source": "MRC R308.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-046", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Window fall protection: when is an opening limiter required?", "back": "When an operable window's sill is less than 24 inches above the interior floor AND more than 72 inches above exterior grade — the opening must not pass a 4-inch sphere or must have an ASTM F2090 opening-control device (R312.2).", "audio_front": "Window fall protection. When is an opening limiter required?", "audio_back": "When an operable window's sill is less than twenty four inches above the interior floor, and more than seventy two inches above the exterior grade. The opening must not pass a four inch sphere, or must have an approved opening control device.", "source": "MRC R312.2", "domain": "09_envelope-interior"}, {"id": "envelope-interior-047", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Required exterior egress DOOR dimensions?", "back": "At least one side-hinged exterior door with 32 inches minimum clear width and 78 inches minimum clear height (R311.2).", "audio_front": "What are the required exterior egress door dimensions?", "audio_back": "At least one side hinged exterior door, with thirty two inches minimum clear width and seventy eight inches minimum clear height.", "source": "MRC R311.2", "domain": "09_envelope-interior"}, {"id": "envelope-interior-048", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Requirements for the door between an attached garage and the dwelling?", "back": "1-3/8 inch solid wood, 1-3/8 inch solid or honeycomb-core steel, or a 20-minute fire-rated door; self-closing; and it may NEVER open into a sleeping room (R302.5.1).", "audio_front": "What are the requirements for the door between an attached garage and the dwelling?", "audio_back": "One and three eighths inch solid wood, one and three eighths inch solid or honeycomb core steel, or a twenty minute fire rated door. It must be self closing, and it may never open into a sleeping room.", "source": "MRC R302.5.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-049", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Maximum skylight U-factor under the Michigan energy code?", "back": "0.55 in all Michigan zones (Table N1102.1.1) — versus 0.32 for vertical fenestration.", "audio_front": "What is the maximum skylight U factor under the Michigan energy code?", "audio_back": "Zero point five five in all Michigan zones, versus zero point three two for vertical windows.", "source": "MRC Table N1102.1.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-050", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "How are windows integrated with the water-resistive barrier?", "back": "Flashed per the fenestration manufacturer's instructions (pan flashing at sills where specified), with flashing lapped shingle-style into the WRB so water drains out, not in (R703.4).", "audio_front": "How are windows integrated with the water resistive barrier?", "audio_back": "Flashed per the window manufacturer's instructions, with pan flashing at sills where specified, and flashing lapped shingle style into the barrier so water drains out, not in.", "source": "MRC R703.4", "domain": "09_envelope-interior"}, {"id": "envelope-interior-051", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "What glazing is required in skylights and sloped glazing?", "back": "Laminated or fully tempered glass (with screening requirements below tempered units in some conditions) per R308.6. Ordinary annealed glass is prohibited overhead.", "audio_front": "What glazing is required in skylights and sloped glazing?", "audio_back": "Laminated or fully tempered glass, with screening required below tempered units in some conditions. Ordinary annealed glass is prohibited overhead.", "source": "MRC R308.6", "domain": "09_envelope-interior"}, {"id": "envelope-interior-052", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "Drywall fastener spacing WITHOUT adhesive: ceilings vs walls?", "back": "Ceilings: nails 7 inches, screws 12 inches. Walls: nails 8 inches, screws 16 inches (Table R702.3.5). Ceilings are always tighter.", "audio_front": "What is the drywall fastener spacing without adhesive, for ceilings versus walls?", "audio_back": "Ceilings, nails every seven inches, screws every twelve inches. Walls, nails every eight inches, screws every sixteen inches. Ceilings are always tighter.", "source": "MRC Table R702.3.5", "domain": "09_envelope-interior"}, {"id": "envelope-interior-053", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "How far must drywall screws penetrate wood framing?", "back": "Minimum 5/8 inch into the framing member (R702.3.5).", "audio_front": "How far must drywall screws penetrate wood framing?", "audio_back": "A minimum of five eighths of an inch into the framing member.", "source": "MRC R702.3.5", "domain": "09_envelope-interior"}, {"id": "envelope-interior-054", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "When does a ceiling require 5/8-inch drywall instead of 1/2-inch?", "back": "With framing at 24 inches on center (perpendicular application) — use 5/8-inch or 1/2-inch sag-resistant board, especially under water-based texture. 1/2-inch standard is fine at 16 inches o.c.", "audio_front": "When does a ceiling require five eighths inch drywall instead of half inch?", "audio_back": "With framing at twenty four inches on center, use five eighths inch, or half inch sag resistant board, especially under water based texture. Standard half inch is fine at sixteen inches on center.", "source": "MRC Table R702.3.5", "domain": "09_envelope-interior"}, {"id": "envelope-interior-055", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "Difference between Type X and Type C gypsum board?", "back": "Type X is the standard fire-rated core (5/8-inch used in rated assemblies). Type C is an enhanced fire-rated board with more glass fiber and a shrinkage-compensating (vermiculite) core — it exceeds Type X and is used where listed designs specify it.", "audio_front": "What is the difference between type X and type C gypsum board?", "audio_back": "Type X is the standard fire rated core, with five eighths inch used in rated assemblies. Type C is an enhanced fire rated board with more glass fiber and a shrinkage compensating core. It exceeds type X and is used where listed designs specify it.", "source": "industry standard (GA)", "domain": "09_envelope-interior"}, {"id": "envelope-interior-056", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "Garage separation: what gypsum goes on garage WALLS vs the CEILING under habitable space?", "back": "Walls to the dwelling: 1/2-inch gypsum on the garage side — always. Ceiling with habitable space above: 5/8-inch Type X. Structure supporting that floor also gets 1/2-inch (Table R302.6). Type X on walls is the trap.", "audio_front": "Garage separation. What gypsum goes on garage walls versus the ceiling under habitable space?", "audio_back": "Walls to the dwelling get half inch gypsum on the garage side, always. A ceiling with habitable space above gets five eighths inch type X. The structure supporting that floor also gets half inch. Type X on the walls is the trap answer.", "source": "MRC Table R302.6", "domain": "09_envelope-interior"}, {"id": "envelope-interior-057", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "Is the garage-dwelling separation a fire-resistance-RATED assembly?", "back": "No — R302.6 requires a SEPARATION with prescribed gypsum thicknesses, not an hourly-rated wall. 'One-hour fire wall' is a trap answer.", "audio_front": "Is the garage to dwelling separation a fire resistance rated assembly?", "audio_back": "No. The code requires a separation with prescribed gypsum thicknesses, not an hourly rated wall. One hour fire wall is a trap answer.", "source": "MRC R302.6", "domain": "09_envelope-interior"}, {"id": "envelope-interior-058", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "What are the requirements for ducts passing through the garage separation?", "back": "Minimum 26-gauge sheet steel with NO openings into the garage (R302.5.2).", "audio_front": "What are the requirements for ducts passing through the garage separation?", "audio_back": "Minimum twenty six gauge sheet steel, with no openings into the garage.", "source": "MRC R302.5.2", "domain": "09_envelope-interior"}, {"id": "envelope-interior-059", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "Which drywall finish level is required for gloss/semi-gloss paint or critical lighting?", "back": "Level 5 — tape plus three coats of compound plus a skim coat over the entire surface. Level 4 (tape + three coats) is the standard for flat paint.", "audio_front": "Which drywall finish level is required for gloss or semi gloss paint, or critical lighting?", "audio_back": "Level five. Tape plus three coats of compound, plus a skim coat over the entire surface. Level four, which is tape plus three coats, is the standard for flat paint.", "source": "GA-214 industry standard", "domain": "09_envelope-interior"}, {"id": "envelope-interior-060", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "What wall finish is required around tubs and showers, and to what height?", "back": "A nonabsorbent surface to at least 6 feet above the floor (R307.2).", "audio_front": "What wall finish is required around tubs and showers, and to what height?", "audio_back": "A nonabsorbent surface to at least six feet above the floor.", "source": "MRC R307.2", "domain": "09_envelope-interior"}, {"id": "envelope-interior-061", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "What backer materials are approved behind tile in tub and shower areas?", "back": "Cement board, fiber-cement board, glass-mat gypsum, or fiber-reinforced gypsum panels per Table R702.4.2 — never paper-faced green board in wet areas.", "audio_front": "What backer materials are approved behind tile in tub and shower areas?", "audio_back": "Cement board, fiber cement board, glass mat gypsum, or fiber reinforced gypsum panels. Never paper faced green board in wet areas.", "source": "MRC Table R702.4.2", "domain": "09_envelope-interior"}, {"id": "envelope-interior-062", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "Thinset vs mastic: which is acceptable in a shower?", "back": "Only thinset (cement-based mortar). Mastic is an organic adhesive for dry-area walls only — it re-emulsifies in sustained moisture and fails.", "audio_front": "Thinset versus mastic. Which is acceptable in a shower?", "audio_back": "Only thinset, the cement based mortar. Mastic is an organic adhesive for dry area walls only. It softens in sustained moisture and fails.", "source": "ANSI A108/A118 industry standard", "domain": "09_envelope-interior"}, {"id": "envelope-interior-063", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "A builder hangs ceiling drywall first, then walls. Why?", "back": "Ceiling boards go first so wall boards support the ceiling edges; hang perpendicular to framing to increase sag resistance and bridge more framing members.", "audio_front": "A builder hangs ceiling drywall first, then the walls. Why?", "audio_back": "Ceiling boards go first so the wall boards support the ceiling edges. Boards are hung perpendicular to framing to resist sag and bridge more framing members.", "source": "industry standard", "domain": "09_envelope-interior"}, {"id": "envelope-interior-064", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "With adhesive plus fasteners, what drywall fastener spacing is allowed?", "back": "Ceilings: 16 inches (nails or screws). Walls: nails 16 inches, screws 24 inches (Table R702.3.5).", "audio_front": "With adhesive plus fasteners, what drywall fastener spacing is allowed?", "audio_back": "Ceilings, sixteen inches for nails or screws. Walls, nails at sixteen inches and screws at twenty four inches.", "source": "MRC Table R702.3.5", "domain": "09_envelope-interior"}, {"id": "envelope-interior-065", "deck": "rb", "section": "trade", "category": "Specialties", "front": "When is an attic access opening required, and what size?", "back": "Where the attic exceeds 30 sq ft AND has 30 inches or more vertical height — rough opening minimum 22 x 30 inches in a readily accessible location with 30 inches minimum headroom above a ceiling opening (R807.1).", "audio_front": "When is an attic access opening required, and what size must it be?", "audio_back": "Where the attic exceeds thirty square feet and has thirty inches or more of vertical height. The rough opening must be at least twenty two by thirty inches, in a readily accessible location, with thirty inches minimum headroom above a ceiling opening.", "source": "MRC R807.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-066", "deck": "rb", "section": "trade", "category": "Specialties", "front": "Memory hook for attic access numbers?", "back": "'Thirty, thirty, thirty — through 22 by 30': 30 sq ft area trigger, 30-inch height trigger, 30-inch headroom above the hatch, through a 22 x 30 rough opening.", "audio_front": "What is the memory hook for the attic access numbers?", "audio_back": "Thirty, thirty, thirty, through twenty two by thirty. Thirty square feet area trigger, thirty inch height trigger, thirty inches of headroom above the hatch, through a twenty two by thirty rough opening.", "source": "MRC R807.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-067", "deck": "rb", "section": "trade", "category": "Specialties", "front": "Where are smoke alarms required, and how must they operate?", "back": "In each sleeping room, outside each sleeping area, and on every story including basements — all interconnected and hardwired with battery backup in new construction (R314).", "audio_front": "Where are smoke alarms required, and how must they operate?", "audio_back": "In each sleeping room, outside each sleeping area, and on every story including basements. All interconnected, and hardwired with battery backup in new construction.", "source": "MRC R314", "domain": "09_envelope-interior"}, {"id": "envelope-interior-068", "deck": "rb", "section": "trade", "category": "Specialties", "front": "CO alarms: what triggers the requirement, where do they go, and must they interconnect?", "back": "Trigger: a fuel-burning appliance OR an attached garage. Location: outside each sleeping area. The 2015 MRC does NOT require CO alarm interconnection — that's a smoke-alarm rule (R315).", "audio_front": "Carbon monoxide alarms. What triggers the requirement, where do they go, and must they interconnect?", "audio_back": "The trigger is a fuel burning appliance or an attached garage. The location is outside each sleeping area. The twenty fifteen code does not require carbon monoxide alarms to interconnect. Interconnection is a smoke alarm rule.", "source": "MRC R315", "domain": "09_envelope-interior"}, {"id": "envelope-interior-069", "deck": "rb", "section": "trade", "category": "Specialties", "front": "Key pool barrier numbers?", "back": "48-inch minimum barrier height; openings must reject a 4-inch sphere; gates self-closing and self-latching with the latch 54 inches above grade or on the pool side (MRC Appendix G).", "audio_front": "What are the key pool barrier numbers?", "audio_back": "Forty eight inch minimum barrier height. Openings must reject a four inch sphere. Gates must be self closing and self latching, with the latch fifty four inches above grade or on the pool side.", "source": "MRC Appendix G", "domain": "09_envelope-interior"}, {"id": "envelope-interior-070", "deck": "rb", "section": "trade", "category": "Specialties", "front": "Scenario: a builder finishes a basement into a bedroom. What three envelope/life-safety items are triggered?", "back": "(1) An egress window (5.7 sq ft, 44-inch max sill) with compliant window well; (2) a smoke alarm in the room, interconnected; (3) basement wall insulation per the energy code (R-10/13 zone 5A) if newly conditioned.", "audio_front": "Scenario. A builder finishes a basement into a bedroom. What three envelope and life safety items are triggered?", "audio_back": "One, an egress window of five point seven square feet with a maximum forty four inch sill, and a compliant window well. Two, an interconnected smoke alarm in the room. Three, basement wall insulation per the energy code, R ten continuous or R thirteen cavity in zone five A.", "source": "MRC R310 / R314 / N1102", "domain": "09_envelope-interior"}, {"id": "envelope-interior-071", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "Scenario: a fixed picture window is 10 sq ft, bottom edge 12 inches above the floor, top edge 80 inches up, next to a hallway. Tempered?", "back": "Yes — all four R308.4.3 conditions are met: over 9 sq ft, bottom under 18 inches, top over 36 inches, walking surface within 36 inches.", "audio_front": "Scenario. A fixed picture window is ten square feet, with its bottom edge twelve inches above the floor and top edge eighty inches up, next to a hallway. Does it need tempered glass?", "audio_back": "Yes. All four conditions are met. It is over nine square feet, the bottom is under eighteen inches, the top is over thirty six inches, and a walking surface is within thirty six inches.", "source": "MRC R308.4.3", "domain": "09_envelope-interior"}, {"id": "envelope-interior-072", "deck": "rb", "section": "trade", "category": "Insulation", "front": "Scenario: builder in Traverse City (zone 6A) submits plans with R-38 ceiling insulation. Compliant?", "back": "No — zone 6A requires R-49 ceiling. R-38 applies only in zone 5A (southern Lower Peninsula) under Michigan's amendment.", "audio_front": "Scenario. A builder in Traverse City, climate zone six A, submits plans with R thirty eight ceiling insulation. Is that compliant?", "audio_back": "No. Zone six A requires R forty nine in the ceiling. R thirty eight applies only in zone five A, the southern Lower Peninsula, under Michigan's amendment.", "source": "MRC Table N1102.1.1", "domain": "09_envelope-interior"}, {"id": "envelope-interior-073", "deck": "rb", "section": "trade", "category": "Ventilation", "front": "TRAP: which exhaust rate belongs to the bathroom — 50/20 or 100/25?", "back": "Bathroom = 50 cfm intermittent / 20 cfm continuous. Kitchen = 100 / 25. Bigger room-load, bigger number: kitchen gets 100.", "audio_front": "Trap. Which exhaust rate belongs to the bathroom, fifty and twenty, or one hundred and twenty five?", "audio_back": "The bathroom gets fifty C F M intermittent or twenty continuous. The kitchen gets one hundred intermittent or twenty five continuous. Bigger load, bigger number. The kitchen gets one hundred.", "source": "MRC Table M1507.4", "domain": "09_envelope-interior"}, {"id": "envelope-interior-074", "deck": "rb", "section": "trade", "category": "Interior & Exterior Finishes", "front": "Match the drywall finish level: behind tile / plenum above insulation / heavy texture / standard flat paint.", "back": "Behind tile: Level 2. Plenum/concealed: Level 1 (Level 0 = none). Heavy texture: Level 3. Standard flat paint: Level 4.", "audio_front": "Match the drywall finish level. Behind tile. Plenum above insulation. Heavy texture. Standard flat paint.", "audio_back": "Behind tile is level two. A plenum or concealed area is level one, and level zero is no finishing. Heavy texture is level three. Standard flat paint is level four.", "source": "GA-214 industry standard", "domain": "09_envelope-interior"}, {"id": "envelope-interior-075", "deck": "rb", "section": "trade", "category": "Windows/Doors/Skylights", "front": "TRAP: egress area at a grade-floor opening vs an upper-floor window?", "back": "Grade-floor opening: 5.0 sq ft. All others: 5.7 sq ft. The height (24 in), width (20 in), and sill (44 in) rules stay the same.", "audio_front": "Trap. What is the egress area at a grade floor opening versus an upper floor window?", "audio_back": "A grade floor opening needs five point zero square feet. All others need five point seven. The height, width, and sill rules stay the same. Twenty four inches high, twenty inches wide, forty four inch maximum sill.", "source": "MRC R310.1", "domain": "09_envelope-interior"}, {"id": "plans-math-trades-001", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "What is the standard scale for residential floor plans and elevations?", "back": "1/4\" = 1'-0\" (one quarter inch equals one foot). Site plans use an engineer's scale, typically 1\" = 20' or 30'.", "audio_front": "What is the standard scale for residential floor plans and elevations?", "audio_back": "One quarter inch equals one foot zero inches. Site plans use an engineer's scale, typically one inch equals twenty or thirty feet.", "source": "Standard drafting convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-002", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "At 1/4\" = 1'-0\" scale, a wall measures 6 inches on the plan. How long is the actual wall?", "back": "24 feet. Each 1/4\" equals 1 foot, so plan inches x 4 = actual feet: 6 x 4 = 24.", "audio_front": "At quarter-inch scale, a wall measures six inches on the plan. How long is the actual wall?", "audio_back": "Twenty-four feet. Each quarter inch equals one foot, so plan inches times four equals actual feet. Six times four is twenty-four.", "source": "Scale math", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-003", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "What is the difference between a section and an elevation drawing?", "back": "A section is a vertical CUT through the building showing what is inside the assembly (framing, insulation, floor-to-floor heights). An elevation is a flat view of an exterior face showing finishes, openings, grade line, and roof slope.", "audio_front": "What is the difference between a section drawing and an elevation drawing?", "audio_back": "A section is a vertical cut through the building showing what is inside the assembly, like framing, insulation, and floor to floor heights. An elevation is a flat view of an exterior face showing finishes, openings, grade line, and roof slope.", "source": "Plan reading convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-004", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "On a plan, a circle split with '3' over 'A5' next to a detail bubble means what?", "back": "Detail number 3 found on sheet A5. The top number is the detail, the bottom is the sheet where it is drawn.", "audio_front": "On a plan, a circle split with the number three over A five next to a detail bubble means what?", "audio_back": "Detail number three, found on sheet A five. The top number is the detail number and the bottom is the sheet where it is drawn.", "source": "Plan reading convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-005", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "A window schedule callout reads '3050'. What size is the window?", "back": "3'-0\" wide by 5'-0\" high. First pair of digits = width in feet and inches, second pair = height.", "audio_front": "A window schedule callout reads three zero five zero. What size is the window?", "audio_back": "Three feet zero inches wide by five feet zero inches high. The first pair of digits is the width in feet and inches, the second pair is the height.", "source": "Schedule convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-006", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Dashed (hidden) lines on a floor plan typically represent what?", "back": "Objects above or below the cut plane — upper cabinets, roof overhangs, or footings beneath a wall.", "audio_front": "Dashed or hidden lines on a floor plan typically represent what?", "audio_back": "Objects above or below the cutting plane, such as upper cabinets, roof overhangs, or footings beneath a wall.", "source": "Plan reading convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-007", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Plans show a dimension of 12'-6\" but scaling the drawing gives 12'-2\". Which governs?", "back": "The written dimension always governs. Never scale a drawing when a figure is given — drawings shrink and stretch in reproduction.", "audio_front": "Plans show a written dimension of twelve feet six inches, but scaling the drawing gives twelve feet two inches. Which governs?", "audio_back": "The written dimension always governs. Never scale a drawing when a figure is given, because drawings distort in reproduction.", "source": "Plan reading convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-008", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Drawings call for one material but the written specifications call for another. What should the builder do?", "back": "Specifications generally govern over drawings, but the correct action is to notify the architect/designer and get written clarification before proceeding.", "audio_front": "The drawings call for one material but the written specifications call for another. What should the builder do?", "audio_back": "Specifications generally govern over drawings, but the correct action is to notify the architect or designer and get written clarification before proceeding.", "source": "Contract documents convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-009", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "In the classic 16-division CSI MasterFormat, what are Divisions 3, 4, and 6?", "back": "Division 3 = Concrete, Division 4 = Masonry, Division 6 = Wood & Plastics (rough and finish carpentry).", "audio_front": "In the classic sixteen division C S I MasterFormat, what are divisions three, four, and six?", "audio_back": "Division three is concrete. Division four is masonry. Division six is wood and plastics, which covers rough and finish carpentry.", "source": "CSI MasterFormat (16-division)", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-010", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "In the 16-division CSI format, which divisions are Mechanical and Electrical?", "back": "Division 15 = Mechanical (plumbing and HVAC), Division 16 = Electrical. Division 9 = Finishes, Division 7 = Thermal & Moisture Protection.", "audio_front": "In the sixteen division C S I format, which divisions are mechanical and electrical?", "audio_back": "Division fifteen is mechanical, covering plumbing and H V A C. Division sixteen is electrical. Also, division nine is finishes and division seven is thermal and moisture protection.", "source": "CSI MasterFormat (16-division)", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-011", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "What do specifications control versus what the drawings control?", "back": "Specs control QUALITY — materials, workmanship, standards. Drawings control QUANTITY and LOCATION — dimensions, layout, extent.", "audio_front": "What do specifications control versus what the drawings control?", "audio_back": "Specifications control quality, meaning materials, workmanship, and standards. Drawings control quantity and location, meaning dimensions, layout, and extent.", "source": "Contract documents convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-012", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "State the board-foot formula.", "back": "Board feet = (nominal thickness in inches x width in inches x length in FEET) / 12.", "audio_front": "State the board foot formula.", "audio_back": "Board feet equals nominal thickness in inches, times width in inches, times length in feet, divided by twelve.", "source": "Estimating formula", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-013", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "How many board feet in one 2x6 that is 10 feet long?", "back": "(2 x 6 x 10) / 12 = 10 board feet.", "audio_front": "How many board feet in one two by six that is ten feet long?", "audio_back": "Two times six times ten is one hundred twenty, divided by twelve equals ten board feet.", "source": "Estimating formula", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-014", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "How many board feet in 40 pieces of 2x10 x 12'? What do they cost at $600 per MBF?", "back": "(2x10x12)/12 = 20 BF each; 40 x 20 = 800 BF. At $600 per thousand board feet: 0.8 x 600 = $480.", "audio_front": "How many board feet in forty pieces of two by ten, twelve feet long? And what do they cost at six hundred dollars per thousand board feet?", "audio_back": "Each piece is twenty board feet, so forty pieces is eight hundred board feet. At six hundred dollars per thousand, that is four hundred eighty dollars.", "source": "Estimating formula", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-015", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "How many cubic feet are in one cubic yard?", "back": "27 cubic feet. Concrete volume in cubic feet divided by 27 gives cubic yards.", "audio_front": "How many cubic feet are in one cubic yard?", "audio_back": "Twenty-seven cubic feet. Concrete volume in cubic feet divided by twenty-seven gives cubic yards.", "source": "Estimating formula", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-016", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "How many cubic yards of concrete for a 20' x 30' slab, 4 inches thick?", "back": "20 x 30 x 0.333 = 200 cu ft; 200/27 = 7.4 CY. With 5-10% waste, order about 8 yards.", "audio_front": "How many cubic yards of concrete for a slab twenty feet by thirty feet, four inches thick?", "audio_back": "Twenty times thirty times one third of a foot is two hundred cubic feet. Divided by twenty-seven, that is seven point four cubic yards. With five to ten percent waste, order about eight yards.", "source": "Estimating formula", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-017", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "How much concrete for a footing 100 LF long, 16\" wide, 8\" thick?", "back": "100 x 1.333 x 0.667 = 88.9 cu ft; / 27 = 3.3 cubic yards.", "audio_front": "How much concrete for a footing one hundred lineal feet long, sixteen inches wide, and eight inches thick?", "audio_back": "One hundred times one point three three three times zero point six six seven is about eighty-nine cubic feet. Divided by twenty-seven, that is three point three cubic yards.", "source": "Estimating formula", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-018", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "What waste factor is standard when ordering ready-mix concrete?", "back": "5 to 10 percent, and always round UP to the ordering increment.", "audio_front": "What waste factor is standard when ordering ready mix concrete?", "audio_back": "Five to ten percent, and always round up to the ordering increment.", "source": "Estimating convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-019", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "How many standard modular bricks per square foot of wall?", "back": "6.75 bricks per square foot (running bond, 3/8\" joints). Add about 5% waste.", "audio_front": "How many standard modular bricks per square foot of wall?", "audio_back": "Six point seven five bricks per square foot, using running bond with three eighths inch joints. Add about five percent waste.", "source": "Estimating constant", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-020", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "A brick veneer wall is 1,000 sf with 100 sf of openings. How many bricks?", "back": "Net 900 sf x 6.75 = 6,075 bricks, before ~5% waste.", "audio_front": "A brick veneer wall is one thousand square feet with one hundred square feet of openings. How many bricks?", "audio_back": "Nine hundred net square feet times six point seven five equals six thousand seventy-five bricks, before about five percent waste.", "source": "Estimating constant", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-021", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "How many 8x8x16 concrete blocks per square foot of wall?", "back": "1.125 blocks per square foot — each block face covers 0.889 sf (128 sq in).", "audio_front": "How many eight by eight by sixteen concrete blocks per square foot of wall?", "audio_back": "One point one two five blocks per square foot. Each block face covers about eight ninths of a square foot.", "source": "Estimating constant", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-022", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "How many blocks for a foundation wall 40' long and 8' high?", "back": "320 sf x 1.125 = 360 blocks.", "audio_front": "How many blocks for a foundation wall forty feet long and eight feet high?", "audio_back": "Three hundred twenty square feet times one point one two five equals three hundred sixty blocks.", "source": "Estimating constant", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-023", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "What is a roofing 'square' and how many shingle bundles make one?", "back": "One square = 100 sq ft of roof area. Standard 3-tab shingles = 3 bundles per square. Add ~10% waste (more for hips/valleys).", "audio_front": "What is a roofing square, and how many shingle bundles make one?", "audio_back": "One square is one hundred square feet of roof area. Standard three tab shingles take three bundles per square. Add about ten percent waste, more for hips and valleys.", "source": "Estimating constant", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-024", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "A roof measures 2,400 sf. How many squares and how many 3-tab bundles?", "back": "24 squares; 24 x 3 = 72 bundles (before waste).", "audio_front": "A roof measures two thousand four hundred square feet. How many squares, and how many three tab bundles?", "audio_back": "Twenty-four squares, and twenty-four times three is seventy-two bundles before waste.", "source": "Estimating constant", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-025", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "How many square feet in a 4x8 sheet of drywall or sheathing?", "back": "32 square feet. Sheets needed = total area / 32, rounded up, plus 5-10% waste. A 4x12 sheet = 48 sf.", "audio_front": "How many square feet in a four by eight sheet of drywall or sheathing?", "audio_back": "Thirty-two square feet. Sheets needed equals total area divided by thirty-two, rounded up, plus five to ten percent waste. A four by twelve sheet is forty-eight square feet.", "source": "Estimating constant", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-026", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "A 12' x 16' room with 8' ceilings: how many 4x8 sheets to cover walls and ceiling (no deductions)?", "back": "Walls: 56' perimeter x 8' = 448 sf. Ceiling: 192 sf. Total 640 / 32 = 20 sheets.", "audio_front": "A twelve by sixteen foot room with eight foot ceilings. How many four by eight sheets to cover walls and ceiling with no deductions?", "audio_back": "The perimeter is fifty-six feet times eight feet high, which is four hundred forty-eight square feet of wall. The ceiling is one hundred ninety-two. The total of six hundred forty divided by thirty-two is twenty sheets.", "source": "Estimating math", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-027", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Formula for stud count at 16 inches on center?", "back": "Studs = (wall length in feet x 0.75) + 1, then add for corners, intersections, and openings. Fast rule: one stud per lineal foot of wall covers the extras.", "audio_front": "What is the formula for stud count at sixteen inches on center?", "audio_back": "Studs equal wall length in feet times zero point seven five, plus one, then add extras for corners, intersections, and openings. The fast rule is one stud per lineal foot of wall.", "source": "Estimating formula", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-028", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "How many floor joists at 16\" o.c. across a 24-foot-long floor?", "back": "(24 x 0.75) + 1 = 19 joists.", "audio_front": "How many floor joists at sixteen inches on center across a twenty-four foot long floor?", "audio_back": "Twenty-four times zero point seven five is eighteen, plus one equals nineteen joists.", "source": "Estimating formula", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-029", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "How many wall plates does a standard framed wall need for takeoff?", "back": "Three runs of plate: one bottom plate plus a double top plate — 3 x wall length in lineal feet.", "audio_front": "How many wall plates does a standard framed wall need for takeoff?", "audio_back": "Three runs of plate. One bottom plate plus a double top plate, so three times the wall length in lineal feet.", "source": "Estimating convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-030", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Excavated bank soil swells or shrinks when hauled loose?", "back": "SWELLS — loose volume exceeds bank volume. Compacted fill shrinks below original bank volume. Common earth swell ~25%.", "audio_front": "Does excavated bank soil swell or shrink when hauled loose?", "audio_back": "It swells. Loose volume exceeds bank volume. Compacted fill shrinks below the original bank volume. Common earth swells about twenty-five percent.", "source": "Estimating convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-031", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "You excavate 100 bank CY of common earth with 25% swell. How many loose CY must be hauled?", "back": "100 x 1.25 = 125 loose cubic yards.", "audio_front": "You excavate one hundred bank cubic yards of common earth with twenty-five percent swell. How many loose cubic yards must be hauled?", "audio_back": "One hundred times one point two five equals one hundred twenty-five loose cubic yards.", "source": "Estimating math", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-032", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "You need 100 CY of compacted fill; shrinkage is 10%. How much bank material must be excavated?", "back": "100 / 0.90 = about 111 bank cubic yards. Divide by (1 minus shrinkage), don't just add 10%.", "audio_front": "You need one hundred cubic yards of compacted fill, and shrinkage is ten percent. How much bank material must be excavated?", "audio_back": "One hundred divided by zero point nine zero, which is about one hundred eleven bank cubic yards. Divide by one minus the shrinkage. Do not just add ten percent.", "source": "Estimating math", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-033", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Basement dig 40' x 30' x 6' deep: bank CY and loose CY at 25% swell?", "back": "7,200 cu ft / 27 = 267 bank CY; x 1.25 = about 333 loose CY.", "audio_front": "A basement dig is forty by thirty feet and six feet deep. How many bank cubic yards, and loose cubic yards at twenty-five percent swell?", "audio_back": "Seven thousand two hundred cubic feet divided by twenty-seven is two hundred sixty-seven bank yards. Times one point two five is about three hundred thirty-three loose yards.", "source": "Estimating math", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-034", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "State the percent-grade formula. What is the grade of a 2-foot fall over 100 feet?", "back": "% grade = (rise / run) x 100. 2/100 = 2% grade.", "audio_front": "State the percent grade formula. What is the grade of a two foot fall over one hundred feet?", "audio_back": "Percent grade equals rise divided by run, times one hundred. Two divided by one hundred is a two percent grade.", "source": "Estimating formula", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-035", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "A slope of 1/4 inch per foot is what percent grade?", "back": "About 2% (0.25/12 = 2.08%). And 1/8\" per foot is about 1% — the standard garage-floor slope.", "audio_front": "A slope of one quarter inch per foot is what percent grade?", "audio_back": "About two percent. And one eighth inch per foot is about one percent, the standard garage floor slope.", "source": "Estimating formula", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-036", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "What ground slope does the 2015 MRC require away from a foundation?", "back": "6 inches of fall within the first 10 feet (5% grade); minimum 2% where impervious surfaces prevent it (MRC R401.3).", "audio_front": "What ground slope does the twenty fifteen Michigan Residential Code require away from a foundation?", "audio_back": "Six inches of fall within the first ten feet, which is a five percent grade. Where impervious surfaces prevent that, a minimum of two percent. That is section R four zero one point three.", "source": "MRC R401.3", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-037", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Area of a gable end 24 feet wide with a 6-foot rise?", "back": "Triangle: (base x height) / 2 = (24 x 6)/2 = 72 sf.", "audio_front": "What is the area of a gable end twenty-four feet wide with a six foot rise?", "audio_back": "A triangle is base times height divided by two. Twenty-four times six divided by two is seventy-two square feet.", "source": "Geometry", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-038", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Concrete for ten 12-inch-diameter piers, each 4 feet deep?", "back": "Each: 3.14 x 0.5^2 x 4 = 3.14 cu ft. Ten piers = 31.4 cu ft / 27 = about 1.2 CY.", "audio_front": "How much concrete for ten twelve-inch diameter piers, each four feet deep?", "audio_back": "Each pier is pi times the radius squared times depth. That is three point one four times a quarter times four, about three point one four cubic feet. Ten piers is thirty-one cubic feet, divided by twenty-seven is about one point two cubic yards.", "source": "Geometry", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-039", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Michigan maximum stair riser and minimum tread depth?", "back": "Max riser 8-1/4\", min tread 9\" — Michigan amendments to the 2015 MRC. The IRC values (7-3/4\" and 10\") are trap answers.", "audio_front": "What are the Michigan maximum stair riser and minimum tread depth?", "audio_back": "Maximum riser eight and one quarter inches, minimum tread nine inches. Those are Michigan amendments. The I R C values of seven and three quarters and ten inches are trap answers.", "source": "2015 MRC R311.7 (MI amended)", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-040", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Total rise is 108 inches. Using Michigan's 8-1/4\" max riser, how many risers and treads?", "back": "108 / 8.25 = 13.09, round UP = 14 risers; actual riser 108/14 = 7.71\". Treads = risers - 1 = 13.", "audio_front": "Total stair rise is one hundred eight inches. Using Michigan's eight and one quarter inch maximum riser, how many risers and treads?", "audio_back": "One hundred eight divided by eight point two five is thirteen point zero nine. Round up to fourteen risers. The actual riser is seven point seven one inches, and treads equal risers minus one, so thirteen treads.", "source": "2015 MRC R311.7 (MI amended)", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-041", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Why must you round UP, never down, when computing riser count?", "back": "Rounding down makes each riser TALLER than the max. 108/13 = 8.31\", over Michigan's 8.25\" limit — a code violation.", "audio_front": "Why must you round up, never down, when computing the number of risers?", "audio_back": "Rounding down makes each riser taller than the maximum. One hundred eight divided by thirteen is eight point three one inches, which exceeds Michigan's eight point two five inch limit and violates code.", "source": "2015 MRC R311.7 (MI amended)", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-042", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "With 13 treads at Michigan's 9\" minimum, what is the minimum total run?", "back": "13 x 9\" = 117 inches (9'-9\").", "audio_front": "With thirteen treads at Michigan's nine inch minimum, what is the minimum total run of the stair?", "audio_back": "Thirteen times nine is one hundred seventeen inches, or nine feet nine inches.", "source": "Stair math", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-043", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Maximum variation allowed between the largest and smallest riser (or tread) in a stair flight?", "back": "3/8 inch.", "audio_front": "What is the maximum variation allowed between the largest and smallest riser or tread in a flight of stairs?", "audio_back": "Three eighths of an inch.", "source": "2015 MRC R311.7", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-044", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "On sheet numbering, what do the prefixes A, S, M, E, P stand for?", "back": "A = Architectural, S = Structural, M = Mechanical, E = Electrical, P = Plumbing (C = Civil/site).", "audio_front": "On sheet numbering, what do the prefixes A, S, M, E, and P stand for?", "audio_back": "A is architectural, S is structural, M is mechanical, E is electrical, and P is plumbing. C is civil or site.", "source": "Drafting convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-045", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "What information is on the site (plot) plan?", "back": "Property lines, setbacks, north arrow, existing/proposed structures, utilities, driveway, contours/grades — drawn at engineer's scale (1\"=20' or 30').", "audio_front": "What information is on the site plan, also called the plot plan?", "audio_back": "Property lines, setbacks, the north arrow, existing and proposed structures, utilities, the driveway, and contour grades. It is drawn at engineer's scale, one inch equals twenty or thirty feet.", "source": "Drafting convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-046", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "What scale range is typical for detail drawings?", "back": "3/4\" to 3\" = 1'-0\" — much larger than plan scale so connections can be shown clearly.", "audio_front": "What scale range is typical for detail drawings?", "audio_back": "Three quarters of an inch up to three inches equals one foot. Much larger than plan scale, so connections can be shown clearly.", "source": "Drafting convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-047", "deck": "rb", "section": "trade", "category": "Trade Boundaries", "front": "Which trades can a Michigan Residential Builder NOT perform with only the RB license?", "back": "Plumbing, electrical, and mechanical/HVAC. Each requires its own LARA license, permit, and inspections. The RB hires and coordinates licensed subs.", "audio_front": "Which trades can a Michigan residential builder not perform with only the R B license?", "audio_back": "Plumbing, electrical, and mechanical H V A C work. Each requires its own license from LARA, its own permit, and its own inspections. The builder hires and coordinates licensed subcontractors.", "source": "Skilled Trades Regulation Act (PA 407 of 2016); LARA BCC", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-048", "deck": "rb", "section": "trade", "category": "Trade Boundaries", "front": "Michigan plumber license tiers and hour requirements?", "back": "Apprentice (registered) -> Journeyman (6,000 hours over 3+ years) -> Master (additional 4,000 hours over 2+ years as journeyman). Contractor entity must employ a master plumber. Skilled Trades Regulation Act, PA 407 of 2016.", "audio_front": "What are the Michigan plumber license tiers and hour requirements?", "audio_back": "Apprentice, which is registered. Journeyman, which requires six thousand hours over at least three years. Master, which requires four thousand additional hours over at least two years as a journeyman. A plumbing contractor entity must employ a master plumber. That is the Skilled Trades Regulation Act, Act four zero seven of twenty sixteen.", "source": "Skilled Trades Regulation Act (PA 407 of 2016), MCL 339.6101 et seq.", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-049", "deck": "rb", "section": "trade", "category": "Trade Boundaries", "front": "Michigan electrician license tiers and hour requirements?", "back": "Journeyman: 8,000 hours over 4+ years. Master: 12,000 hours over 6+ years plus 2 years as journeyman. Electrical contractor is a separate business entity license requiring a master on staff. Skilled Trades Regulation Act, PA 407 of 2016 (replaced the old Electrical Administrative Act, PA 217 of 1956).", "audio_front": "What are the Michigan electrician license tiers and hour requirements?", "audio_back": "Journeyman requires eight thousand hours over at least four years. Master requires twelve thousand hours over at least six years, including two years as a journeyman. The electrical contractor license is a separate business entity license requiring a master electrician on staff. That is the Skilled Trades Regulation Act, Act four zero seven of twenty sixteen, which replaced the old electrical act of nineteen fifty-six.", "source": "Skilled Trades Regulation Act (PA 407 of 2016), MCL 339.5701 et seq.", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-050", "deck": "rb", "section": "trade", "category": "Trade Boundaries", "front": "How is mechanical/HVAC contracting licensed in Michigan?", "back": "The Skilled Trades Regulation Act (PA 407 of 2016) licenses the CONTRACTOR ENTITY only — there is NO individual journeyman or master mechanical license in Michigan. The entity designates a Qualifying Officer and holds classification endorsements for its work types. (Old law: Forbes Mechanical Contractors Act, PA 192 of 1984 — repealed.)", "audio_front": "How is mechanical and H V A C contracting licensed in Michigan?", "audio_back": "The Skilled Trades Regulation Act, Act four zero seven of twenty sixteen, licenses the mechanical contractor as a business entity only. There is no individual journeyman or master mechanical license in Michigan. The entity designates a qualifying officer and holds classification endorsements for its work types.", "source": "Skilled Trades Regulation Act (PA 407 of 2016)", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-051", "deck": "rb", "section": "trade", "category": "Trade Boundaries", "front": "Does a master plumber or master electrician license by itself authorize contracting?", "back": "No. Contracting requires a separate contractor (business entity) license that employs the master. The master credential alone does not authorize running jobs for the public.", "audio_front": "Does a master plumber or master electrician license by itself authorize contracting?", "audio_back": "No. Contracting requires a separate contractor business entity license that employs the master. The master credential alone does not authorize contracting with the public.", "source": "Skilled Trades Regulation Act (PA 407 of 2016)", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-052", "deck": "rb", "section": "trade", "category": "Trade Boundaries", "front": "A homeowner wants to wire their own rental duplex. Allowed under the homeowner exemption?", "back": "No. The homeowner exemption covers only the owner's PRIMARY RESIDENCE with the owner personally doing the work. Rentals are excluded — licensed contractors required.", "audio_front": "A homeowner wants to wire their own rental duplex. Is that allowed under the homeowner exemption?", "audio_back": "No. The homeowner exemption covers only the owner's primary residence, with the owner personally doing the work. Rental properties are excluded, so licensed contractors are required.", "source": "MI trade licensing acts", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-053", "deck": "rb", "section": "trade", "category": "Trade Boundaries", "front": "May a contractor perform trade work under a permit the homeowner pulled?", "back": "No — that is illegal. Trade permits are pulled either by the licensed trade contractor doing the work or by a qualifying homeowner doing their own work.", "audio_front": "May a contractor perform trade work under a permit the homeowner pulled?", "audio_back": "No. That is illegal. Trade permits are pulled either by the licensed trade contractor doing the work, or by a qualifying homeowner doing their own work on their own primary residence.", "source": "MI trade licensing acts", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-054", "deck": "rb", "section": "trade", "category": "Trade Boundaries", "front": "Before letting an electrical sub start, what should the RB verify and where?", "back": "That the sub holds a current electrical contractor license — verified through LARA's online license lookup at michigan.gov/lara — and that the sub pulls its own electrical permit.", "audio_front": "Before letting an electrical subcontractor start, what should the residential builder verify, and where?", "audio_back": "That the subcontractor holds a current electrical contractor license, verified through LARA's online license lookup, and that the subcontractor pulls its own electrical permit.", "source": "LARA BCC guidance", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-055", "deck": "rb", "section": "trade", "category": "Trade Boundaries", "front": "What federal certification is required for anyone handling refrigerants?", "back": "EPA Section 608 certification — a federal requirement, separate from any Michigan state license.", "audio_front": "What federal certification is required for anyone handling refrigerants?", "audio_back": "E P A section six zero eight certification. It is a federal requirement, separate from any Michigan state license.", "source": "EPA Section 608 (federal)", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-056", "deck": "rb", "section": "trade", "category": "Trade Boundaries", "front": "Scenario: an RB's own crew installs the furnace and gas line to save money. Legal?", "back": "No. Mechanical work requires a licensed mechanical contractor with the proper classification endorsements, under a mechanical permit. The RB license never covers it.", "audio_front": "Scenario. A residential builder's own crew installs the furnace and gas line to save money. Is that legal?", "audio_back": "No. Mechanical work requires a licensed mechanical contractor with the proper classification endorsements, working under a mechanical permit. The residential builder license never covers it.", "source": "Skilled Trades Regulation Act (PA 407 of 2016)", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-057", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "What Michigan law governs construction permits and code enforcement?", "back": "The Stille-DeRossett-Hale Single State Construction Code Act — Act 230 of 1972, MCL 125.1501 to 125.1531. No regulated work may begin before the permit is issued.", "audio_front": "What Michigan law governs construction permits and code enforcement?", "audio_back": "The Stille DeRossett Hale Single State Construction Code Act. Act two thirty of nineteen seventy-two, M C L one twenty-five point fifteen zero one through fifteen thirty-one. No regulated work may begin before the permit is issued.", "source": "MCL 125.1501-1531", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-058", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "Under the 2015 MRC R105.2, how tall can a fence be without a building permit?", "back": "Up to 7 feet. Taller requires a permit.", "audio_front": "Under the twenty fifteen code, how tall can a fence be without a building permit?", "audio_back": "Up to seven feet. Anything taller requires a permit. That is section R one zero five point two.", "source": "2015 MRC R105.2", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-059", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "When is a retaining wall exempt from a building permit?", "back": "When it is 4 feet or less measured from the BOTTOM OF THE FOOTING to the top, and does not support a surcharge (MRC R105.2).", "audio_front": "When is a retaining wall exempt from a building permit?", "audio_back": "When it is four feet or less, measured from the bottom of the footing to the top, and it does not support a surcharge. Section R one zero five point two.", "source": "2015 MRC R105.2", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-060", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "What size detached accessory structure (shed) is permit-exempt under the 2015 MRC?", "back": "One-story detached accessory structures up to 200 square feet. (120 sf is the old-code trap answer.)", "audio_front": "What size detached accessory structure, like a shed, is permit exempt under the twenty fifteen code?", "audio_back": "One story detached accessory structures up to two hundred square feet. One hundred twenty square feet is the old code trap answer.", "source": "2015 MRC R105.2", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-061", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "When is a deck permit-exempt under the 2015 MRC?", "back": "200 sq ft or less AND not more than 30 inches above grade (and not attached to the dwelling or serving the required exit door).", "audio_front": "When is a deck permit exempt under the twenty fifteen code?", "audio_back": "When it is two hundred square feet or less, and not more than thirty inches above grade, and not attached to the dwelling or serving the required exit door.", "source": "2015 MRC R105.2", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-062", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "Name four finish-work activities that never need a building permit.", "back": "Painting, papering/wallpaper, tiling, carpeting — also cabinets and countertops (MRC R105.2 'similar finish work').", "audio_front": "Name four finish work activities that never need a building permit.", "audio_back": "Painting, wallpapering, tiling, and carpeting. Cabinets and countertops are also exempt as similar finish work.", "source": "2015 MRC R105.2", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-063", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "Are sidewalks and driveways permit-exempt?", "back": "Yes, when not more than 30 inches above adjacent grade and not over a basement or story below (MRC R105.2).", "audio_front": "Are sidewalks and driveways permit exempt?", "audio_back": "Yes, when they are not more than thirty inches above adjacent grade and not over a basement or story below.", "source": "2015 MRC R105.2", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-064", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "What prefab swimming pools and window awnings are permit-exempt?", "back": "Above-ground prefab pools less than 24\" deep and 5,000 gallons or less; window awnings projecting 54 inches or less.", "audio_front": "Which prefabricated swimming pools and window awnings are permit exempt?", "audio_back": "Above ground prefabricated pools less than twenty-four inches deep and five thousand gallons or less, and window awnings projecting fifty-four inches or less.", "source": "2015 MRC R105.2", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-065", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "How long does the AHJ have to issue or deny a permit after a complete application?", "back": "10 business days; 15 business days for an unusually complicated building or structure (MCL 125.1511).", "audio_front": "How long does the enforcing agency have to issue or deny a permit after receiving a complete application?", "audio_back": "Ten business days, or fifteen business days for an unusually complicated building or structure. That is M C L one twenty-five point fifteen eleven.", "source": "MCL 125.1511", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-066", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "When does an issued permit expire?", "back": "If work has not commenced within 180 days of issuance, or work is suspended or abandoned for 180 days (MRC R105.5).", "audio_front": "When does an issued permit expire?", "audio_back": "If work has not commenced within one hundred eighty days of issuance, or if work is suspended or abandoned for one hundred eighty days. Section R one zero five point five.", "source": "2015 MRC R105.5", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-067", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "How fast must the AHJ issue a Certificate of Occupancy once applied for?", "back": "Within 5 business days after written application and payment of fees (MCL 125.1513). All permits must be finaled, inspections passed, fees paid first.", "audio_front": "How fast must the enforcing agency issue a certificate of occupancy once applied for?", "audio_back": "Within five business days after written application and payment of fees. That is M C L one twenty-five point fifteen thirteen. All permits must be finaled, all inspections passed, and all fees paid first.", "source": "MCL 125.1513", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-068", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "Give the residential inspection sequence from ground to C of O.", "back": "Footing/foundation (before pour) -> waterproofing/drain tile (before backfill) -> rough framing -> rough electrical, plumbing, mechanical (before covering) -> insulation -> drywall -> four finals (building, electrical, plumbing, mechanical) -> Certificate of Occupancy.", "audio_front": "Give the residential inspection sequence from the ground up to the certificate of occupancy.", "audio_back": "Footing and foundation before the pour. Waterproofing and drain tile before backfill. Rough framing. Rough electrical, plumbing, and mechanical before covering. Insulation. Drywall. Then the four finals, building, electrical, plumbing, and mechanical, and finally the certificate of occupancy.", "source": "AHJ practice under Act 230", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-069", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "A drywall crew covered the rough electrical before inspection. What can the inspector do?", "back": "Issue a stop-work order and require the work be uncovered (even demolished) for inspection. Never cover uninspected work.", "audio_front": "A drywall crew covered the rough electrical before inspection. What can the inspector do?", "audio_back": "Issue a stop work order and require the work be uncovered, even demolished, for inspection. Never cover uninspected work.", "source": "MCL 125.1512", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-070", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "After a stop-work order, what work may continue?", "back": "Only work necessary to make the site safe, such as shoring or temporary weatherproofing. Everything else must stop (MCL 125.1512).", "audio_front": "After a stop work order is issued, what work may continue?", "audio_back": "Only work necessary to make the site safe, such as shoring or temporary weatherproofing. Everything else must stop. That is M C L one twenty-five point fifteen twelve.", "source": "MCL 125.1512", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-071", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "Penalty for a knowing violation of the construction code act vs. the unlicensed-work fine?", "back": "Knowing violation: misdemeanor, fine up to $500 and/or up to 90 days (MCL 125.1523(1)). Each knowing violation is a separate offense; each DAY is a separate offense specifically for ignoring a stop-construction order (MCL 125.1523(2)). Unlicensed residential work: separate $100-$500 civil fine under MCL 125.1523a.", "audio_front": "What is the penalty for a knowing violation of the construction code act, versus the unlicensed work fine?", "audio_back": "A knowing violation is a misdemeanor with a fine up to five hundred dollars and or up to ninety days, under M C L one twenty-five point fifteen twenty-three. Each knowing violation is a separate offense, and each day is a separate offense specifically when you ignore a stop construction order. Unlicensed residential work carries a separate one hundred to five hundred dollar civil fine under fifteen twenty-three A.", "source": "MCL 125.1523 / 125.1523a", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-072", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "When are architect/engineer-sealed plans NOT required for a permit?", "back": "For one- and two-family dwellings under 3,500 square feet of calculated floor area.", "audio_front": "When are architect or engineer sealed plans not required for a permit?", "audio_back": "For one and two family dwellings under three thousand five hundred square feet of calculated floor area.", "source": "Act 230 / MCL 125.1510", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-073", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "Who enforces the code where a local unit has no building department?", "back": "LARA's Bureau of Construction Codes (BCC). Michigan has roughly 1,600 local enforcing jurisdictions (AHJs).", "audio_front": "Who enforces the construction code where a local unit has no building department?", "audio_back": "LARA's Bureau of Construction Codes. Michigan has roughly one thousand six hundred local enforcing jurisdictions.", "source": "Act 230 / LARA BCC", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-074", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "Who should pull the building permit, per LARA guidance?", "back": "The licensed contractor performing the work. A contractor asking the homeowner to pull it is a red flag for licensing problems.", "audio_front": "Who should pull the building permit, according to LARA guidance?", "audio_back": "The licensed contractor performing the work. A contractor asking the homeowner to pull the permit is a red flag for licensing problems.", "source": "LARA guidance", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-075", "deck": "rb", "section": "bl", "category": "Permits & Inspections", "front": "Which needs a permit: replacing a faucet cartridge, or replacing a water heater?", "back": "The water heater — it needs a plumbing/mechanical permit. Repairing working parts of a faucet with no piping alteration is an exempt minor repair.", "audio_front": "Which needs a permit. Replacing a faucet cartridge, or replacing a water heater?", "audio_back": "The water heater. It needs a permit. Repairing the working parts of a faucet with no piping alteration is an exempt minor repair.", "source": "2015 MRC R105.2 / AHJ practice", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-076", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Trap check: which stair numbers are Michigan's and which are the IRC traps?", "back": "Michigan: 8-1/4\" max riser, 9\" min tread. IRC traps: 7-3/4\" riser, 10\" tread. On this exam, the Michigan-amended value is the right answer.", "audio_front": "Trap check. Which stair numbers are Michigan's, and which are the I R C traps?", "audio_back": "Michigan allows a maximum riser of eight and one quarter inches and a minimum tread of nine inches. The I R C traps are seven and three quarter inches and ten inches. On this exam, the Michigan amended value is the right answer.", "source": "2015 MRC R311.7 (MI amended)", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-077", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "What code edition does the Michigan RB exam reference for dwelling construction?", "back": "The 2015 Michigan Residential Code. The 2021 update was stayed by court order in July 2025 and never took effect.", "audio_front": "What code edition does the Michigan residential builder exam reference for dwelling construction?", "audio_back": "The twenty fifteen Michigan Residential Code. The twenty twenty-one update was stayed by court order in July twenty twenty-five and never took effect.", "source": "LARA BCC / stay order 7/2025", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-078", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "An estimating question says a wall needs 1,000 board feet at $750/MBF. Cost?", "back": "$750 per 1,000 BF x 1 = $750.", "audio_front": "An estimating question says a wall needs one thousand board feet at seven hundred fifty dollars per thousand board feet. What is the cost?", "audio_back": "Seven hundred fifty dollars. One thousand board feet is exactly one thousand, so one times seven fifty.", "source": "Estimating math", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-079", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Which drawing tells you the wall assembly layers (siding, sheathing, stud, insulation, drywall)?", "back": "The wall section (or a section detail). Sections cut vertically through the assembly and label every layer.", "audio_front": "Which drawing tells you the wall assembly layers, like siding, sheathing, studs, insulation, and drywall?", "audio_back": "The wall section, or a section detail. Sections cut vertically through the assembly and label every layer.", "source": "Plan reading convention", "domain": "10_plans-math-trades"}, {"id": "plans-math-trades-080", "deck": "rb", "section": "trade", "category": "Plans/Specs & Estimating", "front": "Concrete order for a 24' x 24' garage slab, 4\" thick, with 10% waste?", "back": "24 x 24 x 0.333 = 192 cu ft / 27 = 7.1 CY; x 1.10 = 7.8 -> order 8 yards.", "audio_front": "What is the concrete order for a twenty-four by twenty-four foot garage slab, four inches thick, with ten percent waste?", "audio_back": "Twenty-four times twenty-four times a third of a foot is one hundred ninety-two cubic feet. Divided by twenty-seven is seven point one yards. With ten percent waste that is seven point eight, so order eight yards.", "source": "Estimating math", "domain": "10_plans-math-trades"}], "lectures": [{"id": "01_licensing-law_lecture", "title": "Michigan Licensing Law and Exam Logistics — Audio Lecture", "paras": ["Welcome to the licensing law chapter. This is the single biggest business and law category on your exam. Out of fifty business and law questions, thirteen come from regulatory and statutory requirements — more than one in four. And unlike code questions, there is nothing to interpret here. It is pure memorization of Michigan law. Every question you lock down in this chapter is a nearly free point on exam day. Let's earn all thirteen.", "First, the big picture. Michigan licenses residential builders under Article twenty four of the Occupational Code. That's Public Act two ninety nine of nineteen eighty, sections M C L three thirty nine point two four zero one through two four one two. The program is run by LARA — the Department of Licensing and Regulatory Affairs — through its Bureau of Construction Codes. There is also a board: the Residential Builders and Maintenance and Alteration Contractors Board, with nine members. Four licensed residential builders, two licensed M and A contractors, and three members of the public.", "Now the definitions, because the exam loves them. A residential structure, under the current statute, is one of two things. A detached one or two family dwelling, or a townhouse of not more than three stories above grade plane with a separate means of egress. Say that again to yourself. Detached one or two family, or a townhouse, three stories or less, separate egress. This definition was rewritten in twenty twenty, so older study materials that talk about combination residential and commercial structures are out of date. If an answer choice says any building of three units or less, that is a trap. Unit count alone is not the test.", "A residential builder is anyone who, for compensation other than wages for personal labor only, undertakes or even offers to undertake construction, repair, alteration, improvement, wrecking, or demolition of a residential structure. Notice — offering counts. You can violate the licensing law without ever driving a nail. The definition also sweeps in people who deal in prefabricated, precut, packaged, or shell housing, and anyone who erects a residential structure except on their own property for their own use and occupancy.", "The maintenance and alteration contractor — the M and A license — covers repair, alteration, additions, improvement, wrecking, building a garage, and laying concrete on residential property. It also catches house flippers. If you buy, substantially rehab, and resell the same residential structure more than twice in one calendar year, you need a license — unless it's for your own use and occupancy, or you hire all the work out to licensed contractors. Remember the relationship: a residential builder license covers everything the M and A license covers, but an M and A contractor cannot do new construction.", "A salesperson is an employee or agent, other than a qualifying officer, of a licensed builder or contractor, who sells or solicits contracts for the licensee's services. Occasional and incidental sales don't count.", "Now, when do you not need a license at all? The exemptions in section two four zero three. Government representatives. An owner building on their own property for their own use and occupancy. An owner of rental property doing maintenance and alteration of that rental property. Officers of a court. Subcontractors working solely under contract with a licensed builder. Licensed electrical, plumbing, and mechanical contractors — but only for their own trade work. And the famous six hundred dollar exemption: if the aggregate price for labor, materials, and everything else on one undertaking is less than six hundred dollars, no license is required. But watch the anti-evasion clause — you cannot split a big job into little contracts under six hundred dollars to dodge the act. If the work is part of a larger operation, the exemption is gone. And remember what six hundred dollars is not: it is not a written contract trigger. It is purely a licensure exemption threshold.", "Two more framework facts. Michigan does not license commercial builders at the state level — Article twenty four is residential only. And Michigan has no reciprocity with any other state. An out of state builder starts from scratch here.", "How do you get the license? Four things. Good moral character — and for a company, that reaches every partner, officer, director, member, and shareholder. Proof of identity — a copy of your driver's license or state I D, which the department may use only to prove identity. The sixty hour prelicensure education. And the exam. Notice what is not on the list: experience. The statute has no experience requirement.", "The sixty hour course has been required since June first, two thousand eight, and it must include at least six hours in each of seven competency areas. Here they are. Business management, estimating, and job costing. Design and building science. Contracts, liability, and risk management. Marketing and sales. Project management and scheduling. The current Michigan residential code. And MIOSHA construction safety standards. Seven areas, six hours minimum each, sixty hours total. And a nice detail: the certificate never expires, as long as the course was taken after June first, two thousand eight.", "One deadline that trips people up: once LARA receives your application, you have one year to complete everything, including passing the exam. Miss the year and your fees are forfeited and the application is void.", "The license itself runs for three years. You must maintain a place of business in Michigan, and every additional location needs a branch office license. Nonresidents must file a consent to service of process. And your contracts must include your license information — your individual license, and any license you hold as a qualifying officer of a company.", "Renewal. When you renew, you state two things to the department: that you have a current copy of the Michigan Residential Code, and that you meet your continuing competency requirements. Keep your continuing education documentation for at least five years. The hours depend on when you were first licensed. Licensed on or after January first, two thousand nine? Twenty one hours per three year cycle, including at least three hours every calendar year during your first six years, with at least three hours on codes, safety, and changes in the law. Licensed before two thousand nine with a clean record? Just three hours per cycle — one hour of codes, one hour of safety, one hour of legal issues. And if you get disciplined, the department can order anywhere from three to twenty one hours in the next cycle.", "If your license lapses, here's the ladder. Expired less than three years — application and a one hundred eighty five dollar fee, and you're back. Lapsed more than three years — you start over: sixty hours of prelicensure again, application, fees, good moral character, and you retake the exam.", "Companies. A corporation, partnership, or L L C is a new legal person and needs its own license. It designates a qualifying officer from its officers, partners, members, or managing agent. The qualifying officer passes the exam and must also obtain and maintain their own individual license. The qualifying officer is responsible for supervising and controlling the construction operations to secure compliance with the law. Everyone with control in the entity must be at least eighteen. Now the suspension chains — these make great exam questions. If the qualifying officer's license is suspended, revoked, or denied, the company's license is suspended. If the qualifying officer leaves the company, the company license is suspended, though the department can allow a reasonable time to qualify a replacement. And a licensee on inactive status cannot serve as a qualifying officer.", "Discipline. A homeowner has eighteen months to file a complaint. Eighteen months from the latest of completion, occupancy, or purchase for a maintenance and alteration job, or from the certificate of occupancy or closing for a project that needs an occupancy permit. The list of conduct that gets you disciplined is long, but the greatest hits are: abandonment of a project without legal excuse. Diversion of funds — taking money for one project and spending it on another. Failure to account for money belonging to others. Willful departure from the plans and specifications without consent. Willful violation of building laws. Failing to notify the department within ten days of a change in the control of the business. Failing to deliver the entire agreement to the purchaser. Aiding and abetting an unlicensed person, or lending out your license. Becoming insolvent or filing bankruptcy. And here's one people don't expect — workmanship that doesn't meet the Michigan Residential Code is itself a discipline ground, all by itself.", "For workmanship complaints there's a special procedure. The homeowner sends the department a written complaint and a copy to the builder at the same time. You are presumed innocent until the hearing examiner finds otherwise. Once a building inspection report verifies the complaint, the department must mail you the verified complaint by certified mail within thirty days, or it loses the ability to fine you — although it can still pursue restitution or suspension. And builders can put an alternative dispute resolution clause in their contracts. If a complainant skips your contractual A D R procedure and sues, that failure is an affirmative defense.", "Penalties. Learn these in three buckets. Bucket one, administrative — what LARA itself can do: limit, suspend, deny, or revoke your license, censure, probation, restitution, and an administrative fine of up to ten thousand dollars. Bucket two, criminal — for unlicensed residential building, the fines run five thousand to twenty five thousand dollars. First offense, a misdemeanor with up to one year. Second offense, up to two years. And if the unlicensed work causes death or serious injury, it becomes a felony with up to four years. Bucket three, civil — the attorney general or a prosecutor can sue, and the court shall assess a civil fine of five thousand to twenty five thousand dollars on top of any damages.", "And the hammer that matters most in real life: an unlicensed builder cannot sue to collect payment. Section two four one two. You must allege and prove you were licensed during the performance of the work. No license, no lawsuit, and no construction lien either. One trap to bury forever: there is no such statute as M C L three thirty nine point six one one. The penalty sections are six zero one, six zero two, and two four one two.", "Now exam logistics. PSI administers the test. One hundred sixty questions. Fifty business and law, one hundred ten trade. You need one hundred sixteen correct — seventy two and a half percent. You get two hundred forty minutes. Closed book. Since November fourteenth, twenty nineteen, it is one combined exam with one score — no separate section passes, and if you fail, you retake the whole thing. Up to ten unscored experimental questions may be mixed in. The trade questions reference the twenty fifteen Michigan Residential Code — confirmed current in the PSI handbook updated August of twenty twenty six. Fees: one hundred ninety five dollars to apply to LARA, one hundred seventeen dollars for the exam, and the same for a retest. The salesperson exam is forty five questions, thirty two to pass, ninety minutes, eighty five dollars, with no education requirement. Practical rules: no walk-ins. Cancel at least two days ahead or lose your fee. Arrive thirty minutes early — show up after the start time and you forfeit. Bring one valid signature-bearing photo I D matching your registration name. Your calculator must be silent, battery powered, non printing, with no alphabet keys — and the measurement-converting construction calculators are banned. If you pass, you only see the word pass. If you fail, you get section scores. There is no post-exam review.", "Time for the rapid fire recap. Article twenty four, Public Act two ninety nine of nineteen eighty. Nine board members — four builders, two M and A, three public. Residential structure — detached one or two family, or townhouse of three stories or less with separate egress. Six hundred dollars — licensure exemption, aggregate price, anti-splitting rule. Sixty hours prelicensure, seven areas, six hours each, effective June first, two thousand eight, certificate never expires. One year to finish licensure after applying. License term, three years. Continuing competency — twenty one hours per cycle if licensed after two thousand nine, three hours per year in the first six years; three hours per cycle if licensed before. Keep records five years. Twelve M and A crafts. Entity principals at least eighteen. Complaint window, eighteen months. Change of control notice, ten days. Verified complaint certified mail, thirty days. Administrative fine, ten thousand max. Criminal and civil fines, five to twenty five thousand. Jail — one year first offense, two years second, four years felony if death or serious injury. No license means no lawsuit and no lien. Exam — one sixty questions, fifty business and law, one ten trade, one sixteen to pass, two forty minutes, closed book, combined since November twenty nineteen. Regulatory and statutory requirements — thirteen questions. Insurance, bonds and liens — eleven. Fees — one ninety five application, one seventeen exam, one eighty five relicensure, eighty five salesperson. And the code on the exam is the twenty fifteen Michigan Residential Code.", "That's the chapter. Thirteen questions, all sitting right here. Drill the numbers until they're automatic, and go take them."], "words": 2237}, {"id": "02_liens-insurance-bonds_lecture", "title": "Domain 02 Lecture — Construction Liens, Insurance, and Bonds", "paras": ["Welcome back. This chapter covers the heaviest single category in the Business and Law section: insurance, bonds, and liens. Eleven of your fifty Business and Law questions come from this domain, so this is not a chapter to skim. The good news is that it is almost entirely a numbers game. The exam wants to know whether you have five or six deadlines cold, whether you can tell the four lien waivers apart, whether you know which insurance policy answers which loss, and whether you know who a bond actually protects. Let's build it piece by piece.", "Start with the big picture. Michigan's Construction Lien Act is M C L 570 point 1101 and following. It is Act 497 of 1980. It gives contractors, subcontractors, suppliers, and laborers a lien, a legal claim, against the real property they improved when they do not get paid. Two ceilings apply. First, your own lien can never exceed your contract price minus what you have already been paid. Second, the total of everyone's liens against the owner can never exceed what the owner agreed to pay the general contractor, minus payments the owner properly made through sworn statements and lien waivers. That second rule is the no double payment principle. An owner who pays correctly, with the right paperwork, cannot be forced to pay for the same work twice.", "Now walk the paperwork in the order it happens on a real job.", "First, the Notice of Commencement. On a residential project, the owner prepares it, but only when someone asks. A contractor, sub, supplier, or laborer sends a written request by certified mail, and the owner then has ten days from the postmark to complete and return the form. If the owner blows the ten days, the owner can be stuck paying the expenses the requester incurs digging up the information. If the owner does not live at the site, a copy must be posted conspicuously at the site. Here is the trap the exam loves: the residential notice of commencement is not recorded anywhere. On a commercial project, it is the opposite. The commercial owner records the notice of commencement with the register of deeds before physical work begins. Residential, provided on request and posted. Commercial, recorded. Keep those straight. One more detail: the residential form must have a blank notice of furnishing attached to it, easily detachable, so downstream parties can use it.", "Second, the Notice of Furnishing. This is how people the owner has never met, subs and suppliers, announce that they exist and expect to be paid. A subcontractor or supplier must serve it within twenty days after first furnishing labor or material. Twenty days, measured from the first day on the job, not the last. It gets served on the designee named in the notice of commencement and on the general contractor, personally or by certified mail, and certified mail service is complete the moment it is mailed. If no designee is named, you serve the owner. Who does not file one? The general contractor. Anyone in a direct contract with the owner is exempt, because the owner already knows they exist.", "Laborers get their own rules. A laborer's notice for unpaid wages is thirty days, and note the trigger: thirty days after the wages were due but not paid, not thirty days after starting work. For unpaid fringe benefits or withholdings, the deadline is the fifth day of the second month after the month they went unpaid.", "What if a sub serves the notice late? This is a subtle point the exam can test. A late notice does not kill the lien. Everything furnished after the late notice is fully protected. Everything furnished before the notice is also protected, except to the extent the owner already paid the general contractor for that work relying on a sworn statement or a lien waiver. So late notice costs you only the amounts the owner already properly paid out. Laborers are the exception, a laborer who misses the wage notice deadline loses the lien for those wages entirely.", "Third, the sworn statement. This is a notarized list of every sub and supplier you contracted with, plus any unpaid laborers, showing each one's contract price, the amount paid, and the amount still owing. A contractor must give one to the owner whenever payment is due, whenever the contractor asks for payment, or whenever the owner demands it. A subcontractor gives one to the general contractor on the same payment triggers, and to the owner on demand. The sworn statement is the owner's shield. The owner can rely on it, can withhold what is owed to subs, or pay the subs directly. And hear this clearly: giving a false sworn statement with intent to defraud is a crime, on top of civil fraud liability. Also, if you sue to foreclose your lien, your complaint has to show that you provided a sworn statement if one was requested or required.", "Fourth, the claim of lien itself. You must record it within ninety days after your last furnishing of labor or material, with the register of deeds for the county where the property sits. Not with a court, with the register of deeds. Ninety days from your own last day of real contract work. Warranty visits, courtesy callbacks, and punch list touch ups do not restart the clock. The deadline is absolute, no extensions, no good cause exceptions. A sub or supplier must attach proof that the notice of furnishing was served. Then, within fifteen days after recording, you must serve a copy of the recorded claim of lien on the designee, or the owner if there is no designee, personally or by certified mail.", "Fifth, enforcement. A recorded lien is not money, it is leverage. To turn it into money you file a foreclosure action, and you have exactly one year from the date the claim of lien was recorded. Miss the year and the lien simply expires. The suit goes in circuit court for the county where the property is located, it is an equitable action, and when you file it you record a notice of lis pendens with the register of deeds. And there is a sweetener: the court may award reasonable attorney fees to a prevailing lien claimant. It can also award fees against you if your suit was vexatious.", "Now the residential licensing overlay, which Michigan bolted onto this act to protect homeowners. On a residential structure, a contractor has no lien at all unless the work was done under a written contract with the owner, and any amendments or change orders are in writing too. The written contract must contain the statutory statement about licensing, and if a license is required for the work, the contractor's license number. There is no dollar threshold. A handshake deal on a thirty five thousand dollar remodel means no lien, period. And if an unlicensed person records a lien on residential property anyway, the owner can sue to discharge it, and the unlicensed filer is liable for all resulting damages, including actual costs and attorney fees. The case that hammered this home is Stokes versus Millen Roofing: an unlicensed residential contractor cannot enforce the contract, cannot recover the value of the work in quantum meruit, and has no lien. If you sue on work that requires a license, you must plead and prove that you were licensed.", "Next topic, lien waivers. Michigan recognizes exactly four statutory types, and the exam will make you discriminate. Two dimensions: full versus partial, and conditional versus unconditional. A full waiver releases all lien rights, a partial waiver releases only a stated amount. An unconditional waiver is effective the moment it is signed. A conditional waiver is effective only upon actual payment of the amount shown. So the safe practice is simple: sign conditional waivers before the check clears, unconditional only after. Three more waiver rules. One, advance waivers are void. Nobody can require you, as part of the contract, to waive lien rights before the work is performed. That clause is against public policy and invalid. Two, accepting a promissory note does not by itself waive your lien. Three, on residential jobs, if a homeowner receives a waiver from someone other than the claimant who signed it, say the general hands over a stack of sub waivers, the homeowner cannot rely on it without verifying it is authentic with the actual claimant, in writing, by phone, or in person. And the statutory forms themselves shout the practical rule: do not sign blank or incomplete forms, and retain a copy.", "Here comes one of the most reliable trap answers on this exam: the Homeowner Construction Lien Recovery Fund. It is gone. Abolished. Repealed by Public Act 147 of 2010, effective August twenty third, 2010. Builders used to pay into it and homeowners and subs could recover from it. No more. If an answer choice describes the recovery fund as a current remedy or a current license fee, it is wrong. The only correct present tense statement is: abolished in 2010.", "Switch gears to insurance. The exam tests one skill here: given a loss, name the policy. Three policies, three lanes.", "Builders risk is first party property insurance. It covers the structure while it is under construction, plus materials on site, in transit, or in storage, against perils like fire, wind, and theft. Half built house burns down, lumber package stolen off the slab, that is builders risk. Either the owner or the contractor can buy it, the contract should say who, and it ends at completion. It does not cover injuries, it does not cover other people's property, and it does not cover your tools. Tools and equipment ride on an inland marine policy, sometimes called an equipment floater.", "Commercial general liability, C G L, is third party coverage. Bodily injury and property damage to other people, from your operations or your completed operations. A visitor trips over your ladder, your crew cracks the neighbor's windshield, a connection you soldered fails a year later and floods the finished kitchen, that is C G L. What C G L never pays for is redoing your own defective work. The your work exclusion means general liability is not a warranty on your craftsmanship.", "Workers compensation covers your employees, no fault, and it is generally the employee's exclusive remedy against you. Michigan's thresholds are statutory and the exam wants both prongs. Coverage is required if you regularly employ three or more employees at one time, or, and here is the prong people forget, if you employ fewer than three but at least one employee has worked thirty five or more hours per week for thirteen or more weeks during the preceding fifty two weeks. So one steady full time helper triggers mandatory coverage. Public employers are always covered. And remember the statutory principal rule: if a general contractor hires a sub that carries no comp insurance, and that sub's worker gets hurt, the general contractor pays the comp benefits as if it employed that worker directly. That is why you collect certificates of insurance from every sub before they set foot on site, and why you watch the expiration dates. An additional insured endorsement goes one step further, extending the sub's liability policy to protect you.", "Last topic, bonds. A surety bond has three parties. The principal, that is the contractor whose performance is being guaranteed. The obligee, the party the bond protects, an owner or a government unit. And the surety, the company standing behind the promise. A bond is not insurance for the contractor. The surety expects zero losses, and if it pays a claim, the contractor must pay the surety back. The bond protects the obligee, never the principal.", "Know four bond types. A license or permit bond guarantees you will comply with a law or ordinance, think municipal permit bonds for right of way or sidewalk work. The state residential builder license itself does not require a bond. A bid bond guarantees that if you win, you will sign the contract and post the required bonds. A performance bond guarantees the job gets completed per the plans and specs, and it protects the obligee, on public work, solely the governmental unit. A payment bond guarantees that subs, suppliers, and laborers get paid, and it protects only those claimants.", "Michigan public work has hard statutory numbers. On any public contract exceeding fifty thousand dollars, the contractor must furnish both a performance bond and a payment bond before the contract is awarded. Each bond is set by the governmental unit but cannot be less than twenty five percent of the contract amount. Why does the payment bond matter so much? Because you cannot record a construction lien against public property. No lien on the courthouse, no lien on the school. The unpaid sub's remedy on public work is a claim on the payment bond. And that claim has its own clock. A claimant with no direct contract with the principal contractor must serve written notice on the principal contractor within thirty days after first furnishing, and must give written notice of the claim to both the principal contractor and the governmental unit within ninety days after last furnishing, all by certified mail. Suit on the bond is allowed once you have gone unpaid for ninety days after your last furnishing.", "Time for the rapid fire recap. Say these out loud with me.", "Construction Lien Act, M C L 570 point 1101 and following. Residential notice of commencement, returned within ten days of the request, posted if the owner lives elsewhere, never recorded. Commercial notice of commencement, recorded before work begins. Notice of furnishing for subs and suppliers, twenty days from first furnishing, served on the designee and the general contractor. Laborer wage notice, thirty days from wages due but unpaid. Claim of lien, recorded with the register of deeds within ninety days of last furnishing, absolute deadline, warranty work does not count. Serve the recorded lien within fifteen days. Foreclosure, circuit court, within one year of recording, with a lis pendens, attorney fees possible for the prevailing claimant. Residential lien requires a written contract with the license number, any dollar amount. Four waivers, full and partial, conditional and unconditional. Conditional means effective only on actual payment. Advance waivers void. Recovery fund abolished, 2010. Workers comp, three employees at one time, or one employee at thirty five hours for thirteen weeks. Uninsured sub, the general pays under M C L 418 point 171. Builders risk covers the building, C G L covers other people, comp covers your crew, inland marine covers your tools. Public work over fifty thousand dollars, performance bond and payment bond, each at least twenty five percent. Performance protects the government, payment protects the subs. Payment bond notices, thirty days from first furnishing, ninety days from last. No liens on public property, ever.", "That is the whole domain. Eleven questions, and you just heard every number they can ask. Run the deck until the twenty, thirty, ninety, fifteen, and one year roll off your tongue, and this category becomes free points. See you in the next chapter."], "words": 2531}, {"id": "03_contracts-hifa_lecture", "title": "Contracts, HIFA, Risk and Warranty — Michigan Residential Builder Exam Lecture", "paras": ["Welcome back. This chapter covers the Contracts slice of the Business and Law section. On the PSI exam, that's about seven questions out of the fifty Business and Law questions. The territory is contract fundamentals, the Home Improvement Finance Act, the Home Solicitation Sales Act, the written contract rule in the Construction Lien Act, statutes of limitations, and warranties. This is one of the most trap-heavy areas of the whole exam, because Michigan has four different statutes that each do something different, and wrong answers are built by attributing one statute's rule to another. So let's untangle them once and for all.", "Start with the map. Four laws, four different jobs.", "Law number one: M C L five seventy point eleven fourteen, part of the Construction Lien Act. This is the written contract rule that actually matters for builders. It says a contractor has no construction lien on a residential structure unless the work was done under a written contract, and — listen carefully — any amendments or additions to that contract are also in writing. The contract must also contain a statement that residential builders, electricians, plumbers, and mechanical contractors are required to be licensed, and if your work requires a license, the contract must say you are licensed and must include your license number. There is no dollar threshold. Any amount. A five hundred dollar handyman job and a two hundred thousand dollar addition are treated the same. No written contract with the license number, no lien. And a verbal change order means the added scope has no lien protection either.", "Law number two: M C L three thirty nine point twenty four twelve, in the Occupational Code. An unlicensed builder cannot sue to collect compensation for residential work. Period. You can do the work, you just can't use the courts to get paid.", "Law number three: M C L three thirty nine point twenty four oh three. This is where the famous six hundred dollar number lives. Work where labor and materials combined come to under six hundred dollars is exempt from the licensure requirement. Hear me clearly: that is a licensure exemption, and only a licensure exemption. It is not a written contract trigger. If an exam answer says contracts over six hundred dollars must be in writing under HIFA, that answer is wrong twice over.", "Law number four is HIFA itself, the Home Improvement Finance Act, Act three thirty two of nineteen sixty five, M C L four forty five point eleven oh one and following. HIFA is a financing statute. It applies only when the homeowner pays on credit through the contractor — an installment contract or a charge agreement — and only when the cash price is more than three hundred dollars. Exactly three hundred dollars is not covered; it has to exceed three hundred. New home construction is completely excluded. Commercial property is excluded. A loan the homeowner gets directly from their own bank is excluded. Free standing appliances like a stove or refrigerator are excluded. And one more time for the people in the back: there is no section four forty five point eleven oh eight. It does not exist. Never pick an answer built on it.", "Now, when HIFA does apply, it is picky about the paperwork. The contract must be dated and in writing, with the printed portion in at least eight point type. The words home improvement installment contract must appear in at least ten point bold, either at the top or right above the buyer's signature. There's a required notice to the buyer in bold type with four messages: don't sign before you read; you're entitled to a completely filled in copy; you can pay off early and get a partial refund of the finance charge; and you can rescind the contract.", "The contract also has to itemize the money. Cash price. Down payment. Unpaid cash balance. Insurance premiums if any. Official fees. Principal amount financed. The finance charge, in dollars. The time balance, the number and amount of installments, and the time sale price. If one installment is a balloon — substantially bigger than the others — the contract needs a bold legend saying this contract is not payable in installments of equal amounts, with the amount and due date spelled out.", "Here's a favorite exam fact: the contractor must hand the buyer a completed copy of the contract at the time it's signed. Until that completed copy is delivered, the buyer is not obligated to pay. That's section twelve oh four.", "HIFA also has its own rescission right, and this is a huge trap, so slow down with me. Under HIFA, the buyer may rescind the contract until five P M on the business day following the date of the contract. One business day, ending at five in the afternoon. That is not the three day right you've heard about. The three day right comes from a different law — the Home Solicitation Sales Act — and it runs to midnight of the third business day. Two different statutes, two different clocks. HIFA: five P M, next business day. Home solicitation: midnight, third business day. If a question mixes a door to door sale with contractor financing, the buyer gets both rights.", "HIFA bans certain contract provisions outright, under section twelve oh six. You cannot make the buyer waive claims or defenses, against you or against a finance company that buys the paper. You cannot give the holder the power to accelerate the balance arbitrarily when the buyer isn't in default. You cannot make the buyer waive the right to sue over illegal collection tactics. You cannot authorize breaking into the property or breaching the peace to repossess. And here's the one that surprises builders: you cannot put a liquidated damages clause in a HIFA contract that pays you for the buyer's cancellation or rescission. In ordinary construction contracts, a reasonable liquidated damages clause — say, per day delay damages — is enforceable if it's a genuine pre-estimate of harm and not a penalty. But in a HIFA installment contract, liquidated damages for cancellation are flat out prohibited. The offending clause is void, though the rest of the contract survives. On top of that, section fourteen oh nine says no act, agreement, or statement of the buyer is a valid waiver of any protection under the act. The buyer literally cannot sign away HIFA rights.", "What happens if you willfully violate HIFA? It's a misdemeanor. Up to ninety days in jail, a fine up to five hundred dollars, or both, for a first offense. Repeat offenses go up to a year. And paying someone a reward or referral fee to procure a home improvement finance contract is also prohibited.", "Now the Home Solicitation Sales Act, Act two twenty seven of nineteen seventy one, M C L four forty five point one eleven through one seventeen. This applies to seller solicited sales at the buyer's home — the classic storm chaser at the kitchen table. The buyer can cancel until midnight of the third business day after signing. A mailed cancellation counts when it's dropped in the mailbox, properly addressed with postage paid — not when you receive it. The contract must have the cancellation statement right next to the signature line, plus a notice of cancellation form in duplicate. And the seller cannot send a courier to grab the buyer's payment at the house before the three days run out.", "There is an emergency exception, and the exam loves it. To cut off the buyer's cancellation right in an emergency, three things must all be true. First, the buyer asked for the goods or services without delay because of an emergency. Second, the seller in good faith made a substantial beginning of performance before any cancellation notice. And third — this is the one to memorize — the buyer gave the seller a separate, dated, signed personal statement, in the buyer's own handwriting, describing the emergency and expressly waiving the three day right. Handwriting. Not typed, not a checkbox on your form. That handwritten statement is a Michigan statutory requirement, and the federal cooling off rule requires it too. For restoration work — a burst pipe, a tree through the roof — get that handwritten waiver before you set a single fan, or you're working at your own risk.", "If the buyer does cancel in time, you must return every payment, any trade-in, and any signed note within ten business days of receiving the notice. Business days, not calendar days. The buyer makes any delivered goods available at the house, and if you don't pick them up within twenty days, the buyer keeps them free.", "Let's shift to contract fundamentals, because PSI tests the national material too. A valid contract needs five elements: offer, acceptance, consideration, capacity, and legality. Consideration means each side gives something of value. If a party lacks capacity — a minor, for instance — the contract is voidable by that party. An illegal contract is simply void.", "Know your contract types by who eats the cost risk. Fixed price, also called lump sum: the contractor bears the risk. Overrun the budget, you eat it; beat the budget, you keep the savings. Cost plus: the owner bears the risk, paying actual costs plus your fee. Time and materials: the owner again, paying hourly labor and materials, usually where scope is uncertain. Unit price: shared — you carry the unit cost risk, the owner carries the quantity risk.", "Change orders: written, signed by both parties, describing the scope change and the price or time adjustment. In Michigan that's not just best practice — remember, written amendments are a lien rights condition.", "Substantial completion means the owner can use the work for its intended purpose. It triggers release of retainage — typically five to ten percent held from progress payments — and starts the warranty clock. Final completion means every punch list item is done. On breach: a material breach excuses the other party's performance; remedies include compensatory damages, rescission, quantum meruit for the value of work performed, and rarely specific performance. And the injured party always has a duty to mitigate — you can't run up damages you could reasonably have avoided.", "Now the clocks — the statutes of limitations. Breach of contract in Michigan: six years, under M C L six hundred point fifty eight oh seven, subsection nine. Negligence causing injury to a person or property: three years, under M C L six hundred point fifty eight oh five, subsection two. And then the big one, the statute of repose, M C L six hundred point fifty eight thirty nine. For claims arising from a defective or unsafe improvement to real property — against a contractor, architect, or engineer — the action must be brought within six years from occupancy, use, or acceptance of the completed improvement. Not from discovery. From occupancy. A defect discovered in year seven is simply barred, even though nobody could have found it earlier. The only exception is gross negligence: then the claimant gets one year after the defect is discovered or should have been discovered, but never more than ten years after occupancy. So the ten year number is only the cap on the gross negligence exception — it is not the general rule. Limitations versus repose in one breath: limitations runs from the breach or injury; repose runs from a fixed event and kills the claim regardless of discovery.", "Warranties come in three layers. Express warranties are written promises in the contract — enforceable exactly as written. The implied warranty of habitability says a new home sold by a builder vendor must be fit for human habitation — Michigan recognizes it, but Michigan courts may enforce a disclaimer, so it is not untouchable. The implied warranty of workmanship says the work must meet the standard of a reasonably skilled tradesperson, and it exists whether or not the contract mentions it. Classic scenario: bad flashing leaks three years in, and the one year express warranty has expired. The homeowner's best theory is the implied warranty of workmanship — still alive, still within the six year windows.", "Round it out with insurance. Commercial general liability covers third party bodily injury, third party property damage, and personal and advertising injury — never your own work product or your own property. Builder's risk covers the structure while it's being built, plus materials on site and in transit, and it ends at occupancy. Errors and omissions covers design mistakes, which C G L excludes. Umbrella coverage adds limits and may broaden coverage; excess only adds limits. A certificate of insurance is a snapshot — it proves coverage existed on the day it was issued, nothing more. An additional insured endorsement puts the general contractor on the sub's policy. A waiver of subrogation stops an insurer from chasing the named party after paying a claim. And the liability theories: negligence needs duty, breach, causation, and damages; strict liability applies to defective products with no fault needed; vicarious liability means the general contractor can answer for a sub's actions on the site.", "Rapid fire recap. Say these out loud with me. HIFA trigger: cash price over three hundred dollars, on installment credit, existing homes only. HIFA rescission: five P M, next business day. HIFA type sizes: eight point body, ten point bold headings. HIFA copy rule: no completed copy, no duty to pay. HIFA penalty: misdemeanor, ninety days, five hundred dollars. Liquidated damages for cancellation in a HIFA contract: prohibited and void. Home solicitation cancellation: midnight of the third business day. Emergency waiver: separate, dated, signed, in the buyer's own handwriting. Refund after cancellation: ten business days. Goods pickup: twenty days or the buyer keeps them. Licensure exemption: under six hundred dollars, labor plus materials. Unlicensed builder: cannot sue to collect. Lien rights: written contract, license number, written change orders, any dollar amount. Contract statute of limitations: six years. Negligence: three years. Statute of repose: six years from occupancy, use, or acceptance. Gross negligence: one extra year after discovery, capped at ten. Retainage: five to ten percent, released at substantial completion. Five contract elements: offer, acceptance, consideration, capacity, legality. Four negligence elements: duty, breach, causation, damages.", "If you can rattle those off cold, you own all seven contracts questions. Next chapter, we move on. Keep driving."], "words": 2395}, {"id": "04_business-management_lecture", "title": "Business Management, Estimating, Finance, Personnel and Workers Comp — Audio Lecture", "paras": ["Welcome back. This chapter covers the biggest block of the Business and Law section of your Michigan Residential Builder exam. Out of fifty Business and Law questions, roughly nineteen come from this domain: six on project management and administration, six on accounting and finance, four on types of business organization, two on personnel, and one on estimating. Nail this chapter and you have banked more than a third of the Business and Law section. Let's go through it the way the exam thinks about it.", "Start with business organization, because it is pure memorization and easy points. There are five structures you need to compare on two axes: liability and taxes. A sole proprietorship needs no state filing at all. It is the simplest structure, but the owner has unlimited personal liability — the house, the truck, the savings account, all of it is exposed. All profit lands on the owner's personal return and every dollar is hit with self employment tax. A general partnership is the same idea with two or more people, and it is worse than most people realize, because each partner has unlimited joint and several liability. That means a creditor can collect the entire partnership debt from any one partner, even a debt the other partner created. The L L C fixes the liability problem. You file Articles of Organization with LARA, and as long as you maintain the veil — separate bank accounts, no commingling, adequate capitalization, contracts signed in the company name — your personal assets are protected. Taxes pass through by default. Then there is the S corporation. Here is the trap: S corp status is not a Michigan filing. It is a federal election you make with the I R S on form twenty five fifty three. It gives you pass through taxation, but the owner who works in the business must take a reasonable W two salary. And finally the C corporation, which is the double taxation entity — the corporation pays tax on profits, and then shareholders pay tax again on dividends. Small builders almost never want it.", "One housekeeping number for the L L C: the annual statement is due to LARA by February fifteenth every year, and the fee is twenty five dollars. Miss it for about two years and the company falls to not in good standing status. That status is restorable — the company does not automatically dissolve. That is a tested distinction.", "Now accounting and finance. First, cash versus accrual. Cash basis records income when the money actually arrives and expenses when they are actually paid. Accrual records income when it is earned — when you bill it — and expenses when they are incurred. Accrual is what you need for real job costing, because it matches revenue to cost. For long term contracts, know the two revenue methods by name: percentage of completion, which recognizes revenue as the work progresses, and completed contract, which recognizes everything at the end.", "Know your two financial statements cold. The balance sheet is a snapshot at a single point in time, and it is built on the accounting equation: assets equal liabilities plus owner's equity. Always. The income statement — the profit and loss — covers a period of time. Revenue minus direct job costs gives you gross profit. Gross profit minus overhead gives you net profit. If a question asks where the year's profit shows up, the answer is the income statement, not the balance sheet.", "Here comes the one calculation I can almost promise you will see: markup versus margin. Markup is a percentage of cost. Margin is a percentage of the selling price. They are never the same number. Take a job that costs one hundred thousand dollars. Add a twenty five percent markup and you sell it for one hundred twenty five thousand. Your profit is twenty five thousand — but as a share of the sale price, that is only twenty percent. So a twenty five percent markup is a twenty percent margin. The famous ten and ten — ten percent overhead plus ten percent profit — is a twenty percent markup, and it produces only a sixteen point six seven percent margin. The formulas: margin equals markup divided by one plus markup. And if you want a target margin, divide cost by one minus the margin. To earn a twenty percent margin on an eighty thousand dollar job, you divide eighty thousand by point eight and price it at one hundred thousand. If you multiply by one point two instead, you just fell into the trap.", "Two more money formulas. Overhead rate: total annual overhead divided by total annual direct costs. One hundred twenty six thousand of overhead against eight hundred forty thousand of direct cost is fifteen percent. And break even revenue: fixed overhead divided by gross margin percentage. One hundred fifty thousand of overhead at a thirty percent margin means you need five hundred thousand in revenue just to break even.", "On cash flow, remember that contractors pay for labor and materials before the owner pays them. Accounts receivable is money owed to you; accounts payable is money you owe. A company with big receivables and no cash is profitable on paper and dying in real life. Underbilling means you have done more work than you have billed — you are financing the owner's project. Overbilling is the reverse. Bill promptly and match your billings to the work.", "Billing runs on a schedule of values — the contract price broken into line items. The industry payment forms are A I A G seven zero two, the payment application summary, and G seven zero three, the line by line continuation sheet. Retainage is the five to ten percent the owner withholds from each draw until substantial or final completion, and Michigan has no statutory cap on it for private residential work. A lien safe draw schedule ties each draw to a completed milestone, and each check gets exchanged for a conditional lien waiver — conditional meaning it only takes effect when the payment clears. Never, ever sign an unconditional waiver before the money clears your bank, because an unconditional waiver is effective immediately whether you were paid or not.", "Estimating next — light on the blueprint but the math is free money. Board feet: nominal thickness times nominal width times length in feet, divided by twelve. A two by six, ten feet long, is ten board feet. Concrete: length times width times thickness in feet gives cubic feet, and divide by twenty seven for cubic yards. A four inch slab, twenty four by thirty six feet, is two hundred eighty eight cubic feet, about ten point seven yards, call it twelve with waste. A roofing square is one hundred square feet. Waste factors: framing lumber ten to fifteen percent, drywall ten to twelve, shingles ten to fifteen, concrete five to ten, and engineered trusses essentially zero. Contingency is a risk reserve — five to ten percent on new construction, ten to twenty on remodels — and it goes into the estimate before overhead and profit, because it is not profit. Contract types: lump sum puts cost risk on the contractor and needs complete plans. Cost plus puts the risk on the owner and fits unknown scope, ideally with a not to exceed cap. Time and materials is hourly plus materials for small or undefined work. Unit price fits work where quantities are uncertain, like excavation. And an allowance is a plug number for something not yet selected; the difference gets settled by written change order — and in Michigan, every change order is in writing.", "Project management. The critical path method: the critical path is the longest chain of dependent tasks, and it sets the minimum project duration. Tasks on the critical path have zero float. Float, or slack, is how long a task can slip without moving the completion date. A Gantt chart — a bar chart — is the standard scheduling picture, but it does not inherently show dependencies; network diagrams do. Substantial completion means the owner can use the work for its intended purpose, and it triggers the punch list, the warranty clock, and release of most retainage. Final completion means everything, including the punch list, is done. Bonds come in three flavors: the bid bond guarantees you honor your bid, the performance bond guarantees you finish the work, and the payment bond guarantees your subs and suppliers get paid. When the exam asks which bond protects subcontractors, the answer is the payment bond.", "Personnel and payroll. Employee versus independent contractor is decided by the I R S common law test — behavioral control, financial control, and the relationship of the parties — built on the twenty factors of revenue ruling eighty seven forty one. Michigan's workers comp statute adopted that exact twenty factor test for anything on or after January first, twenty thirteen. And if you withhold federal income tax for someone, that alone is prima facie evidence they are your employee. Payroll numbers: FICA is six point two percent social security plus one point four five percent medicare — seven point six five percent from the employer and the same from the employee. Federal unemployment, FUTA, is six percent of the first seven thousand dollars, but with the state credit it nets to point six percent. Withheld taxes are trust fund taxes, and owners are personally liable if they do not get remitted. Michigan unemployment through the U I A: the statutory default taxable wage base is nine thousand five hundred dollars, but it drops to nine thousand dollars for qualified employers — those with all reports filed and no unpaid balance — while the trust fund stays healthy, and nine thousand is the base that actually applies in twenty twenty five and twenty twenty six. Know both numbers. New employers pay two point seven percent — except construction. A new construction employer pays the average rate for the construction industry, which is several times higher. That exception is exactly the kind of thing this exam loves. One genuine change for twenty twenty six: the ten ninety nine reporting threshold rose from six hundred dollars to two thousand dollars for payments made this year. Older study materials still say six hundred. Overtime under the Fair Labor Standards Act is one and a half times the regular rate for hours over forty in a workweek — there is no federal daily overtime. And MIOSHA recordkeeping: employers with eleven or more employees keep the form three hundred injury log, post the annual summary from February first to April thirtieth, and keep records five years. Report a fatality within eight hours; report an in patient hospitalization, an amputation, or the loss of an eye within twenty four hours.", "Workers compensation, Michigan style. The law is the Workers Disability Compensation Act, and it is administered by the Workers Disability Compensation Agency under the Department of Labor and Economic Opportunity — not LARA. It is a no fault system, and it is the exclusive remedy: the injured worker gets benefits — medical, wage loss, vocational rehab, death benefits — but cannot sue the employer. Coverage is required if you meet either of two triggers. Trigger one: you regularly employ three or more employees at one time, part timers included. Trigger two: even with fewer than three, if just one employee has worked thirty five or more hours a week for thirteen weeks or longer during the preceding fifty two weeks. Either one alone requires coverage. A sole proprietor with no employees is exempt but may opt in. Owners can be excluded by filing form W C three thirty seven: a corporate officer who owns at least ten percent of a corporation with ten or fewer stockholders, an L L C member manager who owns at least ten percent of an L L C with ten or fewer members, or a partner. Now the general contractor trap: if your sub has no workers comp and no valid exclusion on file, and his worker gets hurt on your site, the claim lands on you. Collect a comp certificate or the exclusion form before anyone swings a hammer. Penalties for going bare: it is a misdemeanor — up to one thousand dollars and up to six months, and every single day is a separate offense — plus the state can get a court injunction shutting you down and a civil fine of up to one thousand dollars per day, looking back three years. And an uninsured employer loses the exclusive remedy shield, meaning the injured worker can sue you in civil court. One more insurance term: the experience modification rate, or E M R. One point zero is average. Below one means a good safety record and cheaper premiums.", "Time for the rapid fire recap. Michigan sales tax: six percent — contractor pays it on materials, labor is exempt, never charged on the contract price. L L C annual statement: February fifteenth, twenty five dollars. Markup to margin: twenty percent markup is sixteen point seven margin, twenty five markup is twenty margin, fifty markup is thirty three point three margin. Board feet: thickness times width times length over twelve. Concrete: cubic feet divided by twenty seven. Roofing square: one hundred square feet. Contingency: five to ten new, ten to twenty remodel, before profit. Retainage: five to ten percent. Workers comp triggers: three employees at one time, or one employee at thirty five hours for thirteen weeks in the last fifty two. Exclusion: form W C three thirty seven, ten or fewer owners, ten percent or more ownership. Penalty: a thousand dollars, six months, each day separate, plus a thousand a day civil. Independent contractor test: I R S twenty factors, since January first twenty thirteen. FICA: seven point six five each side. FUTA: point six percent net on seven thousand. U I A wage base: nine thousand five hundred statutory default, nine thousand for qualified employers right now; new construction employers pay the industry average, not two point seven. Ten ninety nine threshold: two thousand dollars starting this year. Overtime: time and a half over forty per week. MIOSHA: three hundred log at eleven employees, fatality in eight hours, hospitalization, amputation, or eye in twenty four. Payment bond pays the subs. Conditional waiver until the check clears. Assets equal liabilities plus equity.", "That is the whole domain. Run the flashcards until the numbers come without thinking, and this block of the exam is yours."], "words": 2421}, {"id": "05_miosha-safety_lecture", "title": "MIOSHA Construction Safety — Audio Lecture", "paras": ["This chapter covers MIOSHA construction safety, which is worth about ten of the one hundred ten trade questions on your Michigan Residential Builder exam. That's ten questions you can lock down almost entirely with memorized numbers, because safety questions are number questions. Heights, depths, hours, dollar amounts. If you know the numbers cold, this is the easiest section on the whole test. Let's get them into your head.", "Start with the big picture. MIOSHA stands for the Michigan Occupational Safety and Health Administration. It was created by the MIOSHA Act, which is Act one fifty four of nineteen seventy four. Michigan runs its own state plan, which by federal law must be at least as effective as federal OSHA. And here's a favorite exam discriminator: MIOSHA covers public sector employees, meaning state, county, and city workers, while federal OSHA does not. If a question asks who MIOSHA protects that federal OSHA doesn't, the answer is public employees.", "Who runs MIOSHA today? The Department of Labor and Economic Opportunity, L E O. Not LARA. It moved from LARA to L E O by executive order back in twenty nineteen. On construction sites, the enforcement arm is the Construction Safety and Health Division. If an answer choice says LARA administers MIOSHA, that's the trap.", "Next, the General Duty Clause. Every employer must furnish a workplace free from recognized hazards that are causing or likely to cause death or serious physical harm. That's M C L four oh eight point ten eleven. The key idea: it applies when no specific standard covers the hazard. It's the catch-all. And under the construction general rules, every construction employer must also have an accident prevention program. Not optional, even for a small crew.", "Now the site rules, and we'll go part by part.", "Fall protection is Part forty five. The trigger is six feet. If a work area is six feet or more above a lower level, workers need fall protection. Three conventional systems: guardrails, safety nets, or a personal fall arrest system, meaning harness, lanyard, and anchorage. A guardrail top rail sits at forty two inches, plus or minus three, and must take a two hundred pound force. In a personal fall arrest system, maximum free fall is six feet, and the rig can't let the worker hit a lower level. The anchorage must hold five thousand pounds per worker. On a residential roof where conventional systems are truly infeasible at a particular spot, the fallback is a written, site-specific fall protection plan.", "Ladders are Part eleven. Four numbers. First, the angle: four to one. For every four feet of height, the base sits one foot out. Second, the extension: side rails must extend at least three feet above the upper landing. So a ladder to a sixteen foot eave needs to reach about nineteen feet, with the base about four feet out. Third: secure it. Safety feet, or tie it, block it, or otherwise fix it in place. And never stand on the top three feet. One more Part eleven surprise that trips people: a portable ladder near power transmission or distribution lines needs twenty feet of clearance. Twenty for ladders. That's different from the ten foot clearance for equipment near lines up to fifty kilovolts. Ladders twenty, equipment ten.", "Scaffolds are Part twelve, and here lives the single most-tested trap in this whole domain. General fall protection triggers at six feet. But a guardrail on the open side of a scaffold platform is required at ten feet. Read the question. If it says scaffold, the answer is ten. If it says leading edge, floor opening, or just general fall protection, the answer is six. Other scaffold numbers: a scaffold must support four times its maximum intended load. Planking is scaffold grade two by ten. Access must be a ladder, stair, or ramp, and climbing the cross braces is always a violation. Suspension type scaffolds, like a boatswain's chair or ladder jack, require a personal fall arrest system, and a two-point suspension scaffold requires both a harness system and a guardrail.", "Excavation is Part nine, and it's dense with numbers, so slow down here. A trench or excavation more than five feet deep requires a protective system: sloping, shoring, or a trench shield. Below five feet you still need protection if the ground shows signs of hazardous movement. Egress is a separate rule with a separate number: at four feet deep, forty eight inches, workers need a ladder, and that ladder must extend three feet above the top of the trench and be within twenty five feet of lateral travel of every worker. So four feet means ladder, five feet means protective system. Don't let the exam swap those. Spoil piles and equipment stay at least two feet back from the edge. And a competent person, someone who can spot hazards and has authority to fix them, must inspect the excavation on an ongoing basis and again after every rainstorm.", "Soil types. The exam tests the federal three-letter system. Type A is the most stable: clay, silty clay. Maximum slope three quarters horizontal to one vertical, which is fifty three degrees. Type B is the middle: silt, angular gravel, and any previously disturbed soil. Slope one to one, forty five degrees. Type C is the weakest: sand, gravel, anything submerged or seeping water. Slope one and a half horizontal to one vertical, thirty four degrees, the flattest slope. Two memory hooks. The weaker the soil, the flatter the slope. And previously disturbed soil can never be Type A, so around existing utilities you're at Type B at best.", "Before any of that digging, Michigan law says contact MISS DIG eight one one at least three full working days before you excavate. Know the colors: red is electric, yellow is gas or oil, orange is telecom, blue is water, green is sewer, white marks your proposed dig, pink is survey, purple is reclaimed water.", "Electrical is Part seventeen. Every one hundred twenty volt, fifteen or twenty amp receptacle that isn't part of the building's permanent wiring needs G F C I protection. The alternative is an assured equipment grounding conductor program, a documented testing program covering every cord set, temporary receptacle, and plug-connected tool. G F C I or the assured grounding program, one or the other. And lockout tagout: before servicing equipment, de-energize it, lock it, and tag it.", "A few health and P P E items. First aid: a person with a valid first aid certificate must be present at the worksite. Silica: the permissible exposure limit is fifty micrograms per cubic meter over eight hours, and the action level is twenty five. Wet cutting and vacuum collection come before respirators. Noise: in construction the limit is ninety decibels over eight hours. The eighty five decibel action level with hearing tests is a general industry rule, not construction, and yes, they will bait you with eighty five. Hazard communication is the right to know: labels, safety data sheets, and training. A safety data sheet must be on site and accessible for every hazardous chemical, no matter who brought it. Confined spaces: big enough to enter, limited entry and exit, not designed for occupancy, and you test the atmosphere before anyone goes in.", "Now enforcement, because a builder is an employer. A MIOSHA inspector who shows credentials may enter your site without delay at reasonable times. No advance notice, and tipping off an employer is itself an offense. You can insist on a warrant, but they'll get one. The inspection runs opening conference, walkaround, closing conference, citations. Both you and an employee representative may walk along. Employees can file confidential complaints, can refuse imminently dangerous work after asking you to fix it first, and are protected from retaliation.", "Penalties come from Michigan statute, not the federal schedule. Serious and other-than-serious violations run up to seven thousand dollars each. Willful or repeat violations run up to seventy thousand, with a five thousand dollar minimum on willful. A willful violation that kills a worker is a felony. If an answer choice shows the federal sixteen thousand dollar figure, it's a trap. Michigan is seven and seventy.", "Reporting and recordkeeping. A fatality must be reported to MIOSHA within eight hours of learning of it. An in-patient hospitalization, an amputation, or the loss of an eye must be reported within twenty four hours. Eight for a death, twenty four for the rest, never forty eight. Recordkeeping uses three forms: the three hundred log, the three hundred A annual summary, posted from February first through April thirtieth, and the three oh one incident report. Employers with ten or fewer employees are exempt from the routine logs, but nobody is ever exempt from the eight hour and twenty four hour reports.", "One neighbor topic that rides along with safety: workers' compensation. A Michigan employer needs coverage with one or more employees working thirty five plus hours a week for thirteen or more weeks, or three or more employees at any one time. And if your subcontractor has no coverage and his worker gets hurt on your job, the general contractor can be on the hook. Verify every sub's certificate.", "Time for the rapid-fire recap. Say these with me.", "Fall protection: six feet. Scaffold guardrail: ten feet. Guardrail height: forty two inches, plus or minus three. Max free fall: six feet. Anchorage: five thousand pounds.", "Ladders: four to one angle. Three feet above the landing. Ladder near power lines: twenty feet. Equipment near power lines: ten feet.", "Trenches: protective system at five feet. Ladder at four feet, sticking up three feet, within twenty five feet of travel. Spoil pile: two feet back. Competent person: ongoing, and after every rain.", "Soil: Type A, three quarters to one, fifty three degrees. Type B, one to one, forty five degrees. Type C, one and a half to one, thirty four degrees. Disturbed soil is never Type A.", "MISS DIG: three full working days.", "Scaffolds: four times the load. Two by ten planking. Never climb cross braces.", "Electrical: G F C I on every temporary one twenty volt receptacle, or an assured grounding program.", "Silica: fifty limit, twenty five action. Noise: ninety in construction.", "Reporting: fatality eight hours. Hospitalization, amputation, eye: twenty four hours. Summary posted February first to April thirtieth. Ten or fewer employees: exempt from logs, never from reports.", "Penalties: seven thousand serious. Seventy thousand willful or repeat, five thousand minimum.", "And the agency: L E O runs MIOSHA, MIOSHA covers public employees, and the General Duty Clause fills every gap.", "That's the domain. Ten questions, all numbers, all yours."], "words": 1767}, {"id": "06_sitework-concrete-foundations_lecture", "title": "Sitework, Concrete, and Foundations — Audio Lecture", "paras": ["This chapter covers the biggest single block of your trade exam: excavation and sitework, site engineering, concrete, and footings and foundations. Together that is thirty-two of the one hundred ten trade questions — almost one in three. Everything here comes from the twenty-fifteen Michigan Residential Code, chapter four, plus the MISS DIG law and MIOSHA excavation rules. The exam is closed book, so these numbers have to live in your head. Let's build them in the order a real job happens: engineer the site, dig, form and pour, then protect the foundation.", "Start with the site. Before anyone digs, you read the plot plan. It shows property lines, setbacks, easements, the building footprint, utilities, well and septic, and contour lines. Two definitions the exam loves. A benchmark is a permanent point of known elevation — vertical control, your starting point for all height measurements. A monument is a permanent marker of a property corner or boundary — horizontal control — and disturbing one is illegal. Don't mix them up. Contour lines connect points of equal elevation. Close together means steep, far apart means flat, and contour lines never cross.", "Here is the leveling math, because they will make you do it. Set the instrument, shoot the benchmark. Height of instrument equals the benchmark elevation plus that backsight reading. Then any point's elevation equals height of instrument minus the foresight reading at that point. Say the benchmark is one hundred point zero, the backsight is four and a half feet, so the height of instrument is one hundred four and a half. Foresight at the garage corner reads six and a quarter. One hundred four and a half minus six and a quarter is ninety-eight and a quarter. And remember the logic check: a higher rod reading means lower ground.", "Rural site engineering means well and septic. A percolation test measures how fast water drains through soil, in minutes per inch, to size a septic drain field. Too slow — think dense clay, slower than about sixty minutes per inch — and it fails. The numbers: a one-thousand-gallon tank minimum regardless of flow — that one is in the state E G L E criteria — with twelve fifty for four bedrooms as common local practice. The state well code minimum is fifty feet from a single-family well to both the septic tank and the drain field, though many local health departments push the drain field to seventy-five or one hundred feet. Tank ten feet from the foundation and drain field twenty feet are local practice numbers. Well casing runs at least twenty-five feet below grade and sticks up twelve inches above grade — that one is state well code, rule R three twenty-five point sixteen thirty-two.", "Now, before a single bucket of dirt moves in Michigan, you call MISS DIG. Dial eight one one at least three full working days before excavating. Working days — not calendar days, not seventy-two hours. That's Public Act one seventy-four of twenty thirteen. Fail to call and you face a civil fine of up to five thousand dollars. Knowingly damaging or hiding utility marks — that's the misdemeanor, not the failure to call. And MISS DIG only marks member utility lines. The homeowner's private lines — the run to the detached garage, the well feed — those are on you. Know the colors: red is electric, yellow is gas or oil, orange is telecom, blue is water, green is sewer, white is your own proposed dig, pink is survey, purple is reclaimed water.", "Trench safety. Four depth numbers, and the exam will try to make you swap them. At four feet deep you need a ladder or ramp within twenty-five feet of lateral travel. At five feet deep you need a protective system — sloping, benching, shoring, or a trench box — unless you are in stable rock. At twenty feet deep, the protective system must be designed by a registered professional engineer. And keep your spoil pile and equipment at least two feet back from the edge. One more contrast: six feet is the fall-protection trigger. Five feet is the trench trigger. Different rules, different numbers.", "Soil types. Stable rock can stand vertical. Type A is stiff clay, one and a half tons per square foot or more — slope it three-quarters to one, fifty-three degrees. Type B is medium soils — slope one to one, forty-five degrees. Type C is sand, gravel, or anything submerged or seeping — slope one and a half to one, thirty-four degrees. The weaker the soil, the flatter the slope. And here's the trap: you can never bench Type C soil. Benching is for A and B only. Every excavation needs a competent person — someone who can identify hazards and has authority to fix them — inspecting daily and after every rain.", "Michigan sitework has one more permit trap. A soil erosion and sedimentation control permit — Part ninety-one of the natural resources act — is triggered by disturbing one acre or more, or any earth change within five hundred feet of a lake or stream. Wetlands are a different program entirely, Part three-oh-three. If the question says wetland, the answer is not Part ninety-one.", "On to bearing soil. Footings sit on undisturbed natural soil or engineered fill — never on organic muck, loose fill, or frozen ground. Presumptive bearing values, from best to worst: crystalline bedrock, twelve thousand pounds per square foot. Sedimentary rock, four thousand. Sandy gravel, three thousand. Sand, two thousand. Clay and silt, fifteen hundred. Compaction gets verified against a Proctor test — the lab finds the soil's maximum dry density, and the field spec is usually ninety to ninety-five percent of it.", "Now the foundation itself, and the single most Michigan number on this exam: forty-two inches. All exterior footings and foundation systems extend forty-two inches below actual grade. That's a Michigan amendment — the generic I R C answer of twelve inches below grade is a trap. The exemptions: freestanding accessory buildings up to six hundred square feet of light-frame construction, or four hundred square feet of heavier construction, with eaves ten feet or less — and freestanding decks not attached to the house.", "Footing dimensions. Minimum thickness, six inches. The footing projects at least two inches beyond each face of the wall, and that projection can never exceed the footing's own thickness. Width comes from the code tables based on soil strength and stories — twelve inches is the everyday light-frame answer on decent soil, and it widens as soil weakens. The top of a footing must be level. The bottom can slope up to one in ten — ten percent — and steeper than that, you step the footing. Building next to a slope steeper than one vertical in three horizontal — thirty-three percent — triggers special setback rules.", "Anchor bolts — drill this string until it's automatic. Half-inch diameter minimum. Six feet on center maximum. Seven inches embedded into the concrete or grouted block. At least two bolts per plate section, one within twelve inches of each end, sitting in the middle third of the plate width, nut and washer tightened. And a trap to disarm: the four-foot spacing for buildings over two stories is a seismic rule for design categories C and D — Michigan is category A or B, so six feet on center governs no matter how many stories. Same reason you do not need those big three-by-three plate washers — that's an earthquake-country rule.", "Foundation walls: thickness comes from tables driven by wall height, unbalanced backfill height, and soil class. The wall must stick up above finished grade at least four inches where masonry veneer is used, six inches everywhere else. And never backfill until the wall has cured and is braced or anchored to the floor framing above — then backfill in six to twelve inch compacted lifts of clean material.", "Keeping the basement dry is three separate systems, and the exam tests whether you can tell them apart. First, surface grading: the ground falls six inches in the first ten feet away from the foundation — impervious surfaces need two percent. Second, foundation drains: drain tile or perforated pipe at or below the top of the footing, discharging by gravity or pump to an approved outlet. The gravel over the drain extends one full foot beyond the outside edge of the footing and six inches above the top of the footing, wrapped in filter fabric. The pipe sits on two inches of washed gravel with six inches over it. No drain needed on well-drained gravelly Group One soils. Third, the wall coating. Dampproofing is the default — from top of footing to finished grade, a bituminous coating, with masonry walls parged first with three-eighths of an inch of portland cement. Waterproofing — an actual membrane — is required only where a high water table or severe soil-water conditions are known. Dampproofing stops soil moisture. Waterproofing stops water under pressure.", "Crawl spaces: vent area one square foot per one hundred fifty square feet of floor, dropping to one per fifteen hundred with a ground vapor retarder, with a vent within three feet of each corner. Access through the floor is eighteen by twenty-four inches; through a perimeter wall, sixteen by twenty-four. Floor is bigger — eighteen. Wall is sixteen.", "Concrete. All of Michigan is severe weathering, so learn three strengths. Twenty-five hundred p s i for footings, interior slabs, and foundation walls not exposed to weather. Three thousand for vertical concrete exposed to weather. Thirty-five hundred for garage floor slabs, porches, carport slabs, and steps — anything that sees deicing salt. And every piece of exterior concrete gets air entrainment, five to seven percent — those microscopic bubbles give freezing water room to expand.", "Mix basics: water-cement ratio around point four five to point five zero. Adding water on site raises the slump but kills strength. A slump test measures workability — four to six inches is normal residential, footings often two to four. Admixtures: accelerators for cold weather — but never calcium chloride around embedded or prestressed steel, because chlorides corrode it. Retarders for hot weather and long hauls. Water reducers for workability without extra water. Air entrainers for freeze-thaw.", "Steel placement is a classic discrimination question. Footing rebar goes in the bottom third — the tension zone — with three inches of cover where cast against earth. Welded wire mesh in a slab goes in the upper third, on chairs — mesh lying in the dirt does nothing. Bar sizes are eighths of an inch: number three is three-eighths, number four is a half inch, number five is five-eighths.", "Finishing sequence: screed, bull float, then stop and let the bleed water evaporate. Never finish bleed water back into the surface. Then edge, cut your joints, float, trowel — interior only, because a steel trowel makes exterior concrete dangerously slick — and broom finish outside for traction. Control joints get cut at least a quarter of the slab depth, spaced roughly eight to twelve feet on a four-inch slab. Isolation joints separate the slab from walls and columns. Construction joints end a day's pour.", "Curing and cold weather: concrete hits about seventy percent of design strength at seven days and full design strength at twenty-eight. Keep it moist and around fifty degrees. In cold weather, never pour on frozen ground, and protect fresh concrete from freezing until it reaches five hundred p s i — roughly the first forty-eight to seventy-two hours. Interior slabs: three and a half inches thick minimum, over four inches of granular base, over six-mil poly. Volume math: length times width times thickness, all in feet, divided by twenty-seven gives cubic yards — and order ten percent extra.", "Rapid-fire recap. Forty-two inches — Michigan frost depth. Six in ten — grade away from the house. Six inches — footing thickness; two inches — footing projection. Half inch, six feet, seven inches, two per plate, twelve from the end — anchor bolts. Four with veneer, six otherwise — wall above grade. One foot beyond, six above — drain gravel. Twenty-five hundred, three thousand, thirty-five hundred — footings, exposed walls, garage slabs. Five to seven percent air. Four to six slump. Seven days, seventy percent; twenty-eight days, full strength. Fifty degrees and five hundred p s i for cold weather. Three and a half inch slab, four inch base, six mil poly. One-fifty crawl venting; eighteen by twenty-four floor, sixteen by twenty-four wall. Fifteen hundred, two thousand, three thousand, four thousand, twelve thousand — clay, sand, gravel, sedimentary rock, bedrock. Eight one one, three working days, five thousand dollar fine. Four feet ladder, five feet protection, two feet spoil, twenty feet engineer. Fifty-three, forty-five, thirty-four degrees — A, B, C — and you never bench Type C. One acre or five hundred feet of water — erosion permit. Fifty feet, tank to well; one thousand gallons for three bedrooms. Nail these and you own the biggest block on the exam."], "words": 2171}, {"id": "07_carpentry-framing_lecture", "title": "Carpentry and Structural Framing — Michigan Builder Exam Audio Lecture", "paras": ["Alright, let's talk carpentry and framing. This is the single biggest trade category on the Michigan residential builder exam — sixteen of your one hundred ten trade questions come from here. Nothing else comes close. If you own this chapter, you've banked a seventh of the whole trade section. And here's the good news: almost every question in this domain is a number. A fraction of a joist depth, a percentage of a stud width, a nail count, an inch measurement. Numbers can be drilled, and that's exactly what we're going to do.", "One framing fact before we start: the exam tests the twenty fifteen Michigan Residential Code. Not the twenty twenty one I R C. The newer code was stayed by a court order in July of twenty twenty five and never took effect. That matters because Michigan amended some values away from the I R C defaults, and the exam loves to dangle the national number as a wrong answer. Every time I flag something as a Michigan amendment, burn it in twice.", "Let's start down at the floor. Every joist, beam, or girder needs bearing at its ends — one and a half inches minimum on wood or metal, three inches minimum on masonry or concrete. Say it with me: one and a half on wood, three on concrete. If a wood girder pockets into a concrete or block wall, it gets that three inches of bearing plus a half inch air space around the untreated wood so it doesn't rot.", "Joist ends also need lateral restraint — full depth solid blocking at least two inch nominal, or attachment to a full depth header, band joist, rim joist, or an adjoining stud. That's the end of the joist. Now, mid span: here's a Michigan exam classic. Bridging — meaning solid blocking, diagonal bridging, or a one by three strip nailed across the bottoms — is only required for joists that exceed a nominal two by twelve, and when it's required, the intervals can't exceed eight feet. Hear the trap in that: a two by ten does not need bridging. A two by twelve does not need bridging. Only joists deeper than a two by twelve. The wrong answer on the exam will say two by ten. Don't take the bait.", "Now cutting, drilling, and notching of sawn joists. This is pure fractions, and it shows up constantly. Notches in the top or bottom of a joist: maximum depth is one sixth of the joist depth, the notch can't be longer than one third of the depth, and no notches at all in the middle third of the span. At the very end of the joist, over a bearing, the notch can be deeper — up to one fourth of the depth. Holes are their own rule: maximum diameter one third of the depth, and every hole stays at least two inches away from the top edge, the bottom edge, any other hole, and any notch. So the pattern is: one sixth for notches in the span, one fourth for notches at the ends, one third for holes and for notch length, two inches of clearance everywhere. Run that on a two by ten, actual depth nine and a quarter: notch about an inch and a half, end notch about two and five sixteenths, hole about three and one sixteenth.", "And engineered lumber? Different world. You do not cut, notch, or drill an I joist, an L V L, a glulam, or a truss — period — unless the manufacturer's literature allows it or an engineer signs off. Those pre stamped knockouts in an I joist web are the manufacturer's permission. A truss that got field cut needs a registered design professional. That's an easy exam point.", "Floor openings, like a stairwell. If the header joist span is four feet or less, a single header the same size as the joists is fine, with single trimmers if the header lands within three feet of the trimmer bearing. Once the header span goes over four feet, double the header and double the trimmers. Over six feet, hang it on approved joist hangers. Four feet, double. Six feet, hangers.", "Double joists under a parallel bearing partition that get spread apart for piping? Block between them, full depth, two inch nominal lumber, at no more than four feet on center.", "Cantilevers. The twenty fifteen code says a prescriptive floor cantilever can't exceed the nominal depth of the joist — a two by ten hangs out about ten inches — beyond that you're into the cantilever tables. Here's the trap: the L over four rule, cantilever equals a quarter of the back span — that's a deck rule from the twenty twenty one I R C. It is not in the tested code. If the question says per the code, the answer is the depth rule and the tables.", "Up to the walls. Stud sizes: a two by four bearing wall carrying just a roof and ceiling can go twenty four inches on center up to ten feet tall. Add one floor above, and two by fours drop to sixteen inches on center. Two floors plus a roof? Two by fours are out — you need two by sixes at sixteen. Nonbearing two by fours can run twenty four on center up to fourteen feet. Utility grade studs are the cheap seats: sixteen on center max, roof and ceiling only, eight feet max in exterior walls.", "Top plates: doubled, overlapped at corners and intersections, with end joints offset at least twenty four inches. There's a single top plate exception, and it has its own hardware: a three by six inch, twenty gauge galvanized splice plate with six eight penny nails on each side. Remember twenty gauge for that one, because there's a different plate coming in a second.", "Stud notching and boring — four percentages, and the exam will absolutely try to cross wire them. Notching: twenty five percent of the stud width in a bearing or exterior wall, forty percent in a nonbearing partition. Boring: forty percent in a single bearing stud, sixty percent in a nonbearing stud — or in a bearing stud if you double the studs, and you can only bore two successive doubled studs that way. Every bored hole stays five eighths of an inch from the edge of the stud, and never in the same cross section as a notch. So: notch twenty five and forty. Bore forty and sixty. The forty percent shows up on both lists — notching nonbearing, boring bearing. That's the wire they want you to cross.", "Now the top plate repair. When somebody cuts or notches more than fifty percent of a bearing wall top plate — usually the plumber running a vent — the fix is a galvanized metal tie, sixteen gauge, an inch and a half wide, nailed with eight ten penny nails on each side, extending at least six inches past the opening. Sixteen gauge repair tie versus twenty gauge single plate splice. Two different plates, two different rules.", "Headers over doors and windows come out of the header tables — sized by the header's lumber, the snow load, and the building width — and the same table tells you how many jack studs go under each end. Jack studs, also called trimmers, are cut to header height and carry the load. King studs run full height beside them.", "Wall bracing basics. Every exterior wall line is a braced wall line, and along it, a braced wall panel has to begin within ten feet of each end of the line, with no more than twenty feet between adjacent panels. Know your method letters: L I B is a one by four let in brace. W S P is wood structural panel, minimum three eighths inch. G B is gypsum board. C S dash W S P is continuous sheathing. And in Michigan, wind governs bracing, not earthquakes — we're seismic design category A or B.", "Up to the roof. The ridge board is at least one inch nominal thick, and at least as deep as the cut end of the rafter. Valley and hip rafters are beefier: two inch nominal minimum, same depth rule. And when the roof pitch drops below three in twelve, a ridge board isn't enough — the ridge, hips, and valleys have to be designed as beams.", "Here is the tie question, and it is almost guaranteed to show up. Rafter ties versus collar ties. Rafter ties — usually your ceiling joists — sit down low, at the plate, and they resist the outward thrust that wants to push your walls apart. Minimum two by four when installed as dedicated ties. Collar ties sit up high, in the upper third of the attic, minimum one by four, no more than four feet on center, and they resist wind uplift at the ridge. Low ties stop spreading. High ties stop uplift. If ceiling joists run perpendicular to the rafters or aren't connected at the plate, you add rafter ties or you engineer a ridge beam.", "A few more roof numbers. Ceiling joists lap at least three inches over bearing partitions, or butt and get toenailed. Purlins that shorten rafter spans must be at least the size of the rafters they support, braced down to bearing walls with two by fours at forty five degrees or steeper, braces four feet on center max, and no brace longer than eight feet unbraced. Rafter notching follows the exact same fractions as joists — one sixth, one fourth at ends, one third for holes.", "Fastening schedule — table R six oh two point three. The greatest hits: joist to sill or girder, three eight penny toenails. Ceiling joist to plate, same — three eight penny toenails. Top plate to top plate, sixteen penny commons at sixteen inches on center. Double top plate splice, eight sixteen penny nails each side of the joint. Stud to plate, two sixteen penny end nails. Collar tie to rafter, three ten penny face nails. Band joist to joist, three sixteen penny end nails. Built up girders, twenty penny nails at thirty two inches on center top and bottom, staggered, with two more at every end and splice. And structural sheathing: six inches on center at the panel edges, twelve in the field.", "Stairs. This is Michigan's signature amendment, so lock it down. Minimum tread depth: nine inches. Maximum riser height: eight and a quarter inches. The I R C says ten inch treads and seven and three quarter risers — in Michigan those are the trap answers. And notice the direction of the rule: nine is a minimum and eight and a quarter is a maximum, so a stair built to the stricter national numbers still passes here. Risers and treads can't vary more than three eighths of an inch within a flight. Winders: ten inches of tread at the walk line twelve inches from the narrow side, six inches minimum anywhere. Headroom: six feet eight inches. Width: thirty six inches clear, thirty one and a half with one handrail, twenty seven with two. Handrails kick in at four or more risers, set thirty four to thirty eight inches above the nosings, and a round rail grips at an inch and a quarter to two inches. Guards: required when the walking surface is more than thirty inches up, at least thirty six inches high, no opening that passes a four inch sphere, built to take a two hundred pound load.", "Decks. The ledger is a minimum two by eight, pressure treated, number two grade, bolted or lag screwed with half inch hot dipped galvanized or stainless fasteners — never electroplated — spaced per the table based on joist span, staggered in two rows, and flashed where it meets the house. Where hold downs provide the lateral connection, it's two devices minimum, fifteen hundred pounds each. Deck footings go to Michigan frost depth — forty two inches. And one more trap: the deck post height table — four by four to eight feet, six by six to fourteen feet — is not in the tested code. That's the twenty twenty one I R C.", "Rapid fire recap. Bearing: one and a half wood, three masonry. Bridging: only past two by twelve, eight foot intervals. Joist notch one sixth, end notch one fourth, hole one third, two inch clearances, no middle third notches. Opening headers: double past four feet, hangers past six. Stud notch twenty five bearing, forty nonbearing. Stud bore forty bearing, sixty nonbearing or doubled. Five eighths edge distance. Plate cut past fifty percent: sixteen gauge tie, inch and a half wide, eight ten penny each side, six past the cut. Plate joints offset twenty four. Two by four studs: twenty four on center roof only, sixteen with a floor above, two by six for two floors. Ridge board one inch, hips and valleys two inch, beam below three twelve. Collar ties upper third, one by four, four feet. Ceiling joist lap three inches. Purlin braces two by four, forty five degrees, four feet, eight feet max. Top plates sixteen penny at sixteen. Sheathing six and twelve. Stairs: nine inch tread, eight and a quarter riser, three eighths variation, six eight headroom, thirty six wide, handrail at four risers, thirty four to thirty eight. Guards: thirty inches triggers, thirty six high, four inch sphere, two hundred pounds. Deck: two by eight treated ledger, half inch galvanized bolts, fifteen hundred pound hold downs, forty two inch footings.", "That's the chapter. Sixteen questions live in those numbers. Run this again tomorrow, and they're yours."], "words": 2278}, {"id": "08_masonry-roofing-siding_lecture", "title": "Masonry, Roofing, Siding and Exterior Finishes — Audio Lecture", "paras": ["This chapter covers about twenty two questions on your trade exam: nine on masonry, seven on roofing, three on siding, and a few from the finishes category. Everything here is from the twenty fifteen Michigan Residential Code and standard trade practice. The exam is closed book, so these numbers have to live in your head. Let's build them in.", "Start with mortar, because it opens almost every masonry question set. There are four mortar types, and you rank them from strongest to weakest as M, S, N, O. The memory trick is the word masonwork — take every other letter and you get M, S, N, O. Type M is twenty five hundred p s i, and it goes below grade: foundations, retaining walls, anything touching earth. Type S is eighteen hundred p s i, the structural workhorse at or above grade. Type N is seven hundred fifty p s i, the general purpose mortar, and here's the thing the exam loves: Type N is the standard choice for brick veneer above grade. Don't reach for Type M just because it's strongest — strongest is not the question, application is. Type O is three hundred fifty p s i, for interior non load bearing work and repointing old soft masonry only. Grout is a different animal from mortar. Grout is fluid, at least two thousand p s i, and it gets poured into the block cells around the rebar. Mortar is stiff and goes between the units in bed and head joints, typically three eighths of an inch.", "Weather rules. Cold weather masonry kicks in below forty degrees. Between twenty and forty, you heat the mixing water and sand so the mortar sits between forty and one hundred twenty degrees when you use it, and you protect finished work for twenty four hours. Below twenty degrees, no laying without a heated enclosure. And burn this in: antifreeze in mortar is never allowed. Never. Hot weather rules trigger above one hundred degrees, or above ninety with wind over eight miles an hour — shade the materials, dampen absorptive brick, fog spray the work. Mixed mortar has a board life of about two and a half hours, and you can retemper it once inside that window. One more vocabulary item: efflorescence is that white powdery salt stain on masonry. It means water is moving through the wall, dissolving salts, and leaving them behind when it evaporates. You cure the water problem — flashing and weeps — not the stain.", "Now brick veneer, and this is where the numbers get dense. The air space between the veneer and the sheathing is one inch minimum, four and a half inches maximum. The veneer hangs on wall ties, and each tie can support no more than two point six seven square feet of wall. Spacing is thirty two inches on center horizontally and twenty four inches vertically. Hear the pattern: the bigger number, thirty two, runs horizontally along the course. Corrugated ties are twenty two gauge, seven eighths of an inch wide. Weep holes go in the first course, immediately above the flashing, at a maximum of thirty three inches on center, and at least three sixteenths of an inch in diameter. Here's a nasty trap pair: ties are thirty two, weeps are thirty three. Weeps get the extra inch. Lintels over veneer openings: a three by three by quarter inch steel angle spans up to six feet, with four inches of bearing at each end. And remember, veneer carries only its own weight — never floor or roof loads.", "Behind every siding and veneer is the water resistive barrier — number fifteen felt or an approved housewrap — lapped two inches horizontally and six inches at vertical joints, always upper over lower, shingle fashion. That two and six pair shows up on exams.", "Joints in masonry walls: clay brick expands over its life as it absorbs moisture, so brick walls get expansion joints with compressible filler. Concrete block shrinks as it cures, so block walls get control joints. Brick grows, block shrinks — opposite movements, opposite joints. Reinforcement basics: number four rebar in the grouted cells for typical residential work, and nine gauge ladder wire in the bed joints every sixteen inches, which is every other course of eight inch block.", "Fireplaces and chimneys are their own cluster of numbers, and they are heavily tested. The firebox: walls are ten inches of solid masonry, or eight inches total when lined with two inches of firebrick. Firebox depth, twenty inches minimum. The hearth slab is four inches thick; the hearth extension in front is two inches thick — and it can drop to three eighths of an inch if the firebox opening is raised at least eight inches above it. The extension size depends on the opening: under six square feet, sixteen inches in front and eight inches to each side. Six square feet or bigger, twenty in front and twelve to each side. Sixteen eight, twenty twelve. Clearance to combustibles around the fireplace is two inches at the front faces and sides, and four inches at the back. The damper sits at least eight inches above the top of the opening. And the whole assembly sits on a footing at least twelve inches thick, extending six inches beyond the face on all sides, down below Michigan's forty two inch frost depth.", "Chimney height is the famous three two ten rule: at least three feet above the highest point where the chimney passes through the roof, and at least two feet higher than any part of the building within ten feet horizontally. Both conditions, always. The crown on top slopes at least ten degrees, is two inches thick at the edge, and overhangs two inches. Flue sizing is a ratio of the fireplace opening: a round flue needs one twelfth of the opening area, a square or rectangular flue under a two to one shape needs one tenth, and a skinny rectangle at two to one or more needs one eighth. Quick example: a thirty six by thirty opening is one thousand eighty square inches; divided by twelve, a round flue needs ninety square inches. Chimney clearance to combustibles: two inches for a chimney inside the house or in an exterior wall, one inch for a chimney built entirely outside the walls. The split is interior versus exterior — not below versus above the roof, no matter how tempting that wrong answer looks. Last chimney item: a cricket, that little diverter roof on the uphill side, is required when the chimney is more than thirty inches wide parallel to the ridge and doesn't intersect the ridge.", "Now roofing. Asphalt shingles need a slope of at least two in twelve. From two in twelve up to four in twelve, you must run double underlayment — a nineteen inch starter and thirty six inch sheets lapped nineteen inches. Four in twelve and steeper takes a single layer. Fasteners are twelve gauge roofing nails with three eighths inch heads, driven at least three quarters of an inch into the sheathing, and the code minimum is four nails per strip shingle. Six nails is a manufacturer or high wind spec, not the code floor.", "Michigan cares deeply about ice. The ice barrier membrane runs from the lowest edge of the roof to at least twenty four inches inside the exterior wall line. Inside the wall line — not twenty four inches up from the eave. A big overhang means a lot more membrane. On roofs eight in twelve or steeper, it's at least thirty six inches measured along the slope. The only exemption is a detached accessory building with no conditioned space.", "Drip edge extends a quarter inch below the sheathing, two inches back onto the deck, and laps two inches piece to piece. The sequencing trap: at the eaves, underlayment goes over the drip edge; at the rakes, drip edge goes over the underlayment. Step flashing where a roof meets a sidewall is four by four minimum, and at the bottom of that run you need a kickout flashing to throw water into the gutter instead of behind the siding — in Michigan that kickout is the difference between a dry wall and a rotten one. Open valley metal is twenty four inches wide.", "Low slope numbers, quick and clean. Standing seam metal, a quarter in twelve. Lapped metal with sealant, half in twelve; without sealant, three in twelve. Built up roofing and single ply membranes like E P D M, a quarter in twelve. Mineral surfaced roll roofing, one in twelve. Wood shingles and wood shakes both need three in twelve on a roof, and shakes get an eighteen inch wide number thirty felt interlayment between courses. Reroofing: tear off is mandatory when the deck is water soaked, when the old roof is shake, slate, or tile, or when there are already two layers of anything up there. Two layers is the ceiling.", "Attic ventilation. The base rule is one square foot of net free vent area for every one hundred fifty square feet of attic. You can cut that to one in three hundred by either of two paths: a class one or two vapor retarder on the warm side of the ceiling — but only in climate zones six, seven, and eight — or by putting forty to fifty percent of the vent area high, within three feet of the ridge, with the rest at the eaves. Either path alone is enough. And note the Michigan wrinkle: southern lower Michigan is zone five A, so down there the vapor retarder path doesn't qualify — you need the balanced vents. Keep one inch of clear air space between the insulation and the sheathing with baffles.", "Siding. Fasteners generally penetrate an inch and a quarter into sheathing and framing combined. Vinyl siding lives or dies on movement: a twelve foot panel can move half an inch with temperature, so you center the nails in the slots, leave a thirty second of an inch under the head, and a quarter inch gap at the trim. Nail vinyl tight and it buckles. Installation runs bottom up: barrier, flashing, level starter strip, corners, J channel, then panels locking course over course. Fiber cement laps an inch and a quarter minimum — that's a code number — and every field cut edge gets primed. The manufacturer clearances are six inches to grade and two inches to roofing. Don't cross those wires: inch and a quarter is the lap, six inches is the grade clearance. Stucco takes three coats over lath, two coats over masonry, each coat kept moist for forty eight hours, and the weep screed at the bottom sits four inches above earth or two inches above paving.", "A few finishes items round out the domain. Drywall levels: level one is tape embedded, for plenums. Level two, tape plus one coat, garages and behind tile. Level three, two coats, for heavy texture. Level four, three coats, the standard painted wall. Level five adds a skim coat over the whole surface, and it's required for gloss or semi gloss paint and critical lighting. Tile: thinset, the cement mortar, works everywhere including showers; mastic is for dry area walls only, never wet areas, never floors. Shower tile goes over cement board with a waterproof membrane — green board is not a wet area substrate. Hardwood flooring runs perpendicular to the joists, blind nailed through the tongue, with a three eighths inch expansion gap at the walls.", "Rapid fire recap. Breathe, and repeat these after me. Mortar: M twenty five hundred, S eighteen hundred, N seven fifty, O three fifty — veneer gets N. Grout two thousand. Air space one inch. Ties: two point six seven square feet, thirty two horizontal, twenty four vertical, twenty two gauge. Weeps: thirty three on center, three sixteenths diameter, above the flashing. Lintel: three by three by a quarter, six foot span, four inch bearing. Felt laps: two horizontal, six vertical. Firebox: ten inches solid or eight with firebrick, twenty deep. Hearth four, extension two, or three eighths when raised eight. Extensions: sixteen and eight, or twenty and twelve at six square feet. Fireplace clearance: two front and sides, four at the back. Damper eight above the opening. Footing twelve thick, six past the face. Chimney: three feet, two feet, ten feet. Crown: ten degrees, two thick, two overhang. Flues: one twelfth round, one tenth square, one eighth skinny rectangle. Chimney clearance: two interior, one exterior. Cricket at thirty inches. Shingles: two twelve minimum, double felt below four twelve, four nails, three quarter inch penetration. Ice barrier twenty four inches inside the wall line, thirty six along the slope on steep roofs. Drip edge: quarter inch down, two onto the deck. Step flashing four by four. Valley metal twenty four. Two roof layers maximum. Vents: one fifty, or one three hundred with vapor retarder in zone six or forty to fifty percent high. Baffle space one inch. Siding nails penetrate an inch and a quarter. Fiber cement laps an inch and a quarter, six to grade. Stucco: three coats on lath, two on masonry, forty eight hour cure, screed four above earth, two above paving. Level five for gloss. Thinset in showers, never mastic.", "That's the domain. Run this chapter again tomorrow, and drill the trap pairs until they can't touch you."], "words": 2235}, {"id": "09_envelope-interior_lecture", "title": "Envelope and Interior: Insulation, Ventilation, Windows and Doors, Finishes, and Specialties", "paras": ["This chapter covers about fifteen questions on your trade exam: roughly five on insulation, two on ventilation, five on windows, doors, and skylights, and the rest split between interior finishes and specialty items. Everything here comes from the twenty fifteen Michigan Residential Code — not the twenty twenty-one code. Michigan amended some of these numbers away from the national defaults, and those amendments are exactly where the exam sets its traps. Let's work through it.", "Start with insulation, because it carries the most weight. Michigan has three climate zones. Zone five A is the southern Lower Peninsula — Detroit, Grand Rapids, Lansing. Zone six A is the northern Lower Peninsula and the eastern Upper Peninsula. Zone seven is the western U P — the coldest part of the state.", "Here is the single most important Michigan amendment in this whole chapter. In zone five A, the ceiling insulation requirement is R thirty-eight. The national energy code says R forty-nine for zone five, but Michigan amended it down to thirty-eight. So if the question says southern Michigan, or names a southern city, the answer is R thirty-eight, and R forty-nine is the trap. In zones six A and seven — northern Michigan and the U P — the ceiling is R forty-nine. Say it back to yourself: south thirty-eight, north forty-nine.", "Walls are easier because they're the same statewide: R twenty in the cavity, or R thirteen cavity plus R five continuous insulated sheathing on the outside. Floors over unconditioned space are R thirty, except zone seven, where they rise to R thirty-eight. Basement walls: in zone five A you need R ten continuous or R thirteen cavity. In zones six A and seven, it's R fifteen continuous or R nineteen cavity. When you see two numbers with a slash, like ten slash thirteen, the first number is always continuous insulation — rigid foam — and the second is cavity insulation in a framed wall. Either one complies. Slab edges get R ten in every zone; the difference is depth — two feet down in zone five A, four feet down in six A and seven.", "Windows tie into the energy table too. The maximum window U factor in Michigan is zero point three two, in every zone. Not zero point three zero — that's the twenty twenty-one national number and it is not in force. Skylights get zero point five five. And remember U factor runs backward from R value: lower is better, because U factor is one divided by R. One more giveaway: there is no solar heat gain requirement in Michigan. S H G C limits are for hot southern climates. If a Michigan question offers you a solar heat gain number, it's a trap — the table says not required.", "Air leakage is another Michigan amendment. The maximum is four air changes per hour at fifty pascals, verified with a mandatory blower door test. The model code says three; Michigan says four. Four is your answer.", "Now vapor retarders, which the exam loves because installers get them wrong in real life. In climate zones five, six, and seven — which is all of Michigan — you need a Class one or Class two vapor retarder on the interior side of frame walls. Interior means the warm-in-winter side. Class one is poly sheeting or foil facing, a tenth of a perm or less. Class two is kraft-faced batts, up to one perm. Class three is just latex paint, up to ten perms, and it's only allowed when the wall can dry — either vented cladding over the sheathing, or enough continuous insulated sheathing to keep the wall warm: R five over a two by four wall in zone five, R seven and a half over a two by six. And never, ever put poly on the outside of a Michigan wall. With the required interior retarder, that builds a double vapor barrier — moisture gets in and can't dry either direction. That's rot and mold, and it's a wrong answer every time.", "A few insulation odds and ends. Fiberglass batts run about R three point two per inch, blown cellulose about three point five, extruded polystyrene about five, closed-cell spray foam six or better. Compressing a batt into a smaller cavity lowers its R value — an R nineteen squeezed into a two by four wall performs like R thirteen. And at the eaves, insulation baffles must hold a one-inch minimum air space between the insulation and the roof sheathing so ventilation air can move.", "That brings us to ventilation. Attic ventilation is the one-to-one-fifty rule: net free vent area equal to one one-hundred-fiftieth of the attic floor area. You can cut that in half, to one three-hundredth, if either of two conditions is met — either a Class one or two vapor retarder on the warm side of the ceiling, which only counts in climate zones six and seven, not in zone five A, or forty to fifty percent of the vent area placed high in the attic, within three feet of the ridge measured vertically, with the rest down at the eaves. Either condition alone is enough. Quick math: a fifteen-hundred-square-foot attic at one to three hundred needs five square feet of net free area; at one to one fifty it needs ten.", "Mechanical ventilation has two little numbers the exam swaps on you constantly. Bathrooms: fifty C F M intermittent, or twenty continuous. Kitchens: one hundred C F M intermittent, or twenty-five continuous. Bigger room load, bigger number — the kitchen gets a hundred. Every exhaust fan discharges outdoors. Never into the attic, never into a soffit, never into a crawl space — dumping moist air in an attic breeds mold and feeds ice dams.", "And here's the connection question they like: whole-house mechanical ventilation is required whenever the blower door test comes in under five air changes per hour. Michigan requires every new house to test at four or tighter. So every new Michigan home needs whole-house mechanical ventilation. Typical rate for a house between fifteen hundred and three thousand square feet with two or three bedrooms: sixty C F M continuous.", "One specialty item rides along with ventilation: radon. The E P A action level is four picocuries per liter. The standard new-construction answer is a passive sub-slab depressurization system — a four-inch gravel layer under the slab, a poly soil-gas retarder, and a three-to-four-inch vent pipe running from under the slab straight up through the roof, with power roughed in for a future fan.", "Now windows and doors — five questions, and egress is the heart of it. Emergency escape and rescue openings are required in every sleeping room, in basements with habitable space, and in habitable attics. Burn these four numbers in: five point seven square feet of net clear opening — five point zero if it's a grade-floor opening. Minimum clear height twenty-four inches. Minimum clear width twenty inches. Maximum sill height forty-four inches above the floor. It must open from inside without keys, tools, or special knowledge. And here's the classic trick: a window at exactly twenty wide and twenty-four high is only three point three three square feet. Meeting both minimum dimensions does not meet the area. One dimension has to be bigger. If the egress window is below grade, the window well needs nine square feet of horizontal area with thirty-six inches in each direction, and if the well is deeper than forty-four inches, it needs a permanent ladder or steps.", "Safety glazing — tempered glass — is the other big window topic, section R three oh eight point four. The hazardous locations: All glass in doors. Glass within a twenty-four-inch arc of either side of a closed door when the bottom edge is under sixty inches above the floor. Big panes that meet all four of these together: over nine square feet, bottom edge under eighteen inches from the floor, top edge over thirty-six inches, and a walking surface within thirty-six inches. Glass in guards and railings — always, no exceptions. Wet locations — any glass with a bottom edge less than sixty inches above a tub or shower drain and within sixty inches horizontally of the water. Sixty, not seventy-two. And stairways: glass within thirty-six inches horizontally of a walking surface and under sixty inches above it, plus glass within sixty inches of the bottom tread. Tempered panes carry a permanent etched label — no label, no pass.", "Two more door-and-window rules. Window fall protection: if an operable window's sill is less than twenty-four inches above the floor inside, and the drop outside is more than seventy-two inches, the opening can't pass a four-inch sphere, or it needs an approved opening-control device. Every house needs at least one side-hinged exterior egress door with thirty-two inches of clear width and seventy-eight inches of clear height. And the door from an attached garage into the house: one and three-eighths inch solid wood, one and three-eighths solid or honeycomb-core steel, or a twenty-minute fire-rated door — self-closing — and it may never open into a bedroom.", "On to interior finishes, which mostly means drywall. Fastener spacing without adhesive: ceilings take nails every seven inches or screws every twelve. Walls take nails every eight or screws every sixteen. Ceilings are always tighter — gravity. Screws have to bite five-eighths of an inch into the wood. Half-inch board is standard on walls and on ceilings framed sixteen inches on center. At twenty-four on center, ceilings step up to five-eighths, or half-inch sag-resistant board. Type X is the fire-rated core; Type C is the upgraded fire-rated core that outperforms X.", "The garage separation is a guaranteed question somewhere on this exam. Walls between the garage and the house: half-inch gypsum on the garage side, every wall, always. The ceiling of a garage with living space above it: five-eighths Type X. Structure supporting that floor: half-inch. The trap runs both directions — Type X on the walls is wrong, and plain half-inch on a ceiling under a bedroom is wrong. And remember, this is a separation, not a rated assembly. If an answer says one-hour fire wall, that's the trap. Ducts through the separation must be twenty-six gauge steel with no openings into the garage.", "Drywall finish levels, zero through five. Level one, tape embedded, for plenums. Level two, tape plus one coat, for garages and behind tile. Level three, two coats, for heavy texture. Level four, three coats, standard for flat paint. Level five adds a skim coat over the whole surface — that's for gloss, semi-gloss, and critical lighting.", "Wet areas: tub and shower walls need a nonabsorbent finish to six feet above the floor. Tile in wet areas goes over cement board, fiber-cement, or glass-mat gypsum — never paper-faced green board — and it's set with thinset, the cement mortar. Mastic is for dry walls only; it softens in moisture and fails.", "Last, the specialties. Attic access: required when the attic is over thirty square feet with thirty inches or more of height. The rough opening is twenty-two by thirty inches, in a hallway or other accessible spot, with thirty inches of headroom above the hatch. Memory hook: thirty, thirty, thirty, through twenty-two by thirty. Smoke alarms: in every bedroom, outside every sleeping area, on every story including the basement — all interconnected, hardwired with battery backup. Carbon monoxide alarms: the trigger is a fuel-burning appliance or an attached garage; the location is outside each sleeping area; and under the twenty fifteen code they do not have to interconnect — interconnection is a smoke alarm rule. Pool barriers: forty-eight inches high, no opening passes a four-inch sphere, self-closing self-latching gate with the latch at fifty-four inches or on the pool side.", "Rapid-fire recap. Ceiling insulation: R thirty-eight south, R forty-nine north. Walls: R twenty, or thirteen plus five. Basement: ten thirteen south, fifteen nineteen north. Slab: R ten, two feet south, four feet north. Window U factor: point three two. Skylight: point five five. Air leakage: four A C H fifty with a blower door test. Vapor retarder: Class one or two, interior side. Attic vents: one to one fifty, or one to three hundred. Baffle air space: one inch. Bath fan: fifty and twenty. Kitchen fan: one hundred and twenty-five. Whole house trigger: under five A C H fifty. Egress: five point seven square feet, five flat at grade, twenty-four high, twenty wide, forty-four sill. Window well: nine square feet, thirty-six inches, ladder past forty-four deep. Tempered glass: twenty-four-inch door arc under sixty; nine square feet, eighteen, thirty-six, thirty-six; sixty above the drain; thirty-six and sixty at stairs. Fall protection: sill under twenty-four in, drop over seventy-two out, four-inch sphere. Egress door: thirty-two by seventy-eight clear. Garage door to house: one and three-eighths, self-closing, never to a bedroom. Garage gypsum: half-inch walls, five-eighths Type X ceiling. Drywall fasteners: seven and twelve on ceilings, eight and sixteen on walls. Screws: five-eighths bite. Tub walls: nonabsorbent to six feet. Attic access: twenty-two by thirty, thirty square feet, thirty inches headroom. Radon: four picocuries per liter. Know these cold and this domain is yours."], "words": 2193}, {"id": "10_plans-math-trades_lecture", "title": "Plans, Estimating Math, Trade Boundaries and Permits — Audio Lecture", "paras": ["This chapter covers the second biggest block of the trade exam: plans, specifications, and estimating, which is fourteen of the one hundred and ten trade questions. It also covers trade boundaries, meaning what you may not do without a plumbing, electrical, or mechanical license, and the permit and inspection process, which shows up on the business and law side. Everything here keys to the twenty fifteen Michigan Residential Code. Remember that the twenty twenty-one update was stayed by a court in July of twenty twenty-five and never took effect, so if an answer choice smells like the newer national code, treat it with suspicion.", "Let's start with reading plans. Floor plans and elevations are drawn at one quarter inch equals one foot. That is the single most tested scale fact. If a wall measures six inches on a quarter-scale plan, multiply plan inches by four and you get twenty-four feet of real wall. Site plans are different. They use an engineer's scale, usually one inch equals twenty feet or one inch equals thirty feet. Details, like a stair connection or a flashing condition, are drawn much bigger, anywhere from three quarters of an inch up to three inches equals one foot.", "Know your drawing types. An elevation is a flat picture of the outside face of the house. It shows finishes, window and door openings, the grade line, and the roof slope. A section is a vertical cut through the building, and it is where you find what is inside the wall or floor. Sheathing, studs, insulation, floor to floor heights. If the question asks where you would find the layers of a wall assembly, the answer is the wall section. A detail is a blow-up of one small condition, referenced by a bubble. If you see the number three over the letters A five in a circle, that means detail three, drawn on sheet A five. Sheet prefixes matter too. A is architectural, S is structural, M is mechanical, E is electrical, P is plumbing, and C is civil.", "Two rules about conflicts. First, a written dimension always beats a scaled measurement. Never scale a drawing when the number is printed. Second, when the drawings and the written specifications disagree, the specifications generally govern, but the best exam answer is usually to notify the architect and get clarification before you proceed. Remember the division of labor: specs control quality, drawings control quantity and location.", "Door and window schedules are tables keyed to marks on the plan. A window called out as three zero five zero is three feet zero inches wide by five feet zero inches high. Width first, then height. A door marked two eight six eight is two feet eight inches by six feet eight inches.", "For specifications, know the classic sixteen division C S I MasterFormat. The ones that get tested: division three is concrete, division four is masonry, division six is wood and plastics, division seven is thermal and moisture protection, division eight is doors and windows, division nine is finishes, division fifteen is mechanical, and division sixteen is electrical.", "Now the math, and this is where you bank points, because every one of these problems is just a formula. Board feet first. Board feet equals thickness in inches, times width in inches, times length in feet, divided by twelve. A two by six that is ten feet long: two times six times ten is one hundred twenty, divided by twelve is ten board feet. Lumber is priced per thousand board feet. Eight hundred board feet at six hundred dollars per thousand is point eight times six hundred, which is four hundred eighty dollars.", "Concrete. Twenty-seven cubic feet make one cubic yard. Length times width times thickness, all in feet, divided by twenty-seven. Convert inches to feet first. Four inches is a third of a foot. So a twenty by thirty slab at four inches is two hundred cubic feet, divided by twenty-seven is seven point four yards. Add five to ten percent waste and round up, so you order eight. On any ordering question, round up. Never order short.", "Masonry has two magic numbers. Standard modular brick runs six point seven five bricks per square foot of wall. A thousand square foot wall with a hundred square feet of openings is nine hundred net, times six point seven five is six thousand seventy-five bricks. Standard eight by eight by sixteen block runs one point one two five blocks per square foot. A forty foot wall, eight feet tall, is three hundred twenty square feet, times one point one two five is three hundred sixty blocks.", "Roofing is counted in squares, and a square is one hundred square feet. A twenty-four hundred square foot roof is twenty-four squares, and standard three tab shingles run three bundles per square, so seventy-two bundles, plus roughly ten percent waste. Drywall and sheathing come in four by eight sheets of thirty-two square feet. Total your wall and ceiling area, divide by thirty-two, round up, add waste.", "Framing counts. Studs at sixteen inches on center: take the wall length in feet, multiply by three quarters, add one, then add extras for corners and openings. The fast field rule is one stud per lineal foot of wall. Joists work the same way: a twenty-four foot run at sixteen on center is twenty-four times point seven five plus one, which is nineteen joists. Plates are three times the wall length, one bottom and a double top.", "Excavation. Soil swells when you dig it and shrinks when you compact it. Bank yards are in the ground, loose yards are in the truck, compacted yards are in the fill. Common earth swells about twenty-five percent, so one hundred bank yards becomes one hundred twenty-five loose yards to haul. The trap is shrinkage. If you need one hundred compacted yards and shrinkage is ten percent, you divide by point nine, giving about one hundred eleven bank yards. You divide by one minus the shrinkage. You do not just add ten percent.", "Grade and slope. Percent grade is rise over run times one hundred. Two feet of fall in one hundred feet is two percent. A quarter inch per foot is about two percent, and an eighth inch per foot is about one percent, which is your garage floor slope. The code number to know: the ground must fall six inches in the first ten feet away from the foundation, which is five percent, or two percent minimum on pavement.", "Stairs are the money problem, and Michigan is different from the national code, so listen carefully. Michigan allows a maximum riser of eight and one quarter inches and a minimum tread of nine inches. The national I R C numbers, seven and three quarters and ten inches, are the trap answers. Here is the method. Total rise divided by the maximum riser, rounded up, gives the riser count. Say the floor to floor rise is one hundred eight inches. Divide by eight point two five and you get thirteen point zero nine. Round up to fourteen risers. The actual riser is one hundred eight divided by fourteen, about seven point seven inches. Treads are always one fewer than risers, so thirteen treads, and at nine inches each, the minimum total run is one hundred seventeen inches. Why round up? Because rounding down to thirteen risers makes each one eight point three one inches, which is over the limit and illegal. One more stair number: risers and treads cannot vary more than three eighths of an inch within a flight.", "Now trade boundaries. Your residential builder license lets you build the house, and it lets you coordinate, but it never lets you do plumbing, electrical, or mechanical work. Each trade has its own license, its own permit, and its own inspections. All three trades are now licensed under one law, the Skilled Trades Regulation Act, Act four zero seven of twenty sixteen, which replaced the old separate trade acts. Plumbing goes apprentice, then journeyman at six thousand hours over three years, then master with four thousand more hours over two years. Electrical goes journeyman at eight thousand hours over four years, then master at twelve thousand hours over six years, including two years as a journeyman. In both trades, the contracting business itself needs a separate contractor license, and it must employ a master. A master license alone does not make you a contractor.", "Mechanical is the odd one, and it is a favorite exam trap. Under the same Skilled Trades Regulation Act, Michigan licenses the mechanical contractor as a business entity only. There is no individual journeyman or master mechanical license in Michigan. The company designates a qualifying officer and carries classification endorsements for the kinds of work it does. If an answer choice mentions a Michigan master mechanical license, it is wrong. Anyone handling refrigerant also needs federal E P A section six zero eight certification.", "The homeowner exemption. A homeowner may do their own trade work on their own primary residence, under their own permit. Rentals are excluded, and a contractor may never work under a homeowner's permit. That is illegal. As the builder, your job is to hire licensed subs, verify their licenses on the LARA website before they start, make sure they pull their own permits, and sequence their inspections.", "Permits. The governing law is Act two thirty of nineteen seventy-two, the Stille DeRossett Hale Single State Construction Code Act. No regulated work starts before a permit is issued, ever. But some work is exempt, under section R one zero five point two, and the exemption numbers are pure memorization. A one story detached accessory structure, like a shed, up to two hundred square feet. A fence up to seven feet high. A retaining wall up to four feet, measured from the bottom of the footing, that holds back no surcharge. Sidewalks and driveways not more than thirty inches above grade. Painting, papering, tiling, carpeting, cabinets, and countertops. Above ground prefab pools less than twenty-four inches deep. Window awnings projecting fifty-four inches or less. And decks of two hundred square feet or less that sit no more than thirty inches above grade and do not serve the exit door. Watch the shed trap: two hundred square feet is the current number, one twenty is the old code.", "The timelines. The building department has ten business days to issue or deny a permit, fifteen for an unusually complicated building or structure. An issued permit dies if work does not start within one hundred eighty days, or stops for one hundred eighty days. The certificate of occupancy must be issued within five business days of written application, once every permit is finaled, every inspection passed, and every fee paid. Sealed architect plans are not required for one and two family dwellings under three thousand five hundred square feet.", "The inspection sequence runs footing and foundation before the pour, waterproofing before backfill, rough framing, then rough electrical, plumbing, and mechanical before anything is covered, then insulation, then drywall, then the four finals, and then the certificate of occupancy. The iron rule: never cover uninspected work. If you do, the inspector can issue a stop work order and make you tear it open. After a stop work order, the only work allowed is what makes the site safe. A knowing violation is a misdemeanor, up to five hundred dollars and up to ninety days. Each knowing violation is a separate offense — and each day counts as a separate offense specifically when you keep working through a stop construction order. Unlicensed residential work draws a separate civil fine of one hundred to five hundred dollars.", "Time for the rapid fire recap. Quarter inch equals one foot for floor plans. One inch equals twenty or thirty feet for site plans. Window three zero five zero is three feet by five feet. Board feet is thickness times width times length over twelve. Twenty-seven cubic feet in a yard, five to ten percent concrete waste. Six point seven five bricks per square foot. One point one two five blocks per square foot. A roofing square is one hundred square feet, three bundles per square. A four by eight sheet is thirty-two square feet. Studs at sixteen on center: length times point seven five plus one. Common earth swells twenty-five percent. Grade is rise over run times one hundred, and six inches in ten feet away from the house. Michigan riser eight and a quarter max, tread nine minimum, variance three eighths, treads equal risers minus one, and always round the riser count up. Plumber hours: six thousand journeyman, four thousand more for master. Electrician hours: eight thousand journeyman, twelve thousand master. No individual mechanical license, entity only, with a qualifying officer. Permit exemptions: shed two hundred square feet, fence seven feet, retaining wall four feet, deck two hundred square feet under thirty inches, awning fifty-four inches. Permit in ten business days, dead after one hundred eighty idle days, certificate of occupancy in five business days, sealed plans only at thirty-five hundred square feet and up. And never, ever cover uninspected work.", "That is the whole domain. Drill the numbers until they are boring, and this block becomes the easiest fourteen questions on the test."], "words": 2215}], "quizzes": {"01_licensing-law": [{"q": "A homeowner moved into a newly built house and later discovered workmanship defects. Under Article 24, how long after the latest of completion, occupancy, or purchase does the owner have to file a complaint against the builder?", "opts": ["1 year", "2 years", "18 months", "3 years"], "correct": 2, "why": "MCL 339.2411(1) sets an 18-month complaint window running from the latest of completion, occupancy, or purchase (or C of O issuance/closing on permit projects); 1 and 2 years are trap answers.", "trap": true}, {"q": "What is the statutory composition of the Residential Builders' and Maintenance & Alteration Contractors' Board?", "opts": ["9 members: 4 residential builders, 2 M&A contractors, 3 public members", "7 members: 4 residential builders, 2 M&A contractors, 1 public member", "9 members: 3 residential builders, 3 M&A contractors, 3 public members", "5 members: 3 residential builders, 2 public members"], "correct": 0, "why": "MCL 339.2402 sets a 9-member board: 4 licensed residential builders, 2 licensed M&A contractors, and 3 public members.", "trap": false}, {"q": "An unlicensed handyman splits a $1,500 bathroom repair into three separate $500 contracts with the same homeowner to stay under the licensing threshold. Which statement is correct?", "opts": ["He is exempt because each contract is under $600", "He needs a license - the exemption uses the aggregate price of the whole undertaking, and splitting contracts to evade the act kills the exemption", "He is exempt because the $600 rule applies per contract as long as the work is residential", "He is exempt as long as the homeowner agrees in writing"], "correct": 1, "why": "MCL 339.2403(f) exempts only undertakings whose aggregate price for labor, material, and other items is less than $600, and expressly denies the exemption where work is split into sub-$600 contracts to evade the act.", "trap": true}, {"q": "A person acts as a residential builder without a license, first offense, no injury. What is the criminal penalty?", "opts": ["Fine of $500 and/or up to 90 days", "Civil infraction only, no jail exposure", "Fine of $1,000 and/or up to 1 year", "Misdemeanor, fine of $5,000 to $25,000 and/or imprisonment up to 1 year"], "correct": 3, "why": "MCL 339.601(6)(a) sets the builder-specific first-offense penalty at $5,000-$25,000 and/or up to 1 year; the $500/90-day figure is the generic unlicensed-occupations rate and is a trap.", "trap": true}, {"q": "What is the prelicensure education requirement for a residential builder applicant?", "opts": ["40 hours of approved courses with no subject-area minimums", "60 hours of approved courses with at least 6 hours in each of 7 competency areas", "60 hours of approved courses plus 2 years of documented field experience", "21 hours of approved courses in codes, safety, and legal issues"], "correct": 1, "why": "MCL 339.2404b(1)(c), effective June 1, 2008, requires 60 hours with at least 6 hours in each of 7 competency areas, and no experience requirement appears in the statute.", "trap": false}, {"q": "A builder first licensed in 2015 is renewing. How many hours of continuing competency are required?", "opts": ["At least 21 hours per 3-year cycle, including at least 3 hours in each calendar year during the first 6 calendar years of licensure", "3 hours per 3-year cycle: 1 hour codes, 1 hour safety, 1 hour legal issues", "No continuing competency is required after the first renewal", "45 hours per 3-year cycle"], "correct": 0, "why": "MCL 339.2404b(2) requires 21 hours per 3-year cycle for licensees first licensed on or after January 1, 2009; the 3-hour cycle applies only to pre-2009 licensees, a classic trap pairing.", "trap": true}, {"q": "The qualifying officer of a licensed building corporation resigns. What happens to the company's license?", "opts": ["Nothing, as long as the company hires a new qualifying officer within 3 years", "The license converts automatically to inactive status", "The entity license is suspended, but the department may allow it to remain in force for a reasonable time to qualify a new qualifying officer", "The license is permanently revoked and the company must reapply"], "correct": 2, "why": "MCL 339.2405(4) suspends the entity's license when the QO leaves, though the department may allow the license to remain in force for a reasonable time to qualify a new QO.", "trap": false}, {"q": "A licensed builder's corporation replaces two of its directors. Within how many days must the licensee notify the department of the change in control or direction of the business?", "opts": ["30 days", "60 days", "5 days", "10 days"], "correct": 3, "why": "MCL 339.2411(2)(g) makes failure to notify the department within 10 days of a change in control or direction (partners, directors, officers, trustees) prohibited conduct; 30 days is the trap.", "trap": false}, {"q": "How is the PSI Residential Builder examination structured?", "opts": ["160 questions (50 Business & Law + 110 Trade), passing raw score 116, 240 minutes, closed book, one combined exam", "Two separately passed parts: a 50-question B&L exam and a 110-question trade exam, each passed independently", "100 questions, passing score 70, 180 minutes, open book", "160 questions, passing score 120, 300 minutes, references allowed"], "correct": 0, "why": "The PSI candidate handbook lists 160 questions (50 B&L + 110 trade), passing raw score 116, 240 minutes, closed book, with the parts combined into one exam since 11/14/2019.", "trap": false}, {"q": "The owner of a rental duplex personally repairs and alters the unit between tenants. Does the owner need an Article 24 license?", "opts": ["Yes, because the property produces income", "Yes, unless each project is under $600", "No - an owner of rental property is exempt for maintenance and alteration of that rental property", "No, but only if the owner lives in one of the units"], "correct": 2, "why": "MCL 339.2403(c) exempts an owner of rental property for maintenance and alteration of that rental property.", "trap": false}], "02_liens-insurance-bonds": [{"q": "A lumber supplier with no direct contract with the owner delivers its first load of material to a residential job. To preserve full lien rights, when must it serve its Notice of Furnishing?", "opts": ["Within 30 days after first furnishing", "Within 20 days after first furnishing", "Within 90 days after first furnishing", "Before any material is delivered"], "correct": 1, "why": "MCL 570.1109(1) requires subcontractors and suppliers to serve the Notice of Furnishing within 20 days after first furnishing; 30 days is the laborer rule and a classic trap.", "trap": true}, {"q": "A subcontractor finished its work on March 1; the overall project finished June 1. To have a valid construction lien, the sub must record its claim of lien by when, and where?", "opts": ["Within 90 days after March 1 (its own last furnishing), with the county register of deeds", "Within 90 days after June 1 (project completion), with the county register of deeds", "Within 90 days after March 1, with the circuit court", "Within 1 year after March 1, with the county register of deeds"], "correct": 0, "why": "MCL 570.1111(1) requires recording within 90 days after that claimant's own last furnishing with the register of deeds; measuring from project completion or filing with a court are trap answers.", "trap": true}, {"q": "After recording a claim of lien, how long does the claimant have to file a foreclosure suit, and in what forum?", "opts": ["90 days, in district court", "2 years, with the register of deeds", "6 months, in circuit court", "1 year after the claim of lien was recorded, in circuit court"], "correct": 3, "why": "MCL 570.1117(1) requires the foreclosure action no later than 1 year after the claim of lien was recorded, filed in circuit court for the county where the property sits (MCL 570.1118(1)).", "trap": false}, {"q": "On a residential project, how is the Notice of Commencement handled?", "opts": ["The owner records it with the register of deeds before work begins", "The general contractor prepares and records it", "The owner prepares it only upon written request and must return it within 10 days of the request's postmark; it is not recorded", "It is filed with the local building department with the permit application"], "correct": 2, "why": "MCL 570.1108a makes the residential Notice of Commencement an on-request document the owner returns within 10 days and does not record; recording before work begins is the commercial rule under section 1108.", "trap": true}, {"q": "A GC hands the owner a signed full conditional lien waiver from a subcontractor along with a draw request. When does that waiver become effective?", "opts": ["Immediately upon signing", "Only upon actual payment of the stated amount", "When the owner countersigns it", "When it is recorded with the register of deeds"], "correct": 1, "why": "Under MCL 570.1115 a conditional waiver is effective only upon actual payment of the stated amount; unconditional waivers are the ones effective immediately on signing.", "trap": false}, {"q": "A homeowner asks about recovering losses through the Homeowner Construction Lien Recovery Fund. What is the correct answer?", "opts": ["The fund was abolished - MCL 570.1201-.1207 were repealed by 2010 PA 147, effective August 23, 2010", "The fund pays homeowners up to $75,000 per residential claim", "Builders pay into the fund at each license renewal", "The fund covers only claims by subcontractors, not homeowners"], "correct": 0, "why": "The Recovery Fund no longer exists - MCL 570.1201-.1207 were repealed by 2010 PA 147 effective August 23, 2010, so any present-tense fund answer is a trap.", "trap": true}, {"q": "On a Michigan public construction project, at what contract size do performance and payment bonds become mandatory, and in what minimum amount?", "opts": ["Over $25,000; at least 50% of the contract amount", "Over $100,000; at least 10% of the contract amount", "Over $50,000; each bond not less than 25% of the contract amount", "All public projects regardless of size; 100% of the contract amount"], "correct": 2, "why": "MCL 129.201-.203 require performance and payment bonds on public projects over $50,000, each in an amount not less than 25% of the contract amount.", "trap": false}, {"q": "A drywall sub goes unpaid on a public school project. What is its remedy?", "opts": ["Record a construction lien against the school property", "Sue the school district directly under the Construction Lien Act", "File a claim against the performance bond, which protects subcontractors", "Make a claim on the payment bond - public property cannot be liened"], "correct": 3, "why": "Public property cannot be liened, so the sub's remedy is a payment bond claim under MCL 129.203/.207; the performance bond protects the governmental unit, not subs.", "trap": false}, {"q": "A contractor has 2 employees. One of them has worked 40 hours per week for the past 20 weeks. Is workers' compensation insurance required?", "opts": ["No - coverage is required only with 3 or more employees", "Yes - coverage is also required with 1 employee working 35 or more hours per week for 13 or more weeks during the preceding 52 weeks", "No - construction employers with under 5 employees are exempt", "Only if the employees request coverage in writing"], "correct": 1, "why": "MCL 418.115(b) independently requires coverage where at least 1 employee has worked 35+ hours/week for 13 or more weeks during the preceding 52 weeks, even with fewer than 3 employees.", "trap": false}, {"q": "A GC hires a framing sub that carries no workers' comp coverage, and the sub's employee is injured on the job. Who is liable for comp benefits?", "opts": ["The general contractor, as statutory principal, as if it employed the injured worker directly", "No one - the worker's only remedy is a tort suit against the sub", "The homeowner who contracted for the work", "The state's uninsured employer fund"], "correct": 0, "why": "MCL 418.171 makes the principal (GC) liable for comp benefits to an uninsured sub's injured workers as if it employed them directly, which is why GCs collect certificates of insurance.", "trap": false}], "03_contracts-hifa": [{"q": "A contractor finances a $2,500 kitchen remodel for a homeowner through an installment contract paid to the contractor. Which statute governs, and what is its price trigger?", "opts": ["HIFA applies to any home improvement over $600", "HSSA applies because the price exceeds $300", "HIFA - it covers home improvement installment contracts with a cash price in excess of $300", "The Construction Lien Act, because the price exceeds $1,000"], "correct": 2, "why": "HIFA (MCL 445.1101 et seq.) governs home improvement installment contracts with a cash price in excess of $300 (MCL 445.1102); the $600 figure is the separate licensure exemption in MCL 339.2403 and a trap.", "trap": true}, {"q": "A buyer signs a HIFA home improvement installment contract on Tuesday. Under HIFA's own rescission right, until when may the buyer rescind?", "opts": ["Until 5 p.m. on the business day following the date of the contract", "Until midnight of the third business day after signing", "Within 72 hours of signing", "Within 10 business days of signing"], "correct": 0, "why": "HIFA's rescission right runs until 5 p.m. on the business day following the contract date (MCL 445.1202(c)(4)); the 3-business-day right belongs to the HSSA and is the classic confusion trap.", "trap": true}, {"q": "A siding salesman knocks on a homeowner's door uninvited and signs her to a contract at her kitchen table. Under the Home Solicitation Sales Act, until when may she cancel?", "opts": ["Until 5 p.m. the next business day", "Until midnight of the third business day after signing", "Within 30 days of signing", "She cannot cancel once she has signed"], "correct": 1, "why": "MCL 445.112(1) gives the buyer of a home solicitation sale the right to cancel until midnight of the third business day after signing.", "trap": false}, {"q": "After a storm, a contractor wants to start emergency work immediately and cut off the HSSA 3-day cancellation right. Which is a required element of the emergency waiver?", "opts": ["A waiver clause pre-printed in the contract that the buyer initials", "A verbal waiver witnessed by two people", "Notice filed with the local building department", "A separate, dated, signed personal statement in the buyer's own handwriting describing the emergency and expressly waiving the right"], "correct": 3, "why": "MCL 445.112(5)(b) requires the buyer's own handwritten, dated, signed statement (along with substantial beginning of performance and non-returnable goods) - a typed or pre-printed waiver fails the statute.", "trap": false}, {"q": "A buyer properly cancels an HSSA sale. Within what period must the seller refund payments after receiving the cancellation notice?", "opts": ["10 calendar days", "30 days", "10 business days", "48 hours"], "correct": 2, "why": "MCL 445.113(2) requires refund of payments, trade-ins, and negotiable instruments within 10 BUSINESS days of the seller's receipt of the notice; 10 calendar days is the trap.", "trap": true}, {"q": "A contractor puts a liquidated-damages clause in a HIFA home improvement installment contract charging the buyer $500 if the buyer cancels. Is the clause enforceable?", "opts": ["Yes, if $500 is a reasonable pre-estimate of harm", "No - liquidated damages to the contractor for cancellation or rescission are a prohibited provision in a HIFA contract, and the clause is void", "Yes, because liquidated damages are always enforceable in construction contracts", "No, and the entire contract is void because it contains the clause"], "correct": 1, "why": "MCL 445.1206(1)(f) prohibits liquidated damages to the contractor for cancellation/rescission/refusal of delivery in a HIFA contract - the provision is void while the rest of the contract stands.", "trap": false}, {"q": "A licensed builder does a $4,000 residential addition on a verbal agreement with a handshake. The owner refuses to pay the final draw. Can the builder record a construction lien?", "opts": ["No - a residential construction lien requires a written contract containing the statutory licensure statement and the contractor's license number, with written change orders, at any contract amount", "Yes, because the builder is licensed", "Yes, because the amount exceeds $600", "No, unless the contract exceeded $10,000"], "correct": 0, "why": "MCL 570.1114 conditions residential lien rights on a written contract with the licensure statement and license number and written amendments, with no dollar threshold.", "trap": false}, {"q": "What is the statute of limitations for a breach of contract claim in Michigan?", "opts": ["3 years from the breach", "10 years from the breach", "1 year from discovery", "6 years from the breach"], "correct": 3, "why": "MCL 600.5807(9) sets a 6-year limitations period for breach of contract, running from the breach; 3 years is the negligence period under MCL 600.5805(2).", "trap": false}, {"q": "A homeowner discovers a construction defect 8 years after moving into the completed home and sues the builder for ordinary negligence. What result under the statute of repose?", "opts": ["The claim is timely because it was filed within a year of discovering the defect", "The claim is barred - the repose period is 6 years from occupancy, use, or acceptance, regardless of when the defect was discovered", "The claim is timely because the repose period is 10 years for all defect claims", "The claim is timely if the express warranty was still in effect"], "correct": 1, "why": "MCL 600.5839(1)(a) bars defect claims 6 years from occupancy, use, or acceptance; the 1-year-after-discovery window with a 10-year cap applies only to gross negligence under 600.5839(1)(b).", "trap": true}, {"q": "Under a cost-plus contract, which party bears the risk of construction cost overruns?", "opts": ["The contractor", "Both parties equally by law", "The owner", "The surety"], "correct": 2, "why": "In a cost-plus contract the owner bears the cost risk, while a fixed-price/lump-sum contract puts cost risk on the contractor (corpus contract-types table, Domain 03 section 5).", "trap": false}], "04_business-management": [{"q": "A job costs $10,000 and the contractor applies a 20% markup. What is the resulting gross profit margin on the selling price?", "opts": ["20%", "16.7%", "25%", "12%"], "correct": 1, "why": "Margin = markup divided by (1 + markup), so a 20% markup yields a 16.7% margin - answering 20% is the guaranteed trap (Domain 04 markup-vs-margin rule).", "trap": true}, {"q": "A contractor wants to EARN a 20% profit margin on a job costing $80,000. What should the price be?", "opts": ["$96,000 (cost times 1.20)", "$88,000", "$92,000", "$100,000 (cost divided by 0.80)"], "correct": 3, "why": "To earn a 20% margin you divide cost by 0.80 (a 25% markup): $80,000 / 0.80 = $100,000; multiplying by 1.20 is the trap and yields only a 16.7% margin.", "trap": true}, {"q": "Which corporate officer may be excluded from workers' compensation coverage in Michigan?", "opts": ["An officer owning at least 10% of a corporation with 10 or fewer stockholders, by filing Form WC-337", "Any three officers designated by board resolution", "Any officer, regardless of ownership, who signs a waiver", "Officers cannot be excluded under any circumstances"], "correct": 0, "why": "The exclusion test is 10 or fewer stockholders (or LLC members) AND at least 10% ownership, elected via Form WC-337 filed with the WDCA (MCL 418.161 / corpus Domain 04).", "trap": false}, {"q": "Which state agency administers the Worker's Disability Compensation Act?", "opts": ["LARA, which also licenses builders", "MIOSHA", "The WDCA under LEO (Department of Labor and Economic Opportunity)", "The Michigan Department of Treasury"], "correct": 2, "why": "The WDCA operates under LEO, not LARA - LARA licenses builders, and confusing the two agencies is a listed trap (corpus Domain 04 section 6).", "trap": true}, {"q": "For services performed on or after January 1, 2013, what test does Michigan's workers' compensation statute use to decide whether a worker is an employee or an independent contractor?", "opts": ["The ABC test", "The IRS 20-factor test from Revenue Ruling 87-41", "A 3-prong economic reality test", "The Fair Labor Standards Act joint-employer test"], "correct": 1, "why": "MCL 418.161(1)(n) expressly adopts the IRS 20-factor test (Rev. Rul. 87-41) for services on or after January 1, 2013; the old pre-2013 3-prong test is the trap.", "trap": false}, {"q": "A brand-new residential construction company registers with the Michigan UIA. What new-employer unemployment tax rate applies?", "opts": ["The average construction-industry rate announced annually, not the standard 2.7% new-employer rate", "2.7%, the same as every other new employer", "0.6%", "6.0% on all wages"], "correct": 0, "why": "Construction new employers pay the average construction-industry rate (historically about 5-8%) instead of the standard 2.7% new-employer rate (MI UIA, corpus Domain 04).", "trap": true}, {"q": "How does Michigan's 6% sales tax apply to a residential remodeling contract?", "opts": ["The contractor charges the homeowner 6% on the full contract price", "The contractor charges 6% on materials but not labor on the invoice", "No sales tax applies to construction in any form", "The contractor pays the tax on materials at purchase as the consumer; installation labor is exempt, and no tax is charged on the contract price"], "correct": 3, "why": "Contractors are the consumers of materials and pay 6% tax at purchase; installation labor is exempt and the contract price is not taxed (MI General Sales Tax Act, corpus Domain 04 section 7).", "trap": false}, {"q": "A non-exempt carpenter works four 11-hour days in one workweek (44 hours). Under the FLSA, how many overtime hours are owed?", "opts": ["12 hours - all hours over 8 per day", "None, because no single day exceeded 12 hours", "4 hours - overtime is 1.5 times the regular rate for hours over 40 in a workweek", "8 hours"], "correct": 2, "why": "FLSA overtime is 1.5x the regular rate for hours over 40 in a workweek only; there is no federal daily overtime, so 44 - 40 = 4 OT hours (29 USC 207, corpus Domain 04).", "trap": false}, {"q": "When is a Michigan LLC's annual statement due to LARA, and what is the fee?", "opts": ["February 15, with a $25 fee", "January 31, with a $50 fee", "The anniversary of formation, with a $25 fee", "April 15, with a $100 fee"], "correct": 0, "why": "MCL 450.4207 sets the February 15 annual statement duty with a $25 fee; roughly 2 years of non-filing leads to not-in-good-standing status, not automatic dissolution.", "trap": false}, {"q": "What is the penalty for an employer that fails to carry required workers' compensation coverage in Michigan?", "opts": ["An administrative fine of $10,000 assessed by MIOSHA", "Misdemeanor - fine up to $1,000 and/or up to 6 months, with EACH DAY of noncompliance a separate offense", "Automatic license revocation with no criminal exposure", "A one-time civil infraction of $500"], "correct": 1, "why": "MCL 418.641(1) makes noncompliance a misdemeanor with a fine up to $1,000 and/or up to 6 months, each day a separate offense; the uninsured employer also loses exclusive-remedy protection.", "trap": false}], "05_miosha-safety": [{"q": "Carpenters are working on an unguarded leading edge above a lower level. At what height does MIOSHA require conventional fall protection (guardrails, safety nets, or PFAS)?", "opts": ["10 feet", "4 feet", "6 feet or more above a lower level", "8 feet"], "correct": 2, "why": "MIOSHA Part 45 (R 408.44502, adopting 29 CFR 1926.501) triggers fall protection at 6 feet; 10 feet is the scaffold-specific number and the classic trap.", "trap": true}, {"q": "At what height must a guardrail be installed on the open side of a scaffold platform?", "opts": ["10 feet or more above the floor or ground", "6 feet or more above the floor or ground", "Any height above 4 feet", "Only above 20 feet"], "correct": 0, "why": "R 408.41213 requires a guardrail on any open side or end of a scaffold platform 10 feet or more above the floor or ground - the 6-foot general fall-protection trigger is the trap here.", "trap": true}, {"q": "A crew is digging a trench that will be 4 feet 6 inches deep in Type B soil. Which statement is correct?", "opts": ["Both a protective system and a ladder are required at this depth", "Neither is required until the trench passes 5 feet", "A protective system is required but no ladder", "A ladder (within 25 feet of lateral travel, extending 3 feet above the top) is required now; a sloping or support protective system becomes mandatory when depth exceeds 5 feet"], "correct": 3, "why": "R 408.40933(4) requires ladder egress at 48 inches (4 ft) or deeper within 25 feet of travel, while R 408.40941 requires the protective system when the excavation is more than 5 feet deep.", "trap": false}, {"q": "A worker dies on site Monday at 2 p.m. Another worker is hospitalized overnight Tuesday after an amputation. What are the MIOSHA reporting deadlines?", "opts": ["Both events within 24 hours", "Fatality within 8 hours; in-patient hospitalization or amputation within 24 hours", "Fatality within 24 hours; hospitalization within 48 hours", "Both events on the next 300A annual summary only"], "correct": 1, "why": "R 408.22139 requires fatality reports within 8 hours and in-patient hospitalization, amputation, or loss of an eye within 24 hours - swapping the two numbers is a listed trap.", "trap": true}, {"q": "What is the permissible exposure limit for noise on a MIOSHA construction site?", "opts": ["80 dBA 8-hour TWA", "90 dBA 8-hour TWA", "85 dBA 8-hour TWA", "100 dBA 8-hour TWA"], "correct": 1, "why": "The construction noise PEL (Part 680) is 90 dBA 8-hour TWA; the 85 dBA action level with audiometric testing is general industry only and is the trap on construction questions.", "trap": true}, {"q": "Which statement about MIOSHA's structure and coverage is correct?", "opts": ["MIOSHA is administered by LEO and covers public-sector (state/county/municipal) employees, which federal OSHA does not", "MIOSHA is administered by LARA and covers only private employers", "MIOSHA is a federal agency office located in Lansing", "MIOSHA covers private employers only; public employees are covered by federal OSHA"], "correct": 0, "why": "MIOSHA (Act 154 of 1974) has been administered by LEO since Executive Order 2019-13 and, as a state-plan program, covers public-sector employees that federal OSHA does not - a classic exam discriminator.", "trap": false}, {"q": "A portable extension ladder is set up for roof access. Which setup complies with MIOSHA Part 11?", "opts": ["Base one-half the vertical distance from the wall, rails even with the roof edge", "Base equal to the vertical distance from the wall, rails 2 feet above the landing", "Base one-quarter of the vertical distance from the top support, side rails extending at least 3 feet above the upper landing, secured against displacement", "Any angle is acceptable if the ladder has safety feet"], "correct": 2, "why": "R 408.41124 requires the 4:1 pitch (horizontal distance not more than 1/4 the vertical), side rails extending at least 3 feet above the landing, and the ladder tied, blocked, or otherwise secured.", "trap": false}, {"q": "How far back from the edge of an excavation must the spoil pile and equipment be kept?", "opts": ["6 feet", "4 feet", "1 foot", "At least 2 feet"], "correct": 3, "why": "R 408.40933(2) requires excavated material (and equipment) to be kept at least 2 feet back from the edge of the excavation.", "trap": false}, {"q": "What is the maximum civil penalty for a serious MIOSHA violation?", "opts": ["$16,550 per violation, matching federal OSHA", "$7,000 per violation", "$70,000 per violation", "$1,000 per violation"], "correct": 1, "why": "MCL 408.1035 caps serious and other-than-serious violations at $7,000 each; $70,000 is the willful/repeat maximum, and the federal inflation-adjusted amounts do not apply in Michigan.", "trap": false}, {"q": "A trench is being cut through submerged, sandy soil. What is the maximum allowable slope for this soil classification?", "opts": ["3/4H:1V (53 degrees)", "1H:1V (45 degrees)", "1.5H:1V (34 degrees)", "Vertical walls are permitted with a competent person on site"], "correct": 2, "why": "Sand, gravel, and submerged/wet soil are Type C (least stable, 0.5 tsf or less), with a maximum slope of 1.5H:1V (34 degrees); Type C also cannot be benched.", "trap": false}], "06_sitework-concrete-foundations": [{"q": "How deep must exterior footings and foundation systems extend below grade in Michigan?", "opts": ["12 inches below undisturbed ground or the local frost line", "42 inches below actual grade, statewide", "36 inches below grade", "48 inches below grade"], "correct": 1, "why": "The Michigan amendment to R403.1.4 requires all exterior footings/foundation systems to extend 42 inches below actual grade; the base IRC 12-inch/local-frost-line answer is the trap.", "trap": true}, {"q": "What is the minimum 28-day compressive strength for a residential garage floor slab in Michigan?", "opts": ["2,500 psi", "3,000 psi", "4,000 psi", "3,500 psi"], "correct": 3, "why": "All of Michigan is severe weathering potential, and Table R402.2 requires 3,500 psi for garage floor slabs and porches/carport slabs/steps exposed to weather; 2,500 and 3,000 psi are the lower-tier trap values.", "trap": true}, {"q": "For a two-story Michigan house, what is the code-minimum foundation anchor bolt installation?", "opts": ["Minimum 1/2-inch diameter bolts at maximum 6 feet on center, embedded at least 7 inches, minimum 2 bolts per plate section, one within 12 inches of each plate end", "Minimum 1/2-inch bolts at 4 feet on center because the building is over one story", "Minimum 5/8-inch bolts at 6 feet on center, embedded 6 inches", "Minimum 1/2-inch bolts at 8 feet on center, embedded 7 inches"], "correct": 0, "why": "R403.1.6 requires 1/2-inch bolts, 6 feet o.c., 7-inch embedment, 2 per plate section, within 12 inches of ends; the 4-foot spacing is the seismic R403.1.6.1 rule for SDC C/D and does not apply in Michigan (SDC A/B).", "trap": true}, {"q": "What surface drainage does the 2015 MRC require away from a foundation?", "opts": ["2 inches of fall within the first 10 feet", "12 inches of fall within the first 20 feet", "Grade falls a minimum of 6 inches within the first 10 feet; impervious surfaces within 10 feet need a minimum 2% slope", "6 inches of fall within the first 6 feet"], "correct": 2, "why": "R401.3 requires 6 inches of fall in the first 10 feet from the foundation, with a minimum 2% slope for impervious surfaces within 10 feet.", "trap": false}, {"q": "What total air content is required for residential concrete subject to weathering, and why?", "opts": ["3% to 5%, to improve workability", "Not less than 5% and not more than 7%, so freezing water has room to expand (freeze-thaw and deicer protection)", "8% to 10%, to reduce the water-cement ratio", "Air entrainment is optional in residential work"], "correct": 1, "why": "R402.2 requires 5% to 7% total air content for weathering exposure; the microscopic bubbles give freezing water room to expand, and 3-5% is the listed trap range.", "trap": true}, {"q": "A vented crawl space is 1,500 sq ft with no ground vapor retarder. What ventilation and access are required?", "opts": ["1 sq ft of vent per 300 sq ft; 22x30 access", "1 sq ft of vent per 1,500 sq ft; 18x24 access anywhere", "1 sq ft of vent per 150 sq ft; access 16x24 through the floor or 18x24 through the wall", "1 sq ft of vent per 150 sq ft (10 sq ft here), with an 18x24 through-floor or 16x24 through-perimeter-wall access opening"], "correct": 3, "why": "R408 requires 1/150 crawl ventilation (1/1,500 only with a Class 1 vapor retarder) and access of 18x24 through the floor or 16x24 through the perimeter wall; 1/300 is the attic ratio trap.", "trap": false}, {"q": "When is waterproofing (rather than dampproofing) required on a foundation wall that retains earth and encloses interior space below grade?", "opts": ["Only where a high water table or other severe soil-water conditions are known to exist - dampproofing is the default", "On every basement wall in Michigan because of the climate", "Only on masonry walls; concrete walls never need either", "Whenever the basement will be finished as living space"], "correct": 0, "why": "R406.1 makes dampproofing (top of footing to finished grade) the default; R406.2 requires waterproofing only where a high water table or severe soil-water conditions are known to exist.", "trap": false}, {"q": "How far in advance must a contractor contact MISS DIG 811 before excavating, and what can failing to notify cost?", "opts": ["72 hours before digging; $1,000 fine", "24 hours before digging; $500 fine", "At least 3 full working days before digging; MPSC civil fine up to $5,000", "3 calendar days before digging; misdemeanor only"], "correct": 2, "why": "2013 PA 174 requires notice at least 3 full WORKING days before excavating, and MCL 460.731 authorizes a civil fine up to $5,000 for failure to notify; '3 calendar days / 72 hours' is the trap.", "trap": false}, {"q": "Per the presumptive load-bearing table, what value is assigned to clay soil (CL, CH classifications)?", "opts": ["3,000 psf", "1,500 psf", "2,000 psf", "4,000 psf"], "correct": 1, "why": "Table R401.4.1 assigns clay, sandy clay, silty clay, and silt soils 1,500 psf - the lowest presumptive value; sand-class soils are 2,000 and gravels 3,000.", "trap": false}, {"q": "What are the footing projection limits beyond each face of the foundation wall?", "opts": ["Minimum projection of 2 inches, and the projection cannot exceed the footing thickness", "Minimum projection equal to the footing thickness", "Minimum 4 inches with no maximum", "No projection is required if the footing is at least 12 inches wide"], "correct": 0, "why": "R403.1.1 requires the footing to project a minimum of 2 inches beyond each wall face, with the projection not exceeding the footing thickness (minimum footing thickness 6 inches).", "trap": false}], "07_carpentry-framing": [{"q": "What are the maximum riser height and minimum tread depth for a residential stairway in Michigan?", "opts": ["7-3/4 inch riser, 10 inch tread", "7 inch riser, 11 inch tread", "8-1/4 inch riser, 9 inch tread", "8 inch riser, 9-1/2 inch tread"], "correct": 2, "why": "The Michigan amendments (R311.7 via R 408.30519) set an 8-1/4 inch max riser and 9 inch min tread; the IRC defaults of 7-3/4 and 10 inches are the prime trap.", "trap": true}, {"q": "At what joist size does the 2015 MRC require mid-span bridging or blocking, and at what interval?", "opts": ["Joists exceeding nominal 2x12, at intervals not exceeding 8 feet", "Joists exceeding nominal 2x10, at intervals not exceeding 8 feet", "All floor joists, at mid-span", "Joists exceeding nominal 2x12, at intervals not exceeding 6 feet"], "correct": 0, "why": "R502.7.1 requires lateral support at intervals not exceeding 8 feet only for joists exceeding nominal 2x12 - '2x10' is the classic wrong answer, and 2x12s themselves need no bridging.", "trap": true}, {"q": "What is the function and placement of collar ties in roof framing?", "opts": ["They resist rafter thrust and go in the lower third of the attic", "They replace ceiling joists when the joists run perpendicular to the rafters", "They support the ridge board on low-slope roofs", "They resist wind uplift at the ridge - placed in the upper third of the attic, minimum 1x4, at 4 feet on center or less"], "correct": 3, "why": "R802.3.1: collar ties (upper third, min 1x4, max 4 ft o.c.) resist wind uplift; rafter ties/ceiling joists in the lower part of the attic resist thrust - swapping the roles is the classic discrimination trap.", "trap": true}, {"q": "A plumber wants to notch a sawn floor joist. Which cut is prohibited by R502.8.1?", "opts": ["A notch of D/6 depth in the outer third of the span", "Any notch in the middle third of the span", "A bored hole of D/3 diameter with 2 inches of edge clearance", "An end notch of D/4 over the bearing"], "correct": 1, "why": "R502.8.1 prohibits notches in the middle third of the span; notches elsewhere are limited to D/6 (D/4 at ends) and bored holes to D/3 with 2-inch clearances.", "trap": false}, {"q": "What minimum end bearing is required for a floor joist?", "opts": ["3 inches on wood and 1-1/2 inches on masonry", "1-1/2 inches on all materials", "1-1/2 inches on wood or metal; 3 inches on masonry or concrete", "2 inches on wood; 4 inches on masonry"], "correct": 2, "why": "R502.6 requires 1-1/2 inches minimum bearing on wood or metal and 3 inches on masonry or concrete.", "trap": false}, {"q": "What is the maximum bored hole in a single stud in a load-bearing exterior wall?", "opts": ["40 percent of the stud width, with the hole edge at least 5/8 inch from the stud edge", "60 percent of the stud width", "25 percent of the stud width", "50 percent of the stud width"], "correct": 0, "why": "R602.6 limits bored holes in single bearing studs to 40% of the stud width (60% only in nonbearing partitions or doubled bearing studs), with a 5/8-inch edge distance; cross-wiring the 40/60 values is a listed trap.", "trap": true}, {"q": "A top plate in an exterior bearing wall was cut more than 50 percent of its width for a drain line. What repair does R602.6.1 require?", "opts": ["Sister a second full-length top plate over the cut", "Add a stud directly under the cut", "No repair - double top plates allow one plate to be fully cut", "A 16-gauge (0.054 inch) galvanized metal tie, 1-1/2 inches wide, with eight 10d nails each side, extending at least 6 inches past the opening"], "correct": 3, "why": "R602.6.1 requires the 16-ga x 1-1/2 inch galvanized tie with eight 10d nails each side extending 6 inches past the opening when a bearing-wall top plate is cut or notched more than 50% of its width.", "trap": false}, {"q": "Which statement about ridge framing is correct under R802.3?", "opts": ["The ridge board must be 2-inch nominal and valley rafters 1-inch nominal", "The ridge board must be at least 1-inch nominal thickness and not less than the cut end of the rafter in depth; below 3:12 pitch the ridge must be designed as a beam", "A ridge board is never required if collar ties are installed", "Any roof under 6:12 pitch requires a structural ridge beam"], "correct": 1, "why": "R802.3 requires a ridge board of at least 1-inch nominal thickness (valley/hip rafters 2-inch nominal), depth not less than the rafter cut end, and a designed ridge beam where pitch is under 3:12.", "trap": false}, {"q": "Which deck ledger attachment complies with R507.2?", "opts": ["Minimum 2x8 pressure-treated No. 2 ledger fastened with 1/2-inch hot-dipped galvanized or stainless lag screws or through-bolts with washers, with flashing at the house", "2x6 ledger fastened with 16d galvanized nails at 16 inches on center", "2x8 ledger fastened with electroplated 3/8-inch lag screws", "Any ledger size fastened with structural screws per the framer's judgment"], "correct": 0, "why": "R507.2 requires a minimum 2x8 PT No. 2 ledger with 1/2-inch hot-dipped galvanized or stainless lags or through-bolts with washers plus flashing - nails or electroplated fasteners are always wrong.", "trap": false}, {"q": "A deck walking surface is 34 inches above grade. What guard is required?", "opts": ["No guard - guards start at 36 inches above grade", "A 34-inch guard matching handrail height", "A guard at least 36 inches high, with openings that reject a 4-inch sphere, resisting a 200-lb load", "A 42-inch guard as on commercial work"], "correct": 2, "why": "R312 requires guards at least 36 inches high where the walking surface is more than 30 inches above floor or grade, with the 4-inch sphere rule and 200-lb load.", "trap": false}], "08_masonry-roofing-siding": [{"q": "Which mortar type is the standard choice for brick veneer above grade?", "opts": ["Type M, because it is the strongest", "Type N (750 psi), the general-purpose above-grade mortar", "Type O", "Type S, required for all veneer"], "correct": 1, "why": "Type N (750 psi) is the general-purpose above-grade and brick veneer mortar; picking Type M 'because strongest' is the listed trap - M (2,500 psi) is for below-grade and earth contact.", "trap": true}, {"q": "What is the maximum spacing for brick veneer wall ties?", "opts": ["24 inches o.c. horizontal and 32 inches o.c. vertical", "33 inches o.c. in both directions", "16 inches o.c. each way", "32 inches o.c. horizontal and 24 inches o.c. vertical, each tie supporting not more than 2.67 sq ft"], "correct": 3, "why": "R703.8.4.1 caps ties at 32 inches o.c. horizontal and 24 inches o.c. vertical with max 2.67 sq ft per tie; reversing the two directions is the listed trap.", "trap": true}, {"q": "What does the 2015 MRC require for weepholes in brick veneer?", "opts": ["Maximum 33 inches on center, minimum 3/16 inch diameter, located immediately above the flashing", "Maximum 24 inches on center, minimum 1/4 inch diameter, at the second course", "Maximum 48 inches on center at the top of the wall", "Weepholes are optional if the air space is at least 1 inch"], "correct": 0, "why": "R703.8.6 requires weepholes at maximum 33 inches o.c., minimum 3/16 inch diameter, immediately above the flashing; 32 inches is the tie spacing, not the weep spacing.", "trap": false}, {"q": "How high must a masonry chimney terminate?", "opts": ["2 feet above the roof penetration and 3 feet above anything within 10 feet", "At least 5 feet above the ridge in all cases", "At least 3 feet above the highest point where it passes through the roof AND at least 2 feet higher than any part of the building within 10 feet horizontally", "At least 3 feet above the roof with no other condition"], "correct": 2, "why": "R1003.9 is the 3-2-10 rule: 3 feet above the highest roof penetration point and 2 feet above any part of the building within 10 feet horizontally.", "trap": false}, {"q": "What clearance to combustibles is required for a masonry chimney?", "opts": ["1 inch below the roofline and 2 inches above it", "2 inches for chimneys interior to the building or within an exterior wall; 1 inch for chimneys located entirely outside the exterior walls", "2 inches in all locations", "4 inches in all locations"], "correct": 1, "why": "R1003.18 splits the clearance by interior (2 inches) versus entirely-exterior (1 inch) chimneys - the split is interior/exterior, not below/above the roof, which is the listed trap.", "trap": true}, {"q": "What is the minimum roof slope for asphalt shingles, and what underlayment rule applies on low slopes?", "opts": ["Minimum 2:12; from 2:12 up to (but less than) 4:12, double underlayment is required", "Minimum 3:12; single underlayment everywhere", "Minimum 4:12; shingles are prohibited below that", "Minimum 1:12 with ice barrier"], "correct": 0, "why": "R905.2.2 allows asphalt shingles down to 2:12 with double underlayment from 2:12 to less than 4:12; 3:12 is the wood shingle/lapped-metal minimum and a trap.", "trap": true}, {"q": "How far must the ice barrier extend on a Michigan roof with a 6:12 slope?", "opts": ["24 inches up the slope from the eave edge", "36 inches from the eave edge on all slopes", "Ice barrier is only required in the Upper Peninsula", "From the lowest roof edge to at least 24 inches inside the exterior wall line"], "correct": 3, "why": "R905.1.2 requires the ice barrier from the lowest roof edge to at least 24 inches inside the exterior wall line (36 inches along the slope only where the roof slope is 8:12 or steeper); measuring from the eave edge is the trap.", "trap": false}, {"q": "How is drip edge sequenced with the underlayment?", "opts": ["Underlayment over the drip edge at both eaves and rakes", "Drip edge over the underlayment at both eaves and rakes", "At eaves the underlayment goes OVER the drip edge; at rakes the drip edge goes OVER the underlayment", "Sequencing is left to the installer"], "correct": 2, "why": "R905.2.8.5: at eaves the underlayment laps over the drip edge, while at rakes (gables) the drip edge is installed over the underlayment - reversing eave and rake is the listed trap.", "trap": false}, {"q": "A house already has two layers of asphalt shingles. The owner wants a third layer installed. What does R908.3 require?", "opts": ["A third layer is allowed if the deck is sound", "Tear-off is required - reroofing over two or more existing layers of any roof covering is not permitted", "A third layer is allowed with ring-shank nails", "Only the top layer must be removed"], "correct": 1, "why": "R908.3 requires removal when two or more layers of any roof covering already exist (also for water-soaked/deteriorated roofs and wood shake, slate, or tile), so the maximum is 2 layers total.", "trap": false}, {"q": "A vented attic has a Class II vapor retarder on the warm-in-winter side of the ceiling, in climate zone 6A. What net free ventilating area is required?", "opts": ["1/300 of the vented attic area - the vapor retarder condition alone permits the reduction in zones 6-7-8", "1/150 with no reduction available", "1/300 only if 40-50% of the vents are also high", "1/500 of the attic area"], "correct": 0, "why": "R806.2 reduces the 1/150 base to 1/300 when EITHER a Class I/II ceiling vapor retarder exists (zones 6/7/8 only) OR 40-50% of the vent area is high - either condition alone is sufficient, and requiring both is the trap.", "trap": false}], "09_envelope-interior": [{"q": "What is the required ceiling insulation for a new house in climate zone 5A (southern Lower Peninsula)?", "opts": ["R-30", "R-49", "R-38 - the Michigan amendment; R-49 applies in zones 6A and 7", "R-60"], "correct": 2, "why": "Table N1102.1.1 as amended by Michigan sets zone 5A ceilings at R-38; R-49 is the base-IECC/zones 6-7 value and the listed trap.", "trap": true}, {"q": "What is Michigan's maximum air leakage rate for a new dwelling, and how is it verified?", "opts": ["Maximum 4 ACH50, verified by a mandatory blower-door test", "Maximum 3 ACH50 per the model IECC", "Maximum 5 ACH50, visual inspection allowed", "There is no numeric limit in Michigan"], "correct": 0, "why": "N1102.4.1.2 (Michigan amendment) sets a maximum of 4 ACH50 with a mandatory blower-door test; the model IECC value of 3 ACH50 is a trap.", "trap": true}, {"q": "A basement bedroom egress window measures exactly 20 inches wide by 24 inches high in net clear opening. Does it comply with R310?", "opts": ["Yes - it meets both the minimum width and minimum height", "Yes, as long as the sill is under 44 inches", "No, because the minimum width is 24 inches", "No - 20 x 24 is only 3.33 sq ft, and the net clear opening must be at least 5.7 sq ft, so one dimension must be larger"], "correct": 3, "why": "R310.1 requires 5.7 sq ft net clear opening (min 24-inch height, 20-inch width, 44-inch max sill), and 20 x 24 = 3.33 sq ft - meeting both minimum dimensions does not satisfy the area, the classic math trap.", "trap": true}, {"q": "What is the minimum net clear opening area for a grade-floor emergency escape and rescue opening?", "opts": ["5.7 sq ft", "5.0 sq ft", "4.0 sq ft", "6.0 sq ft"], "correct": 1, "why": "R310.1 reduces the required net clear opening to 5.0 sq ft for grade-floor openings; 5.7 sq ft is the non-grade-floor requirement.", "trap": false}, {"q": "What gypsum board does the code require on the garage side of a wall separating the garage from the dwelling (no habitable space above the garage)?", "opts": ["1/2-inch gypsum board", "5/8-inch Type X on all garage surfaces", "A 1-hour fire-resistance-rated assembly", "No protection is required on walls, only ceilings"], "correct": 0, "why": "Table R302.6 requires 1/2-inch gypsum on garage walls; 5/8-inch Type X applies only to a garage ceiling with habitable space above, and this is a separation, not a rated 1-hour assembly - both listed traps.", "trap": true}, {"q": "What local exhaust rates does Table M1507.4 require for a bathroom?", "opts": ["100 cfm intermittent or 25 cfm continuous", "25 cfm intermittent or 10 cfm continuous", "50 cfm intermittent or 20 cfm continuous", "80 cfm intermittent only"], "correct": 2, "why": "Table M1507.4 requires 50 cfm intermittent or 20 cfm continuous for bathrooms/toilet rooms; 100/25 are the kitchen numbers and the trap.", "trap": false}, {"q": "In Michigan's climate zones, where does a required Class I or II vapor retarder go on a frame wall?", "opts": ["On the exterior side under the sheathing", "On the interior (warm-in-winter) side of the wall", "On both faces of the wall for maximum protection", "Vapor retarders are optional in all Michigan zones"], "correct": 1, "why": "R702.7 requires a Class I or II vapor retarder on the interior warm-in-winter side in zones 5/6/7, and Class I poly on the exterior side is prohibited practice because it creates a double vapor barrier.", "trap": false}, {"q": "A fixed glass panel sits 20 inches to the side of a swinging door, with its bottom edge 30 inches above the floor. Is safety glazing required?", "opts": ["No - only glazing in the door itself must be tempered", "No, because the panel is above 24 inches from the floor", "Only if the panel exceeds 9 sq ft", "Yes - glazing within a 24-inch arc of either side of a door with its bottom edge less than 60 inches above the floor is a hazardous location"], "correct": 3, "why": "R308.4 requires safety glazing within a 24-inch arc of either side of a closed door where the bottom edge is less than 60 inches above the floor.", "trap": false}, {"q": "An operable second-story window has its sill 18 inches above the interior floor and sits 10 feet above exterior grade. What does R312.2 require?", "opts": ["The opening must not pass a 4-inch sphere, or an ASTM F2090 opening-control/fall-prevention device must be used", "Nothing - fall protection applies only to windows over 20 feet up", "The window must be fixed (non-operable)", "A 24-inch interior guardrail in front of the window"], "correct": 0, "why": "R312.2 applies where the sill is less than 24 inches above the floor and more than 72 inches above grade: the opening must reject a 4-inch sphere or use an ASTM F2090 device.", "trap": false}, {"q": "When is an attic access opening required, and what minimum size?", "opts": ["In every house, 24 x 36 inches", "Where the attic exceeds 30 sq ft AND has 30 inches or more of vertical height - rough opening minimum 22 x 30 inches with 30 inches of unobstructed headroom above it", "Where the attic exceeds 100 sq ft, 22 x 36 inches", "Only where mechanical equipment is in the attic, 30 x 30 inches"], "correct": 1, "why": "R807.1 requires attic access where the area exceeds 30 sq ft and vertical height is 30 inches or more, with a 22 x 30 inch minimum rough opening and 30 inches of headroom; 24x30 and 22x36 are listed traps.", "trap": false}], "10_plans-math-trades": [{"q": "How many board feet are in 40 pieces of 2x10 lumber, each 12 feet long?", "opts": ["640 BF", "800 BF", "960 BF", "400 BF"], "correct": 1, "why": "BF = (nominal T x W x L feet) / 12, so each 2x10x12 = 240/12 = 20 BF, and 40 pieces x 20 BF = 800 BF.", "trap": false}, {"q": "A slab measures 20 feet by 30 feet by 4 inches thick. Before waste, how much concrete is required?", "opts": ["10.5 cubic yards", "5.2 cubic yards", "8.9 cubic yards", "About 7.4 cubic yards (200 cu ft divided by 27)"], "correct": 3, "why": "20 x 30 x 0.333 ft = 200 cu ft, and 200 / 27 = 7.4 CY; you would order about 8 CY with 5-10% waste.", "trap": false}, {"q": "A Michigan stairway has a total rise of 108 inches. Using the maximum riser of 8-1/4 inches, how many risers and treads are needed?", "opts": ["14 risers and 13 treads (108 / 8.25 = 13.09, round UP; actual riser 7.71 inches)", "13 risers and 12 treads", "13 risers and 13 treads", "14 risers and 14 treads"], "correct": 0, "why": "Risers = total rise / max riser rounded UP (13.09 becomes 14, since 13 risers would be an illegal 8.31 inches), and treads = risers minus 1 = 13; rounding down is the trap.", "trap": true}, {"q": "On a window schedule, what size is a window with the callout 3050?", "opts": ["30 inches wide by 50 inches high", "3.0 feet high by 5.0 feet wide", "3 feet 0 inches wide by 5 feet 0 inches high", "35 inches by 50 inches"], "correct": 2, "why": "The first pair is width in feet-inches and the second is height, so 3050 = 3'-0\" wide x 5'-0\" high.", "trap": false}, {"q": "After a complete permit application is filed for an ordinary house, how long does the enforcing agency have to issue or deny the building permit?", "opts": ["30 calendar days", "10 business days (15 for an unusually complicated building or structure)", "5 business days", "There is no statutory deadline"], "correct": 1, "why": "MCL 125.1511(1) requires the AHJ to grant or deny within 10 business days (15 for an unusually complicated structure), and failure to act is a deemed denial; 30 days is the trap. The C of O deadline is 5 business days (MCL 125.1513).", "trap": true}, {"q": "Which detached deck can be built WITHOUT a building permit under the 2015 MRC R105.2?", "opts": ["A deck not more than 200 sq ft, not more than 30 inches above grade, not attached to the dwelling or serving the required exit door", "Any deck under 120 sq ft", "Any deck under 400 sq ft if freestanding", "No deck is ever permit-exempt"], "correct": 0, "why": "R105.2 exempts decks of 200 sq ft or less that are not more than 30 inches above grade and not attached to or serving the required exit door; 120 sq ft is the old-code trap number.", "trap": true}, {"q": "A builder wants to hire an individual holding a 'master mechanical license' to run HVAC work. What is wrong with this plan?", "opts": ["Nothing - a master mechanical license requires 12,000 hours", "The master must also hold an electrical license", "Mechanical licenses are issued by MIOSHA, not LARA", "Michigan has NO individual journeyman or master mechanical license - mechanical work requires a contractor ENTITY license with a qualifying officer and classification endorsements"], "correct": 3, "why": "Under the Skilled Trades Regulation Act (PA 407 of 2016) there is no individual mechanical license in Michigan - only a contractor entity license with a qualifying officer; the 'master mechanical license' is a listed trap.", "trap": true}, {"q": "A homeowner wants to personally wire an addition on a rental house she owns, under her own permit. Is this allowed?", "opts": ["Yes - owners may work on any property they own", "Yes, if a licensed electrician inspects the work", "No - the homeowner trade exemption covers only the owner's own primary residence, and rentals are excluded", "Yes, for electrical but not plumbing"], "correct": 2, "why": "The homeowner exemption lets an owner self-perform trade work only on their own primary residence under their own permit; rentals are excluded, and a contractor may never work under a homeowner-pulled permit.", "trap": false}, {"q": "You must haul away 100 bank cubic yards of common earth with a 25% swell factor. How many loose cubic yards will you haul?", "opts": ["75 loose CY", "125 loose CY", "100 loose CY", "133 loose CY"], "correct": 1, "why": "Bank volume swells when excavated: 100 bank CY x 1.25 = 125 loose CY; compacted fill, by contrast, shrinks below bank volume.", "trap": false}, {"q": "A brick veneer wall is 1,000 sq ft with 100 sq ft of openings. Using the standard modular brick count, how many bricks are needed before waste?", "opts": ["6,075 bricks (900 sf x 6.75 per sq ft)", "5,400 bricks", "7,425 bricks", "1,013 bricks"], "correct": 0, "why": "Standard modular brick runs 6.75 per sq ft of wall (3/8-inch joints, running bond): (1,000 - 100) x 6.75 = 6,075 bricks, plus about 5% waste when ordering.", "trap": false}]}};
